/** 空間平視 Gemini：與產品相同組裝鏡頭／曝光／底片 fragments（. 串接）；不含拍攝角度／人物 */
async function buildPromoSpaceEyeLevelCameraBlock(cameraKeys) {
    const raw = cameraKeys && typeof cameraKeys === 'object' ? cameraKeys : {};
    const filtered = Object.assign({}, raw);
    delete filtered.shooting_angle;
    delete filtered.subject_preservation;
    const catRes = await fetchPromoCameraParamCategories(true);
    const cameraUi = buildPromoCameraUiConfigFromCategories(catRes.categories || [], 'en');
    const cam = await resolvePromoCameraPromptFragments(filtered, cameraUi);
    const parts = (cam.fragments || []).map(function (f) { return String(f || '').trim(); }).filter(Boolean);
    const block = parts.join('. ');
    if (!block) {
        console.warn('[promo-space eye_level] cameraBlock empty; keys=', Object.keys(filtered));
    } else {
        console.log('[promo-space eye_level] cameraBlock chars=', block.length, 'parts=', parts.length);
    }
    return block;
}

async function buildPromoSpaceLayoutCameraBlock(cameraKeys) {
    return buildPromoSpaceEyeLevelCameraBlock(cameraKeys);
}

/** eye_level：以 ISO 空間地圖為參考（layout_generation_id 或 layout_image URL） */
async function resolvePromoSpaceEyeLevelReferences(body, userId) {
    const b = body && typeof body === 'object' ? body : {};
    const layoutGenId = String(b.layout_generation_id || b.layout_id || '').trim();
    let layoutUrl = String(b.layout_image || b.layout_reference || '').trim();
    const hasClientLayoutImage = !!layoutUrl;
    let layoutMeta = null;
    let inheritedSpaceUse = null;
    /** 入庫用：僅保留原圖 URL；有字母的合成圖（data URL）不當資產存 */
    let layoutPersistUrl = null;

    if (layoutGenId) {
        const { data: row, error } = await supabase
            .from('product_promo_generations')
            .select('id, user_id, result_image_url, generation_meta_json')
            .eq('id', layoutGenId)
            .maybeSingle();
        if (error || !row || String(row.user_id) !== String(userId)) {
            return { error: '找不到 ISO 空間地圖，請從數位資產重新選擇' };
        }
        layoutPersistUrl = String(row.result_image_url || '').trim() || null;
        /* 前端已標字母的 layout_image 優先給 Gemini；否則用資產庫原圖 */
        if (!hasClientLayoutImage) {
            layoutUrl = layoutPersistUrl || '';
        }
        layoutMeta = parsePromoGenerationMetaJson(row.generation_meta_json);
        inheritedSpaceUse = layoutMeta.space_use_type || null;
    } else if (layoutUrl && !/^data:/i.test(layoutUrl)) {
        layoutPersistUrl = layoutUrl;
    }
    if (!layoutUrl) {
        return { error: '請選擇或生成 ISO 空間地圖作為對照參考' };
    }
    const layoutB64 = await resolveImageToBase64(layoutUrl);
    if (!layoutB64) {
        return { error: 'ISO 空間地圖無法讀取，請重新選擇' };
    }
    const shotKeys = parsePromoSpaceShotIntentKeys(b);
    const viewMode = String(b.view_mode || '').trim().toLowerCase();
    const guided = shotKeys.length > 0 || viewMode === 'guided';
    const viewpoint = String(b.user_prompt || b.prompt || b.viewpoint || '').trim();
    const lookFrom = String(b.look_from || b.from || 'B').trim().toUpperCase();
    const lookTo = String(b.look_to || b.to || 'C').trim().toUpperCase();
    let stagingProduct = null;
    const prodResolved = await resolvePromoStagingProductImage(b);
    if (prodResolved && prodResolved.error) return { error: prodResolved.error };
    if (prodResolved && prodResolved.base64) stagingProduct = prodResolved;
    return {
        layoutImage: { base64: layoutB64, mime: mimeFromPromoImageRef(layoutUrl) },
        layoutUrl: layoutPersistUrl || null,
        layoutGenerationId: layoutGenId || null,
        layoutMeta,
        inheritedSpaceUse,
        viewpoint,
        lookFrom,
        lookTo,
        mapMarkers: b.map_markers && typeof b.map_markers === 'object' ? b.map_markers : null,
        usedLabeledMap: hasClientLayoutImage && /^data:/i.test(String(b.layout_image || b.layout_reference || '')),
        stagingProduct
    };
}

/** 空間生圖：Interactions API（response_format.image_size）；需 @google/genai >= 2 */
async function generatePromoSpaceImageViaInteractions(model, promptText, imageRefs, geminiOpts) {
    const opts = geminiOpts && typeof geminiOpts === 'object' ? geminiOpts : {};
    const responseFormat = promoSpaceGemini.buildPromoSpaceInteractionsResponseFormat(opts);
    const input = promoSpaceGemini.buildPromoSpaceInteractionsInput(promptText, imageRefs);
    console.log('[promo-space interactions] model=', model, 'response_format=', JSON.stringify(responseFormat), 'refs=', input.length - 1);
    const interaction = await runInGeminiImageQueue(() => genAI.interactions.create({
        model,
        input,
        response_format: responseFormat
    }));
    const oi = interaction && interaction.output_image;
    if (!oi || !oi.data) {
        throw new Error('Gemini Interactions 未回傳圖片');
    }
    const buffer = Buffer.from(String(oi.data), 'base64');
    if (!buffer.length) throw new Error('Gemini Interactions 圖片為空');
    return {
        buffer,
        mime: oi.mime_type || oi.mimeType || 'image/jpeg',
        response_format: responseFormat,
        api: 'interactions'
    };
}

async function generatePromoSpaceEyeLevelImageWithGemini(layoutImage, promptText, stagingProduct, geminiOpts) {
    if (!process.env.GEMINI_API_KEY) {
        throw new Error('情境圖服務暫未設定，請稍後再試');
    }
    const prompt = String(promptText || '').trim();
    if (!prompt) throw new Error('平視攝影提示詞為空');
    const opts = geminiOpts && typeof geminiOpts === 'object' ? geminiOpts : {};
    const model = await getPromoSpaceEyeLevelModelName();
    /* 文字在前，再地圖／道具（Interactions multimodal） */
    const imageRefs = [{ base64: layoutImage.base64, mime: layoutImage.mime || 'image/jpeg' }];
    if (stagingProduct && stagingProduct.base64) {
        imageRefs.push({ base64: stagingProduct.base64, mime: stagingProduct.mime || 'image/jpeg' });
    }
    let extracted;
    let apiUsed = 'interactions';
    let responseFormat = promoSpaceGemini.buildPromoSpaceInteractionsResponseFormat(opts);
    try {
        extracted = await generatePromoSpaceImageViaInteractions(model, prompt, imageRefs, opts);
        responseFormat = extracted.response_format || responseFormat;
    } catch (interErr) {
        console.warn('[promo-space eye_level] interactions failed, fallback generateContent:', interErr && interErr.message);
        apiUsed = 'generateContent';
        const parts = [{ text: prompt }];
        parts.push({ inlineData: { mimeType: layoutImage.mime || 'image/jpeg', data: layoutImage.base64 } });
        if (stagingProduct && stagingProduct.base64) {
            parts.push({ inlineData: { mimeType: stagingProduct.mime || 'image/jpeg', data: stagingProduct.base64 } });
        }
        const result = await runInGeminiImageQueue(() => genAI.models.generateContent({
            model,
            contents: [{ role: 'user', parts }],
            config: promoSpaceGemini.buildPromoSpaceGeminiGenerateConfig(opts)
        }));
        const hit = await extractLargestGeminiResponseImageBuffer(result);
        if (!hit || !hit.buffer || !hit.buffer.length) {
            throw interErr;
        }
        extracted = { buffer: hit.buffer, response_format: responseFormat };
    }
    const native = await promoSpaceGemini.measurePromoSpaceImageDimensions(extracted.buffer);
    const buffer = await promoSpaceGemini.ensurePromoSpaceOutputDimensions(
        extracted.buffer,
        opts.targetWidth || opts.width,
        opts.targetHeight || opts.height,
        {
            tier: opts.tier || opts.space_resolution_tier,
            aspect_ratio: opts.aspectRatio || opts.aspect_ratio
        }
    );
    return {
        buffer,
        gemini_native_width: native.width || 0,
        gemini_native_height: native.height || 0,
        image_config: responseFormat,
        api: apiUsed,
        image_provider: 'gemini'
    };
}

/** BFL 最長邊 2048；空間 4K 先以等比縮小送 FLUX，再 sharp 補到目標像素 */
function clampBflFluxOutputSize(width, height, maxEdge) {
    const max = Math.max(256, Number(maxEdge) || 2048);
    let w = Math.max(1, Number(width) || 1024);
    let h = Math.max(1, Number(height) || 1024);
    const longest = Math.max(w, h);
    if (longest > max) {
        const scale = max / longest;
        w = Math.round(w * scale);
        h = Math.round(h * scale);
    }
    return {
        width: Math.min(max, Math.max(256, w)),
        height: Math.min(max, Math.max(256, h))
    };
}

async function generatePromoSpaceEyeLevelImageWithFlux(layoutImage, promptText, stagingProduct, geminiOpts) {
    if (!process.env.BFL_API_KEY) {
        throw new Error('情境圖服務暫未設定，請稍後再試');
    }
    const prompt = String(promptText || '').trim();
    if (!prompt) throw new Error('平視攝影提示詞為空');
    const opts = geminiOpts && typeof geminiOpts === 'object' ? geminiOpts : {};
    const targetW = opts.targetWidth || opts.width;
    const targetH = opts.targetHeight || opts.height;
    const fluxSize = clampBflFluxOutputSize(targetW, targetH, 2048);
    const refs = [layoutImage.base64];
    if (stagingProduct && stagingProduct.base64) refs.push(stagingProduct.base64);
    const fluxModel = await getBflFluxModelIdForConfigKey('bfl_flux_model_promo_space_eye_level');
    const endpointUrl = getBflPlaygroundEndpoint(fluxModel);
    const bufferRaw = await generateImageWithFlux2Pro(prompt, refs, null, 'jpeg', {
        endpointUrl: endpointUrl,
        width: fluxSize.width,
        height: fluxSize.height,
        promptUpsampling: false
    });
    if (!bufferRaw || !bufferRaw.length) throw new Error('FLUX 未回傳圖片');
    const native = await promoSpaceGemini.measurePromoSpaceImageDimensions(bufferRaw);
    const buffer = await promoSpaceGemini.ensurePromoSpaceOutputDimensions(
        bufferRaw,
        targetW,
        targetH,
        {
            tier: opts.tier || opts.space_resolution_tier,
            aspect_ratio: opts.aspectRatio || opts.aspect_ratio
        }
    );
    return {
        buffer,
        gemini_native_width: native.width || 0,
        gemini_native_height: native.height || 0,
        image_config: { engine: 'flux', model: fluxModel, width: fluxSize.width, height: fluxSize.height },
        api: 'bfl',
        image_provider: 'flux',
        flux_model: fluxModel
    };
}

/**
 * 空間平視：Gemini 優先，滿額／429 備援 FLUX.2 [max]（後台 promo_space_eye_level_engine）。
 */
async function generatePromoSpaceEyeLevelImage(layoutImage, promptText, stagingProduct, geminiOpts) {
    const pref = await getPromoSpaceEyeLevelEngine();
    const forceFlux = pref === 'flux';
    const forceGemini = pref === 'gemini';
    const hasGemini = !!process.env.GEMINI_API_KEY;
    const hasFlux = !!process.env.BFL_API_KEY;

    if (!forceFlux && hasGemini) {
        const quota = checkDualColorGeminiQuota();
        if (quota.ok) {
            try {
                recordDualColorGeminiAttempt();
                const gen = await generatePromoSpaceEyeLevelImageWithGemini(
                    layoutImage, promptText, stagingProduct, geminiOpts
                );
                const geminiModel = await getPromoSpaceEyeLevelModelName();
                return Object.assign({}, gen, {
                    image_provider: 'gemini',
                    gemini_model: geminiModel
                });
            } catch (err) {
                if (forceGemini || !isGeminiImageRateLimitError(err)) throw err;
                console.warn('[promo-space eye_level] Gemini rate-limited → FLUX.2:', err.message || err);
            }
        } else if (forceGemini) {
            const e = new Error('Gemini 生圖次數已達上限，請稍後再試');
            e.status = 429;
            e.retry_after_sec = quota.retry_after_sec;
            e.quota_reason = quota.reason;
            throw e;
        }
    }

    if (!hasFlux) {
        throw new Error('情境圖服務暫未設定，請稍後再試');
    }
    return generatePromoSpaceEyeLevelImageWithFlux(layoutImage, promptText, stagingProduct, geminiOpts);
}

async function assertPromoSpaceEyeLevelProvidersReady() {
    const pref = await getPromoSpaceEyeLevelEngine();
    const hasGemini = !!process.env.GEMINI_API_KEY;
    const hasFlux = !!process.env.BFL_API_KEY;
    if (pref === 'gemini' && !hasGemini) {
        return { ok: false, error: '情境圖服務暫未設定，請稍後再試' };
    }
    if (pref === 'flux' && !hasFlux) {
        return { ok: false, error: '情境圖服務暫未設定，請稍後再試' };
    }
    if (pref === 'auto' && !hasGemini && !hasFlux) {
        return { ok: false, error: '情境圖服務暫未設定，請稍後再試' };
    }
    return { ok: true, pref: pref };
}

function mimeFromPromoImageRef(ref) {
    const s = String(ref || '').trim();
    const m = s.match(/^data:(image\/[^;]+);/i);
    return m ? m[1].toLowerCase() : 'image/jpeg';
}

/** 選填：人像／空間陳列用產品／道具參考圖 */
async function resolvePromoStagingProductImage(body) {
    const raw = String((body && (body.product_image || body.staging_product)) || '').trim();
    if (!raw) return null;
    const b64 = await resolveImageToBase64(raw);
    if (!b64) return { error: '產品／道具參考圖無法讀取，請重新上傳' };
    return {
        base64: b64,
        mime: mimeFromPromoImageRef(raw),
        url: (typeof raw === 'string' && /^https?:\/\//i.test(raw)) ? raw : null
    };
}

function promoFluxPortraitExtraRefsPromptPart(opts) {
    const o = opts && typeof opts === 'object' ? opts : {};
    const hasScene = !!o.hasSceneImage;
    const hasProduct = !!o.hasStagingProduct;
    if (hasScene && hasProduct) {
        return 'Reference image 1 is the person for facial identity. Reference image 2 is the scene or environment to place the person in. Reference image 3 is a product or prop. Preserve the same person\'s facial identity; integrate the scene and product naturally per the user description.';
    }
    if (hasScene) {
        return 'Reference image 1 is the person for facial identity. Reference image 2 is the scene or environment reference. Place the same person into this environment; preserve facial identity and match the scene lighting and spatial context.';
    }
    if (hasProduct) {
        return 'Reference image 1 is the person for facial identity. Reference image 2 is the product or prop to feature in the shot. Integrate the product naturally per the user description; preserve the same person\'s facial identity.';
    }
    return '';
}

/** @deprecated use promoFluxPortraitExtraRefsPromptPart */
function promoFluxPortraitProductRefPromptPart() {
    return promoFluxPortraitExtraRefsPromptPart({ hasStagingProduct: true });
}

/** 人像模式：選填場景／環境參考圖 */
async function resolvePromoSceneReferenceImage(body) {
    const raw = String((body && (body.scene_image || body.scene_reference)) || '').trim();
    if (!raw) return null;
    const b64 = await resolveImageToBase64(raw);
    if (!b64) return { error: '場景參考圖無法讀取，請重新上傳' };
    return {
        base64: b64,
        mime: mimeFromPromoImageRef(raw),
        url: (typeof raw === 'string' && /^https?:\/\//i.test(raw)) ? raw : null
    };
}

/** 空間 layout_plan：平面圖 + 選填風格圖 */
async function resolvePromoSpaceLayoutReferences(body) {
    const b = body && typeof body === 'object' ? body : {};
    const styleSource = b.space_style_source === 'image' ? 'image' : 'prompt';
    const floorRaw = b.floor_plan
        || (Array.isArray(b.images) && b.images[0])
        || b.image;
    if (!floorRaw) return { error: '請上傳平面配置圖' };
    const floorB64 = await resolveImageToBase64(floorRaw);
    if (!floorB64) return { error: '平面配置圖無法讀取，請重新上傳' };

    let styleImage = null;
    if (styleSource === 'image') {
        const styleRaw = b.style_image;
        if (!styleRaw) return { error: '請上傳風格參考圖' };
        const styleB64 = await resolveImageToBase64(styleRaw);
        if (!styleB64) return { error: '風格參考圖無法讀取，請重新上傳' };
        styleImage = { base64: styleB64, mime: mimeFromPromoImageRef(styleRaw) };
    }

    const styleText = styleSource === 'prompt' ? String(b.user_prompt || b.prompt || '').trim() : '';
    if (styleSource === 'prompt' && !styleText) {
        return { error: '請填寫風格描述（例：莫蘭迪配色）' };
    }

    const supplement = styleSource === 'image' ? String(b.user_prompt || b.prompt || '').trim() : '';

    let stagingProduct = null;
    const prodResolved = await resolvePromoStagingProductImage(b);
    if (prodResolved && prodResolved.error) return { error: prodResolved.error };
    if (prodResolved && prodResolved.base64) stagingProduct = prodResolved;

    return {
        floorPlan: { base64: floorB64, mime: mimeFromPromoImageRef(floorRaw) },
        styleImage,
        stagingProduct,
        styleSource,
        styleText,
        supplement,
        floorUrl: (typeof floorRaw === 'string' && /^https?:\/\//i.test(floorRaw)) ? floorRaw : null
    };
}

