// PATCH /api/admin/ai-config — 儲存 AI 模型設定（僅管理員）
app.patch('/api/admin/ai-config', express.json(), async (req, res) => {
    try {
        const adminUser = await requireAdmin(req, res);
        if (!adminUser) return;
        const body = req.body || {};
        const now = new Date().toISOString();
        const upserts = [];
        if (body.gemini_model !== undefined) {
            upserts.push({ key: 'gemini_model', value: String(body.gemini_model).trim(), updated_at: now });
        }
        if (body.gemini_model_read !== undefined) {
            upserts.push({ key: 'gemini_model_read', value: String(body.gemini_model_read).trim(), updated_at: now });
        }
        if (body.gemini_model_tagging !== undefined) {
            upserts.push({ key: 'gemini_model_tagging', value: String(body.gemini_model_tagging).trim(), updated_at: now });
        }
        if (body.gemini_model_material_optimize !== undefined) {
            upserts.push({ key: 'gemini_model_material_optimize', value: String(body.gemini_model_material_optimize).trim(), updated_at: now });
        }
        if (body.gemini_model_material_combo_lite !== undefined) {
            upserts.push({ key: 'gemini_model_material_combo_lite', value: String(body.gemini_model_material_combo_lite).trim(), updated_at: now });
        }
        if (body.gemini_model_material_combo_flash !== undefined) {
            upserts.push({ key: 'gemini_model_material_combo_flash', value: String(body.gemini_model_material_combo_flash).trim(), updated_at: now });
        }
        if (body.gemini_model_print_asset !== undefined) {
            upserts.push({ key: 'gemini_model_print_asset', value: String(body.gemini_model_print_asset).trim(), updated_at: now });
        }
        if (body.gemini_model_pattern_extract !== undefined) {
            upserts.push({ key: 'gemini_model_pattern_extract', value: String(body.gemini_model_pattern_extract).trim(), updated_at: now });
        }
        if (body.gemini_model_promo_space_layout !== undefined) {
            upserts.push({ key: 'gemini_model_promo_space_layout', value: String(body.gemini_model_promo_space_layout).trim(), updated_at: now });
        }
        if (body.gemini_model_promo_space_eye_level !== undefined) {
            upserts.push({ key: 'gemini_model_promo_space_eye_level', value: String(body.gemini_model_promo_space_eye_level).trim(), updated_at: now });
        }
        if (body.gemini_model_promo_portrait !== undefined) {
            upserts.push({ key: 'gemini_model_promo_portrait', value: String(body.gemini_model_promo_portrait).trim(), updated_at: now });
        }
        const engineFields = [
            'vendor_asset_optimize_engine',
            'material_dual_color_engine',
            'print_asset_engine',
            'pattern_extract_engine',
            'promo_space_eye_level_engine',
            'promo_portrait_engine'
        ];
        for (const key of engineFields) {
            if (body[key] === undefined) continue;
            const raw = String(body[key]).trim().toLowerCase();
            if (raw !== 'auto' && raw !== 'gemini' && raw !== 'flux') {
                return res.status(400).json({
                    error: '引擎偏好無效：' + key,
                    hint: '請選 auto、gemini 或 flux'
                });
            }
            upserts.push({ key, value: raw, updated_at: now });
        }
        for (const key of Object.keys(BFL_FLUX_MODEL_CONFIG)) {
            if (body[key] === undefined) continue;
            const raw = String(body[key]).trim();
            if (!isPlausibleBflFluxModelId(raw)) {
                return res.status(400).json({
                    error: 'FLUX 模型 ID 格式無效：' + key,
                    hint: '請填 BFL API model id，例如 flux-2-pro、flux-2-max、flux-2-pro-preview'
                });
            }
            upserts.push({ key, value: raw, updated_at: now });
        }
        if (upserts.length === 0) {
            return res.status(400).json({ error: '無可儲存的欄位' });
        }
        const { error } = await supabase.from('payment_config').upsert(upserts, { onConflict: 'key' });
        if (error) {
            console.error('PATCH /api/admin/ai-config upsert:', error);
            return res.status(500).json({
                error: error.message || '寫入 payment_config 失敗',
                hint: error.code === '42P01' ? '請在 Supabase 執行 docs/payment-config-schema.sql' : undefined
            });
        }
        const keys = [...new Set(upserts.map((u) => u.key))];
        const { data: rows, error: readErr } = await supabase.from('payment_config').select('key, value').in('key', keys);
        if (readErr) {
            return res.status(500).json({ error: readErr.message || '儲存後讀取失敗' });
        }
        const byKey = (rows || []).reduce((o, r) => { o[r.key] = r.value?.trim?.(); return o; }, {});
        const bfl = resolveBflFluxModelsFromRows(rows);
        res.json({
            success: true,
            gemini_model: byKey.gemini_model ?? null,
            gemini_model_read: byKey.gemini_model_read ?? null,
            gemini_model_tagging: byKey.gemini_model_tagging ?? null,
            gemini_model_material_optimize: byKey.gemini_model_material_optimize ?? null,
            gemini_model_material_combo_lite: byKey.gemini_model_material_combo_lite ?? null,
            gemini_model_material_combo_flash: byKey.gemini_model_material_combo_flash ?? null,
            gemini_model_print_asset: byKey.gemini_model_print_asset ?? null,
            gemini_model_pattern_extract: byKey.gemini_model_pattern_extract ?? null,
            gemini_model_promo_space_layout: byKey.gemini_model_promo_space_layout ?? null,
            gemini_model_promo_space_eye_level: byKey.gemini_model_promo_space_eye_level ?? null,
            gemini_model_promo_portrait: byKey.gemini_model_promo_portrait ?? null,
            vendor_asset_optimize_engine: byKey.vendor_asset_optimize_engine
                ? normalizeOptimizeEnginePref(byKey.vendor_asset_optimize_engine)
                : null,
            material_dual_color_engine: byKey.material_dual_color_engine
                ? normalizeOptimizeEnginePref(byKey.material_dual_color_engine)
                : null,
            print_asset_engine: byKey.print_asset_engine
                ? normalizeOptimizeEnginePref(byKey.print_asset_engine)
                : null,
            pattern_extract_engine: byKey.pattern_extract_engine
                ? normalizeOptimizeEnginePref(byKey.pattern_extract_engine)
                : null,
            promo_space_eye_level_engine: byKey.promo_space_eye_level_engine
                ? normalizeOptimizeEnginePref(byKey.promo_space_eye_level_engine)
                : null,
            promo_portrait_engine: byKey.promo_portrait_engine
                ? normalizeOptimizeEnginePref(byKey.promo_portrait_engine)
                : null,
            ...bfl.models
        });
    } catch (e) {
        console.error('PATCH /api/admin/ai-config:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

