/**
 * POST /api/admin/backfill-custom-product-tags
 * 管理員手動補跑缺標設計圖（一次一批，不掛公開頁）。
 * body: { limit?: number } 預設 10、上限 20
 */
app.post('/api/admin/backfill-custom-product-tags', express.json(), async (req, res) => {
    try {
        const adminUser = await requireAdmin(req, res);
        if (!adminUser) return;
        if (!process.env.GEMINI_API_KEY) {
            return res.status(503).json({ error: '未設定 GEMINI_API_KEY' });
        }
        const limit = Math.min(Math.max(parseInt((req.body && req.body.limit), 10) || 10, 1), 20);
        let q = supabase
            .from('custom_products')
            .select('id, owner_id, title, category, generation_prompt, ai_generated_image_url, ai_tags, semantics_generated_at')
            .not('ai_generated_image_url', 'is', null)
            .order('created_at', { ascending: false })
            .limit(200);
        let { data: rows, error } = await q;
        if (error && error.code === '42703') {
            ({ data: rows, error } = await supabase
                .from('custom_products')
                .select('id, owner_id, title, category, generation_prompt, ai_generated_image_url, ai_tags')
                .not('ai_generated_image_url', 'is', null)
                .order('created_at', { ascending: false })
                .limit(200));
        }
        if (error) {
            console.error('admin backfill-custom-product-tags query:', error.message);
            return res.status(500).json({ error: error.message || '查詢失敗' });
        }
        const pending = (rows || []).filter(function (row) {
            if (!row || !row.id || !row.ai_generated_image_url) return false;
            if (String(row.ai_generated_image_url).indexOf('data:') === 0) return false;
            if (row.semantics_generated_at) return false;
            return !(Array.isArray(row.ai_tags) && row.ai_tags.length > 0);
        }).slice(0, limit);

        const results = [];
        for (let i = 0; i < pending.length; i++) {
            const row = pending[i];
            try {
                const out = await enrichCustomProductSemantics(row.id, row.owner_id, {
                    imageUrl: row.ai_generated_image_url,
                    generationPrompt: row.generation_prompt || null,
                    title: row.title || null,
                    categoryKey: row.category || null
                });
                results.push({
                    id: row.id,
                    ok: !!(out && Array.isArray(out.ai_tags) && out.ai_tags.length),
                    tags: out && out.ai_tags ? out.ai_tags.length : 0
                });
            } catch (e) {
                results.push({ id: row.id, ok: false, error: (e && e.message) || '失敗' });
            }
        }
        const okCount = results.filter((r) => r.ok).length;
        console.log('admin backfill-custom-product-tags done=%d/%d by=%s', okCount, results.length, adminUser.id);
        res.json({
            success: true,
            requested: limit,
            processed: results.length,
            ok: okCount,
            failed: results.length - okCount,
            items: results
        });
    } catch (e) {
        console.error('POST /api/admin/backfill-custom-product-tags:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// GET /api/admin/semantics-prompts — 視覺語意／標籤用 Gemini 系統提示詞（僅管理員）
app.get('/api/admin/semantics-prompts', async (req, res) => {
    try {
        const adminUser = await requireAdmin(req, res);
        if (!adminUser) return;
        const keys = visualSemantics.SEMANTICS_PROMPT_KEYS;
        const defaults = visualSemantics.DEFAULT_PROMPTS;
        const { data: rows, error } = await supabase.from('payment_config').select('key, value').in('key', keys);
        if (error) {
            if (error.code === '42P01') {
                return res.status(500).json({ error: '請先執行 docs/payment-config-schema.sql 建立 payment_config 表' });
            }
            return res.status(500).json({ error: error.message || '查詢失敗' });
        }
        const byKey = (rows || []).reduce((o, r) => { o[r.key] = r.value != null ? String(r.value) : ''; return o; }, {});
        const saved_in_db = {};
        const out = {};
        keys.forEach((k) => {
            const dbVal = (byKey[k] || '').trim();
            saved_in_db[k] = !!dbVal;
            out[k] = dbVal || defaults[k] || '';
        });
        res.json({ ...out, defaults, saved_in_db });
    } catch (e) {
        console.error('GET /api/admin/semantics-prompts:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/admin/semantics-prompts — 儲存視覺語意系統提示詞（僅管理員）
app.patch('/api/admin/semantics-prompts', express.json(), async (req, res) => {
    try {
        const adminUser = await requireAdmin(req, res);
        if (!adminUser) return;
        const body = req.body || {};
        const keys = visualSemantics.SEMANTICS_PROMPT_KEYS;
        const now = new Date().toISOString();
        const upserts = [];
        keys.forEach((k) => {
            if (body[k] !== undefined) {
                upserts.push({ key: k, value: String(body[k]).trim(), updated_at: now });
            }
        });
        if (upserts.length === 0) {
            return res.status(400).json({ error: '無可儲存的提示詞欄位' });
        }
        const { error } = await supabase.from('payment_config').upsert(upserts, { onConflict: 'key' });
        if (error) {
            console.error('PATCH /api/admin/semantics-prompts:', error);
            return res.status(500).json({
                error: error.message || '寫入失敗',
                hint: error.code === '42P01' ? '請先執行 docs/payment-config-schema.sql' : undefined
            });
        }
        res.json({ success: true, saved: upserts.map((u) => u.key) });
    } catch (e) {
        console.error('PATCH /api/admin/semantics-prompts:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

