// POST /api/payment/notify — 綠界付款結果回調（表單 application/x-www-form-urlencoded）
app.post('/api/payment/notify', express.urlencoded({ extended: true }), async (req, res) => {
    try {
        const body = req.body || {};
        const receivedMac = body.CheckMacValue;
        if (!receivedMac) {
            return res.status(400).send('0|缺少 CheckMacValue');
        }
        const config = await getPaymentConfig();
        const ecpay = config.ecpay;
        if (!ecpay.hashKey || !ecpay.hashIV) {
            return res.status(500).send('0|設定錯誤');
        }
        const computed = ecpayCheckMacValue(body, ecpay.hashKey, ecpay.hashIV);
        if (computed !== receivedMac) {
            console.error('ECPay CheckMacValue 驗證失敗');
            return res.status(400).send('0|CheckMacValue 錯誤');
        }
        const orderId = body.MerchantTradeNo;
        const rtnCode = parseInt(body.RtnCode, 10);
        // 付款失敗：僅更新訂單為 failed，不入點、不建立訂閱
        if (rtnCode !== 1) {
            await supabase.from('payment_orders').update({
                status: 'failed',
                raw_callback: body
            }).eq('order_id', orderId);
            return res.send('1|OK');
        }
        const { data: order, error: ordErr } = await supabase
            .from('payment_orders')
            .select('id, user_id, credits_to_grant, status, order_type, metadata')
            .eq('order_id', orderId)
            .single();
        if (ordErr || !order) {
            console.error('payment_orders select:', ordErr);
            return res.send('1|OK');
        }
        if (order.status === 'paid') {
            return res.send('1|OK');
        }
        // 以下僅在「付款成功」時執行：更新訂單為 paid，再依條件入點／建立年付訂閱
        const paidAt = new Date().toISOString();
        await supabase.from('payment_orders').update({
            status: 'paid',
            external_id: body.TradeNo,
            raw_callback: body,
            paid_at: paidAt
        }).eq('order_id', orderId);
        if (body.SimulatePaid === '1') {
            return res.send('1|OK');
        }
        // 非模擬付款：入點（點數僅在實際付款成功後更新）
        const credits = order.credits_to_grant;
        const { data: cred } = await supabase.from('user_credits').select('balance, total_earned, total_spent').eq('user_id', order.user_id).maybeSingle();
        const balanceBefore = (cred && cred.balance) ? cred.balance : 0;
        const balanceAfter = balanceBefore + credits;
        const totalEarned = (cred && cred.total_earned) ? cred.total_earned + credits : credits;
        const totalSpent = cred ? (cred.total_spent || 0) : 0;
        if (cred) {
            await supabase.from('user_credits').update({
                balance: balanceAfter,
                total_earned: totalEarned,
                updated_at: paidAt
            }).eq('user_id', order.user_id);
        } else {
            await supabase.from('user_credits').insert({
                user_id: order.user_id,
                balance: balanceAfter,
                total_earned: totalEarned,
                total_spent: 0,
                updated_at: paidAt
            });
        }
        await supabase.from('credit_transactions').insert({
            user_id: order.user_id,
            type: 'purchase',
            amount: credits,
            balance_after: balanceAfter,
            source: 'purchase',
            description: order.order_type === 'subscription' ? '綠界月訂閱' : '綠界儲值',
            metadata: { order_id: orderId, provider: 'ecpay' }
        });
        if (order.order_type === 'subscription') {
            await fulfillSubscriptionAfterPayment(order, { mode: 'new' });
        } else if (order.order_type === 'yearly') {
            await fulfillSubscriptionAfterPayment(order, { mode: 'new' });
        }
        res.send('1|OK');
    } catch (e) {
        console.error('POST /api/payment/notify 異常:', e);
        res.status(500).send('0|Exception');
    }
});

// POST /api/payment/notify-period — 綠界定期定額每期扣款結果（PeriodReturnURL，見 5631）
app.post('/api/payment/notify-period', express.urlencoded({ extended: true }), async (req, res) => {
    try {
        const body = req.body || {};
        const receivedMac = body.CheckMacValue;
        if (!receivedMac) return res.status(400).send('0|缺少 CheckMacValue');
        const config = await getPaymentConfig();
        const ecpay = config.ecpay;
        if (!ecpay.hashKey || !ecpay.hashIV) return res.status(500).send('0|設定錯誤');
        const computed = ecpayCheckMacValue(body, ecpay.hashKey, ecpay.hashIV);
        if (computed !== receivedMac) {
            console.error('ECPay notify-period CheckMacValue 驗證失敗');
            return res.status(400).send('0|CheckMacValue 錯誤');
        }
        const rtnCode = parseInt(body.RtnCode, 10);
        // 該期失敗或模擬付款：不入點（定期定額失敗時綠界不撥款，該期不發點數）
        if (rtnCode !== 1) return res.send('1|OK');
        if (body.SimulatePaid === '1') return res.send('1|OK');
        const orderId = body.MerchantTradeNo;
        const periodIndex = String(body.TotalSuccessTimes || body.total_success_times || '');
        const { data: order, error: ordErr } = await supabase
            .from('payment_orders')
            .select('id, user_id, credits_to_grant, order_type, metadata')
            .eq('order_id', orderId)
            .single();
        if (ordErr || !order || order.order_type !== 'subscription') return res.send('1|OK');
        const { data: existing } = await supabase
            .from('credit_transactions')
            .select('id')
            .eq('user_id', order.user_id)
            .contains('metadata', { order_id: orderId, period_index: periodIndex })
            .limit(1)
            .maybeSingle();
        if (existing) return res.send('1|OK');
        const credits = order.credits_to_grant;
        const paidAt = new Date().toISOString();
        const { data: cred } = await supabase.from('user_credits').select('balance, total_earned').eq('user_id', order.user_id).maybeSingle();
        const balanceBefore = (cred && cred.balance) ? cred.balance : 0;
        const balanceAfter = balanceBefore + credits;
        const totalEarned = (cred && cred.total_earned) ? cred.total_earned + credits : credits;
        if (cred) {
            await supabase.from('user_credits').update({
                balance: balanceAfter,
                total_earned: totalEarned,
                updated_at: paidAt
            }).eq('user_id', order.user_id);
        } else {
            await supabase.from('user_credits').insert({
                user_id: order.user_id,
                balance: balanceAfter,
                total_earned: totalEarned,
                total_spent: 0,
                updated_at: paidAt
            });
        }
        await supabase.from('credit_transactions').insert({
            user_id: order.user_id,
            type: 'purchase',
            amount: credits,
            balance_after: balanceAfter,
            source: 'purchase',
            description: '綠界月訂閱（定期扣款）',
            metadata: { order_id: orderId, provider: 'ecpay', period_index: periodIndex }
        });
        await fulfillSubscriptionAfterPayment(order, { mode: 'extend' });
        res.send('1|OK');
    } catch (e) {
        console.error('POST /api/payment/notify-period 異常:', e);
        res.status(500).send('0|Exception');
    }
});

// PayPal 金流：依 getPaymentConfig() 動態建立 client（後台或 .env 設定）
function getPayPalClient(paypalConfig) {
    if (!paypalConfig || !paypalConfig.clientId || !paypalConfig.clientSecret) return null;
    try {
        const paypal = require('@paypal/checkout-server-sdk');
        const env = paypalConfig.sandbox
            ? new paypal.core.SandboxEnvironment(paypalConfig.clientId, paypalConfig.clientSecret)
            : new paypal.core.LiveEnvironment(paypalConfig.clientId, paypalConfig.clientSecret);
        return new paypal.core.PayPalHttpClient(env);
    } catch (_) {
        return null;
    }
}

// POST /api/payment/paypal/create — 建立 PayPal 訂單，回傳 approval_url
app.post('/api/payment/paypal/create', express.json(), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const config = await getPaymentConfig();
        const paypalClient = getPayPalClient(config.paypal);
        if (!paypalClient) {
            return res.status(503).json({
                error: 'PayPal 金流尚未設定',
                hint: '請至後台「金流設定」或 .env 填寫 PAYPAL_CLIENT_ID、PAYPAL_CLIENT_SECRET。測試用 Sandbox 帳號：' + PAYPAL_DEV_DOC
            });
        }
        const body = req.body || {};
        const amount = Math.abs(parseFloat(body.amount) || 0);
        const credits = Math.abs(parseInt(body.credits, 10) || 0);
        if (amount <= 0 || credits <= 0) return res.status(400).json({ error: '請填寫金額與點數' });
        const billing = (body.billing || '').toLowerCase();
        const planKey = body.plan && String(body.plan).trim() ? String(body.plan).trim() : null;
        const isYearly = billing === 'yearly' && planKey;
        if (isYearly && config.paypal && config.paypal.clientId && config.paypal.clientSecret) {
            await cancelUserPayPalSubscriptionsBeforeNewPlan(user.id, config.paypal, {
                reason: 'User switched to yearly plan'
            });
        }
        const orderId = 'PP' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
        const insertPayload = {
            order_id: orderId,
            user_id: user.id,
            provider: 'paypal',
            amount: Math.round(amount),
            currency: 'USD',
            credits_to_grant: credits,
            status: 'pending'
        };
        if (isYearly) {
            insertPayload.order_type = 'yearly';
            insertPayload.metadata = { plan_key: planKey };
        }
        const { error: orderErr } = await supabase.from('payment_orders').insert(insertPayload);
        if (orderErr) {
            console.error('payment_orders insert:', orderErr);
            return res.status(500).json({ error: '建立訂單失敗' });
        }
        const paypal = require('@paypal/checkout-server-sdk');
        const baseUrl = (process.env.BASE_URL || BASE_URL || '').replace(/\/$/, '') || ('http://localhost:' + (process.env.PORT || 3000));
        const request = new paypal.orders.OrdersCreateRequest();
        request.prefer('return=representation');
        request.requestBody({
            intent: 'CAPTURE',
            purchase_units: [{
                reference_id: orderId,
                amount: { currency_code: 'USD', value: amount.toFixed(2) },
                description: credits + ' credits'
            }],
            application_context: {
                return_url: baseUrl + '/payment/return.html?provider=paypal&order_id=' + encodeURIComponent(orderId),
                cancel_url: baseUrl + '/payment/return.html?provider=paypal&cancel=1'
            }
        });
        const response = await paypalClient.execute(request);
        const approvalUrl = response.result.links && response.result.links.find(l => l.rel === 'approve');
        if (!approvalUrl || !approvalUrl.href) {
            return res.status(500).json({ error: '無法取得 PayPal 付款連結' });
        }
        await supabase.from('payment_orders').update({ external_id: response.result.id }).eq('order_id', orderId);
        res.json({ approval_url: approvalUrl.href, order_id: orderId });
    } catch (e) {
        console.error('POST /api/payment/paypal/create 異常:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// POST /api/payment/paypal/capture — 用戶從 PayPal 返回後帶 token 來完成請款並入點
app.post('/api/payment/paypal/capture', express.json(), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const token = (req.body || {}).token || req.query.token;
        if (!token) return res.status(400).json({ error: '缺少 token' });
        const config = await getPaymentConfig();
        const paypalClient = getPayPalClient(config.paypal);
        if (!paypalClient) return res.status(503).json({ error: 'PayPal 金流尚未設定' });
        const paypal = require('@paypal/checkout-server-sdk');
        const request = new paypal.orders.OrdersCaptureRequest(token);
        request.requestBody({});
        const response = await paypalClient.execute(request);
        const paypalOrderId = response.result.id;
        const refId = (response.result.purchase_units && response.result.purchase_units[0] && response.result.purchase_units[0].reference_id) || '';
        const { data: order, error: ordErr } = await supabase
            .from('payment_orders')
            .select('id, user_id, credits_to_grant, status, order_type, metadata')
            .eq('external_id', paypalOrderId)
            .eq('provider', 'paypal')
            .single();
        if (ordErr || !order || order.user_id !== user.id) {
            return res.status(404).json({ error: '找不到對應訂單' });
        }
        if (order.status === 'paid') {
            const { data: c } = await supabase.from('user_credits').select('balance').eq('user_id', user.id).maybeSingle();
            return res.json({ success: true, balance_after: (c && c.balance) ? c.balance : 0 });
        }
        const credits = order.credits_to_grant;
        const paidAt = new Date().toISOString();
        await supabase.from('payment_orders').update({ status: 'paid', paid_at: paidAt }).eq('id', order.id);
        const { data: cred } = await supabase.from('user_credits').select('balance, total_earned, total_spent').eq('user_id', user.id).maybeSingle();
        const balanceBefore = (cred && cred.balance) ? cred.balance : 0;
        const balanceAfter = balanceBefore + credits;
        const totalEarned = (cred && cred.total_earned) ? cred.total_earned + credits : credits;
        if (cred) {
            await supabase.from('user_credits').update({
                balance: balanceAfter,
                total_earned: totalEarned,
                updated_at: paidAt
            }).eq('user_id', user.id);
        } else {
            await supabase.from('user_credits').insert({
                user_id: user.id,
                balance: balanceAfter,
                total_earned: totalEarned,
                total_spent: 0,
                updated_at: paidAt
            });
        }
        await supabase.from('credit_transactions').insert({
            user_id: user.id,
            type: 'purchase',
            amount: credits,
            balance_after: balanceAfter,
            source: 'purchase',
            description: 'PayPal 儲值',
            metadata: { order_id: refId, provider: 'paypal' }
        });
        if (order.order_type === 'yearly') {
            await fulfillSubscriptionAfterPayment(order, { mode: 'new' });
        }
        res.json({ success: true, balance_after: balanceAfter });
    } catch (e) {
        console.error('POST /api/payment/paypal/capture 異常:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

async function processPayPalSubscriptionPayment(order, opts) {
    if (!order || !order.user_id) return { ok: false, reason: 'invalid_order' };
    opts = opts || {};
    const periodIndex = opts.periodIndex != null ? String(opts.periodIndex) : '1';
    const grant = await paypalSubscriptionFulfill.grantPayPalCredits(supabase, order, {
        order_id: order.order_id,
        period_index: periodIndex,
        sale_id: opts.saleId || '',
        subscription_id: opts.subscriptionId || order.external_id || null
    });
    if (!grant.ok) return grant;
    if (grant.duplicate) return grant;
    const paidAt = new Date().toISOString();
    if (order.status !== 'paid') {
        await supabase.from('payment_orders').update({ status: 'paid', paid_at: paidAt }).eq('id', order.id);
    }
    const subMode = periodIndex === '1' ? 'new' : 'extend';
    await fulfillSubscriptionAfterPayment(order, { mode: subMode, autoRenew: true });
    return grant;
}

/** 換方案前取消使用者既有 PayPal 月訂（防雙重扣款） */
async function cancelUserPayPalSubscriptionsBeforeNewPlan(userId, paypalCfg, options) {
    if (!userId || !paypalCfg) return [];
    options = options || {};
    const reason = options.reason || 'User switched subscription plan';
    const { data: rows, error } = await supabase
        .from('payment_orders')
        .select('id, order_id, external_id, status, metadata')
        .eq('user_id', userId)
        .eq('provider', 'paypal')
        .eq('order_type', 'subscription')
        .not('external_id', 'is', null)
        .order('created_at', { ascending: false });
    if (error) {
        console.error('cancelUserPayPalSubscriptionsBeforeNewPlan select:', error);
        return [];
    }
    const seen = new Set();
    const cancelled = [];
    for (const row of (rows || [])) {
        const subId = String(row.external_id || '').trim();
        if (!subId || seen.has(subId)) continue;
        seen.add(subId);
        let sub;
        try {
            sub = await paypalRest.getPayPalSubscription(paypalCfg, subId);
        } catch (e) {
            console.warn('PayPal get subscription skipped:', subId, e.message);
            continue;
        }
        const status = String(sub.status || '').toUpperCase();
        if (paypalRest.isPayPalSubscriptionTerminalStatus(status)) continue;
        if (!paypalRest.isPayPalSubscriptionMustCancelStatus(status)) continue;
        try {
            await paypalRest.cancelPayPalSubscription(paypalCfg, subId, reason);
            cancelled.push(subId);
            const prevMeta = parsePaymentOrderMetadata(row.metadata);
            await supabase.from('payment_orders').update({
                metadata: Object.assign({}, prevMeta, {
                    paypal_subscription_cancelled_at: new Date().toISOString(),
                    paypal_cancel_reason: reason
                })
            }).eq('external_id', subId).eq('user_id', userId);
        } catch (e) {
            const errMsg = (e && e.message) || String(e);
            const alreadyDone = /cancelled|canceled|invalid.*status/i.test(errMsg);
            if (paypalRest.isPayPalSubscriptionMustCancelStatus(status) && !alreadyDone) {
                console.error('PayPal cancel failed:', subId, status, errMsg);
                throw new Error('無法取消既有 PayPal 訂閱，請至 PayPal 帳戶取消後再試，或聯絡客服。');
            }
            console.warn('PayPal cancel skipped:', subId, status, errMsg);
        }
    }
    if (cancelled.length > 0) {
        await supabase
            .from('user_subscriptions')
            .update({ auto_renew: false })
            .eq('user_id', userId)
            .eq('status', 'active');
    }
    return cancelled;
}

// POST /api/payment/paypal/create-subscription — PayPal Billing Subscription（月訂）
app.post('/api/payment/paypal/create-subscription', express.json(), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const config = await getPaymentConfig();
        const paypalCfg = config.paypal;
        if (!paypalCfg.clientId || !paypalCfg.clientSecret) {
            return res.status(503).json({
                error: 'PayPal 金流尚未設定',
                hint: '請至後台「金流設定」填寫 PayPal Client ID / Secret。'
            });
        }
        const body = req.body || {};
        const amount = Math.abs(parseFloat(body.amount) || 0);
        const credits = Math.abs(parseInt(body.credits, 10) || 0);
        const planKey = body.plan && String(body.plan).trim() ? String(body.plan).trim() : null;
        if (amount <= 0 || credits <= 0 || !planKey) {
            return res.status(400).json({ error: '請填寫月付金額、點數與方案' });
        }
        await cancelUserPayPalSubscriptionsBeforeNewPlan(user.id, paypalCfg, {
            reason: 'User switched to a new monthly plan'
        });
        const orderId = 'PPS' + Date.now() + '-' + Math.random().toString(36).slice(2, 10);
        const insertPayload = {
            order_id: orderId,
            user_id: user.id,
            provider: 'paypal',
            amount: Math.round(amount * 100) / 100,
            currency: 'USD',
            credits_to_grant: credits,
            status: 'pending',
            order_type: 'subscription',
            metadata: { plan_key: planKey, billing: 'monthly' }
        };
        const { error: orderErr } = await supabase.from('payment_orders').insert(insertPayload);
        if (orderErr) {
            console.error('payment_orders insert paypal subscription:', orderErr);
            return res.status(500).json({ error: '建立訂閱訂單失敗' });
        }
        const billingPlanId = await paypalRest.ensurePayPalBillingPlan(
            paypalCfg,
            { planKey: planKey, billing: 'monthly', amountUsd: amount },
            getPaymentConfigValue,
            setPaymentConfigValue
        );
        const baseUrl = (process.env.BASE_URL || BASE_URL || '').replace(/\/$/, '') || ('http://localhost:' + (process.env.PORT || 3000));
        const subscription = await paypalRest.createPayPalSubscription(paypalCfg, {
            planId: billingPlanId,
            customId: orderId,
            returnUrl: baseUrl + '/payment/return.html?provider=paypal&subscription=1',
            cancelUrl: baseUrl + '/payment/return.html?provider=paypal&cancel=1'
        });
        const approvalUrl = paypalRest.extractPayPalApprovalUrl(subscription);
        if (!approvalUrl || !subscription.id) {
            return res.status(500).json({ error: '無法取得 PayPal 訂閱核准連結' });
        }
        await supabase.from('payment_orders').update({ external_id: subscription.id }).eq('order_id', orderId);
        res.json({ approval_url: approvalUrl, order_id: orderId, subscription_id: subscription.id });
    } catch (e) {
        console.error('POST /api/payment/paypal/create-subscription 異常:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// POST /api/payment/paypal/subscription-complete — 用戶核准訂閱後啟用（首扣入點）
app.post('/api/payment/paypal/subscription-complete', express.json(), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const subscriptionId = String((req.body && req.body.subscription_id) || (req.body && req.body.subscriptionId) || '').trim();
        if (!subscriptionId) return res.status(400).json({ error: '缺少 subscription_id' });
        const config = await getPaymentConfig();
        const paypalCfg = config.paypal;
        const sub = await paypalRest.getPayPalSubscription(paypalCfg, subscriptionId);
        const status = String(sub.status || '').toUpperCase();
        if (status !== 'ACTIVE' && status !== 'APPROVED') {
            return res.status(400).json({ error: '訂閱尚未啟用（' + (sub.status || '') + '）' });
        }
        const customId = String(sub.custom_id || '').trim();
        const { data: order, error: ordErr } = await supabase
            .from('payment_orders')
            .select('id, order_id, user_id, credits_to_grant, status, order_type, metadata, external_id')
            .eq('order_id', customId)
            .eq('provider', 'paypal')
            .maybeSingle();
        if (ordErr || !order || order.user_id !== user.id) {
            return res.status(404).json({ error: '找不到對應訂閱訂單' });
        }
        if (!order.external_id) {
            await supabase.from('payment_orders').update({ external_id: subscriptionId }).eq('id', order.id);
        }
        const grant = await processPayPalSubscriptionPayment(order, {
            subscriptionId: subscriptionId,
            periodIndex: '1'
        });
        const { data: c } = await supabase.from('user_credits').select('balance').eq('user_id', user.id).maybeSingle();
        res.json({
            success: true,
            duplicate: !!grant.duplicate,
            balance_after: grant.balance_after != null ? grant.balance_after : ((c && c.balance) || 0)
        });
    } catch (e) {
        console.error('POST /api/payment/paypal/subscription-complete 異常:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// POST /api/payment/paypal/webhook — PayPal 訂閱／扣款事件
app.post('/api/payment/paypal/webhook', express.json(), async (req, res) => {
    try {
        const event = req.body || {};
        const eventType = String(event.event_type || '').trim();
        const resource = event.resource || {};
        if (eventType === 'PAYMENT.SALE.COMPLETED') {
            const subscriptionId = resource.billing_agreement_id || resource.billing_agreement || resource.subscription_id || '';
            const saleId = resource.id || '';
            if (subscriptionId) {
                const { data: order } = await supabase
                    .from('payment_orders')
                    .select('id, order_id, user_id, credits_to_grant, status, order_type, metadata, external_id')
                    .eq('external_id', subscriptionId)
                    .eq('provider', 'paypal')
                    .eq('order_type', 'subscription')
                    .maybeSingle();
                if (order) {
                    const periodIndex = saleId || String(Date.now());
                    await processPayPalSubscriptionPayment(order, {
                        subscriptionId: subscriptionId,
                        periodIndex: periodIndex,
                        saleId: saleId
                    });
                }
            }
        } else if (eventType === 'BILLING.SUBSCRIPTION.ACTIVATED') {
            const subscriptionId = resource.id || '';
            const customId = String(resource.custom_id || '').trim();
            if (subscriptionId && customId) {
                const { data: order } = await supabase
                    .from('payment_orders')
                    .select('id, order_id, user_id, credits_to_grant, status, order_type, metadata, external_id')
                    .eq('order_id', customId)
                    .maybeSingle();
                if (order) {
                    if (!order.external_id) {
                        await supabase.from('payment_orders').update({ external_id: subscriptionId }).eq('id', order.id);
                    }
                    await processPayPalSubscriptionPayment(order, {
                        subscriptionId: subscriptionId,
                        periodIndex: '1'
                    });
                }
            }
        }
        res.sendStatus(200);
    } catch (e) {
        console.error('POST /api/payment/paypal/webhook 異常:', e);
        res.sendStatus(500);
    }
});

// 小圖示：在 static 之前註冊，避免雲端/快取導致不顯示
const imgDir = path.join(__dirname, 'public', 'img');
function sendIcon(req, res, filename) {
    const filePath = path.join(imgDir, filename);
    if (fs.existsSync(filePath)) {
        res.setHeader('Cache-Control', 'public, max-age=86400');
        return res.sendFile(filePath);
    }
    res.status(204).end();
}
