// 一鍵匯入預設分類（主分類 + 子分類獨立表）
app.post('/api/categories/seed-defaults', async (req, res) => {
    try {
        const defaultsPath = path.join(__dirname, 'public', 'config', 'ai-categories.defaults.json');
        if (!fs.existsSync(defaultsPath)) {
            return res.status(404).json({ error: '找不到預設分類檔' });
        }
        const raw = JSON.parse(fs.readFileSync(defaultsPath, 'utf-8'));
        const list = raw.categories || [];
        if (!list.length) return res.status(400).json({ error: '預設檔無有效資料' });
        const mainPayload = list.map(c => ({ key: c.key, name: c.name, prompt: c.prompt || '' }));
        const { error: mainErr } = await supabase.from('ai_categories').upsert(mainPayload, { onConflict: 'key' });
        if (mainErr) return res.status(500).json({ error: mainErr.message });
        let subCount = 0;
        for (const c of list) {
            const subs = Array.isArray(c.sub) ? c.sub : [];
            for (let i = 0; i < subs.length; i++) {
                const name = subs[i];
                const subKey = c.key + '__' + String(name).replace(/\s+/g, '_').slice(0, 100);
                const { error: subErr } = await supabase.from('ai_subcategories').upsert(
                    { key: subKey, name, category_key: c.key, sort_order: i },
                    { onConflict: 'key' }
                );
                if (!subErr) subCount++;
            }
        }
        res.json({ success: true, count: list.length, subCount });
    } catch (e) {
        res.status(500).json({ error: '匯入預設分類失敗' });
    }
});

// ===== 客製產品 API =====

/** BFL FLUX safety_tolerance：0 最嚴、6 最寬；NULL／未設＝2（BFL 預設） */
const FLUX_SAFETY_TOLERANCE_DEFAULT = 2;

function clampFluxSafetyTolerance(raw) {
    const n = Number(raw);
    if (!Number.isFinite(n)) return FLUX_SAFETY_TOLERANCE_DEFAULT;
    return Math.max(0, Math.min(6, Math.round(n)));
}

/** 後台輸入：空白＝null（沿用預設 2） */
function parseFluxSafetyToleranceInput(raw) {
    if (raw == null || raw === '') return null;
    return clampFluxSafetyTolerance(raw);
}

async function lookupCategoryFluxSafetyTolerance(categoryKey) {
    const ck = String(categoryKey || '').trim();
    if (!ck) return null;
    try {
        let { data, error } = await supabase
            .from('ai_categories')
            .select('flux_safety_tolerance')
            .eq('key', ck)
            .maybeSingle();
        if (isSupabaseMissingColumnError(error, 'flux_safety_tolerance')) return null;
        if (error || !data) return null;
        return parseFluxSafetyToleranceInput(data.flux_safety_tolerance);
    } catch (_) {
        return null;
    }
}

async function lookupSubcategoryFluxSafetyTolerance(subcategoryKey) {
    const sk = String(subcategoryKey || '').trim();
    if (!sk) return null;
    try {
        let { data, error } = await supabase
            .from('ai_subcategories')
            .select('flux_safety_tolerance')
            .eq('key', sk)
            .maybeSingle();
        if (isSupabaseMissingColumnError(error, 'flux_safety_tolerance')) return null;
        if (error || !data) return null;
        return parseFluxSafetyToleranceInput(data.flux_safety_tolerance);
    } catch (_) {
        return null;
    }
}

async function lookupPromoTemplateFluxSafetyTolerance(templateKey) {
    const key = String(templateKey || '').trim();
    if (!key) return null;
    try {
        let { data, error } = await supabase
            .from('promo_scene_templates')
            .select('flux_safety_tolerance')
            .eq('key', key)
            .maybeSingle();
        if (isSupabaseMissingColumnError(error, 'flux_safety_tolerance')) return null;
        if (error || !data) return null;
        return parseFluxSafetyToleranceInput(data.flux_safety_tolerance);
    } catch (_) {
        return null;
    }
}

async function resolveFluxSafetyToleranceFromCategoryPair(categoryKey, subcategoryKey) {
    const subT = await lookupSubcategoryFluxSafetyTolerance(subcategoryKey);
    if (subT != null) return subT;
    const mainT = await lookupCategoryFluxSafetyTolerance(categoryKey);
    if (mainT != null) return mainT;
    return FLUX_SAFETY_TOLERANCE_DEFAULT;
}

async function resolveFluxSafetyToleranceFromCategoryKeys(categoryKeys) {
    const keys = [...new Set((categoryKeys || []).filter(Boolean).map((k) => String(k).trim()))];
    if (!keys.length) return FLUX_SAFETY_TOLERANCE_DEFAULT;
    const found = [];
    for (let i = 0; i < keys.length; i++) {
        const k = keys[i];
        let t = await lookupSubcategoryFluxSafetyTolerance(k);
        if (t == null) t = await lookupCategoryFluxSafetyTolerance(k);
        if (t != null) found.push(t);
    }
    if (!found.length) return FLUX_SAFETY_TOLERANCE_DEFAULT;
    return Math.max.apply(null, found);
}

async function resolveCategoryKeysFromPromoSource(sourceType, sourceId) {
    const sid = String(sourceId || '').trim();
    if (!sid) return [];
    const st = String(sourceType || '').trim();
    try {
        if (st === 'custom_product') {
            const { data } = await supabase.from('custom_products').select('category, subcategory_key').eq('id', sid).maybeSingle();
            return [data && data.subcategory_key, data && data.category].filter(Boolean);
        }
        if (st === 'vendor_asset') {
            const { data } = await supabase.from('vendor_assets').select('category_key, subcategory_key').eq('id', sid).maybeSingle();
            return [data && data.subcategory_key, data && data.category_key].filter(Boolean);
        }
    } catch (_) { /* ignore */ }
    return [];
}

/** 情境圖：場景 > 主題 > 來源產品分類 > 預設 2 */
async function resolveFluxSafetyToleranceForPromo(opts) {
    const o = opts && typeof opts === 'object' ? opts : {};
    const sceneT = await lookupPromoTemplateFluxSafetyTolerance(o.sceneKey);
    if (sceneT != null) return sceneT;
    const themeT = await lookupPromoTemplateFluxSafetyTolerance(o.themeKey);
    if (themeT != null) return themeT;
    const srcKeys = await resolveCategoryKeysFromPromoSource(o.sourceType, o.sourceId);
    const extra = Array.isArray(o.categoryKeys) ? o.categoryKeys : [];
    const allKeys = [...new Set([...extra, ...srcKeys].filter(Boolean))];
    return resolveFluxSafetyToleranceFromCategoryKeys(allKeys);
}

const BFL_BASE = 'https://api.bfl.ai';
const BFL_FLUX_PRO = BFL_BASE + '/v1/flux-2-pro';

/** Admin Playground 可用模型 → BFL path */
const BFL_PLAYGROUND_MODELS = {
    'flux-2-max': '/v1/flux-2-max',
    'flux-2-pro': '/v1/flux-2-pro',
    'flux-2-pro-preview': '/v1/flux-2-pro-preview',
    'flux-2-flex': '/v1/flux-2-flex',
    'flux-2-klein-9b': '/v1/flux-2-klein-9b',
    'flux-2-klein-4b': '/v1/flux-2-klein-4b'
};

/** payment_config 鍵 → 程式預設 model id（空間平視備援預設 max；其餘 pro） */
const BFL_FLUX_MODEL_CONFIG = {
    bfl_flux_model_generate: 'flux-2-pro',
    bfl_flux_model_official: 'flux-2-pro',
    bfl_flux_model_vendor_product: 'flux-2-pro',
    bfl_flux_model_vendor_material: 'flux-2-pro',
    bfl_flux_model_scene_pattern: 'flux-2-pro',
    bfl_flux_model_design_to_physical: 'flux-2-pro',
    bfl_flux_model_promo_image: 'flux-2-pro',
    bfl_flux_model_promo_space_eye_level: 'flux-2-max'
};

/** 允許後台手填 BFL model id（含未來新型號），格式 flux-2-* */
function isPlausibleBflFluxModelId(id) {
    return /^flux-2-[a-z0-9][a-z0-9-]*$/i.test(String(id || '').trim());
}

function normalizeBflFluxModelId(raw, fallbackId) {
    const id = String(raw || '').trim();
    if (isPlausibleBflFluxModelId(id)) return id;
    const fb = String(fallbackId || 'flux-2-pro').trim();
    if (isPlausibleBflFluxModelId(fb)) return fb;
    return 'flux-2-pro';
}

function getBflPlaygroundEndpoint(model) {
    const id = normalizeBflFluxModelId(model, 'flux-2-pro');
    const path = BFL_PLAYGROUND_MODELS[id];
    if (path) return BFL_BASE + path;
    return BFL_BASE + '/v1/' + id;
}

async function getBflFluxModelIdForConfigKey(configKey) {
    const fallback = BFL_FLUX_MODEL_CONFIG[configKey] || 'flux-2-pro';
    try {
        const { data: row } = await supabase.from('payment_config').select('value').eq('key', configKey).maybeSingle();
        return normalizeBflFluxModelId(row && row.value, fallback);
    } catch (_) {
        return fallback;
    }
}

async function getBflFluxEndpointForConfigKey(configKey) {
    return getBflPlaygroundEndpoint(await getBflFluxModelIdForConfigKey(configKey));
}

function resolveBflFluxModelsFromRows(rows) {
    const byKey = (rows || []).reduce((o, r) => { o[r.key] = r.value?.trim?.(); return o; }, {});
    const out = {};
    const saved = {};
    Object.keys(BFL_FLUX_MODEL_CONFIG).forEach((key) => {
        out[key] = normalizeBflFluxModelId(byKey[key], BFL_FLUX_MODEL_CONFIG[key]);
        saved[key] = !!byKey[key];
    });
    return { models: out, saved_in_db: saved };
}

/** 共用的 BFL 輪詢取圖：createData 含 polling_url，輪詢到 Ready 後下載 sample 回傳 Buffer */
async function pollBflResult(createData, BFL_API_KEY) {
    const pollingUrl = createData.polling_url;
    if (!pollingUrl) throw new Error('BFL 未回傳 polling_url');
    for (let i = 0; i < 120; i++) {
        await new Promise((r) => setTimeout(r, 1500));
        const pollRes = await fetch(pollingUrl, {
            headers: { 'accept': 'application/json', 'x-key': BFL_API_KEY }
        });
        const pollData = await pollRes.json();
        if (pollData.status === 'Ready' && pollData.result && pollData.result.sample) {
            const imageRes = await fetch(pollData.result.sample);
            return Buffer.from(await imageRes.arrayBuffer());
        }
        if (pollData.status === 'Error' || pollData.status === 'Failed') {
            throw new Error(pollData.message || pollData.error || 'FLUX 生成失敗');
        }
    }
    throw new Error('FLUX 逾時');
}

/** FLUX 2.0 PRO 純文字生圖；BFL 僅 body.prompt（無 negative_prompt），prompt 可含製造限制句 */
async function generateImageWithFlux2ProTextToImage(prompt, seed, outputFormat, endpointUrl, captureOut, textToImageOpts) {
    return runInBflQueue(async () => {
    const BFL_API_KEY = process.env.BFL_API_KEY;
    if (!BFL_API_KEY) return null;
    prompt = await translatePromptToEnglishForFlux(prompt);
    if (captureOut && typeof captureOut === 'object') {
        captureOut.prompt = prompt;
        captureOut.referenceCount = 0;
    }
    const tOpts = textToImageOpts && typeof textToImageOpts === 'object' ? textToImageOpts : {};
    const fmt = (outputFormat === 'png' || outputFormat === 'jpeg') ? outputFormat : 'jpeg';
    const body = {
        prompt,
        width: 1024,
        height: 1024,
        output_format: fmt,
        safety_tolerance: clampFluxSafetyTolerance(
            tOpts.safetyTolerance != null ? tOpts.safetyTolerance : FLUX_SAFETY_TOLERANCE_DEFAULT
        )
    };
    if (seed != null && Number.isInteger(Number(seed))) body.seed = Number(seed);
    const endpoint = endpointUrl || BFL_FLUX_PRO;
    const createRes = await fetch(endpoint, {
        method: 'POST',
        headers: { 'accept': 'application/json', 'Content-Type': 'application/json', 'x-key': BFL_API_KEY },
        body: JSON.stringify(body)
    });
    if (!createRes.ok) {
        const errText = await createRes.text();
        throw new Error(`BFL create: ${createRes.status} ${errText}`);
    }
    const createData = await createRes.json();
    return pollBflResult(createData, BFL_API_KEY);
    });
}

/** FLUX 2 參考圖編輯；BFL 僅 body.prompt（無 negative_prompt） */
async function generateImageWithFlux2Pro(prompt, referenceImages, seed, outputFormat, fluxOpts) {
    return runInBflQueue(async () => {
    const BFL_API_KEY = process.env.BFL_API_KEY;
    if (!BFL_API_KEY || !referenceImages || referenceImages.length === 0) return null;
    const fmt = (outputFormat === 'png' || outputFormat === 'jpeg') ? outputFormat : 'jpeg';
    const opts = fluxOpts && typeof fluxOpts === 'object' ? fluxOpts : {};
    const endpoint = opts.endpointUrl || BFL_FLUX_PRO;
    const outW = Math.min(2048, Math.max(256, Number(opts.width) || 1024));
    const outH = Math.min(2048, Math.max(256, Number(opts.height) || 1024));
    if (!opts.skipPromptTranslation) {
        prompt = await translatePromptToEnglishForFlux(prompt);
    } else {
        prompt = String(prompt || '').trim();
    }
    if (opts.captureOut && typeof opts.captureOut === 'object') {
        opts.captureOut.prompt = prompt;
        opts.captureOut.referenceCount = Math.min(8, (referenceImages || []).length);
    }
    const maxImages = 8;
    const images = referenceImages.slice(0, maxImages).map((img) => {
        if (typeof img === 'string' && img.startsWith('data:')) {
            const m = img.match(/^data:image\/\w+;base64,(.+)$/);
            return m ? m[1] : img;
        }
        return img;
    });
    const body = { prompt, output_format: fmt, width: outW, height: outH };
    if (seed != null && Number.isInteger(Number(seed))) body.seed = Number(seed);
    body.safety_tolerance = clampFluxSafetyTolerance(
        opts.safetyTolerance != null ? opts.safetyTolerance : FLUX_SAFETY_TOLERANCE_DEFAULT
    );
    // FLUX.2 [pro]/[max]：預設會做 prompt upsampling；須設 disable_pup=true 才會「照原文」生圖
    // （舊欄位 prompt_upsampling 對 flux-2-pro 無效，曾導致短中文被改寫成長描述）
    if (opts.promptUpsampling === true) {
        body.prompt_upsampling = true;
        body.disable_pup = false;
    } else if (opts.promptUpsampling === false) {
        body.disable_pup = true;
        body.prompt_upsampling = false;
    }
    body.input_image = images[0];
    for (let i = 1; i < images.length; i++) body[`input_image_${i + 1}`] = images[i];
    const createRes = await fetch(endpoint, {
        method: 'POST',
        headers: { 'accept': 'application/json', 'Content-Type': 'application/json', 'x-key': BFL_API_KEY },
        body: JSON.stringify(body)
    });
    if (!createRes.ok) {
        const errText = await createRes.text();
        throw new Error(`BFL create: ${createRes.status} ${errText}`);
    }
    const createData = await createRes.json();
    return pollBflResult(createData, BFL_API_KEY);
    });
}

/** 廠商素材：材料＝FLUX img2img；數位原型／零件＝FLUX 重繪 */
async function optimizeVendorAssetImageWithFlux(
    fileBuffer, mimeType, productNameRaw, assetKind, materialCatalogHint, backgroundColor, seed, filenameHint,
    materialFluxEditPrompt, materialSurfaceType, ownerId, useDisplayStand, photoCtx
) {
    if (!fileBuffer || !fileBuffer.length) throw new Error('無效的參考圖');
    const isMaterial = normalizeVendorAssetKind(assetKind) === 'material';
    const ctx = photoCtx && typeof photoCtx === 'object' ? photoCtx : {};
    if (isMaterial) {
        const prepared = await prepareVendorMaterialFluxImage(fileBuffer);
        const prompt = await buildVendorAssetMaterialFluxOptimizePromptWithPhoto(materialSurfaceType);
        const fluxSafetyTolerance = await resolveFluxSafetyToleranceFromCategoryPair(ctx.categoryKey, ctx.subcategoryKey);
        const fluxOpts = {
            endpointUrl: await getBflFluxEndpointForConfigKey('bfl_flux_model_vendor_material'),
            width: 1024,
            height: 1024,
            skipPromptTranslation: true,
            safetyTolerance: fluxSafetyTolerance
        };
        const dataUrl = `data:${prepared.mimetype};base64,${prepared.buffer.toString('base64')}`;
        const buf = await generateImageWithFlux2Pro(prompt, [dataUrl], VENDOR_MATERIAL_FLUX_SEED, 'jpeg', fluxOpts);
        if (!buf || !buf.length) throw new Error('圖片優化服務未設定或暫時無法使用（BFL_API_KEY）');
        return buf;
    }
    const productNameHint = await translateOptimizeProductNameForFlux(productNameRaw);
    const prompt = await buildVendorAssetProductOptimizePromptWithPhoto(
        productNameHint, backgroundColor, !!useDisplayStand, ctx.categoryKey, ctx.subcategoryKey, assetKind
    );
    const fluxBuffer = fileBuffer;
    const fluxMime = mimeType || 'image/jpeg';
    const fluxSafetyTolerance = await resolveFluxSafetyToleranceFromCategoryPair(ctx.categoryKey, ctx.subcategoryKey);
    const fluxOpts = {
        endpointUrl: await getBflFluxEndpointForConfigKey('bfl_flux_model_vendor_product'),
        skipPromptTranslation: true,
        safetyTolerance: fluxSafetyTolerance
    };
    const dataUrl = `data:${fluxMime};base64,${fluxBuffer.toString('base64')}`;
    const fluxSeed = seed != null ? seed : fluxSeedFromImageBuffer(fluxBuffer);
    const buf = await generateImageWithFlux2Pro(prompt, [dataUrl], fluxSeed, 'jpeg', fluxOpts);
    if (!buf || !buf.length) throw new Error('圖片優化服務未設定或暫時無法使用（BFL_API_KEY）');
    return buf;
}

