function isPromoSpaceAppealsMigrationError(err) {
    const msg = String((err && err.message) || err || '');
    return /promo_space_appeals/i.test(msg) && /does not exist|relation|42P01/i.test(msg);
}

async function getPromoSpaceAppealLockState(userId) {
    const { data, error } = await supabase
        .from('promo_space_appeals')
        .select('id, created_at, status')
        .eq('user_id', userId)
        .eq('status', 'rejected')
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (error) throw error;
    const lockUntil = promoSpaceAppeal.lockUntilFromRejectedAt(data && data.created_at);
    const locked = promoSpaceAppeal.isAppealLocked(lockUntil);
    return {
        locked,
        lock_until: locked ? lockUntil : null,
        last_rejected_at: (data && data.created_at) || null
    };
}

async function getPromoSpaceAppealForGeneration(userId, generationId) {
    const { data, error } = await supabase
        .from('promo_space_appeals')
        .select('id, status, refunded_points, reason_zh, created_at')
        .eq('user_id', userId)
        .eq('generation_id', generationId)
        .order('created_at', { ascending: false })
        .limit(20);
    if (error) throw error;
    const rows = data || [];
    const approved = rows.find((r) => r.status === 'approved') || null;
    return { rows, approved };
}

async function fetchPromoSpaceAppealSummaryMap(generationIds) {
    const ids = [...new Set((generationIds || []).map((id) => String(id || '').trim()).filter(Boolean))];
    if (!ids.length) return {};
    const { data, error } = await supabase
        .from('promo_space_appeals')
        .select('id, generation_id, status, refunded_points, reason_zh, created_at')
        .in('generation_id', ids)
        .order('created_at', { ascending: false });
    if (error) {
        if (isPromoSpaceAppealsMigrationError(error)) return {};
        throw error;
    }
    const map = {};
    (data || []).forEach(function (row) {
        const gid = String(row.generation_id || '').trim();
        if (!gid) return;
        if (!map[gid]) map[gid] = { appeal_count: 0, latest: null, approved: null };
        const entry = map[gid];
        entry.appeal_count += 1;
        if (!entry.latest) entry.latest = row;
        if (row.status === 'approved' && !entry.approved) entry.approved = row;
    });
    return map;
}

function mapPromoSpaceAppealSummary(entry) {
    if (!entry || !entry.appeal_count) {
        return {
            has_appeal: false,
            appeal_count: 0,
            appeal_status: null,
            appeal_refunded_points: 0,
            appeal_reason_zh: null,
            appeal_at: null
        };
    }
    const latest = entry.latest || null;
    const approved = entry.approved || null;
    return {
        has_appeal: true,
        appeal_count: entry.appeal_count,
        appeal_status: latest ? latest.status : null,
        appeal_refunded_points: approved ? (parseInt(approved.refunded_points, 10) || 0) : 0,
        appeal_reason_zh: latest && latest.reason_zh ? String(latest.reason_zh).trim() : null,
        appeal_at: latest ? latest.created_at : null
    };
}

function attachPromoSpaceAppealSummaries(items, appealMap) {
    (items || []).forEach(function (item) {
        if (!item || !item.id) return;
        Object.assign(item, mapPromoSpaceAppealSummary((appealMap || {})[String(item.id)]));
    });
    return items;
}

/** GET /api/promo-camera/space-appeal/status?generation_id= */
app.get('/api/promo-camera/space-appeal/status', async (req, res) => {
    try {
        const user = await getRequestUserFromAuthHeader(req);
        if (!user) return res.status(401).json({ success: false, error: '請先登入' });
        const generationId = String(req.query.generation_id || '').trim();
        if (!generationId) return res.status(400).json({ success: false, error: '缺少 generation_id' });

        let lockState;
        try {
            lockState = await getPromoSpaceAppealLockState(user.id);
        } catch (e) {
            if (isPromoSpaceAppealsMigrationError(e)) {
                return res.status(503).json({
                    success: false,
                    error: '請先執行 docs/add-promo-space-appeals.sql',
                    code: 'MIGRATION_REQUIRED'
                });
            }
            throw e;
        }

        const { data: row, error: rowErr } = await supabase
            .from('product_promo_generations')
            .select('id, user_id, points_charged, result_image_url, source_image_url, generation_meta_json, credit_transaction_id')
            .eq('id', generationId)
            .maybeSingle();
        if (rowErr) {
            console.error('GET space-appeal/status row:', rowErr);
            return res.status(500).json({ success: false, error: '查詢失敗' });
        }
        if (!row || row.user_id !== user.id) {
            return res.status(404).json({ success: false, error: '找不到此生成紀錄' });
        }
        const meta = parsePromoGenerationMetaJson(row.generation_meta_json);
        const isSpace = String(meta.shoot_mode || '').toLowerCase() === 'space'
            || String(meta.space_output_type || '').trim() !== '';
        const pointsCharged = Math.max(0, parseInt(row.points_charged, 10) || 0);
        let appealInfo;
        try {
            appealInfo = await getPromoSpaceAppealForGeneration(user.id, generationId);
        } catch (e) {
            if (isPromoSpaceAppealsMigrationError(e)) {
                return res.status(503).json({
                    success: false,
                    error: '請先執行 docs/add-promo-space-appeals.sql',
                    code: 'MIGRATION_REQUIRED'
                });
            }
            throw e;
        }
        const alreadyRefunded = !!appealInfo.approved;
        const canAppeal = isSpace
            && pointsCharged > 0
            && !!row.result_image_url
            && !!row.source_image_url
            && !alreadyRefunded
            && !lockState.locked;

        return res.json({
            success: true,
            generation_id: generationId,
            is_space: isSpace,
            points_charged: pointsCharged,
            already_refunded: alreadyRefunded,
            refunded_points: appealInfo.approved ? (appealInfo.approved.refunded_points || pointsCharged) : 0,
            locked: lockState.locked,
            lock_until: lockState.lock_until,
            can_appeal: canAppeal,
            last_appeal: appealInfo.rows[0] || null
        });
    } catch (e) {
        console.error('GET /api/promo-camera/space-appeal/status:', e);
        res.status(500).json({ success: false, error: e.message || '查詢失敗' });
    }
});

/** POST /api/promo-camera/space-appeal — 空間攝影 Beta 申訴（讀圖對比 JSON → 退點／24h 鎖） */
app.post('/api/promo-camera/space-appeal', express.json({ limit: '32kb' }), async (req, res) => {
    try {
        const user = await getRequestUserFromAuthHeader(req);
        if (!user) return res.status(401).json({ success: false, error: '請先登入' });
        const body = req.body || {};
        const generationId = String(body.generation_id || '').trim();
        if (!generationId) return res.status(400).json({ success: false, error: '缺少 generation_id' });

        let lockState;
        try {
            lockState = await getPromoSpaceAppealLockState(user.id);
        } catch (e) {
            if (isPromoSpaceAppealsMigrationError(e)) {
                return res.status(503).json({
                    success: false,
                    error: '請先執行 docs/add-promo-space-appeals.sql',
                    code: 'MIGRATION_REQUIRED'
                });
            }
            throw e;
        }
        if (lockState.locked) {
            return res.status(429).json({
                success: false,
                error: '申訴未通過，24 小時內無法再申請',
                code: 'APPEAL_LOCKED',
                locked: true,
                lock_until: lockState.lock_until
            });
        }

        const { data: row, error: rowErr } = await supabase
            .from('product_promo_generations')
            .select('id, user_id, points_charged, result_image_url, source_image_url, generation_meta_json, credit_transaction_id, status')
            .eq('id', generationId)
            .maybeSingle();
        if (rowErr) {
            console.error('POST space-appeal row:', rowErr);
            return res.status(500).json({ success: false, error: '查詢失敗' });
        }
        if (!row || row.user_id !== user.id) {
            return res.status(404).json({ success: false, error: '找不到此生成紀錄' });
        }
        const meta = parsePromoGenerationMetaJson(row.generation_meta_json);
        const isSpace = String(meta.shoot_mode || '').toLowerCase() === 'space'
            || String(meta.space_output_type || '').trim() !== '';
        if (!isSpace) {
            return res.status(400).json({ success: false, error: '僅空間攝影 Beta 可申訴' });
        }
        const pointsCharged = Math.max(0, parseInt(row.points_charged, 10) || 0);
        if (pointsCharged <= 0) {
            return res.status(400).json({ success: false, error: '此筆無扣點可退' });
        }
        if (!row.result_image_url || !row.source_image_url) {
            return res.status(400).json({ success: false, error: '缺少對照圖或結果圖，無法審核' });
        }

        let appealInfo;
        try {
            appealInfo = await getPromoSpaceAppealForGeneration(user.id, generationId);
        } catch (e) {
            if (isPromoSpaceAppealsMigrationError(e)) {
                return res.status(503).json({
                    success: false,
                    error: '請先執行 docs/add-promo-space-appeals.sql',
                    code: 'MIGRATION_REQUIRED'
                });
            }
            throw e;
        }
        if (appealInfo.approved) {
            return res.json({
                success: true,
                status: 'approved',
                already_refunded: true,
                refunded_points: appealInfo.approved.refunded_points || pointsCharged,
                reason_zh: appealInfo.approved.reason_zh || '此筆已退點',
                locked: false,
                lock_until: null,
                can_appeal: false
            });
        }

        if (!process.env.GEMINI_API_KEY) {
            return res.status(503).json({ success: false, error: '審核服務暫未設定，請稍後再試' });
        }

        let sourcePart;
        let resultPart;
        try {
            sourcePart = await visualSemantics.fetchUrlToImagePart(globalThis.fetch, row.source_image_url);
            resultPart = await visualSemantics.fetchUrlToImagePart(globalThis.fetch, row.result_image_url);
        } catch (imgErr) {
            console.error('space-appeal fetch images:', imgErr);
            return res.status(400).json({ success: false, error: '無法讀取對照圖或結果圖' });
        }

        let compare;
        try {
            compare = await promoSpaceAppeal.compareSpaceAppealImages(getVisualSemanticsDeps(), sourcePart, resultPart);
        } catch (cmpErr) {
            console.error('space-appeal compare:', cmpErr);
            return res.status(500).json({ success: false, error: '審核失敗，請稍後再試' });
        }

        const decision = compare.decision || promoSpaceAppeal.decideAppealFromJudge(compare.judge);
        let refundedPoints = 0;
        let refundTxId = null;
        let balanceAfter = null;

        if (decision.should_refund) {
            if (row.credit_transaction_id) {
                const { data: origTx } = await supabase
                    .from('credit_transactions')
                    .select('id, user_id, type, amount, metadata')
                    .eq('id', row.credit_transaction_id)
                    .eq('user_id', user.id)
                    .maybeSingle();
                const metaTx = (origTx && origTx.metadata && typeof origTx.metadata === 'object')
                    ? origTx.metadata
                    : {};
                if (origTx && metaTx.refunded) {
                    refundedPoints = Math.abs(origTx.amount || pointsCharged);
                } else {
                    const granted = await grantUserCredits(
                        user.id,
                        pointsCharged,
                        'promo_space_appeal_refund',
                        '空間攝影申訴退點',
                        {
                            generation_id: generationId,
                            refunded_tx_id: row.credit_transaction_id || null,
                            judge: compare.judge || null
                        }
                    );
                    if (!granted.ok) {
                        return res.status(500).json({ success: false, error: granted.error || '退點失敗' });
                    }
                    refundedPoints = pointsCharged;
                    refundTxId = granted.transaction_id || null;
                    balanceAfter = granted.balance_after;
                    if (origTx) {
                        await supabase
                            .from('credit_transactions')
                            .update({
                                metadata: {
                                    ...metaTx,
                                    refunded: true,
                                    refunded_at: new Date().toISOString(),
                                    refund_source: 'promo_space_appeal'
                                }
                            })
                            .eq('id', origTx.id);
                    }
                }
            } else {
                const granted = await grantUserCredits(
                    user.id,
                    pointsCharged,
                    'promo_space_appeal_refund',
                    '空間攝影申訴退點',
                    {
                        generation_id: generationId,
                        judge: compare.judge || null
                    }
                );
                if (!granted.ok) {
                    return res.status(500).json({ success: false, error: granted.error || '退點失敗' });
                }
                refundedPoints = pointsCharged;
                refundTxId = granted.transaction_id || null;
                balanceAfter = granted.balance_after;
            }
        }

        const insertPayload = {
            user_id: user.id,
            generation_id: generationId,
            status: decision.status,
            refunded_points: refundedPoints,
            refund_transaction_id: refundTxId,
            original_credit_transaction_id: row.credit_transaction_id || null,
            judge_json: compare.judge || { raw: compare.raw_text || null },
            judge_model: compare.model || null,
            reason_zh: (compare.judge && compare.judge.reason_zh) || null
        };
        const { data: appealRow, error: insErr } = await supabase
            .from('promo_space_appeals')
            .insert(insertPayload)
            .select('id, status, refunded_points, reason_zh, created_at')
            .single();
        if (insErr) {
            if (isPromoSpaceAppealsMigrationError(insErr)) {
                return res.status(503).json({
                    success: false,
                    error: '請先執行 docs/add-promo-space-appeals.sql',
                    code: 'MIGRATION_REQUIRED'
                });
            }
            // 競態：已有 approved
            if (/uq_promo_space_appeals_generation_approved|duplicate/i.test(String(insErr.message || ''))) {
                return res.json({
                    success: true,
                    status: 'approved',
                    already_refunded: true,
                    refunded_points: pointsCharged,
                    locked: false,
                    can_appeal: false
                });
            }
            console.error('POST space-appeal insert:', insErr);
            return res.status(500).json({ success: false, error: '無法寫入申訴紀錄' });
        }

        const newLockUntil = decision.lock_on_fail
            ? promoSpaceAppeal.lockUntilFromRejectedAt(appealRow.created_at)
            : null;
        const locked = promoSpaceAppeal.isAppealLocked(newLockUntil);

        let userMessage;
        if (decision.status === 'approved') {
            userMessage = `申訴通過，已退回 ${refundedPoints} 點`;
        } else if (decision.status === 'rejected') {
            userMessage = '審核未通過，24 小時內無法再申請';
        } else {
            userMessage = '無法明確判定，本次不退點也不鎖定，請稍後再試或換一張結果申訴';
        }

        return res.json({
            success: true,
            status: decision.status,
            appeal_id: appealRow.id,
            refunded_points: refundedPoints,
            balance_after: balanceAfter,
            reason_zh: (compare.judge && compare.judge.reason_zh) || null,
            judge: compare.judge || null,
            locked,
            lock_until: locked ? newLockUntil : null,
            can_appeal: decision.status === 'approved' ? false : (decision.status === 'inconclusive'),
            message: userMessage
        });
    } catch (e) {
        console.error('POST /api/promo-camera/space-appeal:', e);
        res.status(500).json({ success: false, error: e.message || '申訴失敗' });
    }
});

/** 情境圖：使用者數位資產庫列表（product_promo_generations） */
app.get('/api/promo-image/generations', async (req, res) => {
    try {
        const authHeader = req.headers.authorization;
        if (!authHeader) return res.status(401).json({ error: '未授權：缺少 token' });
        const token = authHeader.replace(/^\s*Bearer\s+/i, '');
        const { data: { user }, error: authError } = await supabase.auth.getUser(token);
        if (authError || !user) return res.status(401).json({ error: '未授權：token 無效' });

        const limitN = Math.min(50, Math.max(1, parseInt(req.query.limit, 10) || 24));
        const offsetN = Math.max(0, parseInt(req.query.offset, 10) || 0);
        const rangeEnd = offsetN + limitN;
        let { data, error } = await fetchUserPromoGenerationListRows(user.id, offsetN, rangeEnd);
        if (error) {
            console.error('GET /api/promo-image/generations:', error);
            return res.status(500).json({ error: error.message || '載入失敗' });
        }
        const rawList = data || [];
        const hasMore = rawList.length > limitN;
        const pageRows = hasMore ? rawList.slice(0, limitN) : rawList;
        let appealMap = {};
        try {
            appealMap = await fetchPromoSpaceAppealSummaryMap(pageRows.map(function (r) { return r.id; }));
        } catch (appealErr) {
            console.warn('GET /api/promo-image/generations appeals:', appealErr && appealErr.message);
        }
        const items = pageRows.map(function (row) {
            return Object.assign(mapUserPromoGenerationListItem(row), mapPromoSpaceAppealSummary(appealMap[String(row.id)]));
        });
        res.json({ success: true, items: items, count: items.length, offset: offsetN, hasMore: hasMore });
    } catch (e) {
        console.error('GET /api/promo-image/generations:', e);
        res.status(500).json({ error: e.message || '載入失敗' });
    }
});

/** POST 情境圖：讀圖產生描述（對齊設計稿 generate-description；寫入 product_promo_generations.description） */
app.post('/api/promo-image/generations/:id/generate-description', express.json(), async (req, res) => {
    try {
        const authHeader = req.headers.authorization;
        if (!authHeader) return res.status(401).json({ error: '未授權：缺少 token' });
        const token = authHeader.replace(/^\s*Bearer\s+/i, '');
        const { data: { user }, error: authError } = await supabase.auth.getUser(token);
        if (authError || !user) return res.status(401).json({ error: '未授權：token 無效' });

        const id = String(req.params.id || '').trim();
        if (!id) return res.status(400).json({ error: '缺少 id' });

        let promoRow = null;
        const { data: row, error: findErr } = await supabase
            .from('product_promo_generations')
            .select('id, user_id, result_image_url, user_prompt, final_prompt, scene_template_key, scene_key, source_type, source_id, description')
            .eq('id', id)
            .maybeSingle();
        if (findErr) {
            if (isSupabaseMissingColumnError(findErr, 'description') || isSupabaseMissingColumnError(findErr, 'final_prompt')) {
                const fb = await supabase
                    .from('product_promo_generations')
                    .select('id, user_id, result_image_url, user_prompt, scene_template_key, scene_key, source_type, source_id')
                    .eq('id', id)
                    .maybeSingle();
                if (fb.error) return res.status(500).json({ error: fb.error.message });
                promoRow = fb.data;
            } else {
                return res.status(500).json({ error: findErr.message });
            }
        } else {
            promoRow = row;
        }
        if (!promoRow || promoRow.user_id !== user.id) return res.status(404).json({ error: '找不到情境圖紀錄' });
        const imageUrl = (promoRow.result_image_url || '').trim();
        if (!imageUrl) return res.status(400).json({ error: '此情境圖尚無成圖，無法產生描述' });

        const isAdmin = await isAdminUserId(user.id);
        const pointsRequired = await getPointsVendorAssetDescription();
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(user.id, pointsRequired);
            if (!sufficient) return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
        }

        let productTitle = null;
        let categoryKey = null;
        if (promoRow.source_type === 'custom_product' && promoRow.source_id) {
            try {
                const { data: src } = await supabase
                    .from('custom_products')
                    .select('title, category')
                    .eq('id', promoRow.source_id)
                    .maybeSingle();
                if (src) {
                    productTitle = src.title || null;
                    categoryKey = src.category || null;
                }
            } catch (_) {}
        }

        const enriched = await enrichPromoGenerationSemantics(promoRow.id, user.id, {
            imageUrl: imageUrl,
            userPrompt: promoRow.user_prompt || null,
            finalPrompt: promoRow.final_prompt || null,
            themeKey: promoRow.scene_template_key || null,
            sceneKey: promoRow.scene_key || null,
            sourceType: promoRow.source_type || null,
            sourceId: promoRow.source_id || null,
            productTitle: productTitle,
            categoryKey: categoryKey
        });
        if (!enriched || !(enriched.description || '').trim()) {
            return res.status(503).json({
                error: 'AI 描述產生失敗，請稍後重試（若尚未建語意欄位，請執行 docs/add-promo-generations-semantics.sql）'
            });
        }

        let balanceAfter = null;
        let pointsDeducted = 0;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                user.id,
                pointsRequired,
                'promo_generate_description',
                '情境圖 AI 描述',
                { promo_generation_id: promoRow.id }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: consumed.error || '扣點失敗', balance: consumed.balance });
            }
            balanceAfter = consumed.balance_after;
            pointsDeducted = pointsRequired;
        }

        res.json({
            success: true,
            id: promoRow.id,
            description: enriched.description,
            ai_tags: enriched.ai_tags || [],
            points_deducted: pointsDeducted,
            balance_after: balanceAfter
        });
    } catch (e) {
        console.error('POST /api/promo-image/generations/:id/generate-description:', e);
        res.status(503).json({ error: e.message || 'AI 描述產生失敗，請稍後重試' });
    }
});

