/** 情境圖：確認／補寫入數位資產庫（生成成功時通常已寫入；此 API 供補傳 imageData） */
app.post('/api/promo-image/save-to-library', express.json({ limit: '15mb' }), async (req, res) => {
    try {
        const authHeader = req.headers.authorization;
        if (!authHeader) return res.status(401).json({ success: false, error: '請先登入' });
        const token = authHeader.replace(/^\s*Bearer\s+/i, '');
        const { data: { user }, error: authError } = await supabase.auth.getUser(token);
        if (authError || !user) return res.status(401).json({ success: false, error: '請先登入' });

        const body = req.body || {};
        const generationId = body.id ? String(body.id).trim() : '';
        if (generationId) {
            const { data: existing, error: findErr } = await supabase
                .from('product_promo_generations')
                .select('id, user_id, result_image_url')
                .eq('id', generationId)
                .maybeSingle();
            if (findErr) return res.status(500).json({ success: false, error: findErr.message });
            if (!existing || existing.user_id !== user.id) {
                return res.status(404).json({ success: false, error: '找不到情境圖紀錄' });
            }
            if (existing.result_image_url) {
                return res.json({ success: true, id: existing.id, image_url: existing.result_image_url, already_saved: true });
            }
        }

        let buffer = null;
        const imageData = body.imageData || body.image_data;
        if (imageData && typeof imageData === 'string' && imageData.startsWith('data:image/')) {
            const comma = imageData.indexOf(',');
            if (comma >= 0) {
                try { buffer = Buffer.from(imageData.slice(comma + 1), 'base64'); } catch (_) { buffer = null; }
            }
        }
        if (!buffer) {
            return res.status(400).json({ success: false, error: '無可儲存的圖片' });
        }

        let resultImageUrl = null;
        try {
            const uploaded = await uploadToSupabaseStorage(
                'custom-products',
                `promo/${user.id}`,
                { buffer, mimetype: 'image/jpeg', originalname: `promo-${Date.now()}.jpg` },
                { ext: 'jpg', contentType: 'image/jpeg', skipNormalize: true }
            );
            resultImageUrl = uploaded && uploaded.publicUrl ? uploaded.publicUrl : null;
        } catch (upErr) {
            console.warn('promo save-to-library upload:', upErr?.message || upErr);
            return res.status(500).json({ success: false, error: '上傳失敗' });
        }
        if (!resultImageUrl) return res.status(500).json({ success: false, error: '上傳失敗' });

        const w = Math.min(2048, Math.max(512, parseInt(body.width, 10) || 1024));
        const h = Math.min(2048, Math.max(512, parseInt(body.height, 10) || 1024));
        const aspectRatio = String(body.aspect_ratio || '').trim() || `${w}:${h}`;

        if (generationId) {
            const { error: updErr } = await supabase
                .from('product_promo_generations')
                .update({ result_image_url: resultImageUrl, completed_at: new Date().toISOString() })
                .eq('id', generationId)
                .eq('user_id', user.id);
            if (updErr) console.warn('promo save-to-library update:', updErr.message);
            return res.json({ success: true, id: generationId, image_url: resultImageUrl });
        }

        const { data: inserted, error: insErr } = await supabase
            .from('product_promo_generations')
            .insert({
                user_id: user.id,
                source_type: 'upload',
                aspect_ratio: aspectRatio,
                width: w,
                height: h,
                megapixels: promoImageMegapixelsFromResolution(w, h),
                scene_template_key: body.theme_key || body.scene_template_key || null,
                scene_key: body.scene_key || null,
                user_prompt: body.user_prompt || null,
                result_image_url: resultImageUrl,
                status: 'success',
                points_charged: 0,
                completed_at: new Date().toISOString(),
                show_on_homepage: true
            })
            .select('id')
            .single();
        if (insErr) {
            console.warn('promo save-to-library insert:', insErr.message);
            return res.json({ success: true, image_url: resultImageUrl });
        }
        res.json({ success: true, id: inserted && inserted.id ? inserted.id : null, image_url: resultImageUrl });
    } catch (e) {
        console.error('POST /api/promo-image/save-to-library:', e);
        res.status(500).json({ success: false, error: e.message || '儲存失敗' });
    }
});

// API: 生成產品示意圖（categoryKeys 必填，後端組合基礎提示詞 + 使用者描述）
// categorySource: 'remake' 時使用 remake_categories 的 prompt，否則使用訂製分類
app.post('/api/generate-product-image', express.json({ limit: '15mb' }), async (req, res) => {
    try {
        const { prompt, categoryKeys, aspectRatio = '1:1', resolution = '2K', referenceImages, referenceSources, seed, categorySource, output_format, selected_capability_keys, selected_capability_custom_labels } = req.body;
        const userPromptRaw = (prompt != null ? String(prompt) : '').trim();
        const outputFormat = (output_format === 'png' || output_format === 'jpeg') ? output_format : 'jpeg';
        const hasRefsEarly = referenceImages && Array.isArray(referenceImages) && referenceImages.length > 0;
        if (!userPromptRaw && !hasRefsEarly) {
            return res.status(400).json({ success: false, error: '請提供產品描述' });
        }
        if (!categoryKeys || !Array.isArray(categoryKeys) || categoryKeys.length === 0) {
            return res.status(400).json({ success: false, error: '請至少選擇一項圖內容分類' });
        }
        const useRemake = (categorySource === 'remake' || categorySource === 'remake_categories');
        const hasRefs = referenceImages && Array.isArray(referenceImages) && referenceImages.length > 0;
        if (useRemake && !hasRefs) {
            return res.status(400).json({ success: false, error: '設計風向須上傳至少一張參考圖' });
        }
        const capKeysReq = manufacturerTaxonomy.parseJsonStringArray(selected_capability_keys);
        const capCustomReq = manufacturerTaxonomy.parseJsonStringArray(selected_capability_custom_labels);
        // 表面工藝僅在「廠商數位原型」流程驗證；文生圖／自傳參考圖不依賴廠商原型，勿阻擋生圖
        if (capKeysReq.length || capCustomReq.length) {
            const protoIdForCapValidate = resolvePrimaryPrototypeAssetIdFromReferenceSources(referenceSources || []);
            if (protoIdForCapValidate) {
                const capValidReq = await manufacturerTaxonomy.validateSelectedCapabilitiesForPrototype(
                    supabase, protoIdForCapValidate, capKeysReq, capCustomReq
                );
                if (!capValidReq.ok) {
                    return res.status(400).json({ success: false, error: capValidReq.error || '工藝選項無效' });
                }
            }
        }

        // ── 步驟 1：取得使用者資訊，在生圖前先確認點數夠（避免 BFL 費用白花）──
        let currentUser = null;
        let isAdmin = false;
        let isStaffViewer = false;
        let pointsToDeduct = 0;
        let currentBalance = 0;
        const authHeader = req.headers.authorization;
        if (authHeader) {
            const token = authHeader.replace('Bearer ', '');
            const { data: { user }, error: authError } = await supabase.auth.getUser(token);
            if (!authError && user) {
                currentUser = user;
                const { data: profile } = await supabase.from('profiles').select('role').eq('id', user.id).maybeSingle();
                const role = profile && profile.role ? String(profile.role).trim() : '';
                isAdmin = role === 'admin';
                isStaffViewer = role === 'admin' || role === 'tester';
                if (!isAdmin) {
                    const basePoints = await getPointsForProductImageGenerate(hasRefs, referenceSources || []);
                    pointsToDeduct = await applyAnnualDiscount(user.id, basePoints);
                    const { data: creditRow } = await supabase
                        .from('user_credits').select('balance').eq('user_id', user.id).maybeSingle();
                    currentBalance = creditRow?.balance ?? 0;
                    if (currentBalance < pointsToDeduct) {
                        return res.status(402).json({
                            success: false,
                            error: `點數不足，本次生圖需要 ${pointsToDeduct} 點，目前餘額 ${currentBalance} 點`,
                            required: pointsToDeduct,
                            balance: currentBalance
                        });
                    }
                }
            }
        }

        const uiLang = (req.body.ui_locale || req.body.lang || '').trim() || null;
        const composed = await composeGeneratePromptWithReferences({
            categoryKeys,
            userPrompt: userPromptRaw,
            useRemake,
            uiLang,
            referenceImages: hasRefs ? referenceImages : [],
            referenceSources: hasRefs ? (referenceSources || []) : [],
            selectedCapabilityKeys: selected_capability_keys,
            selectedCapabilityCustomLabels: selected_capability_custom_labels
        });
        let fullPrompt = composed.fullPrompt;
        let fluxReferenceImages = composed.fluxReferenceImages;
        let fluxReferenceSources = composed.fluxReferenceSources;
        // 使用者未填 seed 時由後端產生隨機 seed，傳給 FLUX 並寫入 DB，方便重現與顯示
        let seedNum = (seed != null && seed !== '' && Number.isInteger(Number(seed))) ? Number(seed) : null;
        if (seedNum == null) seedNum = Math.floor(Math.random() * 2147483647);

        let imageData = null;
        let usedFlux = false;
        const fluxCaptureOut = isStaffViewer ? {} : null;

        // ── 步驟 2：呼叫 BFL 生圖 ──
        if (process.env.BFL_API_KEY) {
            try {
                const fluxSafetyTolerance = await resolveFluxSafetyToleranceFromCategoryKeys(categoryKeys);
                const fluxModelKey = (hasRefs && referenceSourcesIncludeOfficial(referenceSources || []))
                    ? 'bfl_flux_model_official'
                    : 'bfl_flux_model_generate';
                const fluxGenerateEndpoint = await getBflFluxEndpointForConfigKey(fluxModelKey);
                if (hasRefs) {
                    const buffer = await generateImageWithFlux2Pro(fullPrompt, fluxReferenceImages, seedNum, outputFormat, {
                        endpointUrl: fluxGenerateEndpoint,
                        captureOut: fluxCaptureOut,
                        safetyTolerance: fluxSafetyTolerance
                    });
                    if (buffer) { imageData = buffer.toString('base64'); usedFlux = true; }
                } else {
                    const buffer = await generateImageWithFlux2ProTextToImage(
                        fullPrompt, seedNum, outputFormat, fluxGenerateEndpoint, fluxCaptureOut,
                        { safetyTolerance: fluxSafetyTolerance }
                    );
                    if (buffer) { imageData = buffer.toString('base64'); usedFlux = true; }
                }
            } catch (e) {
                console.warn('FLUX 2.0 pro 失敗:', e.message);
            }
        }

        const staffDebugFlux = isStaffViewer
            ? buildFluxStaffDebugPayload(fullPrompt, fluxCaptureOut, fluxReferenceSources)
            : null;

        if (!imageData) {
            return res.status(500).json({
                success: false,
                error: process.env.BFL_API_KEY
                    ? '生圖失敗，請稍後再試或調整描述' + (hasRefs ? '與參考圖' : '')
                    : '生圖服務暫未設定，請稍後再試',
                ...(staffDebugFlux ? { debugFlux: staffDebugFlux } : {})
            });
        }

        // ── 步驟 3：生圖成功，上傳 Storage ──
        const buffer = Buffer.from(imageData, 'base64');
        const ext = outputFormat === 'png' ? 'png' : 'jpg';
        const mime = outputFormat === 'png' ? 'image/png' : 'image/jpeg';
        let imageUrl = null;
        try {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', 'generated', { buffer, mimetype: mime, originalname: `generated-${Date.now()}.${ext}` }, { ext, contentType: mime });
            imageUrl = publicUrl;
        } catch (e) {
            console.warn('上傳生成圖至 Storage 失敗:', e.message);
        }
        if (!imageUrl) imageUrl = `data:${mime};base64,${imageData}`;

        const showOnHomepageForInsert = currentUser
            ? await resolveDesignShowOnHomepageFromRequest(currentUser.id, req.body)
            : true;

        // ── 生圖已完成：先寫入 custom_products，再回傳；打標在「有圖之後」用成品 buffer 排隊執行 ──
        let insertedProductId = null;
        if (currentUser) {
            try {
                let creditTransactionId = null;
                if (!isAdmin && pointsToDeduct > 0) {
                    const creditSource = hasRefs
                        ? (referenceSourcesIncludeOfficial(referenceSources || []) ? 'official_image_to_image' : 'image_to_image')
                        : 'text_to_image';
                    const creditDesc = !hasRefs
                        ? `文生圖（${pointsToDeduct} 點）`
                        : (referenceSourcesIncludeOfficial(referenceSources || [])
                            ? `官方版型圖生圖（${pointsToDeduct} 點）`
                            : `圖生圖（${pointsToDeduct} 點）`);
                    const consumed = await consumeUserCredits(
                        currentUser.id,
                        pointsToDeduct,
                        creditSource,
                        creditDesc,
                        { category_keys: categoryKeys || [] }
                    );
                    if (!consumed.ok) {
                        console.warn('生圖扣點失敗（仍繼續寫入作品）:', consumed.error || 'unknown');
                    } else {
                        creditTransactionId = consumed.transaction_id || null;
                        console.log('生圖扣點 user=%s points=%d balance_after=%d', currentUser.id, pointsToDeduct, consumed.balance_after);
                    }
                }
                const autoUiLocale = (req.body.ui_locale || req.body.lang || '').trim() || null;
                const titleFallbackEn = autoUiLocale && String(autoUiLocale).toLowerCase().indexOf('en') === 0;
                const title = (prompt && String(prompt).trim())
                    ? String(prompt).trim().substring(0, 80) + (String(prompt).trim().length > 80 ? '…' : '')
                    : (titleFallbackEn ? 'Product design draft' : '產品設計稿');
                const description = (prompt && String(prompt).trim()) || (titleFallbackEn ? '(No description)' : '（無描述）');
                const generationPromptVal = (prompt && String(prompt).trim()) ? String(prompt).trim() : null;
                const mainCategoryKey = (categoryKeys && categoryKeys[0]) ? String(categoryKeys[0]).trim() || null : null;
                const subCategoryKey = (categoryKeys && categoryKeys.length >= 2 && categoryKeys[1]) ? String(categoryKeys[1]).trim() || null : null;
                const showOnHomepage = showOnHomepageForInsert;
                const autoLineage = hasRefs && fluxReferenceSources.length
                    ? await customProductLineage.computeCustomProductLineage(
                        supabase, currentUser.id, fluxReferenceSources
                    )
                    : null;
                const parentKind = String(req.body.parent_record_kind || req.body.parent_kind || '').trim();
                const parentId = String(req.body.parent_record_id || req.body.parent_id || '').trim();
                const autoInsertPayload = {
                    owner_id: currentUser.id,
                    title, description,
                    category: mainCategoryKey,
                    subcategory_key: subCategoryKey,
                    reference_image_url: (fluxReferenceImages && fluxReferenceImages.length) ? fluxReferenceImages[0] : null,
                    ai_generated_image_url: imageUrl,
                    analysis_json: null,
                    status: 'draft',
                    generation_prompt: generationPromptVal,
                    generation_seed: seedNum,
                    show_on_homepage: showOnHomepage,
                    credit_transaction_id: creditTransactionId,
                    composed_flux_prompt: fullPrompt || null,
                    generation_meta_json: {
                        reference_count: fluxReferenceImages ? fluxReferenceImages.length : 0,
                        category_keys: categoryKeys || [],
                        output_format: outputFormat || 'jpeg',
                        used_flux: usedFlux
                    }
                };
                if (parentKind && parentId && provenanceResume.ASSET_KINDS.has(parentKind)) {
                    autoInsertPayload.parent_record_kind = parentKind;
                    autoInsertPayload.parent_record_id = parentId;
                }
                if (autoLineage) {
                    autoInsertPayload.generator_manufacturer_id = autoLineage.generator_manufacturer_id;
                    autoInsertPayload.has_self_vendor_reference = autoLineage.has_self_vendor_reference;
                    autoInsertPayload.is_vendor_self_serve = autoLineage.is_vendor_self_serve;
                    autoInsertPayload.data_lineage_json = autoLineage.data_lineage_json;
                    if (autoLineage.reference_sources) autoInsertPayload.reference_sources = autoLineage.reference_sources;
                }
                mergeDesignerRegionIntoPayload(autoInsertPayload, req, autoUiLocale);
                let insertRes = await supabase.from('custom_products').insert(autoInsertPayload).select('id').single();
                if (insertRes.error && insertRes.error.code === '42703') {
                    insertRes = await supabase.from('custom_products')
                        .insert(stripInternalCustomProductInsertColumns(autoInsertPayload))
                        .select('id').single();
                }
                if (insertRes.error) {
                    console.error('寫入 custom_products 失敗:', insertRes.error.message);
                } else if (insertRes.data && insertRes.data.id) {
                    insertedProductId = insertRes.data.id;
                    console.log('已寫入 custom_products id=%s owner_id=%s', insertedProductId, currentUser.id);
                    // 與情境圖相同：寫入後、回傳前 schedule；帶成品 imageBuffer
                    scheduleCustomProductSemanticsEnrich(insertedProductId, currentUser.id, {
                        imageBuffer: buffer,
                        imageUrl: imageUrl,
                        mimeType: mime,
                        generationPrompt: generationPromptVal,
                        title,
                        categoryKey: mainCategoryKey
                    });
                }
            } catch (e) {
                console.error('扣點或寫入 custom_products 異常:', e.message);
            }
        }

        res.json({
            success: true,
            imageUrl,
            imageData: `data:${mime};base64,${imageData}`,
            output_format: outputFormat,
            resolution: '1024x1024',
            aspectRatio: '1:1',
            usedFlux,
            seedUsed: seedNum,
            mode: hasRefs ? 'image-to-image' : 'text-to-image',
            show_on_homepage: showOnHomepageForInsert,
            product_id: insertedProductId,
            ...(staffDebugFlux ? { debugFlux: staffDebugFlux } : {})
        });
    } catch (error) {
        console.error('生成圖片錯誤:', error);
        res.status(500).json({
            success: false,
            error: '圖片生成失敗，請檢查描述是否清楚或稍後再試',
            details: error.message
        });
    }
});

// API: Admin Playground 生圖（文生圖／圖生圖；管理員與測試員可用）
app.post('/api/admin/playground-generate', express.json(), async (req, res) => {
    try {
        const adminUser = await requireAdminOrTester(req, res);
        if (!adminUser) return;
        const BFL_API_KEY = process.env.BFL_API_KEY;
        if (!BFL_API_KEY) {
            return res.status(503).json({ success: false, error: '未設定 BFL_API_KEY，無法生圖' });
        }
        const { prompt, referenceImage, referenceImages, model = 'flux-2-pro', width = 1024, height = 1024, seed, output_format } = req.body;
        const rawPrompt = (prompt && String(prompt).trim()) ? String(prompt).trim() : '';
        if (!rawPrompt) {
            return res.status(400).json({ success: false, error: '請輸入描述（prompt）' });
        }
        const outputFormat = (output_format === 'png' || output_format === 'jpeg') ? output_format : 'jpeg';
        const endpointUrl = getBflPlaygroundEndpoint(model);
        const w = Math.min(2048, Math.max(512, Number(width) || 1024));
        const h = Math.min(2048, Math.max(512, Number(height) || 1024));
        let seedNum = (seed != null && seed !== '' && Number.isInteger(Number(seed))) ? Number(seed) : null;
        if (seedNum == null) seedNum = Math.floor(Math.random() * 2147483647);

        let refList = Array.isArray(referenceImages) && referenceImages.length > 0
            ? referenceImages
            : (referenceImage && typeof referenceImage === 'string' && referenceImage.length > 0 ? [referenceImage] : []);
        refList = (await normalizeReferenceImagesForFlux(refList.slice(0, 8).filter(Boolean)));

        let buffer;
        if (refList.length > 0) {
            buffer = await bflPlaygroundImageEdit(endpointUrl, rawPrompt, refList, w, h, seedNum, outputFormat, BFL_API_KEY);
        } else {
            buffer = await bflPlaygroundTextToImage(endpointUrl, rawPrompt, w, h, seedNum, outputFormat, BFL_API_KEY);
        }
        if (!buffer) {
            return res.status(500).json({ success: false, error: 'FLUX 生圖失敗' });
        }
        const imageData = buffer.toString('base64');
        const mime = outputFormat === 'png' ? 'image/png' : 'image/jpeg';
        res.json({
            success: true,
            imageData: `data:${mime};base64,${imageData}`,
            output_format: outputFormat,
            width: w,
            height: h,
            seedUsed: seedNum
        });
    } catch (error) {
        console.error('Admin playground 生圖錯誤:', error);
        res.status(500).json({
            success: false,
            error: error.message || '生圖失敗，請稍後再試'
        });
    }
});

// ---------- AI 放大（Stability Fast Upscale） ----------
const FREE_MEMBER_LEVEL_LABEL = '一般';

/** 後台「會員等級」：一般＝免費；進階／尊榮／VIP（及非「一般」之自訂名）＝付費權益 */
function isPaidMemberLevel(memberLevel) {
    const level = (memberLevel != null ? String(memberLevel).trim() : '') || FREE_MEMBER_LEVEL_LABEL;
    return level !== FREE_MEMBER_LEVEL_LABEL;
}

async function readProfileMemberLevel(userId) {
    if (!userId) return FREE_MEMBER_LEVEL_LABEL;
    try {
        const { data } = await supabase.from('profiles').select('member_level').eq('id', userId).maybeSingle();
        return (data && data.member_level) ? String(data.member_level).trim() : FREE_MEMBER_LEVEL_LABEL;
    } catch (_) {
        return FREE_MEMBER_LEVEL_LABEL;
    }
}

function memberLevelFromPlanName(planName) {
    const name = (planName && String(planName).trim()) || '';
    if (name === '進階' || name === '尊榮' || name === 'VIP') return name;
    return '進階';
}

function parsePaymentOrderMetadata(metadata) {
    if (!metadata) return {};
    if (typeof metadata === 'object' && !Array.isArray(metadata)) return metadata;
    if (typeof metadata === 'string') {
        try { return JSON.parse(metadata); } catch (_) { return {}; }
    }
    return {};
}

/**
 * 寫入／延長 user_subscriptions，並同步 profiles.member_level（月訂／年付／後台開通共用）
 * @param {'new'|'extend'} options.mode — new：作廢其他 active 後新建；extend：自現有到期日或今日起延長 duration_months
 * @param {'always'|'if_free_only'} options.syncMemberLevel
 */
async function activateUserSubscriptionFromPlan(userId, plan, options) {
    if (!userId || !plan || !plan.id) return;
    options = options || {};
    const mode = options.mode === 'extend' ? 'extend' : 'new';
    const syncLevel = options.syncMemberLevel || 'always';
    const now = new Date();
    const months = Math.max(1, parseInt(plan.duration_months, 10) || 1);

    if (mode === 'new') {
        await supabase
            .from('user_subscriptions')
            .update({ status: 'expired' })
            .eq('user_id', userId)
            .eq('status', 'active');
        const start = now;
        const end = new Date(start);
        end.setMonth(end.getMonth() + months);
        await supabase.from('user_subscriptions').insert({
            user_id: userId,
            plan_id: plan.id,
            start_date: start.toISOString(),
            end_date: end.toISOString(),
            status: 'active',
            auto_renew: options.autoRenew === true
        });
    } else {
        const { data: active } = await supabase
            .from('user_subscriptions')
            .select('id, end_date')
            .eq('user_id', userId)
            .eq('status', 'active')
            .gt('end_date', now.toISOString())
            .order('end_date', { ascending: false })
            .limit(1)
            .maybeSingle();
        const base = (active && active.end_date && new Date(active.end_date) > now)
            ? new Date(active.end_date)
            : now;
        const end = new Date(base);
        end.setMonth(end.getMonth() + months);
        if (active && active.id) {
            await supabase.from('user_subscriptions').update({
                end_date: end.toISOString(),
                status: 'active'
            }).eq('id', active.id);
        } else {
            await supabase
                .from('user_subscriptions')
                .update({ status: 'expired' })
                .eq('user_id', userId)
                .eq('status', 'active');
            await supabase.from('user_subscriptions').insert({
                user_id: userId,
                plan_id: plan.id,
                start_date: now.toISOString(),
                end_date: end.toISOString(),
                status: 'active',
                auto_renew: options.autoRenew === true
            });
        }
    }

    if (syncLevel === 'always') {
        await supabase.from('profiles').update({ member_level: memberLevelFromPlanName(plan.name) }).eq('id', userId);
    } else {
        const currentLevel = await readProfileMemberLevel(userId);
        if (!isPaidMemberLevel(currentLevel)) {
            await supabase.from('profiles').update({ member_level: memberLevelFromPlanName(plan.name) }).eq('id', userId);
        }
    }
    try {
        await syncMembershipCatalogVisibility(userId);
    } catch (syncErr) {
        console.warn('syncMembershipCatalogVisibility:', syncErr && syncErr.message);
    }
}

/** 付款訂單含 plan_key 時：開通訂閱並連動會員層級（月訂 extend／年付 new） */
async function fulfillSubscriptionAfterPayment(order, options) {
    if (!order || !order.user_id) return;
    const meta = parsePaymentOrderMetadata(order.metadata);
    const planKey = meta.plan_key ? String(meta.plan_key).trim() : '';
    if (!planKey) return;
    const orderType = order.order_type || '';
    if (orderType !== 'subscription' && orderType !== 'yearly') return;
    const { data: plan } = await supabase
        .from('subscription_plans')
        .select('id, name, price, duration_months')
        .eq('plan_key', planKey)
        .maybeSingle();
    if (!plan || !(parseInt(plan.price, 10) > 0)) return;
    const mode = (options && options.mode)
        ? options.mode
        : (orderType === 'subscription' ? 'extend' : 'new');
    await activateUserSubscriptionFromPlan(order.user_id, plan, {
        mode,
        syncMemberLevel: 'always',
        autoRenew: !!(options && options.autoRenew)
    });
}

/** 是否視為付費會員：有效 user_subscriptions（方案價>0）或 profiles.member_level 非「一般」 */
async function hasActivePaidSubscription(userId) {
    if (!userId) return false;
    const now = new Date().toISOString();
    const { data: rows } = await supabase
        .from('user_subscriptions')
        .select('id, subscription_plans(price)')
        .eq('user_id', userId)
        .eq('status', 'active')
        .gt('end_date', now);
    if (rows && rows.length > 0 && rows.some(r => (r.subscription_plans && (r.subscription_plans.price || 0) > 0))) {
        return true;
    }
    return isPaidMemberLevel(await readProfileMemberLevel(userId));
}

/** 付費會員或管理員／測試員：可選是否上媒體牆；免費會員強制公開 */
async function canControlDesignShowOnHomepage(userId) {
    if (!userId) return false;
    if (await isStaffProfileUserId(userId)) return true;
    return hasActivePaidSubscription(userId);
}

/** 新設計寫入時媒體牆預設：一律預設公開；付費／管理員／測試員可於設計頁取消勾選 */
async function defaultShowOnHomepageForNewDesign(userId) {
    void userId;
    return true;
}

/** 依請求 body 與會員資格決定 show_on_homepage（免費強制 true） */
async function resolveDesignShowOnHomepageFromRequest(userId, body) {
    if (!userId) return true;
    if (!(await canControlDesignShowOnHomepage(userId))) return true;
    if (body && typeof body.show_on_homepage !== 'undefined') return !!body.show_on_homepage;
    return true;
}

const VENDOR_ASSET_MEMBERSHIP_HIDE_COL = 'public_hidden_by_membership';
const VENDOR_ASSET_PLATFORM_MANAGED_COL = 'platform_managed';

async function isStaffProfileUserId(userId) {
    if (!userId) return false;
    const { data } = await supabase.from('profiles').select('role').eq('id', userId).maybeSingle();
    const role = data && data.role ? String(data.role) : '';
    return role === 'admin' || role === 'tester';
}

async function isSeedManufacturerAccountUserId(userId) {
    if (!userId) return false;
    const { data } = await supabase.from('manufacturers').select('vendor_source').eq('user_id', userId).maybeSingle();
    return !!(data && data.vendor_source === 'seed');
}

/** 種子展示期代維護、管理員／測試員：作品系列圖／對照圖免方案與點數（與素材上傳 canUploadProductsAndAssets 一致） */
async function canUploadPortfolioBypassPlanAndPoints(userId) {
    if (!userId) return false;
    if (await isStaffProfileUserId(userId)) return true;
    return isSeedManufacturerAccountUserId(userId);
}

/** 限制 A：免費帳號不可上傳（種子展示期平台代維護、管理員／測試員除外） */
async function canUploadProductsAndAssetsUserId(userId) {
    if (!userId) return false;
    if (await isStaffProfileUserId(userId)) return true;
    if (await isSeedManufacturerAccountUserId(userId)) return true;
    return hasActivePaidSubscription(userId);
}

async function assertCanUploadProductsAndAssets(req, res) {
    const user = await getCurrentUser(req, res);
    if (!user) return null;
    if (isOfficialPlatformLibraryRequest(req)) {
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', user.id).maybeSingle();
        if (profile?.role === 'admin') return user;
        res.status(403).json({ error: '僅管理員可上傳官方版型庫', code: 'OFFICIAL_PLATFORM_ADMIN_REQUIRED' });
        return null;
    }
    const allowed = await canUploadProductsAndAssetsUserId(user.id);
    if (!allowed) {
        res.status(403).json({
            error: '免費帳號無法上傳產品與素材，請升級付費方案後再試',
            code: 'MEMBERSHIP_UPLOAD_REQUIRED'
        });
        return null;
    }
    return user;
}

function manufacturerExemptFromMembershipCatalog(mfr) {
    if (!mfr) return true;
    const src = mfr.vendor_source ? String(mfr.vendor_source) : '';
    return src === 'seed' || src === 'platform';
}

async function readProfileMembershipCatalogTier(userId) {
    try {
        const { data, error } = await supabase.from('profiles').select('membership_catalog_tier').eq('id', userId).maybeSingle();
        if (error && error.code === '42703') return null;
        return (data && data.membership_catalog_tier) ? String(data.membership_catalog_tier) : null;
    } catch (_) {
        return null;
    }
}

async function writeProfileMembershipCatalogTier(userId, tier) {
    try {
        await supabase.from('profiles').update({ membership_catalog_tier: tier }).eq('id', userId);
    } catch (_) { /* 欄位未建時略過 */ }
}

/** 僅在付費↔免費「轉換」時處理；不掃每次登入。不動種子／平台代管／管理員上傳素材。 */
async function syncMembershipCatalogVisibility(userId) {
    if (!userId) return;
    if (await isStaffProfileUserId(userId)) return;

    const tierNow = (await hasActivePaidSubscription(userId)) ? 'paid' : 'free';
    const tierPrev = await readProfileMembershipCatalogTier(userId);
    if (tierPrev === tierNow) return;

    await writeProfileMembershipCatalogTier(userId, tierNow);
    if (tierPrev === 'paid' && tierNow === 'free') {
        await hideVendorAssetsOnMembershipDowngrade(userId);
        return;
    }
    if (tierPrev === 'free' && tierNow === 'paid') {
        await restoreVendorAssetsAfterMembershipUpgrade(userId);
    }
}

async function hideVendorAssetsOnMembershipDowngrade(userId) {
    const now = new Date().toISOString();
    const { data: mfr } = await supabase
        .from('manufacturers')
        .select('id, vendor_source')
        .eq('user_id', userId)
        .maybeSingle();
    if (!mfr || manufacturerExemptFromMembershipCatalog(mfr)) return;

    let { data: publicRows, error: selErr } = await supabase
        .from('vendor_assets')
        .select('id')
        .eq('manufacturer_id', mfr.id)
        .eq('is_public', true)
        .eq(VENDOR_ASSET_PLATFORM_MANAGED_COL, false);
    if (selErr && selErr.code === '42703') {
        ({ data: publicRows } = await supabase
            .from('vendor_assets')
            .select('id')
            .eq('manufacturer_id', mfr.id)
            .eq('is_public', true));
    }
    const ids = (publicRows || []).map((r) => r.id).filter(Boolean);
    if (!ids.length) return;

    const hide = { is_public: false, updated_at: now };
    hide[VENDOR_ASSET_MEMBERSHIP_HIDE_COL] = true;
    const { error } = await supabase.from('vendor_assets').update(hide).in('id', ids);
    if (error && error.code === '42703') {
        console.warn('syncMembershipCatalogVisibility: 請執行 docs/add-membership-catalog-visibility.sql（勿在無標記欄位時批量下架）');
    } else if (error) {
        console.error('syncMembershipCatalogVisibility hide vendor_assets:', error.message);
    }
}

async function restoreVendorAssetsAfterMembershipUpgrade(userId) {
    const now = new Date().toISOString();
    const { data: mfr } = await supabase
        .from('manufacturers')
        .select('id, vendor_source')
        .eq('user_id', userId)
        .maybeSingle();
    if (!mfr || manufacturerExemptFromMembershipCatalog(mfr)) return;

    const restore = { is_public: true, updated_at: now };
    restore[VENDOR_ASSET_MEMBERSHIP_HIDE_COL] = false;
    const { error } = await supabase
        .from('vendor_assets')
        .update(restore)
        .eq('manufacturer_id', mfr.id)
        .eq(VENDOR_ASSET_MEMBERSHIP_HIDE_COL, true);
    if (error && error.code === '42703') {
        console.warn('vendor_assets.public_hidden_by_membership 未建，無法還原會員下架素材');
    } else if (error) {
        console.error('syncMembershipCatalogVisibility restore vendor_assets:', error.message);
    }
}
// 是否為有效年繳訂閱（duration_months >= 12，用於生圖 6 折）
async function hasAnnualSubscription(userId) {
    if (!userId) return false;
    const now = new Date().toISOString();
    const { data: rows } = await supabase
        .from('user_subscriptions')
        .select('id, subscription_plans(price, duration_months)')
        .eq('user_id', userId)
        .eq('status', 'active')
        .gt('end_date', now);
    if (!rows || rows.length === 0) return false;
    return rows.some(r => (r.subscription_plans && (r.subscription_plans.duration_months || 0) >= 12));
}
// 訂閱會員「我的 AI 編輯區」點數打 6 折（至少 1 點）
async function applyAiEditDiscountForSubscriber(userId, points) {
    if (!userId || points <= 0) return points;
    const isPaid = await hasActivePaidSubscription(userId);
    if (!isPaid) return points;
    return Math.max(1, Math.round(points * 0.6));
}
// 年繳會員點數打 6 折（至少 1 點）
async function applyAnnualDiscount(userId, points) {
    if (!userId || points <= 0) return points;
    const isAnnual = await hasAnnualSubscription(userId);
    if (!isAnnual) return points;
    return Math.max(1, Math.round(points * 0.6));
}

