/** 攝影模擬頁參考圖：產品模式 1 張；人像 1 張人像 + 選填 scene_image + 選填 product_image */
async function resolvePromoCameraReferences(body) {
    const b = body && typeof body === 'object' ? body : {};
    const shootMode = String(b.shoot_mode || 'product').trim().toLowerCase();
    const raw = [];
    if (Array.isArray(b.images)) {
        b.images.forEach(function (x) {
            if (typeof x === 'string' && x.trim()) raw.push(x.trim());
        });
    }
    if (!raw.length && typeof b.image === 'string' && b.image.trim()) raw.push(b.image.trim());
    if (raw.length > 1) {
        return { error: '主參考圖一次只能使用一張（人像場景／道具請用專用欄位另傳）', images: [], urls: [] };
    }
    const main = await resolvePromoImageReferences(Object.assign({}, b, { images: raw.length ? raw : undefined, image: raw.length ? undefined : b.image }));
    if (main.error) return main;

    let stagingProduct = null;
    let sceneReference = null;
    if (shootMode === 'portrait') {
        const sceneResolved = await resolvePromoSceneReferenceImage(b);
        if (sceneResolved && sceneResolved.error) {
            return { error: sceneResolved.error, images: [], urls: [] };
        }
        if (sceneResolved && sceneResolved.base64) sceneReference = sceneResolved;
        const prodResolved = await resolvePromoStagingProductImage(b);
        if (prodResolved && prodResolved.error) {
            return { error: prodResolved.error, images: [], urls: [] };
        }
        if (prodResolved && prodResolved.base64) stagingProduct = prodResolved;
    }

    const images = main.images.slice();
    if (sceneReference && sceneReference.base64) images.push(sceneReference.base64);
    if (stagingProduct && stagingProduct.base64) images.push(stagingProduct.base64);

    return {
        images: images,
        urls: main.urls,
        hasSceneImage: !!(sceneReference && sceneReference.base64),
        sceneImageUrl: (sceneReference && sceneReference.url) || null,
        hasStagingProduct: !!(stagingProduct && stagingProduct.base64),
        stagingProductUrl: (stagingProduct && stagingProduct.url) || null
    };
}

async function loadPromoTemplatePartsByKey(templateKey) {
    const key = String(templateKey || '').trim();
    if (!key) return { prompt: '', composition: '', slot: '', name: '' };
    try {
        let { data, error } = await supabase
            .from('promo_scene_templates')
            .select('name, scene_prompt, composition_hint, is_active, slot')
            .eq('key', key)
            .maybeSingle();
        if (isSupabaseMissingColumnError(error, 'slot')) {
            ({ data, error } = await supabase
                .from('promo_scene_templates')
                .select('name, scene_prompt, composition_hint, is_active')
                .eq('key', key)
                .maybeSingle());
            if (data) data = { ...data, slot: 'theme' };
        }
        if (error || !data || data.is_active === false) return { prompt: '', composition: '', slot: '', name: '' };
        return {
            prompt: String(data.scene_prompt || '').trim(),
            composition: String(data.composition_hint || '').trim(),
            slot: String(data.slot || 'theme'),
            name: String(data.name || '').trim()
        };
    } catch (_) {
        return { prompt: '', composition: '', slot: '', name: '' };
    }
}

/** 從 promo_scene_templates 取出進 FLUX 的片段（不含包裝標籤） */
function collectPromoSceneTemplateParts(theme, scene) {
    const parts = [];
    const t = theme && typeof theme === 'object' ? theme : {};
    const s = scene && typeof scene === 'object' ? scene : {};
    if (t.prompt) parts.push(String(t.prompt).trim());
    if (t.composition) parts.push(String(t.composition).trim());
    if (s.prompt) parts.push(String(s.prompt).trim());
    if (s.composition) parts.push(String(s.composition).trim());
    return parts.filter(Boolean);
}

function joinPromoPromptParts(parts) {
    return (parts || []).map(function (p) { return String(p || '').trim(); }).filter(Boolean).join('. ').trim();
}

/** 情境圖／攝影模擬（有選場景）：新商業環境＋滿版；不寫 letterbox／留白等失敗樣態 */
function promoFluxFillFramePromptPart(width, height) {
    const w = Math.min(2048, Math.max(512, Number(width) || 1024));
    const h = Math.min(2048, Math.max(512, Number(height) || 1024));
    return 'Output one new ' + w + '×' + h + ' commercial photograph with full-bleed composition: environment, lighting, and product extend naturally to all four edges of the frame. Use the reference for product identity only; direct a fresh advertising shot with new framing, crop, and camera angle';
}

/** 攝影模擬（不選場景）：保留原圖場景／環境，延伸填滿輸出尺寸 */
function promoFluxPreserveReferenceScenePromptPart(width, height) {
    const w = Math.min(2048, Math.max(512, Number(width) || 1024));
    const h = Math.min(2048, Math.max(512, Number(height) || 1024));
    return 'Output one ' + w + '×' + h + ' photograph that preserves the reference image\'s existing scene, environment, background, lighting mood, and spatial context — keep the same real-world setting as the reference, not a studio swap or invented location. When the output aspect ratio differs from the reference, naturally extend or reframe within that same scene so the environment and product continuously fill the entire frame edge to edge';
}

/**
 * 情境圖 /api/promo-image/generate 專用（與攝影模擬分離）。
 * 組裝順序：
 * 1) 固定英文廣告底稿（後端硬編碼）
 * 2) theme prompt + composition（DB promo_scene_templates）
 * 3) scene prompt + composition（DB promo_scene_templates）
 * 4) 使用者描述（Advertising brief: …）
 * 5) photography_prompt_sets body_text（選填）
 * 不進 prompt：中文 name／description、攝影模擬七維參數
 */
async function buildPromoImagePrompt(themeKey, sceneKey, userPrompt, photographySetId, referenceCount, width, height) {
    const theme = await loadPromoTemplatePartsByKey(themeKey);
    const scene = await loadPromoTemplatePartsByKey(sceneKey);
    const user = String(userPrompt || '').trim();
    const photo = photographySetId ? await getPhotographySetBodyById(photographySetId) : '';
    const refN = Math.min(8, Math.max(1, parseInt(referenceCount, 10) || 1));
    const parts = [];
    parts.push(promoFluxFillFramePromptPart(width, height));
    parts.push('Shoot and design a brand-new commercial advertising photograph of this product for store ads, DM flyers, and marketing campaigns');
    parts.push('Goal: advertising creative design and new product photography look — NOT retouching, NOT background cleanup, NOT a lightly edited copy of the reference');
    parts.push('CRITICAL FORBIDDEN: keeping the same mannequin pose, crop, framing, camera height, and overall composition while only changing the backdrop or lighting — that is failure');
    parts.push('Create a fresh advertising shot: new camera angle and crop, stronger hero composition, premium commercial lighting, magazine or campaign energy');
    parts.push('The product must remain clearly the same real product (cut, fabric, color, surface details)');
    parts.push('CRITICAL: the product must be clearly visible and immediately recognizable as the advertising hero — show the primary selling face, key design details, color, texture, and form so a viewer knows exactly what is being sold within one second');
    parts.push('The product must occupy a substantial portion of the frame as the focal subject — not a tiny distant object lost in background blur or bokeh');
    parts.push('CRITICAL FORBIDDEN: product lying flat face-down on a surface (back-only view), edge-only sliver, partially hidden under props, or ambiguous placement where the product identity is unclear');
    parts.push('Prefer hero three-quarter or front-facing product presentation suitable for e-commerce and print ads — the product design must read clearly, not just mood or environment');
    parts.push('Use a clean commercial advertising environment that serves the promo; do not invent unrelated lifestyle room stories');
    if (refN > 1) {
        parts.push(
            'Multiple reference images are provided (input_image through input_image_' + refN +
            '). Treat them as product identity references (angles, colorways, variants). ' +
            'Produce ONE newly directed advertising photograph. Image 1 is the primary product unless the brief says otherwise'
        );
    } else {
        parts.push('Treat the reference as product identity only, then shoot a newly directed advertising photograph of that product');
    }
    if (theme.prompt || theme.composition) {
        parts.push('Theme direction (advertising style)');
        if (theme.prompt) parts.push(theme.prompt);
        if (theme.composition) parts.push(theme.composition);
    }
    if (scene.prompt || scene.composition) {
        parts.push('Scene setting (commercial environment for the ad)');
        if (scene.prompt) parts.push(scene.prompt);
        if (scene.composition) parts.push(scene.composition);
    }
    if (user) parts.push('Advertising brief: ' + user);
    let prompt = joinPromoPromptParts(parts);
    prompt = appendPhotographyParams(prompt, photo);
    return prompt || 'Create a brand-new product advertising key visual from the reference with the product clearly visible as the hero subject — not face-down, not back-only, not a background-only retouch.';
}

const PROMO_CAMERA_PARAM_CATEGORIES = [
    'camera_brand', 'film_simulation', 'shooting_angle', 'subject_preservation', 'aperture', 'exposure_ev',
    'lens', 'aperture_blades'
];

const PROMO_CAMERA_LEGACY_LENS_CATEGORIES = ['focal_length', 'lens_type'];

const PROMO_CAMERA_ADMIN_CATEGORIES = PROMO_CAMERA_PARAM_CATEGORIES.concat(PROMO_CAMERA_LEGACY_LENS_CATEGORIES);

const PROMO_CAMERA_FOCAL_LENGTH_TO_LENS = {
    mm35: 'std_35',
    mm50: 'std_50',
    mm85: 'portrait_85',
    mm135: 'portrait_135'
};

/** 攝影模擬控制台 UI 規則（DB 分類表不可用時的 fallback） */
const PROMO_CAMERA_UI_CONFIG = {
    category_labels: {
        camera_brand: '品牌色彩',
        film_simulation: '底片模擬',
        aperture: '光圈',
        exposure_ev: 'EV 曝光',
        lens: '鏡頭',
        shooting_angle: '拍攝角度',
        subject_preservation: '人物／動物',
        focal_length: '焦段（legacy）',
        lens_type: '鏡頭類型（legacy）',
        aperture_blades: '光圈葉片'
    },
    exclusive_groups: [
        {
            id: 'look',
            label: '成像來源',
            categories: ['camera_brand', 'film_simulation'],
            default_category: 'camera_brand'
        }
    ],
    ui_hidden_categories: ['focal_length', 'lens_type'],
    lens_primary_category: 'lens',
    groupable_categories: ['film_simulation', 'lens'],
    group_meta_key: 'group',
    angle_button_category: 'shooting_angle'
};

const PROMO_CAMERA_CATEGORY_SELECT = 'id, key, name, name_en, name_ja, name_es, name_de, name_fr, sort_order, is_active, meta, created_at, updated_at';

function applyPromoCameraCategoryLocale(row, lang) {
    if (!row) return row;
    return applyPromoSceneTemplateLocale(row, lang);
}

function pickPromoCameraGroupLabel(meta, lang) {
    const m = meta && typeof meta === 'object' ? meta : {};
    const base = String(m.group || '').trim();
    if (!lang || lang === 'zh') return base;
    if (lang === 'en' && m.group_en) return String(m.group_en).trim() || base;
    const col = PROMO_SCENE_LOCALE_COL[lang];
    if (col && m['group_' + lang]) return String(m['group_' + lang]).trim() || base;
    return base;
}

function applyPromoCameraOptionLocale(row, lang) {
    if (!row) return row;
    const localized = applyPromoSceneTemplateLocale(row, lang);
    const meta = row.meta && typeof row.meta === 'object' ? Object.assign({}, row.meta) : {};
    const descEn = row.description_en != null && String(row.description_en).trim()
        ? String(row.description_en).trim()
        : (meta.description_en != null ? String(meta.description_en).trim() : '');
    localized.description = pickVendorLocalizedText(row.description, descEn, lang);
    const groupDisplay = pickPromoCameraGroupLabel(meta, lang);
    if (groupDisplay) meta.group_display = groupDisplay;
    localized.meta = meta;
    return localized;
}

function buildPromoCameraUiConfigFromCategories(categories, lang) {
    const rows = (categories || []).slice().sort(function (a, b) {
        return (Number(a.sort_order) || 0) - (Number(b.sort_order) || 0);
    });
    if (!rows.length) return Object.assign({}, PROMO_CAMERA_UI_CONFIG);
    const categoryLabels = {};
    const groupableCategories = [];
    const uiHiddenCategories = [];
    let angleButtonCategory = null;
    let lensPrimaryCategory = 'lens';
    const exclusiveMap = {};
    rows.forEach(function (cat) {
        const key = String(cat.key || '').trim();
        if (!key) return;
        const localized = applyPromoCameraCategoryLocale(cat, lang);
        categoryLabels[key] = localized.name || key;
        const meta = cat.meta && typeof cat.meta === 'object' ? cat.meta : {};
        if (meta.groupable) groupableCategories.push(key);
        if (meta.ui_type === 'hidden') uiHiddenCategories.push(key);
        if (meta.ui_type === 'angle_buttons') angleButtonCategory = key;
        if (meta.lens_primary) lensPrimaryCategory = key;
        const eg = String(meta.exclusive_group || '').trim();
        if (eg) {
            if (!exclusiveMap[eg]) {
                exclusiveMap[eg] = {
                    id: eg,
                    label: meta.exclusive_group_label || eg,
                    label_en: meta.exclusive_group_label_en || null,
                    categories: []
                };
            }
            exclusiveMap[eg].categories.push({
                key: key,
                order: Number(meta.exclusive_group_order) || 0
            });
        }
    });
    const exclusiveGroups = Object.keys(exclusiveMap).map(function (gid) {
        const g = exclusiveMap[gid];
        g.categories.sort(function (a, b) { return a.order - b.order; });
        let label = g.label;
        if (lang === 'en' && g.label_en) label = g.label_en;
        return {
            id: g.id,
            label: label,
            categories: g.categories.map(function (c) { return c.key; }),
            default_category: g.categories.length ? g.categories[0].key : null
        };
    });
    return {
        category_labels: categoryLabels,
        exclusive_groups: exclusiveGroups.length ? exclusiveGroups : PROMO_CAMERA_UI_CONFIG.exclusive_groups,
        ui_hidden_categories: uiHiddenCategories.length ? uiHiddenCategories : PROMO_CAMERA_UI_CONFIG.ui_hidden_categories,
        lens_primary_category: lensPrimaryCategory || PROMO_CAMERA_UI_CONFIG.lens_primary_category,
        groupable_categories: groupableCategories.length ? groupableCategories : PROMO_CAMERA_UI_CONFIG.groupable_categories,
        group_meta_key: 'group',
        angle_button_category: angleButtonCategory || PROMO_CAMERA_UI_CONFIG.angle_button_category
    };
}

async function fetchPromoCameraParamCategories(activeOnly) {
    try {
        let q = supabase.from('promo_camera_param_categories')
            .select(PROMO_CAMERA_CATEGORY_SELECT)
            .order('sort_order', { ascending: true })
            .order('key', { ascending: true });
        if (activeOnly) q = q.eq('is_active', true);
        const { data, error } = await q;
        if (error) {
            if (error.code === '42P01' || isSupabaseMissingTableError(error)) {
                return { categories: [], error: 'MIGRATION_REQUIRED' };
            }
            return { categories: [], error: error.message || 'query_failed' };
        }
        return { categories: data || [], error: null };
    } catch (e) {
        return { categories: [], error: e.message || 'query_failed' };
    }
}

async function getPromoCameraCategoryKeys(activeOnly, includeLegacy) {
    const res = await fetchPromoCameraParamCategories(activeOnly);
    if (res.categories && res.categories.length) {
        return res.categories
            .filter(function (c) { return includeLegacy || String((c.meta && c.meta.ui_type) || '') !== 'hidden'; })
            .map(function (c) { return c.key; })
            .filter(Boolean);
    }
    return includeLegacy ? PROMO_CAMERA_ADMIN_CATEGORIES.slice() : PROMO_CAMERA_PARAM_CATEGORIES.slice();
}

async function isPromoCameraCategoryKeyValid(categoryKey) {
    const key = String(categoryKey || '').trim();
    if (!key) return false;
    if (PROMO_CAMERA_ADMIN_CATEGORIES.includes(key)) return true;
    const res = await fetchPromoCameraParamCategories(false);
    if (res.categories && res.categories.length) {
        return res.categories.some(function (c) { return c.key === key; });
    }
    return false;
}

function normalizePromoCameraCategoryKey(raw) {
    return String(raw || '').trim().toLowerCase().replace(/\s+/g, '_').slice(0, 64);
}

function appendPromoCameraCategoryMultilangFields(payload, body) {
    if (!body || typeof body !== 'object') return payload;
    if (body.name_en !== undefined) payload.name_en = body.name_en != null && String(body.name_en).trim() !== '' ? String(body.name_en).trim() : null;
    for (const col of ['name_ja', 'name_es', 'name_de', 'name_fr']) {
        if (body[col] !== undefined) payload[col] = body[col] != null && String(body[col]).trim() !== '' ? String(body[col]).trim() : null;
    }
    return payload;
}

function buildPromoCameraCategoryMetaFromBody(body) {
    const meta = body && body.meta && typeof body.meta === 'object' ? Object.assign({}, body.meta) : {};
    if (body.ui_type !== undefined) meta.ui_type = String(body.ui_type || 'dropdown').trim() || 'dropdown';
    if (body.groupable !== undefined) meta.groupable = !!body.groupable;
    if (body.lens_primary !== undefined) meta.lens_primary = !!body.lens_primary;
    if (body.exclusive_group !== undefined) {
        const eg = String(body.exclusive_group || '').trim();
        if (eg) meta.exclusive_group = eg;
        else delete meta.exclusive_group;
    }
    if (body.exclusive_group_label !== undefined) meta.exclusive_group_label = String(body.exclusive_group_label || '').trim() || null;
    if (body.exclusive_group_label_en !== undefined) meta.exclusive_group_label_en = String(body.exclusive_group_label_en || '').trim() || null;
    if (body.exclusive_group_order !== undefined) meta.exclusive_group_order = Number(body.exclusive_group_order) || 0;
    return meta;
}

function buildPromoCameraOptionMetaFromBody(body, prevMeta) {
    const meta = prevMeta && typeof prevMeta === 'object' ? Object.assign({}, prevMeta) : {};
    if (body.meta && typeof body.meta === 'object') Object.assign(meta, body.meta);
    if (body.group !== undefined) {
        const g = String(body.group || '').trim();
        if (g) meta.group = g;
        else delete meta.group;
    }
    if (body.group_en !== undefined) {
        const ge = String(body.group_en || '').trim();
        if (ge) meta.group_en = ge;
        else delete meta.group_en;
    }
    for (const lang of ['ja', 'es', 'de', 'fr']) {
        const field = 'group_' + lang;
        if (body[field] !== undefined) {
            const val = String(body[field] || '').trim();
            if (val) meta[field] = val;
            else delete meta[field];
        }
    }
    return meta;
}

function sanitizePromoCameraKeys(cameraKeys, uiConfig) {
    const ui = uiConfig && typeof uiConfig === 'object' ? uiConfig : PROMO_CAMERA_UI_CONFIG;
    const keys = cameraKeys && typeof cameraKeys === 'object' ? { ...cameraKeys } : {};
    const lookGroup = (ui.exclusive_groups || [])[0];
    if (lookGroup && lookGroup.categories && lookGroup.categories.length >= 2) {
        const digitalCat = lookGroup.categories[0];
        const filmCat = lookGroup.categories[1];
        const mode = String(keys._look_mode || '').trim();
        if (mode === 'film') {
            delete keys[digitalCat];
        } else if (mode === 'digital') {
            delete keys[filmCat];
        } else if (keys[digitalCat] && keys[filmCat]) {
            delete keys[filmCat];
        }
    }
    const lensPrimary = ui.lens_primary_category || 'lens';
    if (keys[lensPrimary]) {
        delete keys.focal_length;
        delete keys.lens_type;
    } else if (keys.focal_length) {
        const mapped = PROMO_CAMERA_FOCAL_LENGTH_TO_LENS[normalizePromoCameraParamKey(keys.focal_length)];
        if (mapped) keys.lens = mapped;
        delete keys.focal_length;
        delete keys.lens_type;
    }
    delete keys._look_mode;
    return keys;
}

function normalizePromoCameraParamKey(raw) {
    return String(raw || '').trim().toLowerCase().replace(/\s+/g, '_').slice(0, 64);
}

