// GET /api/manufacturers — 依分類取得廠商清單（訂製品設計者「找製作方」用）
// Query: category（單一分類，舊版相容） 或 category_key + subcategory_key（子分類優先，不足一頁用主分類填滿）
// 當有 category_key 時：先查 subcategory_key 符合的製作方，不足 per_page 時用 category_key 補滿一頁（子分類排前、去重）
app.get('/api/manufacturers', async (req, res) => {
    try {
        const category = req.query.category;
        const category_key = req.query.category_key || req.query.categoryKey;
        const subcategory_key = req.query.subcategory_key || req.query.subcategoryKey;
        const q = (req.query.q || '').trim();
        const per_page = Math.min(Math.max(parseInt(req.query.per_page || req.query.perPage, 10) || 12, 1), 50);
        const page = Math.max(parseInt(req.query.page, 10) || 1, 1);

        const internalPreview = await getRequestInternalPreviewFlag(req);
        const baseSelect = 'id, name, description, location, rating, contact_json, capabilities, verified, categories, user_id, logo_url, vendor_source, expires_at, seed_public_released_at, is_active';
        let manufacturers = [];
        let fromSub = [];
        let fromMain = [];

        function filterMfrListForAudience(list) {
            return (list || []).filter(function (m) {
                if (internalPreview) return m.is_active !== false;
                return manufacturerVisibleToPublicAudience(m);
            });
        }

        if (category_key || subcategory_key) {
            const expiresFilter = manufacturerVisibleExpiresFilter();
            if (subcategory_key) {
                let subQ = supabase.from('manufacturers').select(baseSelect).eq('is_active', true).contains('categories', [subcategory_key]);
                try { subQ = subQ.or(expiresFilter); } catch (_) {}
                const { data: subList, error: eSub } = await subQ;
                if (!eSub && subList) fromSub = subList;
            }
            const subIds = new Set(fromSub.map(m => m.id));
            if (category_key) {
                let mainQ = supabase.from('manufacturers').select(baseSelect).eq('is_active', true).contains('categories', [category_key]);
                try { mainQ = mainQ.or(expiresFilter); } catch (_) {}
                const { data: mainList, error: eMain } = await mainQ;
                if (!eMain && mainList) fromMain = mainList.filter(m => !subIds.has(m.id));
            }
            manufacturers = filterMfrListForAudience([...fromSub, ...fromMain]);
            // 關鍵字過濾
            if (q) {
                const ql = q.toLowerCase();
                manufacturers = manufacturers.filter(m =>
                    (m.name || '').toLowerCase().includes(ql) ||
                    (m.description || '').toLowerCase().includes(ql)
                );
            }
            const start = (page - 1) * per_page;
            manufacturers = manufacturers.slice(start, start + per_page);
        } else if (category && category !== 'default') {
            let catQ = supabase.from('manufacturers').select(baseSelect).eq('is_active', true).contains('categories', [category]);
            try { catQ = catQ.or(manufacturerVisibleExpiresFilter()); } catch (_) {}
            const { data, error } = await catQ;
            if (error) {
                console.error('GET /api/manufacturers 查詢失敗:', error);
                return res.status(500).json({ error: '查詢廠商失敗' });
            }
            manufacturers = filterMfrListForAudience(data || []);
            if (q) {
                const ql = q.toLowerCase();
                manufacturers = manufacturers.filter(m =>
                    (m.name || '').toLowerCase().includes(ql) ||
                    (m.description || '').toLowerCase().includes(ql)
                );
            }
            const start = (page - 1) * per_page;
            manufacturers = manufacturers.slice(start, start + per_page);
        } else {
            let query = supabase.from('manufacturers').select(baseSelect).eq('is_active', true).order('rating', { ascending: false });
            try { query = query.or(manufacturerVisibleExpiresFilter()); } catch (_) {}
            if (q) {
                query = query.or(`name.ilike.%${q}%,description.ilike.%${q}%`);
            }
            const { data, error } = await query;
            if (error) {
                if (error.code === '42703') {
                    const fallbackSelect = 'id, name, description, location, rating, contact_json, capabilities, verified, categories, user_id, logo_url, is_active, expires_at';
                    let q2 = supabase.from('manufacturers').select(fallbackSelect).eq('is_active', true).order('rating', { ascending: false });
                    try { q2 = q2.or(manufacturerVisibleExpiresFilter()); } catch (_) {}
                    const r2 = await q2;
                    if (r2.error) {
                        console.error('GET /api/manufacturers 查詢失敗:', r2.error);
                        return res.status(500).json({ error: '查詢廠商失敗' });
                    }
                    manufacturers = filterMfrListForAudience((r2.data || []).map(function (m) {
                        return { ...m, vendor_source: null, seed_public_released_at: null };
                    }));
                } else {
                    console.error('GET /api/manufacturers 查詢失敗:', error);
                    return res.status(500).json({ error: '查詢廠商失敗' });
                }
            } else {
                manufacturers = filterMfrListForAudience(data || []);
            }
            const start = (page - 1) * per_page;
            manufacturers = manufacturers.slice(start, start + per_page);
        }

        const ids = manufacturers.map(m => m.id);
        let portfolioByMfr = {};
        if (ids.length > 0) {
            const { data: portfolios } = await supabase
                .from('manufacturer_portfolio')
                .select('id, manufacturer_id, title, image_url, image_url_before, design_highlight, tags, sort_order, min_order_quantity')
                .in('manufacturer_id', ids)
                .order('sort_order', { ascending: true });
            (portfolios || []).forEach(p => {
                if (!portfolioByMfr[p.manufacturer_id]) portfolioByMfr[p.manufacturer_id] = [];
                portfolioByMfr[p.manufacturer_id].push({ id: p.id, title: p.title, image_url: p.image_url, image_url_before: p.image_url_before || null, design_highlight: p.design_highlight || null, tags: p.tags || [], min_order_quantity: (p.min_order_quantity != null && Number.isFinite(Number(p.min_order_quantity))) ? Number(p.min_order_quantity) : null });
            });
        }

        const list = manufacturers.map(mfr => ({
            id: mfr.id,
            name: mfr.name,
            specialty: mfr.description || mfr.name,
            rating: mfr.rating,
            location: mfr.location,
            capabilities: mfr.capabilities,
            contact: mfr.contact_json,
            verified: mfr.verified,
            categories: mfr.categories || [],
            user_id: mfr.user_id || null,
            logo_url: manufacturerLogoFromRow(mfr),
            portfolio: portfolioByMfr[mfr.id] || []
        })).sort((a, b) => (b.rating || 0) - (a.rating || 0));

        res.json({ manufacturers: list });
    } catch (e) {
        console.error('GET /api/manufacturers 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/manufacturers/:id — 單一廠商詳情（vendor-profile.html 用）
// 不篩 is_active：從靈感牆對照圖/系列圖點進來的廠商應能開啟詳情頁；若已過 expires_at 則 404
app.get('/api/manufacturers/:id', async (req, res) => {
    const { id } = req.params;
    const contentLang = normalizeVendorContentLang(req.query.lang);
    try {
        const internalPreview = await getRequestInternalPreviewFlag(req);
        const fullSelect = 'id, name, name_en, description, description_en, location, rating, contact_json, capabilities, verified, categories, user_id, logo_url, is_active, expires_at, vendor_source, seed_public_released_at';
        let resq = await supabase.from('manufacturers').select(fullSelect).eq('id', id).maybeSingle();
        if (!resq.error && !resq.data) {
            resq = await supabase.from('manufacturers').select(fullSelect).eq('user_id', id).maybeSingle();
        }
        if (!resq.error && !resq.data) {
            const { data: assetRow } = await supabase.from('vendor_assets').select('manufacturer_id').eq('id', id).maybeSingle();
            if (assetRow && assetRow.manufacturer_id) {
                resq = await supabase.from('manufacturers').select(fullSelect).eq('id', assetRow.manufacturer_id).maybeSingle();
            }
        }

        if (resq.error) {
            console.warn('GET /api/manufacturers/:id 完整查詢失敗:', resq.error.code, resq.error.message);
            resq = await supabase.from('manufacturers').select('id, name, description, location, contact_json, categories, expires_at').eq('id', id).maybeSingle();
            if (!resq.error && resq.data) {
                resq.data.name_en = null;
                resq.data.description_en = null;
            }
            if (!resq.error && !resq.data) {
                resq = await supabase.from('manufacturers').select('id, name, description, location, contact_json, categories, expires_at').eq('user_id', id).maybeSingle();
            }
            if (!resq.error && !resq.data) {
                const { data: assetRow } = await supabase.from('vendor_assets').select('manufacturer_id').eq('id', id).maybeSingle();
                if (assetRow && assetRow.manufacturer_id) {
                    resq = await supabase.from('manufacturers').select('id, name, description, location, contact_json, categories, expires_at').eq('id', assetRow.manufacturer_id).maybeSingle();
                }
            }
            if (!resq.error && resq.data) {
                resq.data.rating = null;
                resq.data.capabilities = null;
                resq.data.verified = null;
                resq.data.is_active = true;
                resq.data.user_id = null;
                resq.data.logo_url = null;
            }
        }
        if (resq.error) {
            console.error('GET /api/manufacturers/:id 查詢失敗:', resq.error);
            return res.status(500).json({ error: '查詢失敗', detail: resq.error.message });
        }
        const mfr = resq.data;
        if (!mfr) return res.status(404).json({ error: '廠商不存在' });
        const authUser = await getRequestUserFromAuthHeader(req);
        let ownerPreview = !!(authUser && mfr.user_id && authUser.id === mfr.user_id);
        if (!ownerPreview && authUser && mfr.id) {
            const { data: ownedRow } = await supabase
                .from('manufacturers')
                .select('id')
                .eq('id', mfr.id)
                .eq('user_id', authUser.id)
                .maybeSingle();
            ownerPreview = !!ownedRow;
        }
        const profileEligible = await manufacturerEligibleForProfilePage(mfr, { internalPreview, ownerPreview });
        if (!profileEligible) {
            if (manufacturerIsSeedVendor(mfr) && !manufacturerSeedPublicReleased(mfr)) {
                return res.status(404).json({ error: '此廠商尚未對外開放展示。' });
            }
            if (mfr.is_active === false) return res.status(404).json({ error: '此廠商已下架。' });
            return res.status(404).json({ error: '找不到廠商' });
        }
        if (mfr.expires_at && new Date(mfr.expires_at) <= new Date()) {
            if (!internalPreview && !ownerPreview) {
                return res.status(404).json({ error: '此廠商已過公開期。如需繼續曝光請至挖貝升級付費方案。' });
            }
        }

        const mfrId = mfr.id;
        let portfolio = [];
        const portSelect = 'id, title, title_en, description, description_en, image_url, image_url_before, design_highlight, design_highlight_en, tags, category_key, subcategory_key, sort_order, min_order_quantity, series_image_urls, series_image_valid_until';
        let portRes = await supabase
            .from('manufacturer_portfolio')
            .select(portSelect)
            .eq('manufacturer_id', mfrId)
            .order('sort_order', { ascending: true });
        if (portRes.error && portRes.error.code === '42703') {
            portRes = await supabase
                .from('manufacturer_portfolio')
                .select('id, title, title_en, description, description_en, image_url, image_url_before, design_highlight, design_highlight_en, tags, category_key, subcategory_key, sort_order, min_order_quantity')
                .eq('manufacturer_id', mfrId)
                .order('sort_order', { ascending: true });
            if (portRes.error && portRes.error.code === '42703') {
                portRes = await supabase
                    .from('manufacturer_portfolio')
                    .select('id, title, description, image_url, image_url_before, design_highlight, tags, category_key, subcategory_key, sort_order, min_order_quantity')
                    .eq('manufacturer_id', mfrId)
                    .order('sort_order', { ascending: true });
            }
        }
        if (portRes.error) {
            console.warn('GET /api/manufacturers/:id portfolio 查詢失敗:', portRes.error.message);
        } else {
            portfolio = (portRes.data || []).map((p) => mapPortfolioItemForLocale(p, contentLang));
        }

        const displayName = pickVendorLocalizedText(mfr.name, mfr.name_en, contentLang) || mfr.name;
        const displayDesc = pickVendorLocalizedText(mfr.description, mfr.description_en, contentLang);

        res.json({
            id: mfr.id,
            name: displayName,
            name_zh: mfr.name || '',
            name_en: mfr.name_en || '',
            specialty: displayDesc || '',
            description: displayDesc || '',
            description_zh: mfr.description || '',
            description_en: mfr.description_en || '',
            lang: contentLang,
            rating: mfr.rating,
            location: mfr.location,
            capabilities: mfr.capabilities,
            contact: attachStoreUrlsToContactJson(mfr.contact_json),
            verified: mfr.verified,
            categories: mfr.categories || [],
            user_id: mfr.user_id || null,
            logo_url: manufacturerLogoFromRow(mfr),
            portfolio
        });
    } catch (e) {
        console.error('GET /api/manufacturers/:id 異常:', e);
        res.status(500).json({ error: '系統錯誤', detail: e.message });
    }
});

// GET /api/manufacturer-portfolio — 廠商作品圖列表（圖庫找廠商、從圖庫選擇、純文字搜廠商圖）
// Query: manufacturer_id（單一廠商）, category（依廠商分類篩選）, keyword / q（搜尋 title、tags）
/** @param {unknown} raw @param {{ forUpdate?: boolean }} [opts] */
function parseManufacturerPortfolioMinOrderQty(raw, opts) {
    const forUpdate = opts && opts.forUpdate;
    if (raw === undefined) {
        if (forUpdate) return { omit: true };
        return { value: null };
    }
    if (raw === null) return { value: null };
    const s = String(raw).trim();
    if (s === '' || s.toLowerCase() === 'null') return { value: null };
    const n = parseInt(s, 10);
    if (!Number.isFinite(n) || n < 1) return { error: '最小可訂製數量須為 1 以上的整數，或留空表示未填寫' };
    return { value: n };
}

const MANUFACTURER_PORTFOLIO_SELECT_FULL = 'id, manufacturer_id, title, description, image_url, image_url_before, design_highlight, tags, ai_tags, sort_order, created_at, category_key, subcategory_key, category_type, series_image_valid_until, before_image_valid_until, series_image_urls, show_on_media_wall, min_order_quantity, customization_levels';
const MANUFACTURER_PORTFOLIO_SELECT_BASE = 'id, manufacturer_id, title, description, image_url, image_url_before, design_highlight, tags, sort_order, created_at, category_key, subcategory_key, category_type, min_order_quantity, customization_levels';
const MANUFACTURER_PORTFOLIO_SELECT_CATEGORY_MIN = 'id, manufacturer_id, title, description, image_url, image_url_before, design_highlight, tags, sort_order, created_at, category_key, subcategory_key, category_type, show_on_media_wall, min_order_quantity, customization_levels';
const MANUFACTURER_PORTFOLIO_SELECT_CATEGORY_ONLY = 'id, manufacturer_id, title, description, image_url, image_url_before, design_highlight, tags, sort_order, created_at, category_key, subcategory_key, category_type, min_order_quantity, customization_levels';
const MANUFACTURER_PORTFOLIO_LIST_SELECT_FALLBACKS = [
    MANUFACTURER_PORTFOLIO_SELECT_FULL,
    MANUFACTURER_PORTFOLIO_SELECT_CATEGORY_MIN,
    MANUFACTURER_PORTFOLIO_SELECT_CATEGORY_ONLY,
    MANUFACTURER_PORTFOLIO_SELECT_BASE
];
const MANUFACTURER_PORTFOLIO_INSERT_SELECT = 'id, manufacturer_id, title, description, design_highlight, image_url, image_url_before, tags, sort_order, category_key, subcategory_key, created_at, min_order_quantity, ai_tags';

const MANUFACTURER_PORTFOLIO_OPTIONAL_INSERT_COLS = [
    'series_image_urls', 'series_image_valid_until', 'before_image_valid_until',
    'show_on_media_wall', 'customization_levels',
    'ai_tags', 'image_semantics_json', 'tags_source', 'ai_tags_generated_at'
];

const MANUFACTURER_PORTFOLIO_REQUIRED_COLS = ['category_key', 'subcategory_key', 'category_type', 'min_order_quantity'];

const MANUFACTURER_PORTFOLIO_UPDATE_SELECT = 'id, manufacturer_id, title, description, design_highlight, image_url, image_url_before, tags, ai_tags, sort_order, category_key, subcategory_key, category_type, show_on_media_wall, min_order_quantity, customization_levels, series_image_urls';

function validateManufacturerPortfolioCategoryKeys(categoryKey, subcategoryKey, opts) {
    const allowEmptySubcategory = !!(opts && opts.allowEmptySubcategory);
    const ck = (categoryKey != null ? String(categoryKey) : '').trim();
    const sk = (subcategoryKey != null ? String(subcategoryKey) : '').trim();
    if (!ck) return '請選擇主分類';
    if (!allowEmptySubcategory && !sk) return '請選擇子分類';
    return null;
}

function portfolioCategoryColumnHint(error) {
    if (!isSupabaseMissingColumnError(error)) return '';
    const msg = String(error.message || '');
    if (msg.includes('category_key') || msg.includes('subcategory_key') || msg.includes('category_type')) {
        return '（資料庫缺少分類欄位，請執行 docs/manufacturer-portfolio-add-all-missing-columns.sql）';
    }
    if (msg.includes('min_order_quantity')) {
        return '（資料庫缺少 min_order_quantity 欄位，請執行 docs/manufacturer-portfolio-add-all-missing-columns.sql）';
    }
    if (msg.includes('customization_levels')) {
        return '（資料庫缺少 customization_levels 欄位，請執行 docs/manufacturer-portfolio-add-all-missing-columns.sql）';
    }
    return '';
}

/** 列表查詢：依序嘗試含 category_key 的 select，避免缺 ai_tags/series 欄位時 fallback 掉分類 */
async function queryManufacturerPortfolioRows(buildQuery) {
    let lastError = null;
    for (const selectCols of MANUFACTURER_PORTFOLIO_LIST_SELECT_FALLBACKS) {
        const { data, error } = await buildQuery(supabase.from('manufacturer_portfolio').select(selectCols));
        if (!error) return { data: data || [], error: null, selectCols };
        if (!isSupabaseMissingColumnError(error)) return { data: null, error, selectCols: null };
        lastError = error;
        console.warn('manufacturer_portfolio list select fallback:', error.message);
    }
    return { data: null, error: lastError || new Error('queryManufacturerPortfolioRows failed'), selectCols: null };
}

function mapManufacturerPortfolioListItems(list, mfrMap) {
    const now = new Date();
    return (list || []).map((p) => {
        const seriesExpired = p.series_image_valid_until && now > new Date(p.series_image_valid_until);
        const beforeExpired = p.before_image_valid_until && now > new Date(p.before_image_valid_until);
        const seriesUrls = (Array.isArray(p.series_image_urls) && p.series_image_urls.length) ? p.series_image_urls : (p.image_url ? [p.image_url] : []);
        return {
            id: p.id,
            manufacturer_id: p.manufacturer_id,
            manufacturer_name: mfrMap[p.manufacturer_id]?.name || '',
            manufacturer_location: mfrMap[p.manufacturer_id]?.location || '',
            manufacturer_contact: mfrMap[p.manufacturer_id]?.contact_json || null,
            manufacturer_user_id: mfrMap[p.manufacturer_id]?.user_id || null,
            categories: mfrMap[p.manufacturer_id]?.categories || [],
            title: p.title,
            description: p.description,
            image_url: seriesExpired ? null : (p.image_url || null),
            series_image_urls: seriesExpired ? [] : seriesUrls,
            image_url_before: beforeExpired ? null : (p.image_url_before || null),
            design_highlight: p.design_highlight || null,
            tags: p.tags || [],
            ai_tags: p.ai_tags || [],
            sort_order: p.sort_order,
            category_key: p.category_key || null,
            subcategory_key: p.subcategory_key || null,
            category_type: p.category_type || null,
            show_on_media_wall: p.show_on_media_wall !== false,
            min_order_quantity: (p.min_order_quantity != null && Number.isFinite(Number(p.min_order_quantity))) ? Number(p.min_order_quantity) : null,
            customization_levels: sanitizeCustomizationLevelsForStorage(p.customization_levels)
        };
    });
}

async function insertManufacturerPortfolioRow(payload) {
    const row = { ...payload };
    let selectCols = MANUFACTURER_PORTFOLIO_INSERT_SELECT;
    for (let attempt = 0; attempt < 16; attempt++) {
        const { data, error } = await supabase.from('manufacturer_portfolio').insert(row).select(selectCols).single();
        if (!error) return { data, error: null };
        if (!isSupabaseMissingColumnError(error)) return { data: null, error };
        const msg = String(error.message || '');
        let stripped = false;
        for (const col of MANUFACTURER_PORTFOLIO_OPTIONAL_INSERT_COLS) {
            if (msg.includes(col) && Object.prototype.hasOwnProperty.call(row, col)) {
                delete row[col];
                stripped = true;
            }
        }
        if (!stripped) {
            const msg = String(error.message || '');
            if (MANUFACTURER_PORTFOLIO_REQUIRED_COLS.some((c) => msg.includes(c) && Object.prototype.hasOwnProperty.call(row, c))) {
                return { data: null, error };
            }
            const parts = selectCols.split(',').map((c) => c.trim()).filter(Boolean);
            const badSel = parts.find((c) => msg.includes(c));
            if (badSel) {
                selectCols = parts.filter((c) => c !== badSel).join(', ');
                stripped = true;
            }
        }
        if (!stripped) return { data: null, error };
    }
    return { data: null, error: new Error('insert retries exhausted') };
}

