/** 相對路徑／protocol-relative → 可 fetch 的絕對 URL（版型／設計稿共用） */
function resolveFetchableImageUrl(imageUrl) {
    const u = String(imageUrl || '').trim();
    if (!u || /^data:/i.test(u)) return '';
    if (/^https?:\/\//i.test(u)) return u;
    if (u.startsWith('//')) return 'https:' + u;
    const base = String(BASE_URL || process.env.PUBLIC_SITE_URL || 'https://matchdo.cc').replace(/\/$/, '');
    return base + (u.startsWith('/') ? u : '/' + u);
}

async function fetchPortfolioImageFileFromUrl(imageUrl) {
    const url = resolveFetchableImageUrl(imageUrl);
    if (!url) return null;
    const deps = getVisualSemanticsDeps();
    const resImg = await deps.fetch(url, { redirect: 'follow' });
    if (!resImg.ok) return null;
    const imgBuf = Buffer.from(await resImg.arrayBuffer());
    const imgMime = (resImg.headers.get('content-type') || 'image/jpeg').split(';')[0].trim();
    return normalizeVendorUploadFile({
        buffer: imgBuf,
        mimetype: imgMime,
        originalname: 'portfolio.jpg'
    });
}

async function tryPortfolioSemanticsFromUrls(imageUrl, imageUrlBefore, context, ownerId, portfolioId) {
    const primary = (imageUrl || '').trim();
    if (!primary || !process.env.GEMINI_API_KEY) return null;
    try {
        const fileEntries = [];
        const afterFile = await fetchPortfolioImageFileFromUrl(primary);
        if (!afterFile) return null;
        fileEntries.push({ file: afterFile, label: '作品圖' });
        const before = (imageUrlBefore || '').trim();
        if (before) {
            const beforeFile = await fetchPortfolioImageFileFromUrl(before);
            if (beforeFile) fileEntries.push({ file: beforeFile, label: '設計圖' });
        }
        const semanticsCtx = await vendorAssetSemanticsContextFields({
            asset_kind: 'prototype',
            category_key: (context && context.category_key) || '',
            subcategory_key: (context && context.subcategory_key) || '',
            title: (context && context.title) || '',
            description: (context && context.description) || '',
            design_highlight: (context && context.design_highlight) || '',
            image_url: primary
        });
        const result = await runVendorAssetImageSemanticsFromFiles(fileEntries, semanticsCtx, ownerId);
        await recordVisualSemanticsEvent({
            source_type: 'portfolio',
            source_id: portfolioId || null,
            image_url: primary,
            text_input: fileEntries.length > 1 ? 'comparison:2' : null,
            semantics_kind: 'image',
            ai_tags: result.tags,
            semantics_json: result.semantics,
            model: result.model,
            prompt_version: result.prompt_version,
            owner_id: ownerId || null,
            category_key: semanticsCtx.category_key || null
        });
        return { ...result, description: result.description || vendorAssetDescriptionFromSemantics(result.semantics) || null };
    } catch (e) {
        console.warn('tryPortfolioSemanticsFromUrls:', e.message || e);
        return null;
    }
}

app.get('/api/manufacturer-portfolio', async (req, res) => {
    try {
        const { manufacturer_id, category, keyword, q } = req.query;
        const search = keyword || q;

        let manufacturerIdsFilter = null;
        if (category && category !== 'default') {
            let mfrQ = supabase.from('manufacturers').select('id').eq('is_active', true).contains('categories', [category]);
            try { mfrQ = mfrQ.or(manufacturerVisibleExpiresFilter()); } catch (_) {}
            const { data: mfrIds } = await mfrQ;
            manufacturerIdsFilter = (mfrIds || []).map(m => m.id);
            if (manufacturerIdsFilter.length === 0) return res.json({ items: [] });
        }

        const { data: items, error } = await queryManufacturerPortfolioRows((q) => {
            let query = q;
            if (manufacturer_id) query = query.eq('manufacturer_id', manufacturer_id);
            if (manufacturerIdsFilter) query = query.in('manufacturer_id', manufacturerIdsFilter);
            return query.order('sort_order', { ascending: true }).order('created_at', { ascending: false });
        });

        if (error) {
            console.error('GET /api/manufacturer-portfolio 失敗:', error);
            const hint = portfolioCategoryColumnHint(error);
            return res.status(500).json({ error: '查詢作品圖失敗' + hint });
        }

        let list = items || [];
        if (search && String(search).trim()) {
            const k = String(search).trim().toLowerCase();
            list = list.filter(p => {
                const titleMatch = (p.title || '').toLowerCase().includes(k);
                const tagsMatch = Array.isArray(p.tags) && p.tags.some(t => String(t).toLowerCase().includes(k));
                const highlightMatch = (p.design_highlight || '').toLowerCase().includes(k);
                return titleMatch || tagsMatch || highlightMatch;
            });
        }

        const internalPreview = await getRequestInternalPreviewFlag(req);
        list = await manufacturerAudience.filterPortfolioRowsForAudience(supabase, list, { internalPreview: internalPreview });

        const mfrIds = [...new Set(list.map(p => p.manufacturer_id).filter(Boolean))];
        let mfrMap = {};
        if (mfrIds.length > 0) {
            const { data: mfrs } = await supabase.from('manufacturers').select('id, name, location, categories, contact_json, user_id').in('id', mfrIds);
            (mfrs || []).forEach(m => { mfrMap[m.id] = m; });
        }

        const result = mapManufacturerPortfolioListItems(list, mfrMap);

        if (result.length === 0) {
            console.warn('GET /api/manufacturer-portfolio 回傳 0 筆。若首頁媒體牆有廠商作品，請確認 .env 已設 SUPABASE_SERVICE_ROLE_KEY 並在 Supabase 執行過 docs/seed-manufacturers-and-portfolio.sql');
        }
        res.json({ items: result });
    } catch (e) {
        console.error('GET /api/manufacturer-portfolio 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

