// POST /api/manufacturers/:id/portfolio — 上傳廠商作品圖（系列圖＝1800 方案；對照圖＝所有人）
app.post('/api/manufacturers/:id/portfolio', upload.fields([{ name: 'image', maxCount: 10 }, { name: 'image_before', maxCount: 1 }]), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const manufacturerId = req.params.id;
        const body = req.body || {};
        const { title, description, design_highlight, tags: tagsParam, image_url: bodyImageUrl, image_url_before: bodyImageUrlBefore, category_key: bodyCategoryKey, subcategory_key: bodySubcategoryKey, category_type: bodyCategoryType, show_on_media_wall: bodyShowOnMediaWall, upload_type: bodyUploadType } = body;
        const moqPost = parseManufacturerPortfolioMinOrderQty(body.min_order_quantity);
        if (moqPost.error) return res.status(400).json({ error: moqPost.error });
        const tags = Array.isArray(tagsParam) ? tagsParam : (typeof tagsParam === 'string' && tagsParam ? tagsParam.split(/[,，\s]+/).filter(Boolean) : []);
        const categoryKey = (bodyCategoryKey != null && String(bodyCategoryKey).trim()) ? String(bodyCategoryKey).trim() : null;
        const subcategoryKey = (bodySubcategoryKey != null && String(bodySubcategoryKey).trim()) ? String(bodySubcategoryKey).trim() : null;
        const allowEmptySubcategory = String(bodyUploadType || '').toLowerCase() === 'series';
        const categoryErr = validateManufacturerPortfolioCategoryKeys(categoryKey, subcategoryKey, { allowEmptySubcategory });
        if (categoryErr) return res.status(400).json({ error: categoryErr });
        const clValidPost = validatePrototypeCustomizationLevels(body.customization_levels);
        if (clValidPost.error) return res.status(400).json({ error: clValidPost.error });
        const categoryType = (bodyCategoryType === 'remake') ? 'remake' : 'custom';

        const files = req.files || {};
        const rawImages = files.image;
        const mainFiles = Array.isArray(rawImages) ? rawImages : (rawImages ? [rawImages] : []);
        const mainFile = mainFiles[0] || null;
        const beforeFile = (files.image_before && files.image_before[0]) || null;

        const { data: mfr } = await supabase.from('manufacturers').select('id, user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfr) return res.status(404).json({ error: '找不到該廠商' });
        const isAdmin = await isAdminUserId(user.id);
        if (mfr.user_id !== user.id && !isAdmin) return res.status(403).json({ error: '僅廠商本人或管理員可上傳作品' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfr, res)) return;

        const bypassPortfolioPaywall = isAdmin || await canUploadPortfolioBypassPlanAndPoints(user.id);

        if (mainFiles.length === 0 && !beforeFile && !bodyImageUrl) {
            return res.status(400).json({ error: '請上傳系列圖（多張可），或對照圖前、後兩張' });
        }

        const uploadTypePost = String(bodyUploadType || '').toLowerCase();
        const isComparisonUpload = uploadTypePost === 'comparison' || (!!beforeFile && !!mainFile);
        const beforeFileUsedAsBefore = isComparisonUpload && !!beforeFile && !!mainFile;

        let pointsDeductedPost = 0;
        if (!bypassPortfolioPaywall) {
            if (beforeFileUsedAsBefore) {
                const compPts = await getPointsPortfolioComparisonCreate();
                const deductBefore = await deductPortfolioBeforePoints(user.id);
                if (deductBefore === null) {
                    return res.status(403).json({ error: `對照圖首次建立需付 ${compPts} 點（點數不足）` });
                }
                pointsDeductedPost = deductBefore.pointsDeducted || 0;
            } else if (mainFiles.length > 0) {
                const seriesPts = await getPointsPortfolioSeriesCreate();
                const deductSeries = await deductPortfolioSeriesPoints(user.id);
                if (deductSeries === null) {
                    return res.status(403).json({ error: `系列圖首次建立需付 ${seriesPts} 點（點數不足）` });
                }
                pointsDeductedPost = deductSeries.pointsDeducted || 0;
            }
        }

        let imageUrl = bodyImageUrl;
        let seriesImageUrls = [];
        if (mainFiles.length > 0) {
            for (const f of mainFiles) {
                const { publicUrl } = await uploadToSupabaseStorage('custom-products', `manufacturer/${manufacturerId}`, f);
                seriesImageUrls.push(publicUrl);
            }
            imageUrl = seriesImageUrls[0];
        }

        let imageUrlBefore = bodyImageUrlBefore || null;
        if (beforeFileUsedAsBefore && beforeFile) {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', `manufacturer/${manufacturerId}`, beforeFile);
            imageUrlBefore = publicUrl;
        }

        // 對照圖＝一筆作品：設計圖存 image_url_before、作品圖存 image_url，絕不分開存兩筆
        const insertPayload = {
            manufacturer_id: manufacturerId,
            title: title || null,
            description: description || null,
            design_highlight: design_highlight || null,
            image_url: imageUrl,
            image_url_before: imageUrlBefore,
            tags: tags.length ? tags : [],
            category_key: categoryKey,
            subcategory_key: subcategoryKey,
            category_type: categoryType,
            show_on_media_wall: manufacturerAudience.seedVendorPortfolioShowOnMediaWall(mfr, bodyShowOnMediaWall),
            min_order_quantity: moqPost.value,
            customization_levels: clValidPost.levels
        };
        // 健康邏輯：純系列才寫 series_image_urls，且 image_url_before 必為 null；對照圖不寫 series_image_urls
        if (seriesImageUrls.length > 0 && !beforeFileUsedAsBefore) insertPayload.series_image_urls = seriesImageUrls;
        if (!beforeFileUsedAsBefore) insertPayload.image_url_before = null;

        if (!imageUrl) return res.status(400).json({ error: '請上傳作品圖' });

        const { data: inserted, error } = await insertManufacturerPortfolioRow(insertPayload);

        if (error) {
            console.error('POST /api/manufacturers/:id/portfolio 失敗:', error);
            const catHint = portfolioCategoryColumnHint(error);
            const hint = catHint || (isSupabaseMissingColumnError(error)
                ? '（資料庫欄位未齊，請執行 docs/manufacturer-portfolio-add-all-missing-columns.sql 與 docs/add-digital-prototype-ai-tags.sql）'
                : '');
            return res.status(500).json({ error: '新增作品圖失敗' + hint });
        }

        res.status(201).json({
            ...inserted,
            customization_levels: clValidPost.levels,
            points_deducted: pointsDeductedPost
        });
    } catch (e) {
        console.error('POST /api/manufacturers/:id/portfolio 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/manufacturers/:manufacturerId/portfolio/reorder — 拖曳排序後批次更新 sort_order（廠商頁作品集順序）
app.post('/api/manufacturers/:manufacturerId/portfolio/reorder', express.json(), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const { manufacturerId } = req.params;
        const { data: mfrRow } = await supabase.from('manufacturers').select('user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfrRow) return res.status(404).json({ error: '找不到該廠商' });
        const isAdmin = await isAdminUserId(user.id);
        if (mfrRow.user_id !== user.id && !isAdmin) return res.status(403).json({ error: '僅廠商本人或管理員可調整作品順序' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfrRow, res)) return;
        const order = req.body && req.body.order;
        if (!Array.isArray(order) || !order.length) {
            return res.status(400).json({ error: '請提供 order 陣列（作品 id 順序）' });
        }
        const ids = order.map((id) => String(id).trim()).filter(Boolean);
        const { data: existing } = await supabase
            .from('manufacturer_portfolio')
            .select('id')
            .eq('manufacturer_id', manufacturerId);
        const allowed = new Set((existing || []).map((r) => r.id));
        if (!ids.every((id) => allowed.has(id))) {
            return res.status(400).json({ error: 'order 含有不屬於此廠商的作品' });
        }
        for (let i = 0; i < ids.length; i++) {
            const { error } = await supabase
                .from('manufacturer_portfolio')
                .update({ sort_order: i, updated_at: new Date().toISOString() })
                .eq('id', ids[i])
                .eq('manufacturer_id', manufacturerId);
            if (error) return res.status(500).json({ error: '排序儲存失敗' });
        }
        const { data: items, error: listErr } = await supabase
            .from('manufacturer_portfolio')
            .select(MANUFACTURER_PORTFOLIO_SELECT_BASE)
            .eq('manufacturer_id', manufacturerId)
            .order('sort_order', { ascending: true })
            .order('created_at', { ascending: false });
        if (listErr) return res.status(500).json({ error: '讀取作品失敗' });
        res.json({ success: true, items: items || [] });
    } catch (e) {
        console.error('POST /api/manufacturers/:manufacturerId/portfolio/reorder:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PUT /api/manufacturers/:id/portfolio/:portfolioId — 更新廠商作品（作品重點、主圖／第二張圖）
app.put('/api/manufacturers/:manufacturerId/portfolio/:portfolioId', upload.fields([{ name: 'image', maxCount: 1 }, { name: 'image_before', maxCount: 1 }]), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const { manufacturerId, portfolioId } = req.params;
        const body = req.body || {};
        const { title, description, design_highlight, tags: tagsParam, image_url: bodyImageUrl, image_url_before: bodyImageUrlBefore, category_key: bodyCategoryKey, subcategory_key: bodySubcategoryKey, category_type: bodyCategoryType, show_on_media_wall: bodyShowOnMediaWall, upload_type: bodyUploadType } = body;
        const moqPut = parseManufacturerPortfolioMinOrderQty(body.min_order_quantity, { forUpdate: true });
        if (moqPut.error) return res.status(400).json({ error: moqPut.error });
        const tags = Array.isArray(tagsParam) ? tagsParam : (typeof tagsParam === 'string' && tagsParam ? tagsParam.split(/[,，\s]+/).filter(Boolean) : []);
        const allowEmptySubcategoryPut = String(bodyUploadType || '').toLowerCase() === 'series';
        const categoryErrPut = validateManufacturerPortfolioCategoryKeys(bodyCategoryKey, bodySubcategoryKey, { allowEmptySubcategory: allowEmptySubcategoryPut });
        if (categoryErrPut) return res.status(400).json({ error: categoryErrPut });
        const clValidPut = validatePrototypeCustomizationLevels(body.customization_levels);
        if (clValidPut.error) return res.status(400).json({ error: clValidPut.error });

        const files = req.files || {};
        const mainFile = (files.image && files.image[0]) || null;
        const beforeFile = (files.image_before && files.image_before[0]) || null;

        const { data: mfrPut } = await supabase.from('manufacturers').select('user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfrPut) return res.status(404).json({ error: '找不到該廠商' });
        const isAdminPut = await isAdminUserId(user.id);
        if (mfrPut.user_id !== user.id && !isAdminPut) return res.status(403).json({ error: '僅廠商本人或管理員可編輯作品' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfrPut, res)) return;

        const { data: row } = await supabase.from('manufacturer_portfolio').select('id, image_url, image_url_before, series_image_urls').eq('id', portfolioId).eq('manufacturer_id', manufacturerId).single();
        if (!row) return res.status(404).json({ error: '找不到該作品' });

        const updates = {
            updated_at: new Date().toISOString(),
            ...(title !== undefined && { title: title || null }),
            ...(description !== undefined && { description: description || null }),
            ...(design_highlight !== undefined && { design_highlight: design_highlight || null }),
            ...(tags && { tags: tags.length ? tags : [] })
        };
        if (bodyCategoryKey !== undefined) updates.category_key = (bodyCategoryKey != null && String(bodyCategoryKey).trim()) ? String(bodyCategoryKey).trim() : null;
        if (bodySubcategoryKey !== undefined) updates.subcategory_key = (bodySubcategoryKey != null && String(bodySubcategoryKey).trim()) ? String(bodySubcategoryKey).trim() : null;
        if (bodyCategoryType !== undefined) updates.category_type = (bodyCategoryType === 'remake') ? 'remake' : 'custom';
        if (bodyShowOnMediaWall !== undefined) {
            updates.show_on_media_wall = manufacturerAudience.seedVendorPortfolioShowOnMediaWall(mfrPut, bodyShowOnMediaWall);
        }
        if (!moqPut.omit) updates.min_order_quantity = moqPut.value;
        updates.customization_levels = clValidPut.levels;

        if (mainFile) {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', `manufacturer/${manufacturerId}`, mainFile);
            updates.image_url = publicUrl;
            const uploadTypeSeries = String(bodyUploadType || '').toLowerCase() === 'series';
            if (uploadTypeSeries) {
                const existingSeries = (Array.isArray(row.series_image_urls) && row.series_image_urls.length)
                    ? row.series_image_urls.slice()
                    : (row.image_url ? [row.image_url] : []);
                if (existingSeries.length > 0) {
                    existingSeries[0] = publicUrl;
                    updates.series_image_urls = existingSeries;
                } else {
                    updates.series_image_urls = [publicUrl];
                }
            }
        } else if (bodyImageUrl !== undefined) updates.image_url = bodyImageUrl || row.image_url;

        // 系列圖順序：僅允許現有 URL 的重排（第一張同步為 image_url 主圖）
        if (String(bodyUploadType || '').toLowerCase() === 'series' && body.series_image_urls !== undefined && !mainFile) {
            let ordered = body.series_image_urls;
            if (typeof ordered === 'string') {
                try { ordered = JSON.parse(ordered); } catch (_) { ordered = null; }
            }
            const existingSeries = (Array.isArray(row.series_image_urls) && row.series_image_urls.length)
                ? row.series_image_urls.map(function (u) { return String(u || '').trim(); }).filter(Boolean)
                : (row.image_url ? [String(row.image_url).trim()] : []);
            const cleaned = Array.isArray(ordered)
                ? ordered.map(function (u) { return String(u || '').trim(); }).filter(Boolean)
                : [];
            const existingSet = new Set(existingSeries);
            const sameSet = cleaned.length === existingSeries.length
                && cleaned.length > 0
                && new Set(cleaned).size === cleaned.length
                && cleaned.every(function (u) { return existingSet.has(u); });
            if (!sameSet) {
                return res.status(400).json({ error: '系列圖順序無效（僅可調整現有圖片順序）' });
            }
            updates.series_image_urls = cleaned;
            updates.image_url = cleaned[0];
            updates.image_url_before = null;
        }

        if (beforeFile) {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', `manufacturer/${manufacturerId}`, beforeFile);
            updates.image_url_before = publicUrl;
        } else if (bodyImageUrlBefore !== undefined) updates.image_url_before = bodyImageUrlBefore || null;
        // 健康邏輯：編輯時若為「系列」且未上傳設計圖，明確清除 image_url_before，避免混成對照圖
        else if (String(bodyUploadType || '').toLowerCase() === 'series') updates.image_url_before = null;

        const { data: updated, error } = await updateManufacturerPortfolioRow(portfolioId, manufacturerId, updates);
        if (error) {
            console.error('PUT /api/manufacturers/:id/portfolio/:portfolioId 失敗:', error);
            const catHint = portfolioCategoryColumnHint(error);
            const hint = catHint || (isSupabaseMissingColumnError(error)
                ? '（資料庫欄位未齊，請執行 docs/manufacturer-portfolio-add-all-missing-columns.sql）'
                : '');
            return res.status(500).json({ error: '更新失敗' + hint });
        }
        res.json({ ...updated, customization_levels: clValidPut.levels });
    } catch (e) {
        console.error('PUT /api/manufacturers/:id/portfolio/:portfolioId 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// DELETE /api/manufacturers/:manufacturerId/portfolio/:portfolioId — 刪除廠商作品圖
app.delete('/api/manufacturers/:manufacturerId/portfolio/:portfolioId', async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const { manufacturerId, portfolioId } = req.params;
        const { data: mfrDel } = await supabase.from('manufacturers').select('user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfrDel) return res.status(404).json({ error: '找不到該廠商' });
        const isAdminDel = await isAdminUserId(user.id);
        if (mfrDel.user_id !== user.id && !isAdminDel) return res.status(403).json({ error: '僅廠商本人或管理員可刪除作品' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfrDel, res)) return;
        const { data: row } = await supabase.from('manufacturer_portfolio').select('id').eq('id', portfolioId).eq('manufacturer_id', manufacturerId).single();
        if (!row) return res.status(404).json({ error: '找不到該作品' });
        const { error } = await supabase.from('manufacturer_portfolio').delete().eq('id', portfolioId);
        if (error) {
            console.error('DELETE /api/manufacturers/:id/portfolio/:portfolioId 失敗:', error);
            return res.status(500).json({ error: '刪除失敗' });
        }
        res.status(204).send();
    } catch (e) {
        console.error('DELETE /api/manufacturers/:id/portfolio/:portfolioId 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/manufacturers/:manufacturerId/portfolio/generate-description — 讀圖產生作品描述（與供應商產品庫相同 Gemini 管線，扣點預設 1）
app.post('/api/manufacturers/:manufacturerId/portfolio/generate-description', upload.single('image'), async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const { manufacturerId } = req.params;
        const { data: mfr } = await supabase.from('manufacturers').select('id, user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfr) return res.status(404).json({ error: '找不到該廠商' });
        const isAdmin = await isAdminUserId(user.id);
        if (mfr.user_id !== user.id && !isAdmin) return res.status(403).json({ error: '僅廠商本人或管理員可操作' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfr, res)) return;
        const body = req.body || {};
        const portfolioId = (body.portfolio_id || '').trim();
        let imageFile = req.file ? await vendorAssetFileFromMulter(req.file) : null;
        let context = await portfolioSemanticsContextFromBody(body, null);
        if (!imageFile && portfolioId) {
            const { data: row } = await supabase.from('manufacturer_portfolio')
                .select('id, image_url, category_key, subcategory_key, title, description, design_highlight')
                .eq('id', portfolioId).eq('manufacturer_id', manufacturerId).maybeSingle();
            if (!row || !row.image_url) return res.status(404).json({ error: '找不到該作品或無圖片' });
            context = await portfolioSemanticsContextFromBody(body, row);
            context.image_url = row.image_url;
            imageFile = await fetchPortfolioImageFileFromUrl(row.image_url);
        }
        if (!imageFile) return res.status(400).json({ error: '請上傳圖片或提供作品 id' });
        const result = await runPortfolioImageSemanticsLikeSupplierCatalog(imageFile, context, user.id, portfolioId || null);
        const description = result.description || vendorAssetDescriptionFromSemantics(result.semantics);
        if (!description) return res.status(503).json({ error: '無法產生說明，請稍後重試' });
        const pointsRequired = await getPointsVendorAssetDescription();
        let balanceAfter = null;
        let pointsDeducted = 0;
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(user.id, pointsRequired);
            if (!sufficient) return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            const consumed = await consumeUserCredits(
                user.id,
                pointsRequired,
                'portfolio_description',
                '廠商作品 AI 產生說明',
                { manufacturer_id: manufacturerId, portfolio_id: portfolioId || null }
            );
            if (!consumed.ok) return res.status(402).json({ error: consumed.error || '扣點失敗', balance: consumed.balance });
            balanceAfter = consumed.balance_after;
            pointsDeducted = pointsRequired;
        }
        res.json({
            description,
            product_description_zh: result.semantics?.product_description_zh || null,
            product_description_en: result.semantics?.product_description_en || null,
            points_deducted: pointsDeducted,
            balance_after: balanceAfter
        });
    } catch (e) {
        console.error('POST portfolio/generate-description:', e);
        res.status(503).json({ error: e.message || 'AI 說明產生失敗，請稍後重試' });
    }
});

// POST /api/manufacturers/:manufacturerId/portfolio/:portfolioId/regenerate-tags — 依作品圖重算 AI 標籤
app.post('/api/manufacturers/:manufacturerId/portfolio/:portfolioId/regenerate-tags', async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        const { manufacturerId, portfolioId } = req.params;
        const { data: mfr } = await supabase.from('manufacturers').select('id, user_id, vendor_source').eq('id', manufacturerId).single();
        if (!mfr) return res.status(404).json({ error: '找不到該廠商' });
        const isAdmin = await isAdminUserId(user.id);
        if (mfr.user_id !== user.id && !isAdmin) return res.status(403).json({ error: '僅廠商本人或管理員可操作' });
        if (await rejectSeedVendorSelfServiceWrite(user.id, mfr, res)) return;
        const { data: row } = await supabase.from('manufacturer_portfolio')
            .select('id, image_url, image_url_before, category_key, subcategory_key, title, description, design_highlight, tags')
            .eq('id', portfolioId).eq('manufacturer_id', manufacturerId).maybeSingle();
        if (!row || !row.image_url) return res.status(404).json({ error: '找不到該作品或無圖片' });
        const pointsRequired = await getPointsVendorAssetRegenerateTags();
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(user.id, pointsRequired);
            if (!sufficient) return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
        }
        const imageFile = await fetchPortfolioImageFileFromUrl(row.image_url);
        if (!imageFile) return res.status(503).json({ error: '無法讀取作品圖片' });
        const context = await portfolioSemanticsContextFromBody({}, row);
        context.image_url = row.image_url;
        const sem = await runPortfolioImageSemanticsLikeSupplierCatalog(imageFile, context, user.id, row.id);
        if (!sem || !sem.tags || !sem.tags.length) return res.status(503).json({ error: 'AI 標籤產生失敗，請稍後重試' });
        let balanceAfter = null;
        let pointsDeducted = 0;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(user.id, pointsRequired, 'portfolio_regenerate_tags', '廠商作品 AI 重生標籤', { manufacturer_id: manufacturerId, portfolio_id: portfolioId });
            if (!consumed.ok) return res.status(402).json({ error: consumed.error || '扣點失敗', balance: consumed.balance });
            balanceAfter = consumed.balance_after;
            pointsDeducted = pointsRequired;
        }
        const tagUpdates = {
            ...portfolioSemanticsPatchFromResult(sem),
            tags: sem.tags,
            updated_at: new Date().toISOString()
        };
        const { data: updated, error } = await updateManufacturerPortfolioRow(portfolioId, manufacturerId, tagUpdates);
        if (error) {
            console.error('portfolio regenerate-tags update:', error);
            return res.status(500).json({ error: '更新標籤失敗' });
        }
        res.json({
            item: updated,
            ai_tags: sem.tags,
            points_deducted: pointsDeducted,
            balance_after: balanceAfter
        });
    } catch (e) {
        console.error('POST portfolio/regenerate-tags:', e);
        res.status(503).json({ error: e.message || 'AI 標籤產生失敗，請稍後重試' });
    }
});

// ---------- 廠商自訂分類（獨立於網站 category_key）----------
function slugifyVendorCatalogGroupName(name) {
    const s = String(name || '').trim().toLowerCase()
        .replace(/\s+/g, '-')
        .replace(/[^\w\u4e00-\u9fff-]+/g, '')
        .slice(0, 48);
    return s || 'group';
}

function parseCatalogGroupIdsFromBody(body) {
    const ids = new Set();
    const raw = body && body.catalog_group_ids;
    if (raw) {
        try {
            const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
            if (Array.isArray(arr)) arr.forEach((id) => { if (id) ids.add(String(id).trim()); });
        } catch (_) {}
    }
    const single = body && (body.catalog_group_id || '').trim();
    if (single) ids.add(single);
    return [...ids];
}

/** 材料自訂分類名稱（供 AI 優化／生圖附錄，取代 material_key） */
async function vendorCatalogGroupNamesByIds(manufacturerId, groupIds) {
    const ids = [...new Set((groupIds || []).map((id) => String(id).trim()).filter(Boolean))];
    if (!ids.length || !manufacturerId) return '';
    let { data: groups, error } = await supabase
        .from('vendor_catalog_groups')
        .select('id, name, asset_kind')
        .eq('manufacturer_id', manufacturerId)
        .in('id', ids);
    if (error && error.code === '42703') {
        ({ data: groups } = await supabase
            .from('vendor_catalog_groups')
            .select('id, name')
            .eq('manufacturer_id', manufacturerId)
            .in('id', ids));
    }
    return (groups || [])
        .filter((g) => vendorCatalogGroupRowAssetKind(g) === 'material')
        .map((g) => String(g.name || '').trim())
        .filter(Boolean)
        .join('、');
}

/** 材料素材已勾選的自訂分類名稱（供 AI 優化提示詞） */
async function materialCatalogHintForVendorAsset(manufacturerId, assetId) {
    if (!manufacturerId || !assetId) return '';
    const enriched = await attachCatalogGroupIdsToAssets([{ id: assetId }]);
    const row = enriched && enriched[0];
    if (!row || !row.catalog_groups || !row.catalog_groups.length) return '';
    return row.catalog_groups
        .map((g) => String(g.name || '').trim())
        .filter(Boolean)
        .join('、');
}

async function vendorCatalogGroupsTableReady() {
    const { error } = await supabase.from('vendor_catalog_groups').select('id').limit(1);
    return !error || error.code !== '42P01';
}

async function vendorAssetGroupLinksTableReady() {
    const { error } = await supabase.from('vendor_asset_group_links').select('asset_id').limit(1);
    return !error || error.code !== '42P01';
}

async function vendorPrototypeLinksTableReady() {
    const { error } = await supabase.from('vendor_asset_prototype_links').select('id').limit(1);
    return !error || error.code !== '42P01';
}

function parseJsonUuidArrayFromBody(val) {
    if (val === undefined || val === null) return null;
    let arr;
    if (Array.isArray(val)) arr = val;
    else if (typeof val === 'string') {
        const s = val.trim();
        if (!s) return [];
        try {
            const parsed = JSON.parse(s);
            arr = Array.isArray(parsed) ? parsed : [s];
        } catch (_) {
            arr = s.split(/[,，]/).map((x) => x.trim()).filter(Boolean);
        }
    } else return null;
    return [...new Set(arr.map((x) => String(x).trim()).filter((x) => /^[0-9a-f-]{36}$/i.test(x)))];
}

let _vendorPrototypeLinkSelectCols = null;

async function vendorPrototypeLinkSelectColumns() {
    if (_vendorPrototypeLinkSelectCols) return _vendorPrototypeLinkSelectCols;
    const full = 'linked_asset_id, sort_order, allow_multi_pick, pick_group';
    const { error } = await supabase.from('vendor_asset_prototype_links').select(full).limit(1);
    if (error && (error.code === '42703' || String(error.message || '').includes('allow_multi_pick') || String(error.message || '').includes('pick_group'))) {
        _vendorPrototypeLinkSelectCols = 'linked_asset_id, sort_order';
    } else {
        _vendorPrototypeLinkSelectCols = full;
    }
    return _vendorPrototypeLinkSelectCols;
}

function vendorPrototypeLinkMetaColumnsReady(cols) {
    return cols && String(cols).indexOf('allow_multi_pick') >= 0;
}

function normalizePrototypeLinkEntries(linkedInput) {
    if (linkedInput === undefined || linkedInput === null) return [];
    let arr = linkedInput;
    if (typeof linkedInput === 'string') {
        const s = linkedInput.trim();
        if (!s) return [];
        try {
            arr = JSON.parse(s);
        } catch (_) {
            return [];
        }
    }
    if (!Array.isArray(arr)) return [];
    const out = [];
    const seen = new Set();
    arr.forEach(function (item) {
        let id = '';
        let allowMulti = true;
        let pickGroup = null;
        if (typeof item === 'string') {
            id = item.trim();
        } else if (item && typeof item === 'object') {
            id = String(item.linked_asset_id || item.id || '').trim();
            if (item.allow_multi_pick === false) allowMulti = false;
            if (item.pick_group != null && String(item.pick_group).trim()) {
                pickGroup = String(item.pick_group).trim();
            }
        }
        if (!id || !/^[0-9a-f-]{36}$/i.test(id) || seen.has(id)) return;
        seen.add(id);
        out.push({
            linked_asset_id: id,
            allow_multi_pick: allowMulti,
            pick_group: pickGroup
        });
    });
    return out;
}

/** @returns {Array|null|undefined} null = 格式錯誤；undefined = 未提供 */
function parseLinkedLinksFromBody(body) {
    if (!body) return undefined;
    if (body.linked_links !== undefined) {
        let raw = body.linked_links;
        if (typeof raw === 'string') {
            const s = raw.trim();
            if (!s) return [];
            try {
                raw = JSON.parse(s);
            } catch (_) {
                return null;
            }
        }
        if (!Array.isArray(raw)) return null;
        return normalizePrototypeLinkEntries(raw);
    }
    if (body.linked_asset_ids !== undefined) {
        const ids = parseJsonUuidArrayFromBody(body.linked_asset_ids);
        if (ids === null) return null;
        return normalizePrototypeLinkEntries(ids);
    }
    return undefined;
}

function parseReferenceSourcesList(raw) {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw;
    if (typeof raw === 'string') {
        try {
            const parsed = JSON.parse(raw);
            return Array.isArray(parsed) ? parsed : [];
        } catch (_) {
            return [];
        }
    }
    return [];
}

function productReferencesPrototype(sources, prototypeAssetId) {
    const pid = String(prototypeAssetId || '').trim();
    if (!pid) return false;
    return parseReferenceSourcesList(sources).some(function (s) {
        return s && String(s.vendor_asset_id || '') === pid &&
            normalizeVendorAssetKind(s.asset_kind || 'prototype') === 'prototype';
    });
}

function buildComboKeyFromReferenceSources(sources) {
    const ids = parseReferenceSourcesList(sources)
        .filter(function (s) {
            if (!s || !s.vendor_asset_id) return false;
            const k = normalizeVendorAssetKind(s.asset_kind || '');
            return k === 'material' || k === 'part';
        })
        .map(function (s) { return String(s.vendor_asset_id); })
        .sort();
    return ids.join('|');
}

function buildComboLabelFromReferenceSources(sources, titleById) {
    const parts = parseReferenceSourcesList(sources)
        .filter(function (s) {
            if (!s || !s.vendor_asset_id) return false;
            const k = normalizeVendorAssetKind(s.asset_kind || '');
            return k === 'material' || k === 'part';
        })
        .map(function (s) {
            const id = String(s.vendor_asset_id);
            const t = (s.title || titleById[id] || '').trim();
            const k = normalizeVendorAssetKind(s.asset_kind || '');
            const kindLbl = k === 'material' ? '材料' : (k === 'part' ? '配件' : '');
            return (t || id) + (kindLbl ? '（' + kindLbl + '）' : '');
        });
    return parts.length ? parts.join(' · ') : '僅主產品';
}

function customProductRowIsEmbedVisitor(row) {
    if (!row) return false;
    const aj = row.analysis_json && typeof row.analysis_json === 'object' ? row.analysis_json : {};
    if (aj.embed_visitor_design === true || aj.source === 'embed') return true;
    const dl = row.data_lineage_json && typeof row.data_lineage_json === 'object' ? row.data_lineage_json : {};
    return dl.embed_visitor_design === true || dl.source === 'embed';
}

function productRowReferencesManufacturer(row, manufacturerId) {
    const mid = String(manufacturerId || '').trim();
    if (!mid || !row) return false;
    if (String(row.generator_manufacturer_id || '') === mid) return true;
    return parseReferenceSourcesList(row.reference_sources).some(function (s) {
        return s && String(s.manufacturer_id || '') === mid;
    });
}

async function buildVendorAssetTitleMap(manufacturerId) {
    const titleById = {};
    const { data: assets } = await supabase
        .from('vendor_assets')
        .select('id, title')
        .eq('manufacturer_id', manufacturerId);
    (assets || []).forEach(function (a) {
        if (a && a.id) titleById[a.id] = (a.title || '').trim() || a.id;
    });
    return titleById;
}

function mapEmbedDesignListItem(row, titleById, protoTitleById, instanceNameById) {
    const protoId = row.prototype_asset_id || null;
    return {
        id: row.id,
        source: 'embed',
        created_at: row.created_at,
        ai_generated_image_url: row.ai_generated_image_url || null,
        prompt: row.prompt || null,
        prototype_asset_id: protoId,
        prototype_title: (protoId && protoTitleById[protoId]) || '',
        combo_label: buildComboLabelFromReferenceSources(row.reference_sources, titleById),
        reference_sources: row.reference_sources || [],
        referrer_host: row.referrer_host || null,
        points_charged: row.points_charged || 0,
        billing_type: row.billing_type || null,
        generation_seed: row.generation_seed != null ? row.generation_seed : null,
        custom_product_id: row.custom_product_id || null,
        embed_instance_id: row.embed_instance_id || null,
        embed_instance_name: (row.embed_instance_id && instanceNameById[row.embed_instance_id]) || null
    };
}

async function listVendorEmbedDesigns(manufacturerId, opts) {
    opts = opts || {};
    const limit = Math.min(100, Math.max(1, parseInt(opts.limit, 10) || 30));
    const offset = Math.max(0, parseInt(opts.offset, 10) || 0);
    const protoId = (opts.prototype_asset_id || '').trim();

    let q = supabase
        .from('vendor_embed_designs')
        .select('id, embed_instance_id, manufacturer_id, prototype_asset_id, reference_sources, prompt, ai_generated_image_url, generation_seed, referrer_host, billing_type, points_charged, custom_product_id, created_at', { count: 'exact' })
        .eq('manufacturer_id', manufacturerId)
        .order('created_at', { ascending: false })
        .range(offset, offset + limit - 1);
    if (protoId) q = q.eq('prototype_asset_id', protoId);

    const { data: rows, error, count } = await q;
    if (error) {
        if (error.code === '42P01') return { error: 'schema', items: [], total: 0 };
        throw error;
    }

    const titleById = await buildVendorAssetTitleMap(manufacturerId);
    const protoTitleById = titleById;
    const instanceIds = [...new Set((rows || []).map(function (r) { return r.embed_instance_id; }).filter(Boolean))];
    const instanceNameById = {};
    if (instanceIds.length) {
        const { data: instRows } = await supabase
            .from('manufacturer_embed_instances')
            .select('id, name')
            .in('id', instanceIds);
        (instRows || []).forEach(function (i) {
            if (i && i.id) instanceNameById[i.id] = i.name || '';
        });
    }

    return {
        items: (rows || []).map(function (r) {
            return mapEmbedDesignListItem(r, titleById, protoTitleById, instanceNameById);
        }),
        total: count || 0,
        limit: limit,
        offset: offset
    };
}

async function listAdminGenerationRecords(opts) {
    opts = opts || {};
    const source = (opts.source || 'all').trim().toLowerCase();
    const limit = Math.min(100, Math.max(1, parseInt(opts.limit, 10) || 50));
    const offset = Math.max(0, parseInt(opts.offset, 10) || 0);
    const manufacturerId = (opts.manufacturer_id || '').trim();
    const qText = (opts.q || '').trim().toLowerCase();
    const from = (opts.from || '').trim();
    const to = (opts.to || '').trim();
    const fetchN = Math.min(500, limit + offset + 50);
    const merged = [];

    if (source === 'all' || source === 'site') {
        let cpQ = supabase
            .from('custom_products')
            .select('id, title, description, ai_generated_image_url, generation_prompt, generation_seed, reference_sources, created_at, owner_id, category, subcategory_key, is_vendor_self_serve, analysis_json, data_lineage_json, generator_manufacturer_id, show_on_homepage')
            .not('ai_generated_image_url', 'is', null)
            .order('created_at', { ascending: false })
            .limit(fetchN);
        if (from) cpQ = cpQ.gte('created_at', from);
        if (to) cpQ = cpQ.lte('created_at', to + 'T23:59:59.999Z');
        const cpRes = await cpQ;
        if (!cpRes.error) {
            (cpRes.data || []).forEach(function (row) {
                if (customProductRowIsEmbedVisitor(row)) return;
                if (manufacturerId && !productRowReferencesManufacturer(row, manufacturerId)) return;
                const prompt = (row.generation_prompt || row.description || row.title || '').trim();
                const hay = [row.title, prompt, row.category, row.subcategory_key].join(' ').toLowerCase();
                if (qText && !hay.includes(qText)) return;
                merged.push({
                    id: row.id,
                    source: 'site',
                    created_at: row.created_at,
                    ai_generated_image_url: row.ai_generated_image_url,
                    title: row.title || '',
                    prompt: prompt,
                    generation_seed: row.generation_seed,
                    reference_sources: row.reference_sources || [],
                    owner_id: row.owner_id || null,
                    category: row.category || null,
                    subcategory_key: row.subcategory_key || null,
                    is_vendor_self_serve: row.is_vendor_self_serve === true,
                    show_on_homepage: row.show_on_homepage !== false,
                    manufacturer_id: row.generator_manufacturer_id || null
                });
            });
        }
    }

    if (source === 'all' || source === 'embed') {
        let embQ = supabase
            .from('vendor_embed_designs')
            .select('id, embed_instance_id, manufacturer_id, prototype_asset_id, reference_sources, prompt, ai_generated_image_url, generation_seed, referrer_host, billing_type, points_charged, custom_product_id, created_at')
            .order('created_at', { ascending: false })
            .limit(fetchN);
        if (manufacturerId) embQ = embQ.eq('manufacturer_id', manufacturerId);
        if (from) embQ = embQ.gte('created_at', from);
        if (to) embQ = embQ.lte('created_at', to + 'T23:59:59.999Z');
        const embRes = await embQ;
        if (!embRes.error) {
            const mfrIds = [...new Set((embRes.data || []).map(function (r) { return r.manufacturer_id; }).filter(Boolean))];
            const mfrNameById = {};
            if (mfrIds.length) {
                const { data: mfrs } = await supabase.from('manufacturers').select('id, name').in('id', mfrIds);
                (mfrs || []).forEach(function (m) {
                    if (m && m.id) mfrNameById[m.id] = m.name || '';
                });
            }
            (embRes.data || []).forEach(function (row) {
                const prompt = (row.prompt || '').trim();
                const hay = [prompt, row.referrer_host, row.prototype_asset_id].join(' ').toLowerCase();
                if (qText && !hay.includes(qText)) return;
                merged.push({
                    id: row.id,
                    source: 'embed',
                    created_at: row.created_at,
                    ai_generated_image_url: row.ai_generated_image_url,
                    title: 'Embed 訪客試做',
                    prompt: prompt,
                    generation_seed: row.generation_seed,
                    reference_sources: row.reference_sources || [],
                    manufacturer_id: row.manufacturer_id || null,
                    manufacturer_name: mfrNameById[row.manufacturer_id] || '',
                    referrer_host: row.referrer_host || null,
                    points_charged: row.points_charged || 0,
                    billing_type: row.billing_type || null,
                    custom_product_id: row.custom_product_id || null,
                    embed_instance_id: row.embed_instance_id || null,
                    prototype_asset_id: row.prototype_asset_id || null,
                    is_vendor_self_serve: false
                });
            });
        }
    }

    if (source === 'all' || source === 'promo' || source === 'promo_camera' || source === 'promo_camera_web' || source === 'promo_camera_app' || ADMIN_PROMO_CAMERA_SHOOT_FILTER[source]) {
        const promoSelectFull = 'id, user_id, source_type, source_id, source_image_url, aspect_ratio, width, height, megapixels, scene_template_key, scene_key, user_prompt, final_prompt, result_image_url, status, points_charged, created_at, completed_at, generation_mode, generation_meta_json, client_channel, camera_params';
        let promoQ = supabase
            .from('product_promo_generations')
            .select(promoSelectFull)
            .eq('status', 'success')
            .not('result_image_url', 'is', null)
            .order('created_at', { ascending: false })
            .limit(fetchN);
        if (from) promoQ = promoQ.gte('created_at', from);
        if (to) promoQ = promoQ.lte('created_at', to + 'T23:59:59.999Z');
        let promoRes = await promoQ;
        if (promoRes.error && (isSupabaseMissingColumnError(promoRes.error, 'scene_key') || isSupabaseMissingColumnError(promoRes.error, 'generation_mode') || isSupabaseMissingColumnError(promoRes.error, 'generation_meta_json') || isSupabaseMissingColumnError(promoRes.error, 'camera_params') || isSupabaseMissingColumnError(promoRes.error, 'client_channel'))) {
            promoQ = supabase
                .from('product_promo_generations')
                .select('id, user_id, source_type, source_id, source_image_url, aspect_ratio, width, height, megapixels, scene_template_key, user_prompt, final_prompt, result_image_url, status, points_charged, created_at, completed_at, generation_mode, client_channel, camera_params')
                .eq('status', 'success')
                .not('result_image_url', 'is', null)
                .order('created_at', { ascending: false })
                .limit(fetchN);
            if (from) promoQ = promoQ.gte('created_at', from);
            if (to) promoQ = promoQ.lte('created_at', to + 'T23:59:59.999Z');
            promoRes = await promoQ;
        }
        if (!promoRes.error) {
            const shootFilter = ADMIN_PROMO_CAMERA_SHOOT_FILTER[source];
            (promoRes.data || []).forEach(function (row) {
                const itemSource = adminPromoGenerationRecordSource(row);
                if (source === 'promo' && itemSource !== 'promo') return;
                if (source === 'promo_camera' && itemSource !== 'promo_camera_web' && itemSource !== 'promo_camera_app') return;
                if (source === 'promo_camera_web' && itemSource !== 'promo_camera_web') return;
                if (source === 'promo_camera_app' && itemSource !== 'promo_camera_app') return;
                if (shootFilter) {
                    if (itemSource !== 'promo_camera_web' && itemSource !== 'promo_camera_app') return;
                    if (adminPromoCameraShootMode(row) !== shootFilter) return;
                }
                const prompt = (row.final_prompt || row.user_prompt || '').trim();
                const themeLabel = (row.scene_template_key || '').trim();
                const sceneLabel = (row.scene_key || '').trim();
                const shootMode = adminPromoCameraShootMode(row);
                const titleParts = [adminPromoCameraRecordTitleLabel(itemSource, shootMode)];
                if (themeLabel) titleParts.push(themeLabel);
                if (sceneLabel) titleParts.push(sceneLabel);
                const cameraSummary = formatAdminPromoCameraParamsSummary(row.camera_params);
                const meta = parsePromoGenerationMetaJson(row.generation_meta_json);
                const hay = [prompt, row.user_prompt, themeLabel, sceneLabel, row.source_type, row.source_id, row.source_image_url, cameraSummary, adminPromoCameraShootModeLabel(shootMode)].join(' ').toLowerCase();
                if (qText && !hay.includes(qText)) return;
                merged.push({
                    id: row.id,
                    source: itemSource,
                    generation_mode: row.generation_mode || (itemSource === 'promo_camera_web' || itemSource === 'promo_camera_app' ? 'camera_advanced' : 'standard'),
                    shoot_mode: shootMode,
                    space_output_type: meta.space_output_type || null,
                    shoot_mode_label: shootMode ? adminPromoCameraShootModeLabel(shootMode) : null,
                    client_channel: row.client_channel || null,
                    created_at: row.created_at || row.completed_at,
                    ai_generated_image_url: row.result_image_url,
                    title: titleParts.join(' · '),
                    prompt: prompt,
                    user_prompt: row.user_prompt || null,
                    scene_template_key: themeLabel || null,
                    scene_key: sceneLabel || null,
                    source_type: row.source_type || null,
                    source_id: row.source_id || null,
                    source_image_url: row.source_image_url || null,
                    aspect_ratio: row.aspect_ratio || null,
                    width: row.width || null,
                    height: row.height || null,
                    megapixels: row.megapixels != null ? row.megapixels : null,
                    points_charged: row.points_charged || 0,
                    owner_id: row.user_id || null,
                    status: row.status || 'success',
                    camera_params: row.camera_params || null,
                    camera_params_summary: cameraSummary || null,
                    reference_sources: row.source_image_url ? [{ type: row.source_type || 'upload', url: row.source_image_url, id: row.source_id || null }] : []
                });
            });
        } else if (promoRes.error && promoRes.error.code !== '42P01') {
            console.warn('listAdminGenerationRecords promo:', promoRes.error.message || promoRes.error);
        }
    }

    merged.sort(function (a, b) {
        return new Date(b.created_at || 0) - new Date(a.created_at || 0);
    });
    const items = merged.slice(offset, offset + limit);

    const ownerIds = [...new Set(items.filter(function (i) { return (i.source === 'site' || i.source === 'promo' || i.source === 'promo_camera_web' || i.source === 'promo_camera_app') && i.owner_id; }).map(function (i) { return i.owner_id; }))];
    const ownerById = {};
    if (ownerIds.length) {
        const { data: profs } = await supabase.from('profiles').select('id, email, full_name').in('id', ownerIds);
        (profs || []).forEach(function (p) {
            if (p && p.id) ownerById[p.id] = p;
        });
    }
    items.forEach(function (item) {
        if ((item.source === 'site' || item.source === 'promo' || item.source === 'promo_camera_web' || item.source === 'promo_camera_app') && item.owner_id && ownerById[item.owner_id]) {
            const p = ownerById[item.owner_id];
            item.owner_email = p.email || null;
            item.owner_name = p.full_name || null;
        }
    });

    const promoItemIds = items.filter(function (item) {
        return isPromoLikeGenerationRecordSource(item.source) && item.id;
    }).map(function (item) { return item.id; });
    if (promoItemIds.length) {
        try {
            const appealMap = await fetchPromoSpaceAppealSummaryMap(promoItemIds);
            attachPromoSpaceAppealSummaries(items, appealMap);
        } catch (appealErr) {
            console.warn('listAdminGenerationRecords appeals:', appealErr && appealErr.message);
        }
    }

    const summary = await adminGenerationRecordSummaryCounts({ from, to, qText: qText });

    return {
        items: items,
        total: merged.length,
        limit: limit,
        offset: offset,
        has_more: merged.length > offset + limit,
        summary: summary
    };
}

function normalizePromoClientChannel(raw) {
    const v = String(raw || 'web').trim().toLowerCase();
    if (v === 'app' || v === 'embed' || v === 'web') return v;
    return 'web';
}

function isPromoLikeGenerationRecordSource(source) {
    const s = String(source || '').trim();
    return s === 'promo' || s === 'promo_camera' || s === 'promo_camera_web' || s === 'promo_camera_app';
}

function adminPromoGenerationRecordSource(row) {
    const mode = String(row && row.generation_mode || '').trim();
    if (mode !== 'camera_advanced') return 'promo';
    const ch = normalizePromoClientChannel(row && row.client_channel);
    return ch === 'app' ? 'promo_camera_app' : 'promo_camera_web';
}

function adminPromoCameraRecordTitleLabel(itemSource, shootMode) {
    const modeLabel = adminPromoCameraShootModeLabel(shootMode);
    if (itemSource === 'promo_camera_app') return '商攝・' + modeLabel + ' App';
    if (itemSource === 'promo_camera_web') return '商攝・' + modeLabel + ' 網站';
    return '產品情境圖';
}

function adminPromoCameraShootModeLabel(shootMode) {
    const map = { product: '產品攝影', space: '空間攝影', portrait: '人像攝影' };
    return map[String(shootMode || 'product').trim().toLowerCase()] || '產品攝影';
}

function adminPromoCameraShootMode(row) {
    const meta = parsePromoGenerationMetaJson(row && row.generation_meta_json);
    const mode = String((row && row.generation_mode) || meta.generation_mode || '').trim();
    if (mode !== 'camera_advanced') return null;
    return String(meta.shoot_mode || 'product').trim().toLowerCase();
}

const ADMIN_PROMO_CAMERA_SHOOT_FILTER = {
    promo_camera_product: 'product',
    promo_camera_space: 'space',
    promo_camera_portrait: 'portrait'
};

function formatAdminPromoCameraParamsSummary(cameraParams) {
    const cp = cameraParams && typeof cameraParams === 'object' ? cameraParams : {};
    const resolved = cp.resolved && typeof cp.resolved === 'object' ? cp.resolved : {};
    const labels = (PROMO_CAMERA_UI_CONFIG && PROMO_CAMERA_UI_CONFIG.category_labels) || {};
    return Object.keys(resolved).map(function (cat) {
        const hit = resolved[cat];
        const name = hit && (hit.name || hit.key) ? String(hit.name || hit.key) : '';
        if (!name) return '';
        const label = labels[cat] || cat;
        return label + ':' + name;
    }).filter(Boolean).join(' · ');
}

/** 後台生圖紀錄：依來源筆數（日期篩選；關鍵字篩選時僅供參考） */
async function countPromoCameraRowsByShootMode(from, to) {
    const counts = { product: 0, space: 0, portrait: 0 };
    const pageSize = 1000;
    let offset = 0;
    let useModeOnly = false;
    while (true) {
        let q = supabase
            .from('product_promo_generations')
            .select(useModeOnly ? 'generation_mode' : 'generation_mode, generation_meta_json')
            .eq('status', 'success')
            .not('result_image_url', 'is', null)
            .eq('generation_mode', 'camera_advanced')
            .order('created_at', { ascending: true })
            .range(offset, offset + pageSize - 1);
        if (from) q = q.gte('created_at', from);
        if (to) q = q.lte('created_at', to + 'T23:59:59.999Z');
        const res = await q;
        if (res.error) {
            if (!useModeOnly && isSupabaseMissingColumnError(res.error, 'generation_meta_json')) {
                useModeOnly = true;
                offset = 0;
                continue;
            }
            if (res.error.code === '42P01') return counts;
            throw res.error;
        }
        const batch = res.data || [];
        batch.forEach(function (row) {
            const shoot = adminPromoCameraShootMode(row) || 'product';
            if (shoot === 'space') counts.space += 1;
            else if (shoot === 'portrait') counts.portrait += 1;
            else counts.product += 1;
        });
        if (batch.length < pageSize) break;
        offset += pageSize;
    }
    return counts;
}

async function adminGenerationRecordSummaryCounts(opts) {
    opts = opts || {};
    const from = (opts.from || '').trim();
    const to = (opts.to || '').trim();
    const qText = (opts.qText || '').trim();
    const summary = {
        site: 0,
        embed: 0,
        promo: 0,
        promo_camera_web: 0,
        promo_camera_app: 0,
        promo_camera: 0,
        promo_camera_product: 0,
        promo_camera_space: 0,
        promo_camera_portrait: 0,
        total: 0,
        filtered: !!qText
    };
    if (qText) return summary;

    let cpQ = supabase
        .from('custom_products')
        .select('id', { count: 'exact', head: true })
        .not('ai_generated_image_url', 'is', null);
    if (from) cpQ = cpQ.gte('created_at', from);
    if (to) cpQ = cpQ.lte('created_at', to + 'T23:59:59.999Z');
    const cpRes = await cpQ;
    if (!cpRes.error && cpRes.count != null) summary.site = cpRes.count;

    let embQ = supabase
        .from('vendor_embed_designs')
        .select('id', { count: 'exact', head: true });
    if (from) embQ = embQ.gte('created_at', from);
    if (to) embQ = embQ.lte('created_at', to + 'T23:59:59.999Z');
    const embRes = await embQ;
    if (!embRes.error && embRes.count != null) summary.embed = embRes.count;

    let promoCamQ = supabase
        .from('product_promo_generations')
        .select('id', { count: 'exact', head: true })
        .eq('status', 'success')
        .not('result_image_url', 'is', null)
        .eq('generation_mode', 'camera_advanced');
    if (from) promoCamQ = promoCamQ.gte('created_at', from);
    if (to) promoCamQ = promoCamQ.lte('created_at', to + 'T23:59:59.999Z');
    const promoCamRes = await promoCamQ;
    let promoCameraTotal = 0;
    if (!promoCamRes.error && promoCamRes.count != null) {
        promoCameraTotal = promoCamRes.count;
    }

    let promoCamAppQ = supabase
        .from('product_promo_generations')
        .select('id', { count: 'exact', head: true })
        .eq('status', 'success')
        .not('result_image_url', 'is', null)
        .eq('generation_mode', 'camera_advanced')
        .eq('client_channel', 'app');
    if (from) promoCamAppQ = promoCamAppQ.gte('created_at', from);
    if (to) promoCamAppQ = promoCamAppQ.lte('created_at', to + 'T23:59:59.999Z');
    const promoCamAppRes = await promoCamAppQ;
    if (!promoCamAppRes.error && promoCamAppRes.count != null) {
        summary.promo_camera_app = promoCamAppRes.count;
    }
    summary.promo_camera_web = Math.max(0, promoCameraTotal - summary.promo_camera_app);
    summary.promo_camera = summary.promo_camera_web + summary.promo_camera_app;
    try {
        const shootCounts = await countPromoCameraRowsByShootMode(from, to);
        summary.promo_camera_product = shootCounts.product;
        summary.promo_camera_space = shootCounts.space;
        summary.promo_camera_portrait = shootCounts.portrait;
    } catch (shootErr) {
        console.warn('adminGenerationRecordSummaryCounts shoot_mode:', shootErr && shootErr.message);
    }

    let promoQ = supabase
        .from('product_promo_generations')
        .select('id', { count: 'exact', head: true })
        .eq('status', 'success')
        .not('result_image_url', 'is', null);
    if (from) promoQ = promoQ.gte('created_at', from);
    if (to) promoQ = promoQ.lte('created_at', to + 'T23:59:59.999Z');
    const promoRes = await promoQ;
    if (!promoRes.error && promoRes.count != null) {
        summary.promo = Math.max(0, promoRes.count - (summary.promo_camera || 0));
        if (promoCamRes.error) summary.promo = promoRes.count;
    }

    summary.total = summary.site + summary.embed + summary.promo + summary.promo_camera_web + summary.promo_camera_app;
    return summary;
}

async function buildVendorPrototypeDesignInsights(manufacturerId, prototypeAssetId) {
    const { data: proto, error: protoErr } = await supabase
        .from('vendor_assets')
        .select('id, title, image_url, asset_kind')
        .eq('id', prototypeAssetId)
        .eq('manufacturer_id', manufacturerId)
        .maybeSingle();
    if (protoErr) throw protoErr;
    if (!proto || normalizeVendorAssetKind(proto.asset_kind) !== 'prototype') {
        return { error: 'not_found' };
    }
    const titleById = {};
    const { data: mfrAssets, error: assetErr } = await supabase
        .from('vendor_assets')
        .select('id, title, asset_kind')
        .eq('manufacturer_id', manufacturerId);
    if (assetErr) throw assetErr;
    (mfrAssets || []).forEach(function (a) {
        if (a && a.id) titleById[a.id] = (a.title || '').trim() || a.id;
    });
    const { data: products, error: prodErr } = await supabase
        .from('custom_products')
        .select('id, title, ai_generated_image_url, reference_sources, created_at, is_vendor_self_serve, analysis_json')
        .not('reference_sources', 'is', null)
        .not('ai_generated_image_url', 'is', null)
        .order('created_at', { ascending: false })
        .limit(3000);
    if (prodErr) throw prodErr;
    const matched = [];
    const comboCounts = {};
    (products || []).forEach(function (row) {
        if (row.is_vendor_self_serve === true) return;
        const aj = row.analysis_json && typeof row.analysis_json === 'object' ? row.analysis_json : {};
        if (aj.embed_visitor_design === true || aj.source === 'embed') return;
        if (!productReferencesPrototype(row.reference_sources, prototypeAssetId)) return;
        const comboKey = buildComboKeyFromReferenceSources(row.reference_sources);
        const comboLabel = buildComboLabelFromReferenceSources(row.reference_sources, titleById);
        matched.push({
            id: row.id,
            title: row.title || '',
            ai_generated_image_url: row.ai_generated_image_url,
            created_at: row.created_at,
            combo_key: comboKey,
            combo_label: comboLabel
        });
        if (!comboCounts[comboKey]) {
            comboCounts[comboKey] = { combo_key: comboKey, combo_label: comboLabel, count: 0 };
        }
        comboCounts[comboKey].count += 1;
    });
    let embedRows = [];
    try {
        const embedRes = await supabase
            .from('vendor_embed_designs')
            .select('id, ai_generated_image_url, reference_sources, created_at, custom_product_id, source, prompt')
            .eq('manufacturer_id', manufacturerId)
            .eq('prototype_asset_id', prototypeAssetId)
            .not('ai_generated_image_url', 'is', null)
            .order('created_at', { ascending: false })
            .limit(500);
        if (!embedRes.error) embedRows = embedRes.data || [];
    } catch (_) {}
    (embedRows || []).forEach(function (row) {
        const comboKey = buildComboKeyFromReferenceSources(row.reference_sources);
        const comboLabel = buildComboLabelFromReferenceSources(row.reference_sources, titleById);
        matched.push({
            id: row.custom_product_id || row.id,
            title: (row.prompt || '').trim() || 'Embed 訪客試做',
            ai_generated_image_url: row.ai_generated_image_url,
            created_at: row.created_at,
            combo_key: comboKey,
            combo_label: comboLabel,
            source: 'embed'
        });
        if (!comboCounts[comboKey]) {
            comboCounts[comboKey] = { combo_key: comboKey, combo_label: comboLabel, count: 0 };
        }
        comboCounts[comboKey].count += 1;
    });
    matched.sort(function (a, b) {
        return new Date(b.created_at || 0) - new Date(a.created_at || 0);
    });
    const generationCount = matched.length;
    const topCombos = Object.values(comboCounts)
        .sort(function (a, b) { return b.count - a.count; })
        .slice(0, 12)
        .map(function (c) {
            return {
                combo_key: c.combo_key,
                combo_label: c.combo_label,
                count: c.count,
                share_pct: generationCount ? Math.round((c.count / generationCount) * 1000) / 10 : 0
            };
        });
    const recentGenerations = matched.slice(0, 48).map(function (m) {
        return {
            id: m.id,
            title: m.title,
            ai_generated_image_url: m.ai_generated_image_url,
            created_at: m.created_at,
            combo_label: m.combo_label,
            source: m.source || 'custom_product'
        };
    });
    return {
        prototype: {
            id: proto.id,
            title: proto.title || '',
            image_url: proto.image_url || null
        },
        generation_count: generationCount,
        top_combos: topCombos,
        recent_generations: recentGenerations,
        scanned_products: (products || []).length
    };
}

async function fetchVendorAssetsByIdsForManufacturer(manufacturerId, ids, cols) {
    if (!ids.length) return [];
    const selectCols = cols || 'id, title, image_url, asset_kind, manufacturer_id';
    const { data, error } = await supabase
        .from('vendor_assets')
        .select(selectCols)
        .eq('manufacturer_id', manufacturerId)
        .in('id', ids);
    if (error) throw error;
    return data || [];
}

async function validatePrototypeLinkTargets(manufacturerId, prototypeId, linkedIds) {
    if (!linkedIds.length) return { ok: true, rows: [] };
    const rows = await fetchVendorAssetsByIdsForManufacturer(manufacturerId, linkedIds);
    if (rows.length !== linkedIds.length) {
        return { ok: false, error: '部分關聯素材不存在或不屬於您的廠商' };
    }
    for (const r of rows) {
        const k = normalizeVendorAssetKind(r.asset_kind);
        if (k !== 'material' && k !== 'part') {
            return { ok: false, error: '僅可關聯材料或配件素材' };
        }
        if (r.id === prototypeId) return { ok: false, error: '不可將主產品連結至自身' };
    }
    return { ok: true, rows };
}

async function validateLinkedAssetPrototypeTargets(manufacturerId, linkedAssetId, prototypeIds) {
    if (!prototypeIds.length) return { ok: true, rows: [] };
    const rows = await fetchVendorAssetsByIdsForManufacturer(manufacturerId, prototypeIds);
    if (rows.length !== prototypeIds.length) {
        return { ok: false, error: '部分主產品不存在或不屬於您的廠商' };
    }
    for (const r of rows) {
        if (normalizeVendorAssetKind(r.asset_kind) !== 'prototype') {
            return { ok: false, error: '僅可關聯數位原型（主產品）' };
        }
    }
    const { data: linkedRow } = await supabase
        .from('vendor_assets')
        .select('id, asset_kind')
        .eq('id', linkedAssetId)
        .eq('manufacturer_id', manufacturerId)
        .maybeSingle();
    if (!linkedRow) return { ok: false, error: '找不到該素材' };
    const lk = normalizeVendorAssetKind(linkedRow.asset_kind);
    if (lk !== 'material' && lk !== 'part') {
        return { ok: false, error: '僅材料或配件可設定關聯主產品' };
    }
    return { ok: true, rows };
}

async function replacePrototypeMaterialPartLinks(manufacturerId, prototypeId, linkedInput) {
    if (!(await vendorPrototypeLinksTableReady())) return null;
    const entries = normalizePrototypeLinkEntries(linkedInput);
    const linkedAssetIds = entries.map(function (e) { return e.linked_asset_id; });
    const { data: proto } = await supabase
        .from('vendor_assets')
        .select('id, asset_kind')
        .eq('id', prototypeId)
        .eq('manufacturer_id', manufacturerId)
        .maybeSingle();
    if (!proto) return '找不到該主產品';
    if (normalizeVendorAssetKind(proto.asset_kind) !== 'prototype') return '僅主產品可設定關聯材料／配件';
    const valid = await validatePrototypeLinkTargets(manufacturerId, prototypeId, linkedAssetIds);
    if (!valid.ok) return valid.error;
    const { error: delErr } = await supabase
        .from('vendor_asset_prototype_links')
        .delete()
        .eq('prototype_asset_id', prototypeId)
        .eq('manufacturer_id', manufacturerId);
    if (delErr) throw delErr;
    if (!entries.length) return null;
    const cols = await vendorPrototypeLinkSelectColumns();
    const metaOk = vendorPrototypeLinkMetaColumnsReady(cols);
    const inserts = entries.map(function (e, idx) {
        const row = {
            manufacturer_id: manufacturerId,
            prototype_asset_id: prototypeId,
            linked_asset_id: e.linked_asset_id,
            sort_order: idx
        };
        if (metaOk) {
            row.allow_multi_pick = e.allow_multi_pick !== false;
            row.pick_group = e.pick_group || null;
        }
        return row;
    });
    const { error: insErr } = await supabase.from('vendor_asset_prototype_links').insert(inserts);
    if (insErr) throw insErr;
    return null;
}

async function replaceLinkedAssetPrototypeLinks(manufacturerId, linkedAssetId, prototypeIds) {
    if (!(await vendorPrototypeLinksTableReady())) return null;
    const valid = await validateLinkedAssetPrototypeTargets(manufacturerId, linkedAssetId, prototypeIds);
    if (!valid.ok) return valid.error;
    const { error: delErr } = await supabase
        .from('vendor_asset_prototype_links')
        .delete()
        .eq('linked_asset_id', linkedAssetId)
        .eq('manufacturer_id', manufacturerId);
    if (delErr) throw delErr;
    if (!prototypeIds.length) return null;
    const inserts = prototypeIds.map((pid) => ({
        manufacturer_id: manufacturerId,
        prototype_asset_id: pid,
        linked_asset_id: linkedAssetId,
        sort_order: 0
    }));
    const { error: insErr } = await supabase.from('vendor_asset_prototype_links').insert(inserts);
    if (insErr) throw insErr;
    return null;
}

async function getLinkedAssetIdsForPrototype(manufacturerId, prototypeAssetId) {
    const pack = await getLinkedLinksForPrototype(manufacturerId, prototypeAssetId);
    return { ids: pack.ids, sortById: pack.sortById, metaById: pack.metaById };
}

async function getLinkedLinksForPrototype(manufacturerId, prototypeAssetId) {
    if (!(await vendorPrototypeLinksTableReady())) return { ids: [], sortById: {}, metaById: {} };
    const cols = await vendorPrototypeLinkSelectColumns();
    const { data, error } = await supabase
        .from('vendor_asset_prototype_links')
        .select(cols)
        .eq('prototype_asset_id', prototypeAssetId)
        .eq('manufacturer_id', manufacturerId)
        .order('sort_order', { ascending: true });
    if (error && error.code === '42P01') return { ids: [], sortById: {}, metaById: {} };
    if (error) throw error;
    const metaOk = vendorPrototypeLinkMetaColumnsReady(cols);
    const ids = [];
    const sortById = {};
    const metaById = {};
    (data || []).forEach((r) => {
        ids.push(r.linked_asset_id);
        sortById[r.linked_asset_id] = r.sort_order != null ? r.sort_order : 0;
        metaById[r.linked_asset_id] = {
            allow_multi_pick: !metaOk || r.allow_multi_pick !== false,
            pick_group: metaOk && r.pick_group ? String(r.pick_group).trim() : null
        };
    });
    return { ids, sortById, metaById };
}

function attachLinkMetaToLinkedAssetNodes(linkedAssets, metaById) {
    const meta = metaById || {};
    return (linkedAssets || []).map(function (node) {
        if (!node || !node.id) return node;
        const m = meta[node.id] || {};
        return {
            ...node,
            allow_multi_pick: m.allow_multi_pick !== false,
            pick_group: m.pick_group || null
        };
    });
}

async function getPrototypeIdsForLinkedAsset(manufacturerId, linkedAssetId) {
    if (!(await vendorPrototypeLinksTableReady())) return [];
    const { data, error } = await supabase
        .from('vendor_asset_prototype_links')
        .select('prototype_asset_id')
        .eq('linked_asset_id', linkedAssetId)
        .eq('manufacturer_id', manufacturerId);
    if (error && error.code === '42P01') return [];
    if (error) throw error;
    return (data || []).map((r) => r.prototype_asset_id);
}

function mapVendorAssetLinkTreeNode(r) {
    if (!r) return null;
    const kind = normalizeVendorAssetKind(r.asset_kind);
    const imageItems = buildVendorAssetImageItems(r);
    const imageUrls = imageItems.map((it) => it.url).filter(Boolean);
    return {
        id: r.id,
        title: r.title || '',
        description: (r.description != null ? String(r.description) : '').trim(),
        image_url: r.image_url || null,
        asset_kind: kind,
        is_public: !!r.is_public,
        image_urls: imageUrls,
        image_items: imageItems,
        inspiration_url: r.id ? ('/inspiration/' + kind + '/' + r.id) : null
    };
}

async function buildVendorProductLinkTreePayload(manufacturerId) {
    const cols = 'id, title, description, image_url, cover_image_label, gallery_images, asset_kind, sort_order, created_at, is_public';
    const { data: assets, error: assetErr } = await supabase
        .from('vendor_assets')
        .select(cols)
        .eq('manufacturer_id', manufacturerId)
        .order('sort_order', { ascending: true })
        .order('created_at', { ascending: false });
    if (assetErr) throw assetErr;
    const prototypes = [];
    let linkableAssets = [];
    (assets || []).forEach((r) => {
        const node = mapVendorAssetLinkTreeNode(r);
        if (!node) return;
        if (node.asset_kind === 'prototype') prototypes.push(node);
        else if (node.asset_kind === 'material' || node.asset_kind === 'part') linkableAssets.push(node);
    });
    if (linkableAssets.length) {
        try {
            linkableAssets = await attachCatalogGroupIdsToAssets(linkableAssets);
        } catch (catErr) {
            console.warn('buildVendorProductLinkTreePayload catalog_groups:', catErr && catErr.message);
        }
    }
    const tableReady = await vendorPrototypeLinksTableReady();
    let links = [];
    if (tableReady) {
        const linkCols = await vendorPrototypeLinkSelectColumns();
        const linkSelect = 'prototype_asset_id, ' + linkCols;
        const { data: linkRows, error: linkErr } = await supabase
            .from('vendor_asset_prototype_links')
            .select(linkSelect)
            .eq('manufacturer_id', manufacturerId)
            .order('sort_order', { ascending: true });
        if (linkErr && linkErr.code !== '42P01') throw linkErr;
        links = linkRows || [];
    }
    const linkedAssetIdSet = new Set(links.map((l) => l.linked_asset_id));
    const orphans = linkableAssets.filter((a) => !linkedAssetIdSet.has(a.id)).map((a) => a.id);
    const checks = [];
    prototypes.forEach((p) => {
        const n = links.filter((l) => l.prototype_asset_id === p.id).length;
        if (!n) {
            checks.push({
                prototype_id: p.id,
                code: 'no_links',
                severity: 'info',
                message: '尚未關聯材料或配件'
            });
        }
    });
    return {
        manufacturer_id: manufacturerId,
        prototypes,
        assets: linkableAssets,
        links,
        orphans,
        checks,
        table_ready: tableReady
    };
}

async function buildPublicPrototypeLinkTree(prototypeAssetId) {
    const { data: proto, error: protoErr } = await supabase
        .from('vendor_assets')
        .select('id, manufacturer_id, category_key, subcategory_key, title, description, image_url, cover_image_label, cover_link_group, gallery_images, asset_kind, is_public, customization_levels, production_type_key, capability_custom_labels')
        .eq('id', prototypeAssetId)
        .maybeSingle();
    if (protoErr) throw protoErr;
    if (!proto || normalizeVendorAssetKind(proto.asset_kind) !== 'prototype') {
        return { error: 'not_found' };
    }
    const internalPreview = false;
    if (!proto.is_public) return { error: 'not_public' };
    let mfrName = '廠商';
    const { data: mfr } = await supabase.from('manufacturers').select('id, name, is_active').eq('id', proto.manufacturer_id).eq('is_active', true).maybeSingle();
    if (!mfr) return { error: 'not_found' };
    mfrName = mfr.name || mfrName;
    
    // 查詢工藝能力
    const capabilityMap = await batchVendorAssetCapabilities([proto]);
    const capabilities = capabilityMap[proto.id] || [];
    
    const linkPack = await getLinkedAssetIdsForPrototype(proto.manufacturer_id, prototypeAssetId);
    const cardLinkedIds = linkPack.ids || [];
    /* 圖片層覆寫可帶入卡片預設以外的同廠材料／配件；卡片連結仍是 fallback。 */
    const imageOverrideIds = [...new Set(buildVendorAssetImageItems(proto)
        .flatMap((item) => normalizeImageLinkedAssetIds(item.linked_asset_ids)))];
    const linkedIds = [...new Set(cardLinkedIds.concat(imageOverrideIds))];
    let linkedAssets = [];
    if (linkedIds.length) {
        const { data: rows } = await supabase
            .from('vendor_assets')
            .select('id, title, description, image_url, cover_image_label, gallery_images, asset_kind, is_public')
            .eq('manufacturer_id', proto.manufacturer_id)
            .in('id', linkedIds);
        const byId = {};
        (rows || []).forEach((r) => {
            const kind = normalizeVendorAssetKind(r.asset_kind);
            if (kind === 'material' || kind === 'part') byId[r.id] = mapVendorAssetLinkTreeNode(r);
        });
        linkedAssets = linkedIds.map((id, idx) => {
            const node = byId[id];
            if (!node) return null;
            const m = (linkPack.metaById && linkPack.metaById[id]) || {};
            return {
                ...node,
                sort_order: linkPack.sortById[id] != null ? linkPack.sortById[id] : idx,
                allow_multi_pick: m.allow_multi_pick !== false,
                pick_group: m.pick_group || null,
                image_override_only: cardLinkedIds.indexOf(id) < 0
            };
        }).filter(Boolean);
    }
    if (linkedAssets.length) {
        try {
            linkedAssets = await attachCatalogGroupIdsToAssets(linkedAssets);
        } catch (catErr) {
            console.warn('buildPublicPrototypeLinkTree catalog_groups:', catErr && catErr.message);
        }
    }
    const protoNode = mapVendorAssetLinkTreeNode(proto) || {};
    return {
        prototype: {
            ...protoNode,
            manufacturer_id: proto.manufacturer_id,
            manufacturer_name: mfrName,
            category_key: proto.category_key || null,
            subcategory_key: proto.subcategory_key || null,
            customization_levels: proto.customization_levels || [],
            production_type_key: proto.production_type_key || null,
            capability_custom_labels: proto.capability_custom_labels || [],
            capabilities: capabilities
        },
        linked_assets: linkedAssets,
        material_count: linkedAssets.filter((a) => a.asset_kind === 'material').length,
        part_count: linkedAssets.filter((a) => a.asset_kind === 'part').length
    };
}

async function buildVendorPrototypeLinkTreeExport(manufacturerId, prototypeAssetId) {
    const { data: proto, error: protoErr } = await supabase
        .from('vendor_assets')
        .select('id, manufacturer_id, category_key, subcategory_key, title, description, image_url, cover_image_label, gallery_images, asset_kind, is_public')
        .eq('id', prototypeAssetId)
        .eq('manufacturer_id', manufacturerId)
        .maybeSingle();
    if (protoErr) throw protoErr;
    if (!proto || normalizeVendorAssetKind(proto.asset_kind) !== 'prototype') {
        return { error: 'not_found' };
    }
    let mfrName = '廠商';
    const { data: mfr } = await supabase.from('manufacturers').select('id, name').eq('id', manufacturerId).maybeSingle();
    if (mfr) mfrName = mfr.name || mfrName;
    const linkPack = await getLinkedAssetIdsForPrototype(manufacturerId, prototypeAssetId);
    const linkedIds = linkPack.ids || [];
    let linkedAssets = [];
    if (linkedIds.length) {
        const { data: rows } = await supabase
            .from('vendor_assets')
            .select('id, title, description, image_url, cover_image_label, gallery_images, asset_kind, is_public')
            .eq('manufacturer_id', manufacturerId)
            .in('id', linkedIds);
        const byId = {};
        (rows || []).forEach((r) => { byId[r.id] = mapVendorAssetLinkTreeNode(r); });
        linkedAssets = linkedIds.map((id, idx) => {
            const node = byId[id];
            if (!node) return null;
            const m = (linkPack.metaById && linkPack.metaById[id]) || {};
            return {
                ...node,
                sort_order: linkPack.sortById[id] != null ? linkPack.sortById[id] : idx,
                allow_multi_pick: m.allow_multi_pick !== false,
                pick_group: m.pick_group || null
            };
        }).filter(Boolean);
    }
    const protoNode = mapVendorAssetLinkTreeNode(proto) || {};
    return {
        prototype: {
            ...protoNode,
            manufacturer_id: proto.manufacturer_id,
            manufacturer_name: mfrName,
            category_key: proto.category_key || null,
            subcategory_key: proto.subcategory_key || null
        },
        linked_assets: linkedAssets,
        material_count: linkedAssets.filter((a) => a.asset_kind === 'material').length,
        part_count: linkedAssets.filter((a) => a.asset_kind === 'part').length
    };
}

async function sendProductLinkTreePdfResponse(res, payload) {
    if (!payload || payload.error || !payload.prototype) {
        return res.status(404).json({ error: '找不到主產品' });
    }
    const pdf = await productLinkTreePdf.generateProductLinkTreePdf(payload);
    const fname = productLinkTreePdf.safePdfFilename(payload.prototype.title);
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader(
        'Content-Disposition',
        "attachment; filename=\"matchdo-link-tree.pdf\"; filename*=UTF-8''" + encodeURIComponent(fname)
    );
    res.send(pdf);
}

async function getPrototypeLinkKindCounts(manufacturerId, prototypeAssetId) {
    if (!(await vendorPrototypeLinksTableReady())) {
        return { material_count: 0, part_count: 0 };
    }
    const { data: links, error: linkErr } = await supabase
        .from('vendor_asset_prototype_links')
        .select('linked_asset_id')
        .eq('prototype_asset_id', prototypeAssetId)
        .eq('manufacturer_id', manufacturerId);
    if (linkErr && linkErr.code === '42P01') return { material_count: 0, part_count: 0 };
    if (linkErr) throw linkErr;
    const ids = (links || []).map((r) => r.linked_asset_id).filter(Boolean);
    if (!ids.length) return { material_count: 0, part_count: 0 };
    const { data: assets, error: assetErr } = await supabase
        .from('vendor_assets')
        .select('id, asset_kind')
        .eq('manufacturer_id', manufacturerId)
        .in('id', ids);
    if (assetErr) throw assetErr;
    let material_count = 0;
    let part_count = 0;
    (assets || []).forEach((r) => {
        const k = normalizeVendorAssetKind(r.asset_kind);
        if (k === 'material') material_count += 1;
        else if (k === 'part') part_count += 1;
    });
    return { material_count, part_count };
}

/** 瀏覽款式列表：批次計算各原型的材料／配件關聯筆數 */
async function batchPrototypeLinkCounts(prototypeRows) {
    const out = {};
    (prototypeRows || []).forEach((r) => {
        if (r && r.id) out[r.id] = { material_count: 0, part_count: 0 };
    });
    const ids = Object.keys(out);
    if (!ids.length || !(await vendorPrototypeLinksTableReady())) return out;
    const { data: links, error: linkErr } = await supabase
        .from('vendor_asset_prototype_links')
        .select('prototype_asset_id, linked_asset_id, manufacturer_id')
        .in('prototype_asset_id', ids);
    if (linkErr) {
        if (linkErr.code === '42P01') return out;
        throw linkErr;
    }
    const linkedIds = [...new Set((links || []).map((l) => l.linked_asset_id).filter(Boolean))];
    if (!linkedIds.length) return out;
    const { data: assets, error: assetErr } = await supabase
        .from('vendor_assets')
        .select('id, asset_kind')
        .in('id', linkedIds);
    if (assetErr) throw assetErr;
    const kindById = {};
    (assets || []).forEach((a) => { kindById[a.id] = normalizeVendorAssetKind(a.asset_kind); });
    (links || []).forEach((l) => {
        const pid = l.prototype_asset_id;
        if (!out[pid]) return;
        const k = kindById[l.linked_asset_id];
        if (k === 'material') out[pid].material_count += 1;
        else if (k === 'part') out[pid].part_count += 1;
    });
    return out;
}

/** 批次查詢 vendor_asset 的工藝能力標籤（taxonomy capability） */
async function batchVendorAssetCapabilities(assetRows) {
    const out = {};
    (assetRows || []).forEach((r) => {
        if (r && r.id) out[r.id] = [];
    });
    const ids = Object.keys(out);
    if (!ids.length) return out;
    try {
        const { data: links, error: linkErr } = await supabase
            .from('vendor_asset_taxonomy_links')
            .select('asset_id, taxonomy_key')
            .in('asset_id', ids);
        if (linkErr) return out;
        const taxKeys = [...new Set((links || []).map((l) => l.taxonomy_key).filter(Boolean))];
        if (!taxKeys.length) return out;
        const { data: nodes, error: nodeErr } = await supabase
            .from('taxonomy_nodes')
            .select('key, name_zh, dimension')
            .in('key', taxKeys)
            .eq('dimension', 'capability')
            .eq('is_active', true);
        if (nodeErr) return out;
        const nodeMap = {};
        (nodes || []).forEach((n) => { nodeMap[n.key] = n; });
        (links || []).forEach((l) => {
            const node = nodeMap[l.taxonomy_key];
            if (node && out[l.asset_id]) {
                out[l.asset_id].push({ key: node.key, name: node.name_zh });
            }
        });
    } catch (e) {
        console.error('batchVendorAssetCapabilities error:', e);
    }
    return out;
}

/** 廠商素材對外分享用 absolute URL（試做／導覽） */
function buildVendorAssetAbsoluteShareUrls(item, linkCount) {
    const base = String(BASE_URL || '').replace(/\/$/, '');
    if (!base || !item || !item.id) return {};
    const kind = normalizeVendorAssetKind(item.asset_kind);
    const enc = (s) => encodeURIComponent(String(s));
    const q = (path) => base + path;
    if (kind === 'prototype') {
        let designPath = '/custom-product.html?tab=product-design&prototype_asset_id=' + enc(item.id);
        if (item.manufacturer_id) designPath += '&manufacturer_id=' + enc(item.manufacturer_id);
        if (item.category_key) designPath += '&category_key=' + enc(item.category_key);
        if (item.subcategory_key) designPath += '&subcategory_key=' + enc(item.subcategory_key);
        const lc = linkCount != null ? Number(linkCount) : 0;
        return {
            design_share_url: q(designPath),
            guide_share_url: lc > 0 ? q('/product-tree.html?prototype_asset_id=' + enc(item.id)) : null
        };
    }
    if (kind === 'material' || kind === 'part') {
        let designPath = '/custom-product.html?tab=product-design&vendor_asset_id=' + enc(item.id);
        if (item.manufacturer_id) designPath += '&manufacturer_id=' + enc(item.manufacturer_id);
        if (item.category_key) designPath += '&category_key=' + enc(item.category_key);
        if (item.subcategory_key) designPath += '&subcategory_key=' + enc(item.subcategory_key);
        return { design_share_url: q(designPath), guide_share_url: null };
    }
    return {};
}

function sortVendorAssetsWithPrototypeLinks(items, linkedIdSet, sortById) {
    if (!linkedIdSet || !linkedIdSet.size) return items;
    const linked = [];
    const rest = [];
    items.forEach((it) => {
        if (linkedIdSet.has(it.id)) linked.push(it);
        else rest.push(it);
    });
    linked.sort((a, b) => {
        const sa = sortById[a.id] != null ? sortById[a.id] : 0;
        const sb = sortById[b.id] != null ? sortById[b.id] : 0;
        if (sa !== sb) return sa - sb;
        return String(a.title || '').localeCompare(String(b.title || ''), 'zh-Hant');
    });
    return linked.concat(rest);
}

function attachPrototypeLinkFlagsToItems(items, linkedIdSet) {
    if (!linkedIdSet || !linkedIdSet.size) {
        return items.map((it) => ({ ...it, is_linked_to_prototype: false }));
    }
    return items.map((it) => ({
        ...it,
        is_linked_to_prototype: linkedIdSet.has(it.id)
    }));
}

async function getAssetIdsForCatalogGroup(catalogGroupId, manufacturerId) {
    if (!catalogGroupId) return { assetIds: null, error: null };
    const { data: grp, error: grpErr } = await supabase
        .from('vendor_catalog_groups')
        .select('id, manufacturer_id')
        .eq('id', catalogGroupId)
        .maybeSingle();
    if (grpErr && grpErr.code === '42P01') return { assetIds: null, error: 'no_table' };
    if (grpErr) throw grpErr;
    if (!grp) return { assetIds: [], error: 'not_found' };
    if (manufacturerId && grp.manufacturer_id !== manufacturerId) return { assetIds: [], error: 'mismatch' };
    const { data: links, error: linkErr } = await supabase
        .from('vendor_asset_group_links')
        .select('asset_id')
        .eq('group_id', catalogGroupId);
    if (linkErr && linkErr.code === '42P01') return { assetIds: null, error: 'no_table' };
    if (linkErr) throw linkErr;
    return { assetIds: (links || []).map((r) => r.asset_id), group: grp };
}

function normalizeVendorCatalogGroupKindFilter(q) {
    const k = String(q || '').trim().toLowerCase();
    if (k === 'material' || k === 'prototype' || k === 'part') return k;
    return null;
}

async function buildVendorCatalogGroupsPayload(manufacturerId, assetKindFilter, lang) {
    const contentLang = normalizeVendorContentLang(lang);
    const kindFilter = normalizeVendorCatalogGroupKindFilter(assetKindFilter);
    let { data: groups, error } = await supabase
        .from('vendor_catalog_groups')
        .select('id, manufacturer_id, name, name_en, slug, parent_id, sort_order, asset_kind, created_at, updated_at')
        .eq('manufacturer_id', manufacturerId)
        .order('sort_order', { ascending: true })
        .order('name', { ascending: true });
    if (error && error.code === '42703') {
        ({ data: groups, error } = await supabase
            .from('vendor_catalog_groups')
            .select('id, manufacturer_id, name, slug, parent_id, sort_order, created_at, updated_at')
            .eq('manufacturer_id', manufacturerId)
            .order('sort_order', { ascending: true })
            .order('name', { ascending: true }));
        (groups || []).forEach((g) => { g.name_en = null; });
    }
    if (error) throw error;
    let list = groups || [];
    if (kindFilter) {
        list = list.filter((g) => vendorCatalogGroupRowAssetKind(g) === kindFilter);
    }
    const groupIds = list.map((g) => g.id);
    let countMap = {};
    if (groupIds.length) {
        const { data: links } = await supabase.from('vendor_asset_group_links').select('group_id, asset_id').in('group_id', groupIds);
        const assetIds = [...new Set((links || []).map((l) => l.asset_id).filter(Boolean))];
        const assetKindById = {};
        if (assetIds.length) {
            const { data: assets } = await supabase.from('vendor_assets').select('id, asset_kind').in('id', assetIds);
            (assets || []).forEach((a) => { assetKindById[a.id] = normalizeVendorAssetKind(a.asset_kind); });
        }
        (links || []).forEach((l) => {
            const ak = assetKindById[l.asset_id] || 'prototype';
            if (kindFilter && ak !== kindFilter) return;
            countMap[l.group_id] = (countMap[l.group_id] || 0) + 1;
        });
    }
    const byId = {};
    list.forEach((g) => {
        byId[g.id] = { ...g, asset_count: countMap[g.id] || 0, children: [] };
    });
    const roots = [];
    list.forEach((g) => {
        const node = byId[g.id];
        if (g.parent_id && byId[g.parent_id]) byId[g.parent_id].children.push(node);
        else roots.push(node);
    });
    function flatten(nodes, depth, out) {
        nodes.sort((a, b) => (a.sort_order - b.sort_order) || String(a.name).localeCompare(String(b.name), 'zh-Hant'));
        nodes.forEach((n) => {
            const pad = depth > 0 ? '\u3000'.repeat(Math.min(depth, 3)) : '';
            const displayName = pickVendorLocalizedText(n.name, n.name_en, contentLang);
            out.push({
                id: n.id,
                name: displayName,
                name_zh: n.name,
                name_en: n.name_en || '',
                slug: n.slug,
                parent_id: n.parent_id,
                sort_order: n.sort_order,
                asset_count: n.asset_count,
                asset_kind: vendorCatalogGroupRowAssetKind(n),
                depth,
                label: pad + displayName + (n.asset_count ? ` (${n.asset_count})` : '')
            });
            if (n.children && n.children.length) flatten(n.children, depth + 1, out);
        });
    }
    const flat = [];
    flatten(roots, 0, flat);
    return { tree: roots, flat };
}

async function setVendorAssetCatalogGroups(assetId, manufacturerId, groupIds) {
    if (!(await vendorCatalogGroupsTableReady()) || !(await vendorAssetGroupLinksTableReady())) return;
    const ids = [...new Set((groupIds || []).map((id) => String(id).trim()).filter(Boolean))];
    if (ids.length) {
        const { data: assetRow } = await supabase.from('vendor_assets').select('asset_kind').eq('id', assetId).maybeSingle();
        const assetKind = normalizeVendorAssetKind(assetRow && assetRow.asset_kind);
        let { data: owned, error: ownErr } = await supabase
            .from('vendor_catalog_groups')
            .select('id, asset_kind')
            .eq('manufacturer_id', manufacturerId)
            .in('id', ids);
        if (ownErr && ownErr.code === '42703') {
            ({ data: owned } = await supabase
                .from('vendor_catalog_groups')
                .select('id')
                .eq('manufacturer_id', manufacturerId)
                .in('id', ids));
        }
        const allowed = new Set((owned || []).filter((g) => vendorCatalogGroupRowAssetKind(g) === assetKind).map((g) => g.id));
        const valid = ids.filter((id) => allowed.has(id));
        await supabase.from('vendor_asset_group_links').delete().eq('asset_id', assetId);
        if (valid.length) {
            await supabase.from('vendor_asset_group_links').insert(valid.map((group_id) => ({ asset_id: assetId, group_id })));
        }
    } else {
        await supabase.from('vendor_asset_group_links').delete().eq('asset_id', assetId);
    }
}

async function attachCatalogGroupIdsToAssets(items) {
    if (!(await vendorCatalogGroupsTableReady()) || !(await vendorAssetGroupLinksTableReady()) || !items || !items.length) return items;
    const assetIds = items.map((r) => r.id).filter(Boolean);
    if (!assetIds.length) return items;
    const { data: links, error: linkErr } = await supabase
        .from('vendor_asset_group_links')
        .select('asset_id, group_id')
        .in('asset_id', assetIds);
    if (linkErr && linkErr.code === '42P01') return items;
    if (linkErr) throw linkErr;
    const groupIds = [...new Set((links || []).map((l) => l.group_id).filter(Boolean))];
    const groupsById = {};
    if (groupIds.length) {
        let { data: groups, error: grpErr } = await supabase
            .from('vendor_catalog_groups')
            .select('id, name, parent_id, asset_kind')
            .in('id', groupIds);
        if (grpErr && grpErr.code === '42703') {
            ({ data: groups, error: grpErr } = await supabase
                .from('vendor_catalog_groups')
                .select('id, name, parent_id')
                .in('id', groupIds));
        }
        if (grpErr) throw grpErr;
        (groups || []).forEach((g) => {
            const name = (g.name != null) ? String(g.name).trim() : '';
            if (g.id && name) groupsById[g.id] = { id: g.id, name, parent_id: g.parent_id || null, asset_kind: g.asset_kind };
        });
        const parentIds = [...new Set(Object.values(groupsById).map((g) => g.parent_id).filter(Boolean))];
        const missingParentIds = parentIds.filter((id) => !groupsById[id]);
        if (missingParentIds.length) {
            let { data: parents, error: parentErr } = await supabase
                .from('vendor_catalog_groups')
                .select('id, name, parent_id, asset_kind')
                .in('id', missingParentIds);
            if (parentErr && parentErr.code === '42703') {
                ({ data: parents, error: parentErr } = await supabase
                    .from('vendor_catalog_groups')
                    .select('id, name, parent_id')
                    .in('id', missingParentIds));
            }
            if (!parentErr) {
                (parents || []).forEach((g) => {
                    const name = (g.name != null) ? String(g.name).trim() : '';
                    if (g.id && name) groupsById[g.id] = { id: g.id, name, parent_id: g.parent_id || null, asset_kind: g.asset_kind };
                });
            }
        }
    }
    const map = {};
    (links || []).forEach((l) => {
        if (!map[l.asset_id]) map[l.asset_id] = [];
        const g = groupsById[l.group_id];
        if (g) map[l.asset_id].push(g);
    });
    return items.map((r) => {
        const itemKind = normalizeVendorAssetKind(r.asset_kind);
        const cats = (map[r.id] || []).filter((g) => vendorCatalogGroupRowAssetKind(g) === itemKind);
        return {
            ...r,
            catalog_group_ids: cats.map((g) => g.id),
            catalog_groups: cats.map((g) => ({
                id: g.id,
                name: g.name,
                parent_id: g.parent_id,
                parent_name: g.parent_id && groupsById[g.parent_id] ? groupsById[g.parent_id].name : null
            }))
        };
    });
}

// GET /api/me/vendor-catalog-groups — 廠商自己的分類樹
app.get('/api/me/vendor-catalog-groups', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        if (!(await vendorCatalogGroupsTableReady())) {
            return res.json({ tree: [], flat: [], message: '請執行 docs/add-vendor-catalog-groups.sql' });
        }
        const assetKindQ = (req.query.asset_kind || '').trim().toLowerCase();
        const assetKindFilter = normalizeVendorCatalogGroupKindFilter(assetKindQ);
        let hasAssetKindColumn = true;
        const probe = await supabase.from('vendor_catalog_groups').select('asset_kind').limit(1);
        if (probe.error && probe.error.code === '42703') hasAssetKindColumn = false;
        if ((assetKindFilter === 'material' || assetKindFilter === 'part') && !hasAssetKindColumn) {
            return res.json({
                tree: [],
                flat: [],
                asset_kind_split_unavailable: true,
                message: '請執行 docs/add-vendor-catalog-groups-asset-kind.sql'
            });
        }
        const payload = await buildVendorCatalogGroupsPayload(manufacturerId, assetKindFilter);
        res.json({ ...payload, asset_kind_split_unavailable: false });
    } catch (e) {
        console.error('GET /api/me/vendor-catalog-groups:', e);
        res.status(500).json({ error: '查詢失敗' });
    }
});

function isMissingVendorCatalogAssetKindError(error) {
    if (!error) return false;
    if (error.code === '42703') return true;
    if (error.code === 'PGRST204') {
        const msg0 = String(error.message || error.details || '').toLowerCase();
        if (msg0.includes('asset_kind')) return true;
    }
    const msg = String(error.message || error.details || error.hint || '').toLowerCase();
    return msg.includes('asset_kind') && (msg.includes('column') || msg.includes('schema cache') || msg.includes('does not exist'));
}

// POST /api/me/vendor-catalog-groups — 新增分類
app.post('/api/me/vendor-catalog-groups', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        if (!(await vendorCatalogGroupsTableReady())) {
            return res.status(500).json({ error: '請執行 docs/add-vendor-catalog-groups.sql' });
        }
        const body = req.body || {};
        const name = (body.name || '').trim();
        if (!name) return res.status(400).json({ error: '請填寫分類名稱' });
        const parentId = (body.parent_id || '').trim() || null;
        if (parentId) {
            const { data: parent } = await supabase.from('vendor_catalog_groups').select('id').eq('id', parentId).eq('manufacturer_id', manufacturerId).maybeSingle();
            if (!parent) return res.status(400).json({ error: '上層分類不存在' });
        }
        const catalogKind = normalizeVendorAssetKind(body.asset_kind);
        const slugBase = (body.slug || '').trim() || slugifyVendorCatalogGroupName(name);
        const sortOrder = (body.sort_order != null && !isNaN(body.sort_order)) ? parseInt(body.sort_order, 10) : 0;
        let data = null;
        let error = null;
        // 舊庫 slug 唯一跨類型：撞到原型同名時加後綴重試；新庫遷移後同類型才需後綴
        for (let attempt = 0; attempt < 6; attempt++) {
            let slug = slugBase;
            if (attempt === 1) slug = slugBase + '-' + catalogKind;
            else if (attempt > 1) slug = slugBase + '-' + catalogKind + '-' + attempt;
            slug = String(slug).slice(0, 64);
            const row = {
                manufacturer_id: manufacturerId,
                name,
                slug,
                parent_id: parentId,
                sort_order: sortOrder,
                asset_kind: catalogKind
            };
            ({ data, error } = await supabase.from('vendor_catalog_groups').insert(row).select().single());
            if (!error) break;
            if (isMissingVendorCatalogAssetKindError(error)) {
                if (catalogKind === 'material' || catalogKind === 'part') {
                    return res.status(503).json({ error: '請先執行 docs/add-vendor-catalog-groups-asset-kind.sql，材料／零件才能使用獨立分類' });
                }
                const fallback = { manufacturer_id: manufacturerId, name, slug, parent_id: parentId, sort_order: sortOrder };
                ({ data, error } = await supabase.from('vendor_catalog_groups').insert(fallback).select().single());
                if (!error) break;
                if (error.code === '23505' && attempt < 5) continue;
                break;
            }
            if (error.code === '23505' && attempt < 5) continue;
            break;
        }
        if (error) {
            console.error('POST /api/me/vendor-catalog-groups:', error);
            if (error.code === '23505') {
                return res.status(409).json({ error: '此分類名稱已存在，請換一個名稱' });
            }
            return res.status(500).json({
                error: '新增失敗',
                details: error.message || error.code || undefined
            });
        }
        res.status(201).json(data);
    } catch (e) {
        console.error('POST /api/me/vendor-catalog-groups 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PUT /api/me/vendor-catalog-groups/:id
app.put('/api/me/vendor-catalog-groups/:id', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const id = (req.params.id || '').trim();
        const body = req.body || {};
        const updates = { updated_at: new Date().toISOString() };
        if (body.name !== undefined) updates.name = (body.name || '').trim() || null;
        if (body.slug !== undefined) updates.slug = (body.slug || '').trim() || null;
        if (body.sort_order !== undefined) updates.sort_order = parseInt(body.sort_order, 10) || 0;
        if (body.parent_id !== undefined) {
            const pid = (body.parent_id || '').trim() || null;
            if (pid === id) return res.status(400).json({ error: '不可將自己設為上層' });
            if (pid) {
                const { data: parent } = await supabase.from('vendor_catalog_groups').select('id').eq('id', pid).eq('manufacturer_id', manufacturerId).maybeSingle();
                if (!parent) return res.status(400).json({ error: '上層分類不存在' });
            }
            updates.parent_id = pid;
        }
        const { data, error } = await supabase
            .from('vendor_catalog_groups')
            .update(updates)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select()
            .single();
        if (error) return res.status(500).json({ error: '更新失敗' });
        if (!data) return res.status(404).json({ error: '找不到分類' });
        res.json(data);
    } catch (e) {
        console.error('PUT /api/me/vendor-catalog-groups:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/vendor-catalog-groups/reorder — 拖曳排序後批次更新 sort_order
app.post('/api/me/vendor-catalog-groups/reorder', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        if (!(await vendorCatalogGroupsTableReady())) {
            return res.status(500).json({ error: '請執行 docs/add-vendor-catalog-groups.sql' });
        }
        const order = req.body && req.body.order;
        if (!Array.isArray(order) || !order.length) {
            return res.status(400).json({ error: '請提供 order 陣列（分類 id 順序）' });
        }
        const ids = order.map((id) => String(id).trim()).filter(Boolean);
        const kindFilter = normalizeVendorCatalogGroupKindFilter(req.body.asset_kind);
        let { data: existing, error: existErr } = await supabase
            .from('vendor_catalog_groups')
            .select('id, asset_kind')
            .eq('manufacturer_id', manufacturerId);
        if (existErr && existErr.code === '42703') {
            ({ data: existing } = await supabase
                .from('vendor_catalog_groups')
                .select('id')
                .eq('manufacturer_id', manufacturerId));
        }
        const allowed = new Set((existing || []).filter((r) => {
            if (!kindFilter) return true;
            return vendorCatalogGroupRowAssetKind(r) === kindFilter;
        }).map((r) => r.id));
        if (!ids.every((id) => allowed.has(id))) {
            return res.status(400).json({ error: 'order 含有不屬於此廠商或此類型的分類' });
        }
        for (let i = 0; i < ids.length; i++) {
            const { error } = await supabase
                .from('vendor_catalog_groups')
                .update({ sort_order: i, updated_at: new Date().toISOString() })
                .eq('id', ids[i])
                .eq('manufacturer_id', manufacturerId);
            if (error) return res.status(500).json({ error: '排序儲存失敗' });
        }
        const payload = await buildVendorCatalogGroupsPayload(manufacturerId, kindFilter);
        res.json({ success: true, ...payload });
    } catch (e) {
        console.error('POST /api/me/vendor-catalog-groups/reorder:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

