// PUT /api/me/vendor-assets/:id/prototype-links — 以主產品為準整批更新關聯
app.put('/api/me/vendor-assets/:id/prototype-links', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        let entries = parseLinkedLinksFromBody(req.body);
        if (entries === undefined) {
            const linkedIds = parseJsonUuidArrayFromBody(req.body.linked_asset_ids);
            if (linkedIds === null) return res.status(400).json({ error: 'linked_asset_ids 須為 UUID 陣列' });
            entries = normalizePrototypeLinkEntries(linkedIds);
        } else if (entries === null) {
            return res.status(400).json({ error: 'linked_links 格式錯誤' });
        }
        const linkErr = await replacePrototypeMaterialPartLinks(manufacturerId, id, entries);
        if (linkErr) return res.status(400).json({ error: linkErr });
        const linkPack = await getLinkedAssetIdsForPrototype(manufacturerId, id);
        const linkedLinks = (linkPack.ids || []).map(function (lid) {
            const m = (linkPack.metaById && linkPack.metaById[lid]) || {};
            return {
                linked_asset_id: lid,
                allow_multi_pick: m.allow_multi_pick !== false,
                pick_group: m.pick_group || null
            };
        });
        res.json({
            prototype_asset_id: id,
            linked_asset_ids: linkPack.ids,
            linked_links: linkedLinks,
            sort_by_id: linkPack.sortById
        });
    } catch (e) {
        console.error('PUT /api/me/vendor-assets/:id/prototype-links:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/vendor-assets/browse-prototypes — 公開：瀏覽可訂製數位原型（與 GET /api/vendor-assets?asset_kind=prototype 同邏輯）
app.get('/api/vendor-assets/browse-prototypes', async (req, res) => {
    try {
        const internalPreview = await getRequestInternalPreviewFlag(req);
        const manufacturerId = (req.query.manufacturer_id || '').trim() || null;
        const categoryKey = (req.query.category_key || '').trim() || null;
        const subcategoryKey = (req.query.subcategory_key || '').trim() || null;
        const searchQ = (req.query.q || req.query.search || '').trim() || null;
        const page = parseVendorAssetsListPageParams(req.query);
        if (!categoryKey && !manufacturerId) {
            return res.status(400).json({ error: '請傳入 category_key 或 manufacturer_id' });
        }
        const assetKindFilter = 'prototype';
        const selectCols = 'id, manufacturer_id, category_key, subcategory_key, title, description, image_url, cover_image_label, gallery_images, sort_order, created_at, asset_kind, is_public, style_key, customization_levels, production_type_key, capability_custom_labels';
        async function runBrowseQuery(cols) {
            let q = supabase
                .from('vendor_assets')
                .select(cols)
                .order('sort_order', { ascending: true })
                .order('created_at', { ascending: false });
            if (!internalPreview) q = q.eq('is_public', true);
            if (categoryKey) q = q.eq('category_key', categoryKey);
            if (manufacturerId) q = q.eq('manufacturer_id', manufacturerId);
            if (assetKindFilter && cols.includes('asset_kind')) q = q.eq('asset_kind', assetKindFilter);
            return q;
        }
        let { data: rows, error } = await runBrowseQuery(selectCols);
        if (error && error.code === '42703') {
            const legacyCols = selectCols.split(',').map((c) => c.trim())
                .filter((c) => c && c !== 'asset_kind' && c !== 'style_key' && 
                        c !== 'customization_levels' && c !== 'production_type_key' && 
                        c !== 'capability_custom_labels')
                .join(', ');
            ({ data: rows, error } = await runBrowseQuery(legacyCols));
        }
        if (error) {
            if (error.code === '42P01') return res.status(200).json({ items: [], manufacturers: [], total: 0, limit: page.limit, offset: page.offset });
            console.error('GET browse-prototypes:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        let list = rows || [];
        if (list.length) {
            const hasAssetKindCol = list.some((r) => r.asset_kind != null && String(r.asset_kind).trim() !== '');
            if (hasAssetKindCol) {
                list = list.filter((r) => effectiveVendorAssetKind(r) === assetKindFilter);
            }
        }
        let subcategory_relaxed = false;
        if (subcategoryKey && list.length) {
            const strict = list.filter((r) => (r.subcategory_key || '') === subcategoryKey);
            if (strict.length) {
                list = strict;
            } else {
                subcategory_relaxed = true;
            }
        }
        const mfrIds = [...new Set(list.map((r) => r.manufacturer_id).filter(Boolean))];
        const mfrMap = await buildManufacturerMapForVendorAssetList(mfrIds, { internalPreview });
        list = list.filter((r) => {
            const mfr = getManufacturerFromMap(mfrMap, r.manufacturer_id);
            if (!mfr) return !!internalPreview;
            if (internalPreview) return true;
            return vendorAssetVisibleToPublicAudience(mfr, r);
        });
        if (searchQ) {
            const qLower = searchQ.toLowerCase();
            list = list.filter((r) => {
                const title = String(r.title || '').toLowerCase();
                const desc = String(r.description || '').toLowerCase();
                const mfr = getManufacturerFromMap(mfrMap, r.manufacturer_id);
                const mname = mfr ? String(mfr.name || '').toLowerCase() : '';
                return title.includes(qLower) || desc.includes(qLower) || mname.includes(qLower);
            });
        }
        const linkCounts = await batchPrototypeLinkCounts(list);
        const capabilityMap = await batchVendorAssetCapabilities(list);
        const manufacturers = [...new Set(list.map((r) => r.manufacturer_id).filter(Boolean))].map((id) => {
            const mfr = getManufacturerFromMap(mfrMap, id);
            return {
                id,
                name: manufacturerNameForVendorAssetItem(mfrMap, id),
                logo_url: manufacturerLogoFromRow(mfr),
                profile_url: '/vendor-profile.html?id=' + encodeURIComponent(id)
            };
        }).sort((a, b) => String(a.name).localeCompare(String(b.name), 'zh-Hant'));
        const itemsAll = list.map((r) => {
            const counts = linkCounts[r.id] || { material_count: 0, part_count: 0 };
            const capabilities = capabilityMap[r.id] || [];
            const mfr = getManufacturerFromMap(mfrMap, r.manufacturer_id);
            const node = mapVendorAssetLinkTreeNode(r) || {};
            const imageUrls = node.image_urls || [];
            return {
                id: r.id,
                title: r.title,
                description: r.description,
                image_url: node.image_url || r.image_url,
                image_urls: imageUrls,
                image_items: node.image_items || [],
                image_count: imageUrls.length,
                category_key: r.category_key,
                subcategory_key: r.subcategory_key,
                style_key: r.style_key || null,
                manufacturer_id: r.manufacturer_id,
                manufacturer_name: manufacturerNameForVendorAssetItem(mfrMap, r.manufacturer_id),
                manufacturer_logo_url: (() => { const m = getManufacturerFromMap(mfrMap, r.manufacturer_id); return manufacturerLogoFromRow(m); })(),
                manufacturer_profile_url: r.manufacturer_id ? '/vendor-profile.html?id=' + encodeURIComponent(r.manufacturer_id) : null,
                material_count: counts.material_count,
                part_count: counts.part_count,
                link_count: counts.material_count + counts.part_count,
                match_guide_url: '/product-tree.html?prototype_asset_id=' + encodeURIComponent(r.id),
                customization_levels: r.customization_levels || [],
                production_type_key: r.production_type_key || null,
                capabilities: capabilities,
                capability_custom_labels: r.capability_custom_labels || []
            };
        });
        const paged = paginateVendorAssetList(itemsAll, page);
        // 圖庫順序／封面會即時變動，勿讓 CDN／瀏覽器共用長快取
        res.set('Cache-Control', 'private, max-age=0, must-revalidate');
        res.json({
            items: paged.items,
            manufacturers,
            total: paged.total,
            limit: paged.limit,
            offset: paged.offset,
            subcategory_relaxed: subcategory_relaxed
        });
    } catch (e) {
        console.error('GET /api/vendor-assets/browse-prototypes:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/vendor-assets/:id/link-tree — 公開：單一主產品關聯子樹（guide 頁）
app.get('/api/vendor-assets/:id/link-tree', async (req, res) => {
    try {
        const id = (req.params.id || '').trim();
        if (!id) return res.status(400).json({ error: '缺少 id' });
        const internalPreview = await getRequestInternalPreviewFlag(req);
        const payload = await buildPublicPrototypeLinkTree(id);
        if (payload.error === 'not_found') return res.status(404).json({ error: '找不到主產品' });
        if (payload.error === 'not_public') {
            if (!internalPreview) return res.status(404).json({ error: '此主產品未公開' });
            const { data: protoRow } = await supabase
                .from('vendor_assets')
                .select('id, manufacturer_id, category_key, subcategory_key, title, description, image_url, cover_image_label, gallery_images, asset_kind, is_public')
                .eq('id', id)
                .maybeSingle();
            if (!protoRow) return res.status(404).json({ error: '找不到主產品' });
            let mfrName = '廠商';
            const { data: mfr } = await supabase.from('manufacturers').select('id, name').eq('id', protoRow.manufacturer_id).maybeSingle();
            if (mfr) mfrName = mfr.name || mfrName;
            const linkPack = await getLinkedAssetIdsForPrototype(protoRow.manufacturer_id, id);
            const linkedIds = linkPack.ids || [];
            let linkedAssets = [];
            if (linkedIds.length) {
                const { data: rows } = await supabase
                    .from('vendor_assets')
                    .select('id, title, description, image_url, cover_image_label, gallery_images, asset_kind, is_public')
                    .eq('manufacturer_id', protoRow.manufacturer_id)
                    .in('id', linkedIds);
                const byId = {};
                (rows || []).forEach((r) => { byId[r.id] = mapVendorAssetLinkTreeNode(r); });
                linkedAssets = linkedIds.map((lid, idx) => {
                    const node = byId[lid];
                    if (!node) return null;
                    const m = (linkPack.metaById && linkPack.metaById[lid]) || {};
                    return {
                        ...node,
                        sort_order: linkPack.sortById[lid] != null ? linkPack.sortById[lid] : idx,
                        allow_multi_pick: m.allow_multi_pick !== false,
                        pick_group: m.pick_group || null
                    };
                }).filter(Boolean);
            }
            if (linkedAssets.length) {
                try {
                    linkedAssets = await attachCatalogGroupIdsToAssets(linkedAssets);
                } catch (catErr) {
                    console.warn('link-tree preview catalog_groups:', catErr && catErr.message);
                }
            }
            const previewProtoNode = mapVendorAssetLinkTreeNode(protoRow) || {};
            res.set('Cache-Control', 'private, max-age=0, must-revalidate');
            return res.json({
                prototype: {
                    ...previewProtoNode,
                    manufacturer_id: protoRow.manufacturer_id,
                    manufacturer_name: mfrName,
                    category_key: protoRow.category_key || null,
                    subcategory_key: protoRow.subcategory_key || null
                },
                linked_assets: linkedAssets,
                material_count: linkedAssets.filter((a) => a.asset_kind === 'material').length,
                part_count: linkedAssets.filter((a) => a.asset_kind === 'part').length,
                preview: true
            });
        }
        res.set('Cache-Control', 'private, max-age=0, must-revalidate');
        res.json(payload);
    } catch (e) {
        console.error('GET /api/vendor-assets/:id/link-tree:', e);
        res.status(500).json({ error: '查詢失敗' });
    }
});

// GET /api/vendor-assets/:id/design-capabilities — 設計頁：此款式廠商已設工藝（供使用者勾選）
app.get('/api/vendor-assets/:id/design-capabilities', async (req, res) => {
    try {
        const id = (req.params.id || '').trim();
        if (!id) return res.status(400).json({ error: '缺少 id' });
        const internalPreview = await getRequestInternalPreviewFlag(req);
        const { data: row, error } = await supabase
            .from('vendor_assets')
            .select('id, asset_kind, is_public, manufacturer_id')
            .eq('id', id)
            .maybeSingle();
        if (error) throw error;
        if (!row || normalizeVendorAssetKind(row.asset_kind) !== 'prototype') {
            return res.status(404).json({ error: '找不到數位原型' });
        }
        if (!row.is_public && !internalPreview) {
            return res.status(404).json({ error: '此款式未公開' });
        }
        const payload = await manufacturerTaxonomy.getVendorAssetDesignCapabilities(supabase, id);
        return res.json(payload);
    } catch (e) {
        console.error('GET /api/vendor-assets/:id/design-capabilities:', e);
        return res.status(500).json({ error: '查詢失敗' });
    }
});

// --- Embed Simulator API（對齊主站 link-tree / design-capabilities / composeGeneratePromptWithReferences）---

async function fetchPublicPrototypeForEmbed(manufacturerId, prototypeAssetId) {
    const id = String(prototypeAssetId || '').trim();
    if (!id || !manufacturerId) return null;
    const cols = 'id, manufacturer_id, category_key, subcategory_key, title, description, image_url, cover_image_label, cover_link_group, gallery_images, asset_kind, is_public';
    const { data: row, error } = await supabase.from('vendor_assets').select(cols).eq('id', id).eq('manufacturer_id', manufacturerId).maybeSingle();
    if (error || !row) return null;
    if (normalizeVendorAssetKind(row.asset_kind) !== 'prototype') return null;
    if (!row.is_public) return null;
    const node = mapVendorAssetLinkTreeNode(row);
    if (!node) return null;
    return Object.assign({}, node, {
        category_key: row.category_key || null,
        subcategory_key: row.subcategory_key || null
    });
}

async function resolveEmbedPrototypeForRequest(ctx, prototypeAssetIdParam) {
    const bound = ctx.instance.prototype_asset_id;
    const requested = String(prototypeAssetIdParam || bound || '').trim();
    if (!requested) {
        throw new embedSimulator.EmbedSimulatorError('prototype_not_found', 404, '尚未綁定主產品');
    }
    if (bound && String(bound) !== requested) {
        throw new embedSimulator.EmbedSimulatorError('prototype_not_found', 404, '該款式已下架');
    }
    const proto = await fetchPublicPrototypeForEmbed(ctx.instance.manufacturer_id, requested);
    if (!proto) {
        throw new embedSimulator.EmbedSimulatorError('prototype_not_found', 404, '該款式已下架');
    }
    return proto;
}

async function buildValidatedEmbedReferencePayload(ctx, body, proto) {
    const prototypeId = proto.id;
    const angleUrls = Array.isArray(body.prototype_angle_urls) ? body.prototype_angle_urls.slice(0, 3) : [];
    const validUrlSet = {};
    (proto.image_items || []).forEach(function (it) {
        if (!it || !it.url) return;
        if (it.designer_selectable === false) return;
        validUrlSet[String(it.url).trim()] = true;
    });
    if (!Object.keys(validUrlSet).length) {
        const coverItem = (proto.image_items || []).find(function (it) { return it && it.is_cover && it.url; });
        if (coverItem && coverItem.designer_selectable !== false) {
            validUrlSet[String(coverItem.url).trim()] = true;
        } else if (proto.image_url && readCoverDesignerSelectableMeta(proto.gallery_images) !== false) {
            // 無 image_items 時：封面預設可選
            validUrlSet[String(proto.image_url).trim()] = true;
        }
    }
    let angles = angleUrls.filter(function (u) { return validUrlSet[String(u || '').trim()]; });
    if (!angles.length) {
        const coverUrl = proto.image_url ? String(proto.image_url).trim() : '';
        if (coverUrl && validUrlSet[coverUrl]) angles = [coverUrl];
    }

    const linkPack = await getLinkedAssetIdsForPrototype(ctx.instance.manufacturer_id, prototypeId);
    const linkedSet = new Set((linkPack.ids || []).map(String));
    const materialIds = (Array.isArray(body.material_ids) ? body.material_ids : []).slice(0, 1).map(String);
    const partIds = (Array.isArray(body.part_ids) ? body.part_ids : []).slice(0, 3).map(String);

    materialIds.forEach(function (mid) {
        if (mid && !linkedSet.has(mid)) {
            throw new embedSimulator.EmbedSimulatorError('invalid_material', 400, '材料選項無效');
        }
    });
    partIds.forEach(function (pid) {
        if (pid && !linkedSet.has(pid)) {
            throw new embedSimulator.EmbedSimulatorError('invalid_part', 400, '配件選項無效');
        }
    });

    const referenceSources = [];
    const referenceImages = [];
    function pushRef(src, url) {
        if (!url) return;
        referenceSources.push(src);
        referenceImages.push(url);
    }

    angles.forEach(function (url) {
        pushRef({
            intent: 'prototype',
            vendor_asset_id: prototypeId,
            asset_kind: 'prototype',
            image_url: url
        }, url);
    });

    const assetIdsToLoad = partIds.concat(materialIds).filter(Boolean);
    let assetRows = [];
    if (assetIdsToLoad.length) {
        const { data: rows } = await supabase
            .from('vendor_assets')
            .select('id, title, image_url, cover_image_label, cover_link_group, gallery_images, asset_kind, is_public')
            .eq('manufacturer_id', ctx.instance.manufacturer_id)
            .in('id', assetIdsToLoad);
        assetRows = rows || [];
    }
    const byId = {};
    assetRows.forEach(function (r) { byId[r.id] = r; });

    partIds.forEach(function (pid) {
        const r = byId[pid];
        if (!r || !r.is_public) return;
        const items = buildVendorAssetImageItems(r);
        const url = r.image_url || (items[0] && items[0].url) || '';
        pushRef({
            intent: 'part',
            vendor_asset_id: pid,
            asset_kind: 'part',
            image_url: url,
            title: r.title || undefined
        }, url);
    });

    materialIds.forEach(function (mid) {
        const r = byId[mid];
        if (!r || !r.is_public) return;
        const items = buildVendorAssetImageItems(r);
        // 材料封面不可選用：embed 改用第一張設計者可選圖
        const pick = (items || []).find(function (it) {
            return it && it.url && it.designer_selectable !== false;
        });
        const url = pick && pick.url ? String(pick.url).trim() : '';
        if (!url) return;
        pushRef({
            intent: 'material',
            vendor_asset_id: mid,
            asset_kind: 'material',
            image_url: url,
            title: r.title || undefined
        }, url);
    });

    (Array.isArray(body.reference_sources) ? body.reference_sources : []).forEach(function (src) {
        if (!src || src.vendor_asset_id) return;
        const intent = src.intent || (src.pattern_intent === 'style' ? 'pattern_style' : 'pattern_print');
        if (intent !== 'pattern_print' && intent !== 'pattern_style') return;
        const url = (src.image_url || '').trim();
        if (!url) return;
        pushRef({
            intent: intent,
            asset_kind: 'other',
            image_url: url,
            pattern_intent: intent === 'pattern_style' ? 'style' : 'print'
        }, url);
    });

    if (referenceImages.length > 8) {
        referenceSources.length = 8;
        referenceImages.length = 8;
    }
    return { referenceSources, referenceImages };
}

app.get('/api/embed/simulator/bootstrap', async (req, res) => {
    try {
        const ctx = await embedSimulator.resolveEmbedInstance(supabase, req.query.embed_id, req.query.sig);
        const proto = await resolveEmbedPrototypeForRequest(ctx, ctx.instance.prototype_asset_id);
        const mfrName = ctx.manufacturer.name || '廠商';
        const embedTier = await embedSimulator.resolveEmbedPlanTier(supabase, ctx.vendorUserId);
        const sceneSimEnabled = embedSimulator.resolveEmbedSceneSimFromInstance(ctx.instance, embedTier);
        res.json({
            manufacturer: {
                id: ctx.manufacturer.id,
                name: mfrName,
                logo_url: embedSimulator.manufacturerLogoFromRow(ctx.manufacturer),
                profile_url: embedSimulator.manufacturerProfileUrlFromRow(ctx.manufacturer)
            },
            prototype: proto,
            prototype_asset_id: proto.id,
            embed_branding: embedSimulator.embedBrandingFromInstance(ctx.instance),
            scene_sim_enabled: sceneSimEnabled,
            service_status: 'ok'
        });
    } catch (e) {
        return embedSimulator.sendEmbedError(res, e, null);
    }
});

