app.post('/api/embed/simulator/generate', express.json({ limit: '15mb' }), async (req, res) => {
    let billing = null;
    let ctx = null;
    try {
        const body = req.body || {};
        ctx = await embedSimulator.resolveEmbedInstance(supabase, body.embed_id, body.sig);
        const proto = await resolveEmbedPrototypeForRequest(ctx, body.prototype_asset_id || ctx.instance.prototype_asset_id);

        const clientIp = embedSimulator.getRequestClientIp(req);
        embedSimulator.checkIpHourlyLimit(ctx.instance.id, clientIp, ctx.instance.rate_limit_per_ip_hour);
        const usage = await embedSimulator.getInstanceUsageCounts(supabase, ctx.instance.id);
        embedSimulator.assertCaps(ctx.instance, usage);

        const pointsRequired = await getPointsEmbedSimulatorGenerate();
        billing = await embedSimulator.resolveEmbedBilling(supabase, ctx.vendorUserId, pointsRequired);

        const refs = await buildValidatedEmbedReferencePayload(ctx, body, proto);
        const hasRefs = refs.referenceImages.length > 0;
        const userPrompt = (body.prompt != null ? String(body.prompt) : '').trim();
        if (!userPrompt && !hasRefs) {
            return res.status(400).json({ error: '請提供產品描述或參考圖', error_code: 'missing_input' });
        }

        const categoryKeys = [proto.category_key, proto.subcategory_key].filter(Boolean);
        if (!categoryKeys.length) {
            return res.status(400).json({ error: '主產品缺少分類設定', error_code: 'missing_category' });
        }

        const capKeys = manufacturerTaxonomy.parseJsonStringArray(body.capability_keys);
        const capCustom = manufacturerTaxonomy.parseJsonStringArray(body.capability_custom_labels);
        if (capKeys.length || capCustom.length) {
            const capValid = await manufacturerTaxonomy.validateSelectedCapabilitiesForPrototype(
                supabase, proto.id, capKeys, capCustom
            );
            if (!capValid.ok) {
                return res.status(400).json({ error: capValid.error || '工藝選項無效', error_code: 'invalid_capabilities' });
            }
        }

        const uiLang = resolveUiLocaleFromRequest(req);
        const composed = await composeGeneratePromptWithReferences({
            categoryKeys,
            userPrompt,
            useRemake: false,
            uiLang,
            referenceImages: hasRefs ? refs.referenceImages : [],
            referenceSources: hasRefs ? refs.referenceSources : [],
            selectedCapabilityKeys: body.capability_keys,
            selectedCapabilityCustomLabels: body.capability_custom_labels
        });

        let seedNum = Math.floor(Math.random() * 2147483647);
        let imageData = null;
        const outputFormat = 'jpeg';
        const fluxGenerateEndpoint = await getBflFluxEndpointForConfigKey('bfl_flux_model_generate');

        if (process.env.BFL_API_KEY) {
            try {
                const fluxSafetyTolerance = await resolveFluxSafetyToleranceFromCategoryKeys(categoryKeys);
                if (hasRefs) {
                    const buffer = await generateImageWithFlux2Pro(composed.fullPrompt, composed.fluxReferenceImages, seedNum, outputFormat, {
                        endpointUrl: fluxGenerateEndpoint,
                        safetyTolerance: fluxSafetyTolerance
                    });
                    if (buffer) imageData = buffer.toString('base64');
                } else {
                    const buffer = await generateImageWithFlux2ProTextToImage(
                        composed.fullPrompt, seedNum, outputFormat, fluxGenerateEndpoint, null,
                        { safetyTolerance: fluxSafetyTolerance }
                    );
                    if (buffer) imageData = buffer.toString('base64');
                }
            } catch (fluxErr) {
                console.warn('embed generate FLUX failed:', fluxErr.message);
            }
        }

        if (!imageData) {
            throw new embedSimulator.EmbedSimulatorError('flux_error', 500, '生成失敗，請稍後再試');
        }

        const buffer = Buffer.from(imageData, 'base64');
        const mime = 'image/jpeg';
        let imageUrl = null;
        try {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', 'embed-generated', {
                buffer,
                mimetype: mime,
                originalname: 'embed-' + Date.now() + '.jpg'
            }, { ext: 'jpg', contentType: mime });
            imageUrl = publicUrl;
        } catch (uploadErr) {
            console.warn('embed upload failed:', uploadErr.message);
            imageUrl = 'data:' + mime + ';base64,' + imageData;
        }

        if (billing.points_charged > 0) {
            await embedSimulator.chargeVendorCredits(
                supabase,
                ctx.vendorUserId,
                billing.points_charged,
                'Embed 模擬器生圖'
            );
        }

        await embedSimulator.incrementDailyUsage(supabase, ctx.instance.id);

        const referrerHost = (req.headers.referer || req.headers.origin || '').trim();
        let refHost = null;
        if (referrerHost) {
            try { refHost = new URL(referrerHost).host; } catch (_) { refHost = referrerHost.slice(0, 120); }
        }

        const refSourcesFinal = composed.fluxReferenceSources.length ? composed.fluxReferenceSources : refs.referenceSources;
        const showOnHomepage = embedSimulator.resolveEmbedMediaWallFromInstance(ctx.instance);
        const mfrName = ctx.manufacturer.name || '廠商';
        const embedTitle = ((proto.title || '訂製品') + ' · 官網試做').slice(0, 120);
        const embedDesc = (userPrompt || ('Embed 訪客試做 · ' + mfrName)).slice(0, 500);
        const embedAnalysis = {
            embed_visitor_design: true,
            source: 'embed',
            embed_instance_id: ctx.instance.id,
            embed_session_id: (body.session_id || '').trim() || null,
            referrer_host: refHost
        };
        let customProductId = null;
        if (ctx.vendorUserId) {
            const cpPayload = {
                owner_id: ctx.vendorUserId,
                title: embedTitle,
                description: embedDesc,
                category: proto.category_key || null,
                subcategory_key: proto.subcategory_key || null,
                ai_generated_image_url: imageUrl,
                reference_sources: refSourcesFinal,
                generation_prompt: composed.fullPrompt || null,
                generation_seed: seedNum,
                show_on_homepage: showOnHomepage,
                status: 'draft',
                is_vendor_self_serve: false,
                has_self_vendor_reference: true,
                generator_manufacturer_id: ctx.instance.manufacturer_id,
                data_lineage_json: {
                    embed_visitor_design: true,
                    source: 'embed',
                    billed_vendor_user_id: ctx.vendorUserId,
                    is_vendor_self_serve: false,
                    computed_at: new Date().toISOString()
                },
                analysis_json: embedAnalysis
            };
            let cpRes = await supabase.from('custom_products').insert(cpPayload).select('id').single();
            if (cpRes.error && cpRes.error.code === '42703') {
                const slim = Object.assign({}, cpPayload);
                delete slim.is_vendor_self_serve;
                delete slim.has_self_vendor_reference;
                delete slim.generator_manufacturer_id;
                delete slim.data_lineage_json;
                cpRes = await supabase.from('custom_products').insert(slim).select('id').single();
            }
            if (!cpRes.error && cpRes.data && cpRes.data.id) {
                customProductId = cpRes.data.id;
                scheduleCustomProductSemanticsEnrich(customProductId, ctx.vendorUserId, {
                    imageUrl: imageUrl,
                    generationPrompt: composed.fullPrompt || userPrompt,
                    title: embedTitle,
                    categoryKey: proto.category_key || null
                });
            } else if (cpRes.error) {
                console.warn('embed custom_products insert:', cpRes.error.message);
            }
        }

        const embedInsert = {
            embed_instance_id: ctx.instance.id,
            manufacturer_id: ctx.instance.manufacturer_id,
            prototype_asset_id: proto.id,
            reference_sources: refSourcesFinal,
            prompt: userPrompt || null,
            ai_generated_image_url: imageUrl,
            generation_seed: seedNum,
            visitor_ip_hash: embedSimulator.hashVisitorIp(clientIp),
            embed_session_id: (body.session_id || '').trim() || null,
            referrer_host: refHost,
            billing_type: billing.billing_type,
            points_charged: billing.points_charged || 0,
            source: 'embed'
        };
        if (customProductId) embedInsert.custom_product_id = customProductId;
        let embedDesignRes = await supabase.from('vendor_embed_designs').insert(embedInsert);
        if (embedDesignRes.error) {
            const slimEmbed = Object.assign({}, embedInsert);
            if (embedDesignRes.error.code === '42703') {
                delete slimEmbed.source;
                delete slimEmbed.custom_product_id;
                embedDesignRes = await supabase.from('vendor_embed_designs').insert(slimEmbed);
            }
            if (embedDesignRes.error && String(embedDesignRes.error.message || '').includes('billing_type')) {
                slimEmbed.billing_type = 'credit_overage';
                embedDesignRes = await supabase.from('vendor_embed_designs').insert(slimEmbed);
            }
            if (embedDesignRes.error) console.warn('vendor_embed_designs insert:', embedDesignRes.error.message);
        }

        res.json({
            success: true,
            imageUrl,
            billing_type: billing.billing_type,
            points_charged: billing.points_charged || 0
        });
    } catch (e) {
        const name = ctx && ctx.manufacturer ? ctx.manufacturer.name : null;
        return embedSimulator.sendEmbedError(res, e, name);
    }
});

function embedProductImageUrlKey(url) {
    const s = String(url || '').trim();
    if (!s) return '';
    if (s.indexOf('data:') === 0) return s;
    try {
        const u = new URL(s, 'https://matchdo.cc');
        return u.origin + u.pathname;
    } catch (_) {
        return s.split('?')[0];
    }
}

function embedProductImageMatches(clientUrl, storedUrl) {
    if (!clientUrl || !storedUrl) return false;
    const a = embedProductImageUrlKey(clientUrl);
    const b = embedProductImageUrlKey(storedUrl);
    if (a === b) return true;
    return String(clientUrl).trim() === String(storedUrl).trim();
}

async function resolveLatestEmbedSessionDesign(supabase, instanceId, sessionId) {
    const sid = String(sessionId || '').trim();
    if (!instanceId || !sid) return null;
    const { data, error } = await supabase
        .from('vendor_embed_designs')
        .select('id, ai_generated_image_url, created_at')
        .eq('embed_instance_id', instanceId)
        .eq('embed_session_id', sid)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (error) {
        if (error.code === '42P01') return null;
        throw error;
    }
    return data || null;
}

app.post('/api/embed/simulator/scene-simulate', express.json({ limit: '15mb' }), async (req, res) => {
    let billing = null;
    let ctx = null;
    try {
        const body = req.body || {};
        ctx = await embedSimulator.resolveEmbedInstance(supabase, body.embed_id, body.sig);
        const embedTier = await embedSimulator.resolveEmbedPlanTier(supabase, ctx.vendorUserId);
        if (!embedSimulator.resolveEmbedSceneSimFromInstance(ctx.instance, embedTier)) {
            throw new embedSimulator.EmbedSimulatorError('scene_sim_disabled', 403, '實境模擬未開啟');
        }

        const clientIp = embedSimulator.getRequestClientIp(req);
        embedSimulator.checkIpHourlyLimit(ctx.instance.id, clientIp, ctx.instance.rate_limit_per_ip_hour);
        const usage = await embedSimulator.getInstanceUsageCounts(supabase, ctx.instance.id);
        embedSimulator.assertCaps(ctx.instance, usage);

        const pointsRequired = await getPointsEmbedSimulatorGenerate();
        billing = await embedSimulator.resolveEmbedBilling(supabase, ctx.vendorUserId, pointsRequired);

        const { environmentImage, productImage, prompt } = body;
        if (!environmentImage || typeof environmentImage !== 'string') {
            return res.status(400).json({ error: '請上傳情境或環境照片', error_code: 'missing_environment' });
        }
        if (!productImage || typeof productImage !== 'string') {
            return res.status(400).json({ error: '請先在「產品試做」生成設計圖', error_code: 'missing_product' });
        }

        const sessionId = (body.session_id || body.embed_session_id || '').trim();
        const latestDesign = await resolveLatestEmbedSessionDesign(supabase, ctx.instance.id, sessionId);
        if (!latestDesign || !latestDesign.ai_generated_image_url) {
            return res.status(400).json({ error: '請先在「產品試做」生成設計圖', error_code: 'missing_product' });
        }
        if (!embedProductImageMatches(productImage, latestDesign.ai_generated_image_url)) {
            return res.status(400).json({ error: '僅可使用本次試做成圖，請勿上傳其他產品圖', error_code: 'invalid_product' });
        }
        const envBase64 = await resolveImageToBase64(environmentImage);
        const productBase64 = await resolveImageToBase64(productImage);
        if (!envBase64) {
            return res.status(400).json({ error: '情境圖片無法讀取，請重新上傳', error_code: 'invalid_environment' });
        }
        if (!productBase64) {
            return res.status(400).json({ error: '產品圖片無法讀取', error_code: 'invalid_product' });
        }
        if (!process.env.BFL_API_KEY) {
            throw new embedSimulator.EmbedSimulatorError('flux_error', 503, '實境模擬服務暫未設定，請稍後再試');
        }

        const seed = Math.floor(Math.random() * 2147483647);
        const userPrompt = (prompt != null ? String(prompt) : '').trim();
        const buffer = await generateSceneSimulateImage(envBase64, productBase64, userPrompt, seed);
        if (!buffer) {
            throw new embedSimulator.EmbedSimulatorError('flux_error', 500, '合成失敗，請稍後再試');
        }

        const imageData = buffer.toString('base64');
        const mime = 'image/jpeg';
        let imageUrl = null;
        try {
            const { publicUrl } = await uploadToSupabaseStorage('custom-products', 'embed-scene-sim', {
                buffer,
                mimetype: mime,
                originalname: 'embed-scene-' + Date.now() + '.jpg'
            }, { ext: 'jpg', contentType: mime });
            imageUrl = publicUrl;
        } catch (uploadErr) {
            console.warn('embed scene-sim upload failed:', uploadErr.message);
            imageUrl = 'data:' + mime + ';base64,' + imageData;
        }

        if (billing.points_charged > 0) {
            await embedSimulator.chargeVendorCredits(
                supabase,
                ctx.vendorUserId,
                billing.points_charged,
                'Embed 實境模擬',
                'embed_simulator_scene_simulate'
            );
        }

        await embedSimulator.incrementDailyUsage(supabase, ctx.instance.id);

        res.json({
            success: true,
            imageUrl,
            billing_type: billing.billing_type,
            points_charged: billing.points_charged || 0
        });
    } catch (e) {
        const name = ctx && ctx.manufacturer ? ctx.manufacturer.name : null;
        return embedSimulator.sendEmbedError(res, e, name);
    }
});

function embedSchemaMissingResponse(res) {
    return res.status(503).json({
        error: '嵌入試做尚未啟用，請聯絡平台管理員',
        code: 'EMBED_SCHEMA',
        hint: 'docs/add-embed-simulator-schema.sql'
    });
}

function isEmbedInstanceOptionalColumnError(err, colName) {
    if (!err) return false;
    const code = String(err.code || '');
    const msg = String(err.message || '');
    if (code === '42703' || code === 'PGRST204') {
        if (!colName) return /show_powered_by|show_on_media_wall|scene_sim_enabled/i.test(msg);
        return msg.includes(colName);
    }
    if (/schema cache|could not find the/i.test(msg)) {
        if (!colName) return /show_powered_by|show_on_media_wall|scene_sim_enabled/i.test(msg);
        return msg.includes(colName);
    }
    return false;
}

async function getOrCreateEmbedSimulatorInstance(supabase, manufacturerId, prototypeAssetId, instanceName, vendorUserId) {
    const protoId = String(prototypeAssetId || '').trim();
    if (!protoId) return { error: 'missing_prototype' };

    const { data: row, error: rowErr } = await supabase
        .from('vendor_assets')
        .select('id, manufacturer_id, title, asset_kind, is_public')
        .eq('id', protoId)
        .eq('manufacturer_id', manufacturerId)
        .maybeSingle();
    if (rowErr) throw rowErr;
    if (!row || normalizeVendorAssetKind(row.asset_kind) !== 'prototype') {
        return { error: 'not_prototype' };
    }
    if (!row.is_public) {
        return { error: 'not_public' };
    }

    const embedSelectFull = 'id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active, show_on_media_wall, scene_sim_enabled';
    const embedSelectBase = 'id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active';
    let existingRes = await supabase
        .from('manufacturer_embed_instances')
        .select(embedSelectFull)
        .eq('manufacturer_id', manufacturerId)
        .eq('prototype_asset_id', protoId)
        .eq('is_active', true)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (existingRes.error && isEmbedInstanceOptionalColumnError(existingRes.error)) {
        existingRes = await supabase
            .from('manufacturer_embed_instances')
            .select(embedSelectBase)
            .eq('manufacturer_id', manufacturerId)
            .eq('prototype_asset_id', protoId)
            .eq('is_active', true)
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();
        if (!existingRes.error && existingRes.data) {
            existingRes.data.show_on_media_wall = true;
            existingRes.data.scene_sim_enabled = true;
        }
    }
    if (existingRes.error) {
        if (existingRes.error.code === '42P01') return { error: 'schema' };
        throw existingRes.error;
    }
    if (existingRes.data) {
        return { instance: existingRes.data, created: false, prototype_title: row.title || '' };
    }

    const tier = await resolveVendorEmbedTier(vendorUserId);
    const tierBranding = embedSimulator.embedBrandingForTier(tier);

    const embedKey = embedSimulator.randomEmbedKey();
    const embedSecret = embedSimulator.randomEmbedSecret();
    const name = String(instanceName || '').trim() || ((row.title || '主產品') + ' 官網試做');
    const insertPayload = {
        manufacturer_id: manufacturerId,
        name: name.slice(0, 120),
        embed_key: embedKey,
        embed_secret: embedSecret,
        prototype_asset_id: protoId,
        is_active: true,
        show_on_media_wall: true,
        scene_sim_enabled: true,
        show_powered_by: tierBranding.show_powered_by !== false,
        updated_at: new Date().toISOString()
    };
    const insertSelectFull = 'id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active, show_on_media_wall, show_powered_by, scene_sim_enabled';
    const insertSelectBase = 'id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active';
    let insertRes = await supabase
        .from('manufacturer_embed_instances')
        .insert(insertPayload)
        .select(insertSelectFull)
        .single();
    if (insertRes.error && isEmbedInstanceOptionalColumnError(insertRes.error)) {
        delete insertPayload.show_powered_by;
        delete insertPayload.show_on_media_wall;
        delete insertPayload.scene_sim_enabled;
        insertRes = await supabase
            .from('manufacturer_embed_instances')
            .insert(insertPayload)
            .select(insertSelectBase)
            .single();
        if (!insertRes.error && insertRes.data) {
            insertRes.data.show_on_media_wall = true;
            insertRes.data.show_powered_by = tierBranding.show_powered_by !== false;
            insertRes.data.scene_sim_enabled = true;
        }
    }
    if (insertRes.error) {
        if (insertRes.error.code === '42P01') return { error: 'schema' };
        if (insertRes.error.code === '23505') {
            existingRes = await supabase
                .from('manufacturer_embed_instances')
                .select(embedSelectBase)
                .eq('manufacturer_id', manufacturerId)
                .eq('prototype_asset_id', protoId)
                .eq('is_active', true)
                .maybeSingle();
            if (existingRes.data) {
                if (existingRes.data.show_on_media_wall === undefined) existingRes.data.show_on_media_wall = true;
                return { instance: existingRes.data, created: false, prototype_title: row.title || '' };
            }
        }
        throw insertRes.error;
    }
    return { instance: insertRes.data, created: true, prototype_title: row.title || '' };
}

/** 廠商 embed 方案等級（用於 Powered by、媒體牆等；取得嵌入碼不另做付費限制） */
async function resolveVendorEmbedTier(vendorUserId) {
    if (!vendorUserId) return '300';
    let tier = await embedSimulator.resolveEmbedPlanTier(supabase, vendorUserId);
    if (!tier && await hasActivePaidSubscription(vendorUserId)) tier = '300';
    return tier || '300';
}

// GET /api/me/embed-simulator-instances?prototype_asset_id= — 廠商：查此款 iframe
app.get('/api/me/embed-simulator-instances', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const protoId = (req.query.prototype_asset_id || '').trim();
        if (!protoId) return res.status(400).json({ error: '請提供 prototype_asset_id' });

        const { data: row, error } = await supabase
            .from('manufacturer_embed_instances')
            .select('id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active, show_on_media_wall, scene_sim_enabled')
            .eq('manufacturer_id', manufacturerId)
            .eq('prototype_asset_id', protoId)
            .eq('is_active', true)
            .order('created_at', { ascending: false })
            .limit(1)
            .maybeSingle();
        if (error) {
            if (error.code === '42P01') return embedSchemaMissingResponse(res);
            if (isEmbedInstanceOptionalColumnError(error)) {
                const fallback = await supabase
                    .from('manufacturer_embed_instances')
                    .select('id, manufacturer_id, name, embed_key, embed_secret, prototype_asset_id, is_active')
                    .eq('manufacturer_id', manufacturerId)
                    .eq('prototype_asset_id', protoId)
                    .eq('is_active', true)
                    .order('created_at', { ascending: false })
                    .limit(1)
                    .maybeSingle();
                if (fallback.error) throw fallback.error;
                if (!fallback.data) {
                    const { data: mfrRow } = await supabase.from('manufacturers').select('user_id').eq('id', manufacturerId).maybeSingle();
                    const tier = mfrRow && mfrRow.user_id ? await resolveVendorEmbedTier(mfrRow.user_id) : '300';
                    return res.json({ instance: null, embed_tier: tier });
                }
                const origin = embedSimulator.publicOriginFromRequest(req);
                const mapped = embedSimulator.mapEmbedInstanceForVendor(fallback.data, origin, { title: '產品試做' });
                const { data: mfrRow } = await supabase.from('manufacturers').select('user_id').eq('id', manufacturerId).maybeSingle();
                const tier = mfrRow && mfrRow.user_id ? await resolveVendorEmbedTier(mfrRow.user_id) : '300';
                return res.json({ instance: mapped, embed_tier: tier });
            }
            throw error;
        }
        const { data: mfrRow } = await supabase.from('manufacturers').select('user_id').eq('id', manufacturerId).maybeSingle();
        const tier = mfrRow && mfrRow.user_id ? await resolveVendorEmbedTier(mfrRow.user_id) : '300';
        const tierCfg = tier ? embedSimulator.getEmbedTierConfig(tier) : null;
        const activeCount = await embedSimulator.countActiveEmbedInstances(supabase, manufacturerId);
        if (!row) return res.json({ instance: null, embed_tier: tier, embed_tier_config: tierCfg, active_instance_count: activeCount });
        const origin = embedSimulator.publicOriginFromRequest(req);
        const mapped = embedSimulator.mapEmbedInstanceForVendor(row, origin, { title: '產品試做' });
        return res.json({ instance: mapped, embed_tier: tier, embed_tier_config: tierCfg, active_instance_count: activeCount });
    } catch (e) {
        console.error('GET /api/me/embed-simulator-instances:', e);
        return res.status(500).json({ error: '查詢失敗' });
    }
});

// POST /api/me/embed-simulator-instances — 廠商：建立或取得 iframe（一主產品一實例）
app.post('/api/me/embed-simulator-instances', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;

        const body = req.body || {};
        const protoId = (body.prototype_asset_id || '').trim();
        if (!protoId) return res.status(400).json({ error: '請提供 prototype_asset_id' });

        const { data: mfrRow } = await supabase.from('manufacturers').select('user_id').eq('id', manufacturerId).maybeSingle();
        const vendorUserId = mfrRow && mfrRow.user_id ? mfrRow.user_id : null;

        const pack = await getOrCreateEmbedSimulatorInstance(supabase, manufacturerId, protoId, body.name, vendorUserId);
        if (pack.error === 'schema') return embedSchemaMissingResponse(res);
        if (pack.error === 'not_prototype') {
            return res.status(400).json({ error: '僅主產品可建立 iframe 試做器' });
        }
        if (pack.error === 'missing_prototype') {
            return res.status(400).json({ error: '請提供 prototype_asset_id' });
        }
        if (pack.error === 'not_public') {
            return res.status(400).json({ error: '請先上架主產品，才能產生官網 iframe' });
        }

        const tier = vendorUserId ? await resolveVendorEmbedTier(vendorUserId) : '300';
        const origin = embedSimulator.publicOriginFromRequest(req);
        const mapped = embedSimulator.mapEmbedInstanceForVendor(pack.instance, origin, {
            title: (pack.prototype_title || '產品試做').slice(0, 80)
        });
        if (!mapped) {
            return res.status(500).json({ error: '建立失敗：無法產生嵌入連結' });
        }
        return res.json(Object.assign({}, mapped, {
            created: !!pack.created,
            embed_tier: tier,
            embed_tier_config: tier ? embedSimulator.getEmbedTierConfig(tier) : null,
            active_instance_count: await embedSimulator.countActiveEmbedInstances(supabase, manufacturerId)
        }));
    } catch (e) {
        if (e instanceof embedSimulator.EmbedSimulatorError) {
            return res.status(e.httpStatus || 403).json({ error: e.message, error_code: e.code });
        }
        console.error('POST /api/me/embed-simulator-instances:', e);
        const detail = e && e.message ? String(e.message).slice(0, 240) : '';
        const hint = e && e.code === '42P01' ? '（請執行 docs/add-embed-simulator-schema.sql）' : '';
        return res.status(500).json({
            error: '建立失敗' + hint,
            error_detail: detail || undefined
        });
    }
});

// PATCH /api/me/embed-simulator-instances/:id — 1800：媒體牆；900/1800：實境模擬開關
app.patch('/api/me/embed-simulator-instances/:id', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;

        const instanceId = (req.params.id || '').trim();
        if (!instanceId) return res.status(400).json({ error: '缺少 id' });

        const { data: mfrRow } = await supabase.from('manufacturers').select('user_id').eq('id', manufacturerId).maybeSingle();
        const vendorUserId = mfrRow && mfrRow.user_id ? mfrRow.user_id : null;
        const tier = vendorUserId ? await resolveVendorEmbedTier(vendorUserId) : null;
        const tierCfg = tier ? embedSimulator.getEmbedTierConfig(tier) : null;

        const body = req.body || {};
        const updatePayload = { updated_at: new Date().toISOString() };
        const responsePayload = { success: true };

        if (body.show_on_media_wall !== undefined) {
            if (!tierCfg || tierCfg.wallMode !== 'configurable') {
                return res.status(403).json({ error: '僅 1800 方案可設定 embed 成圖是否上首頁媒體牆' });
            }
            updatePayload.show_on_media_wall = body.show_on_media_wall !== false
                && body.show_on_media_wall !== 'false'
                && body.show_on_media_wall !== 0;
            responsePayload.show_on_media_wall = updatePayload.show_on_media_wall;
        }

        if (body.scene_sim_enabled !== undefined) {
            if (!tierCfg || tierCfg.sceneSimMode !== 'configurable') {
                return res.status(403).json({ error: '僅 900／1800 方案可設定 embed 實境模擬開關' });
            }
            updatePayload.scene_sim_enabled = body.scene_sim_enabled !== false
                && body.scene_sim_enabled !== 'false'
                && body.scene_sim_enabled !== 0;
            responsePayload.scene_sim_enabled = updatePayload.scene_sim_enabled;
        }

        if (Object.keys(updatePayload).length <= 1) {
            return res.status(400).json({ error: '請提供 show_on_media_wall 或 scene_sim_enabled' });
        }

        const { data: row, error } = await supabase
            .from('manufacturer_embed_instances')
            .update(updatePayload)
            .eq('id', instanceId)
            .eq('manufacturer_id', manufacturerId)
            .select('id, show_on_media_wall, scene_sim_enabled')
            .maybeSingle();
        if (error) {
            if (error.code === '42703') {
                return res.status(503).json({ error: '請先執行 docs/add-embed-simulator-plan-tiers.sql 或 docs/add-embed-scene-sim-enabled.sql' });
            }
            throw error;
        }
        if (!row) return res.status(404).json({ error: '找不到 iframe 實例' });
        if (responsePayload.show_on_media_wall === undefined && row.show_on_media_wall !== undefined) {
            responsePayload.show_on_media_wall = row.show_on_media_wall !== false;
        }
        if (responsePayload.scene_sim_enabled === undefined && row.scene_sim_enabled !== undefined) {
            responsePayload.scene_sim_enabled = row.scene_sim_enabled !== false;
        }
        return res.json(responsePayload);
    } catch (e) {
        console.error('PATCH /api/me/embed-simulator-instances/:id:', e);
        return res.status(500).json({ error: '更新失敗' });
    }
});

