// GET /api/vendor-assets/prototype-link-summary — 設計端：主產品已關聯的材／配筆數（用於頁籤提示）
app.get('/api/vendor-assets/prototype-link-summary', async (req, res) => {
    try {
        const prototypeAssetId = (req.query.prototype_asset_id || '').trim();
        if (!prototypeAssetId) return res.status(400).json({ error: '缺少 prototype_asset_id' });
        if (!(await vendorPrototypeLinksTableReady())) {
            return res.json({ prototype_asset_id: prototypeAssetId, material_count: 0, part_count: 0 });
        }
        const { data: protoRow, error: protoErr } = await supabase
            .from('vendor_assets')
            .select('id, manufacturer_id, asset_kind, is_public')
            .eq('id', prototypeAssetId)
            .maybeSingle();
        if (protoErr) {
            console.error('GET prototype-link-summary:', protoErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        if (!protoRow || normalizeVendorAssetKind(protoRow.asset_kind) !== 'prototype') {
            return res.json({ prototype_asset_id: prototypeAssetId, material_count: 0, part_count: 0 });
        }
        const internalPreview = await getRequestInternalPreviewFlag(req);
        if (!internalPreview && !protoRow.is_public) {
            return res.json({ prototype_asset_id: prototypeAssetId, material_count: 0, part_count: 0 });
        }
        const counts = await getPrototypeLinkKindCounts(protoRow.manufacturer_id, prototypeAssetId);
        res.json({ prototype_asset_id: prototypeAssetId, ...counts });
    } catch (e) {
        console.error('GET /api/vendor-assets/prototype-link-summary:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// ---------- 廠商素材庫（設計端參考圖來源；依設計當下分類載入；必顯示廠商名稱與連結）----------
// GET /api/vendor-assets — 設計端選圖用。分類素材池：必傳 category_key；個別廠商版型庫：可只傳 manufacturer_id
// 種子廠商：未同意公開前僅 admin/tester 可見；同意後僅 is_public 素材對一般使用者顯示
app.get('/api/vendor-assets', async (req, res) => {
    try {
        const internalPreview = await getRequestInternalPreviewFlag(req);
        const forProfile = parseTruthyBody(req.query.for_profile);
        const categoryKey = (req.query.category_key || '').trim() || null;
        const subcategoryKey = (req.query.subcategory_key || '').trim() || null;
        const styleKey = normalizeVendorStyleKey(req.query.style_key) || null;
        const materialKey = normalizeVendorMaterialKey(req.query.material_key) || null;
        const colorQ = (req.query.color || req.query.color_key || '').trim().toLowerCase() || null;
        let manufacturerId = (req.query.manufacturer_id || '').trim() || null;
        const manufacturerNameQ = (req.query.manufacturer_name || req.query.q || '').trim() || null;
        const serviceAreaCode = (req.query.service_area || '').trim() || null;
        const searchQ = (req.query.q || req.query.search || '').trim() || null;
        const assetKindQ = (req.query.asset_kind || '').trim().toLowerCase();
        const assetKindFilter = (assetKindQ === 'prototype' || assetKindQ === 'material' || assetKindQ === 'part') ? assetKindQ : null;
        const pageParams = parseVendorAssetsListPageParams(req.query);
        const manufacturersOnly = parseTruthyBody(req.query.manufacturers_only);
        const prototypeLinkedOnly = parseTruthyBody(req.query.prototype_linked_only);
        const hasPrototypeLinks = parseTruthyBody(req.query.has_prototype_links);
        const catalogGroupId = (req.query.catalog_group_id || '').trim() || null;
        const moqFilterRaw = (req.query.min_order_quantity != null ? String(req.query.min_order_quantity) : '').trim();
        const moqFilter = moqFilterRaw ? parseInt(moqFilterRaw, 10) : null;
        if (moqFilterRaw && (!Number.isFinite(moqFilter) || moqFilter < 1)) {
            return res.status(400).json({ error: 'min_order_quantity 須為 1 以上的整數' });
        }
        const customFilterKeys = normalizeCustomizationLevels(
            (req.query.customization_levels || '').trim().split(/[,，]/).filter(Boolean)
        );
        if (!categoryKey && !manufacturerId) return res.status(400).json({ error: '請傳入 category_key（分類素材池）或 manufacturer_id（個別廠商版型庫）' });

        let catalogGroupAssetIds = null;
        if (catalogGroupId) {
            const cg = await getAssetIdsForCatalogGroup(catalogGroupId, manufacturerId);
            if (cg.error === 'no_table') catalogGroupAssetIds = null;
            else if (cg.error === 'not_found' || cg.error === 'mismatch') return res.json({ items: [], manufacturers: [] });
            else {
                catalogGroupAssetIds = new Set(cg.assetIds || []);
                if (!manufacturerId && cg.group) manufacturerId = cg.group.manufacturer_id;
            }
        }

        const selectCols = 'id, manufacturer_id, category_key, subcategory_key, title, title_en, description, description_en, image_url, cover_image_label, gallery_images, usage_type, sort_order, style_key, material_key, color_key, asset_kind, part_key, ai_tags, image_semantics_json, min_order_quantity, customization_levels, production_type_key';
        async function runQuery(cols) {
            let q = supabase
                .from('vendor_assets')
                .select(cols)
                .order('sort_order', { ascending: true })
                .order('created_at', { ascending: false });
            if (!internalPreview) q = q.eq('is_public', true);
            if (categoryKey) q = q.eq('category_key', categoryKey);
            /* 材料／零件上傳不填子分類（見 POST subcategoryKey=null）；僅數位原型依子分類 SQL 篩選 */
            if (subcategoryKey && assetKindFilter !== 'material' && assetKindFilter !== 'part') {
                q = q.eq('subcategory_key', subcategoryKey);
            }
            if (styleKey) q = q.eq('style_key', styleKey);
            if (materialKey && assetKindFilter !== 'material') q = q.eq('material_key', materialKey);
            if (manufacturerId) q = q.eq('manufacturer_id', manufacturerId);
            if (assetKindFilter && cols.includes('asset_kind')) q = q.eq('asset_kind', assetKindFilter);
            return q;
        }
        let { data: rows, error } = await runQuery(selectCols);
        if (error && error.code === '42703') {
            const legacyCols = selectCols.split(',').map((c) => c.trim()).filter((c) => c && c !== 'cover_image_label' && c !== 'part_key' && c !== 'asset_kind' && c !== 'color_key' && c !== 'min_order_quantity' && c !== 'customization_levels' && c !== 'production_type_key' && c !== 'title_en' && c !== 'description_en').join(', ');
            ({ data: rows, error } = await runQuery(legacyCols));
        }
        if (error) {
            if (error.code === '42P01') return res.status(200).json({ items: [], manufacturers: [], message: '尚未建立廠商素材表，請執行 docs/vendor-assets-schema.sql' });
            console.error('GET /api/vendor-assets 失敗:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        let list = rows || [];
        if (assetKindFilter && list.length) {
            const hasAssetKindCol = list.some((r) => r.asset_kind != null && String(r.asset_kind).trim() !== '');
            if (hasAssetKindCol) {
                list = list.filter((r) => effectiveVendorAssetKind(r) === assetKindFilter);
            } else if (assetKindFilter === 'part') {
                list = list.filter((r) => !!(r.part_key && String(r.part_key).trim()));
            } else if (assetKindFilter === 'material') {
                list = list.filter((r) => effectiveVendorAssetKind(r) === 'material');
            }
        }
        /* 素材類型「全部」+ 已選子分類：原型依子分類；材料／零件仍顯示該主分類下全部 */
        if (subcategoryKey && !assetKindFilter) {
            list = list.filter((r) => {
                const rk = effectiveVendorAssetKind(r);
                if (rk === 'material' || rk === 'part') return true;
                return (r.subcategory_key || '') === subcategoryKey;
            });
        }
        if (colorQ) list = list.filter((r) => vendorAssetMatchesColor(r, colorQ));
        const mfrIds = [...new Set(list.map(r => r.manufacturer_id).filter(Boolean))];
        const mfrMap = await buildManufacturerMapForVendorAssetList(mfrIds, { internalPreview });
        if (manufacturerNameQ) {
            list = list.filter((r) => manufacturerNameMatches(getManufacturerFromMap(mfrMap, r.manufacturer_id), manufacturerNameQ));
        }
        if (serviceAreaCode) {
            list = list.filter((r) => manufacturerMatchesServiceArea(getManufacturerFromMap(mfrMap, r.manufacturer_id), serviceAreaCode));
        }
        if (searchQ) {
            list = list.filter((r) => vendorAssetMatchesSearch(r, getManufacturerFromMap(mfrMap, r.manufacturer_id), searchQ));
        }
        if (catalogGroupAssetIds) {
            list = list.filter((r) => catalogGroupAssetIds.has(r.id));
        }
        if (moqFilter != null) {
            list = list.filter((r) => vendorAssetMatchesMoqFilter(r, moqFilter));
        }
        if (customFilterKeys.length) {
            list = list.filter((r) => vendorAssetMatchesCustomizationFilter(r, customFilterKeys));
        }
        list = list.filter(function (r) {
            const mfr = getManufacturerFromMap(mfrMap, r.manufacturer_id);
            if (!mfr) return !!internalPreview;
            if (internalPreview) return true;
            if (forProfile && manufacturerId) return vendorAssetVisibleOnManufacturerProfile(mfr, r);
            return vendorAssetVisibleToPublicAudience(mfr, r);
        });
        const lang = (req.query.lang || '').trim();
        const contentLang = normalizeVendorContentLang(lang);
        const manufacturers = [...new Set(list.map(r => r.manufacturer_id).filter(Boolean))].map((id) => {
            const mfr = getManufacturerFromMap(mfrMap, id);
            return {
                id,
                name: manufacturerNameForVendorAssetItem(mfrMap, id, contentLang),
                logo_url: (mfr && mfr.logo_url) ? mfr.logo_url : null,
                profile_url: '/vendor-profile.html?id=' + encodeURIComponent(id)
            };
        }).sort((a, b) => String(a.name).localeCompare(String(b.name), 'zh-Hant'));
        if (manufacturersOnly) {
            return res.json({ manufacturers });
        }
        let linkCountsByProto = {};
        if (assetKindFilter === 'prototype' && list.length && (await vendorPrototypeLinksTableReady())) {
            linkCountsByProto = await batchPrototypeLinkCounts(list);
        }
        if (hasPrototypeLinks && assetKindFilter === 'prototype') {
            list = list.filter((r) => {
                const c = linkCountsByProto[r.id];
                return c && (c.material_count + c.part_count) > 0;
            });
        }
        const items = list.map(r => {
            const kind = normalizeVendorAssetKind(r.asset_kind);
            const pk = kind === 'material' ? null : (r.part_key || null);
            const mapped = mapVendorAssetForApi(r, lang);
            const protoMeta = enrichVendorAssetPrototypeFields(r, lang);
            const protoLinkCounts = (kind === 'prototype' && linkCountsByProto[r.id])
                ? linkCountsByProto[r.id]
                : { material_count: 0, part_count: 0 };
            const linkCount = protoLinkCounts.material_count + protoLinkCounts.part_count;
            const shareUrls = buildVendorAssetAbsoluteShareUrls(r, linkCount);
            return {
                id: r.id,
                manufacturer_id: r.manufacturer_id,
                category_key: r.category_key,
                subcategory_key: r.subcategory_key,
                title: pickVendorLocalizedText(r.title, r.title_en, contentLang),
                description: pickVendorLocalizedText(r.description, r.description_en, contentLang),
                title_zh: r.title || '',
                title_en: r.title_en || '',
                description_zh: r.description || '',
                description_en: r.description_en || '',
                image_url: r.image_url,
                gallery_images: mapped.gallery_images,
                image_urls: mapped.image_urls,
                image_items: mapped.image_items,
                image_count: mapped.image_count,
                usage_type: r.usage_type,
                sort_order: r.sort_order,
                style_key: r.style_key || null,
                style_label: r.style_key ? vendorStyleKeyLabel(r.style_key, lang) : null,
                material_key: kind === 'material' ? null : (r.material_key || null),
                material_label: kind === 'material' ? null : (r.material_key ? vendorMaterialKeyLabel(r.material_key, lang) : null),
                color_key: r.color_key || null,
                color_label: r.color_key ? vendorColorKeyLabel(r.color_key, lang) : null,
                asset_kind: kind,
                part_key: pk,
                min_order_quantity: protoMeta.min_order_quantity,
                customization_levels: protoMeta.customization_levels,
                customization_level_labels: protoMeta.customization_level_labels,
                material_count: kind === 'prototype' ? protoLinkCounts.material_count : undefined,
                part_count: kind === 'prototype' ? protoLinkCounts.part_count : undefined,
                link_count: kind === 'prototype' ? linkCount : undefined,
                match_guide_url: kind === 'prototype'
                    ? '/product-tree.html?prototype_asset_id=' + encodeURIComponent(r.id)
                    : null,
                design_share_url: shareUrls.design_share_url || null,
                guide_share_url: shareUrls.guide_share_url || null,
                manufacturer_name: manufacturerNameForVendorAssetItem(mfrMap, r.manufacturer_id, contentLang),
                manufacturer_logo_url: (() => { const m = getManufacturerFromMap(mfrMap, r.manufacturer_id); return manufacturerLogoFromRow(m); })(),
                manufacturer_profile_url: r.manufacturer_id ? '/vendor-profile.html?id=' + encodeURIComponent(r.manufacturer_id) : null,
                manufacturer_location: (() => { const m = getManufacturerFromMap(mfrMap, r.manufacturer_id); return (m && m.location) ? m.location : ''; })(),
                manufacturer_user_id: (() => { const m = getManufacturerFromMap(mfrMap, r.manufacturer_id); return (m && m.user_id) ? m.user_id : null; })(),
                manufacturer_contact: (() => { const m = getManufacturerFromMap(mfrMap, r.manufacturer_id); return (m && m.contact_json) ? m.contact_json : null; })(),
                ai_tags: r.ai_tags || [],
                production_type_key: r.production_type_key || null
            };
        });
        let itemsOut = items;
        if (items.length && (await vendorCatalogGroupsTableReady())) {
            itemsOut = await attachCatalogGroupIdsToAssets(items);
        }
        try {
            itemsOut = await manufacturerTaxonomy.enrichVendorAssetItems(supabase, itemsOut);
        } catch (taxErr) {
            console.warn('GET /api/vendor-assets enrich taxonomy:', taxErr && taxErr.message);
        }
        const forPrototypeAssetId = (req.query.for_prototype_asset_id || '').trim() || null;
        let linkedIdSet = null;
        let linkSortById = {};
        if (forPrototypeAssetId && (await vendorPrototypeLinksTableReady())) {
            const { data: protoRow, error: protoErr } = await supabase
                .from('vendor_assets')
                .select('id, manufacturer_id, asset_kind, is_public')
                .eq('id', forPrototypeAssetId)
                .maybeSingle();
            if (!protoErr && protoRow && normalizeVendorAssetKind(protoRow.asset_kind) === 'prototype') {
                if (!internalPreview && !protoRow.is_public) {
                    linkedIdSet = new Set();
                } else {
                    const linkPack = await getLinkedAssetIdsForPrototype(protoRow.manufacturer_id, forPrototypeAssetId);
                    linkedIdSet = new Set(linkPack.ids);
                    linkSortById = linkPack.sortById;
                }
            }
        }
        if (linkedIdSet) {
            if (prototypeLinkedOnly) {
                itemsOut = itemsOut.filter((it) => linkedIdSet.has(it.id));
            } else {
                itemsOut = attachPrototypeLinkFlagsToItems(itemsOut, linkedIdSet);
                if (linkedIdSet.size) itemsOut = sortVendorAssetsWithPrototypeLinks(itemsOut, linkedIdSet, linkSortById);
            }
        }
        const paged = paginateVendorAssetList(itemsOut, pageParams);
        // 圖庫順序／封面會即時變動，勿讓 CDN／瀏覽器共用長快取
        res.set('Cache-Control', 'private, max-age=0, must-revalidate');
        res.json({
            items: paged.items,
            total: paged.total,
            limit: paged.limit,
            offset: paged.offset,
            manufacturers,
            catalog_group_id: catalogGroupId || null,
            for_prototype_asset_id: forPrototypeAssetId || null
        });
    } catch (e) {
        console.error('GET /api/vendor-assets 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/me/vendor-assets — 廠商自己的素材列表（需登入且已建立廠商資料）
app.get('/api/me/vendor-assets', async (req, res) => {
    try {
        const user = await getCurrentUser(req, res);
        if (!user) return;
        try {
            syncMembershipCatalogVisibility(user.id).catch((syncErr) => {
                console.warn('syncMembershipCatalogVisibility:', syncErr && syncErr.message);
            });
        } catch (syncErr) {
            console.warn('syncMembershipCatalogVisibility:', syncErr && syncErr.message);
        }
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        let manufacturerName = null;
        try {
            const { data: mfrRow } = await supabase.from('manufacturers').select('name').eq('id', manufacturerId).maybeSingle();
            manufacturerName = (mfrRow && mfrRow.name) ? mfrRow.name : null;
        } catch (_) { /* ignore */ }

        /** 情境圖選卡：輕量列表（跳過語意／關聯／分享 URL 等重處理） */
        const lite = String(req.query.lite || '').trim() === '1' || String(req.query.lite || '').toLowerCase() === 'true';
        if (lite) {
            const LITE_SELECT = 'id, manufacturer_id, title, image_url, gallery_images, asset_kind, cover_image_label, cover_link_group, is_public, created_at, updated_at';
            const LITE_SELECT_MIN = 'id, manufacturer_id, title, image_url, gallery_images, asset_kind, is_public, created_at, updated_at';
            const kindQ = String(req.query.asset_kind || '').trim().toLowerCase();
            let q = supabase
                .from('vendor_assets')
                .select(LITE_SELECT)
                .eq('manufacturer_id', manufacturerId)
                .order('sort_order', { ascending: true })
                .order('created_at', { ascending: false });
            if (kindQ === 'prototype' || kindQ === 'part') {
                q = q.eq('asset_kind', kindQ);
            } else {
                q = q.in('asset_kind', ['prototype', 'part']);
            }
            let { data: list, error } = await q;
            if (error && error.code === '42703') {
                ({ data: list, error } = await supabase
                    .from('vendor_assets')
                    .select(LITE_SELECT_MIN)
                    .eq('manufacturer_id', manufacturerId)
                    .order('created_at', { ascending: false }));
                if (!error && list) {
                    list = list.filter((row) => {
                        const k = normalizeVendorAssetKind(row.asset_kind);
                        if (kindQ === 'prototype' || kindQ === 'part') return k === kindQ;
                        return k === 'prototype' || k === 'part';
                    });
                }
            }
            if (error) {
                if (error.code === '42P01') return res.json({ items: [], lite: true });
                console.error('GET /api/me/vendor-assets?lite=1 失敗:', error);
                return res.status(500).json({ error: '查詢失敗' });
            }
            const lang = resolveVendorAssetApiLang(req);
            const mapped = (list || []).map((row) => mapVendorAssetForApi(row, lang));
            return res.json({
                items: mapped,
                total: mapped.length,
                lite: true,
                viewer: {
                    user_id: user.id,
                    email: user.email || null,
                    manufacturer_id: manufacturerId,
                    manufacturer_name: manufacturerName
                }
            });
        }

        const categoryKey = (req.query.category_key || '').trim() || null;
        const catalogGroupId = (req.query.catalog_group_id || '').trim() || null;
        const assetKindQ = (req.query.asset_kind || '').trim().toLowerCase();
        const assetKindFilter = normalizeVendorCatalogGroupKindFilter(assetKindQ);
        async function runList(selectCols) {
            let query = supabase
                .from('vendor_assets')
                .select(selectCols)
                .eq('manufacturer_id', manufacturerId)
                .order('sort_order', { ascending: true })
                .order('created_at', { ascending: false });
            if (categoryKey) query = query.eq('category_key', categoryKey);
            if (assetKindFilter && selectCols.includes('asset_kind')) query = query.eq('asset_kind', assetKindFilter);
            return query;
        }
        let { data: list, error } = await runList(VENDOR_ASSET_SELECT_ME);
        if (error && error.code === '42703') {
            ({ data: list, error } = await runList(VENDOR_ASSET_SELECT_ME_LEGACY));
            if (error && error.code === '42703') {
                ({ data: list, error } = await runList(VENDOR_ASSET_SELECT_ME_MINIMAL));
            }
            if (list) {
                list = list.map((row) => ({
                    ...row,
                    asset_kind: row.asset_kind || 'prototype',
                    gallery_images: row.gallery_images != null ? row.gallery_images : [],
                    cover_image_label: row.cover_image_label != null ? row.cover_image_label : null
                }));
            }
        }
        if (error) {
            if (error.code === '42P01') return res.json({ items: [] });
            console.error('GET /api/me/vendor-assets 失敗:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        if (assetKindFilter && list && list.length && list[0].asset_kind == null) {
            list = list.filter((row) => normalizeVendorAssetKind(row.asset_kind) === assetKindFilter);
        }
        if (catalogGroupId) {
            const cg = await getAssetIdsForCatalogGroup(catalogGroupId, manufacturerId);
            if (cg.assetIds) {
                const idSet = new Set(cg.assetIds);
                list = (list || []).filter((row) => idSet.has(row.id));
            }
        }
        list = await enrichVendorAssetsWithSupplierMeta(manufacturerId, list || []);
        if (list && list.length) list = await attachCatalogGroupIdsToAssets(list);
        const lang = resolveVendorAssetApiLang(req);
        let mapped = (list || []).map(function (row) { return mapVendorAssetForApi(row, lang); });
        try {
            mapped = await manufacturerTaxonomy.enrichVendorAssetItems(supabase, mapped);
        } catch (taxErr) {
            console.warn('enrichVendorAssetItems:', taxErr && taxErr.message);
        }
        const protoRowsForLinks = (list || []).filter((r) => normalizeVendorAssetKind(r.asset_kind) === 'prototype');
        let linkCountsByProtoMe = {};
        if (protoRowsForLinks.length && (await vendorPrototypeLinksTableReady())) {
            linkCountsByProtoMe = await batchPrototypeLinkCounts(protoRowsForLinks);
        }
        mapped = mapped.map(function (item) {
            const kind = normalizeVendorAssetKind(item.asset_kind);
            if (kind !== 'prototype') {
                const shareUrlsOther = buildVendorAssetAbsoluteShareUrls(item, 0);
                return {
                    ...item,
                    design_share_url: shareUrlsOther.design_share_url || null,
                    guide_share_url: null
                };
            }
            const c = linkCountsByProtoMe[item.id] || { material_count: 0, part_count: 0 };
            const linkCount = c.material_count + c.part_count;
            const shareUrls = buildVendorAssetAbsoluteShareUrls(item, linkCount);
            return {
                ...item,
                material_count: c.material_count,
                part_count: c.part_count,
                link_count: linkCount,
                match_guide_url: '/product-tree.html?prototype_asset_id=' + encodeURIComponent(item.id),
                design_share_url: shareUrls.design_share_url || null,
                guide_share_url: shareUrls.guide_share_url || null
            };
        });
        /* 廠商後台依分頁在前端各 Tab 篩選；此處回傳完整列表，避免只取 12 筆導致原型／零件列表空白 */
        res.json({
            items: mapped,
            total: mapped.length,
            limit: mapped.length,
            offset: 0,
            viewer: {
                user_id: user.id,
                email: user.email || null,
                manufacturer_id: manufacturerId,
                manufacturer_name: manufacturerName
            }
        });
    } catch (e) {
        console.error('GET /api/me/vendor-assets 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

