// POST /api/me/vendor-assets/material-dual-color-flux — 雙色卡 Step2 材質化（登入＋扣點；不限廠商）
app.post('/api/me/vendor-assets/material-dual-color-flux', upload.fields([
    { name: 'image', maxCount: 1 },
    { name: 'main_pattern', maxCount: 1 },
    { name: 'accent_pattern', maxCount: 1 },
    { name: 'third_pattern', maxCount: 1 }
]), async (req, res) => {
    try {
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        const body = req.body || {};
        const isAdmin = await isAdminUserId(seedUser.id);
        let manufacturerId = null;
        let storageFolder;

        if (isAdmin) {
            if (isOfficialPlatformLibraryRequest(req)) {
                const { data: profile } = await supabase.from('profiles').select('role').eq('id', seedUser.id).maybeSingle();
                if (profile?.role !== 'admin') {
                    return res.status(403).json({ error: '僅管理員可編輯官方版型庫', code: 'OFFICIAL_PLATFORM_ADMIN_REQUIRED' });
                }
                manufacturerId = await getOrEnsureOfficialPlatformManufacturerId();
                storageFolder = `vendor-assets-preview/${manufacturerId}`;
            } else {
                const { data: mfrRow } = await supabase.from('manufacturers').select('id').eq('user_id', seedUser.id).maybeSingle();
                manufacturerId = mfrRow?.id || null;
                if (manufacturerId) {
                    if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
                    storageFolder = `vendor-assets-preview/${manufacturerId}`;
                } else {
                    storageFolder = `material-combo-preview/${seedUser.id}`;
                }
            }
        } else {
            const { data: mfrRow } = await supabase.from('manufacturers').select('id').eq('user_id', seedUser.id).maybeSingle();
            manufacturerId = mfrRow?.id || null;
            if (manufacturerId) {
                if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
                storageFolder = `vendor-assets-preview/${manufacturerId}`;
            } else {
                storageFolder = `material-combo-preview/${seedUser.id}`;
            }
        }

        const files = req.files || {};
        const swatchFile = Array.isArray(files.image) ? files.image[0] : null;
        if (!swatchFile || !swatchFile.buffer || !swatchFile.buffer.length) {
            return res.status(400).json({ error: '請上傳色卡圖片' });
        }
        const swatchBuffer = swatchFile.buffer;

        const mainMaterial = body.main_material || body.mainMaterial || '';
        const accentMaterial = body.accent_material || body.accentMaterial || '';
        const thirdMaterial = body.third_material || body.thirdMaterial || '';
        const boundary = body.boundary || body.stitch_material || body.stitchMaterial || '';
        const colorCount = parseInt(body.color_count || body.colorCount, 10) === 3 ? 3 : 2;
        const ratioPercents = normalizeMaterialComboRatioPercents(body.ratio_percents || body.ratioPercents, colorCount);
        const mainPatternFile = Array.isArray(files.main_pattern) ? files.main_pattern[0] : null;
        const accentPatternFile = Array.isArray(files.accent_pattern) ? files.accent_pattern[0] : null;
        const thirdPatternFile = Array.isArray(files.third_pattern) ? files.third_pattern[0] : null;
        const mainPatternUrl = String(body.main_pattern_url || body.mainPatternUrl || '').trim();
        const accentPatternUrl = String(body.accent_pattern_url || body.accentPatternUrl || '').trim();
        const thirdPatternUrl = String(body.third_pattern_url || body.thirdPatternUrl || '').trim();
        const patternRefs = {
            main: mainPatternFile && mainPatternFile.buffer && mainPatternFile.buffer.length
                ? { buffer: mainPatternFile.buffer, mimetype: mainPatternFile.mimetype }
                : (mainPatternUrl || null),
            accent: accentPatternFile && accentPatternFile.buffer && accentPatternFile.buffer.length
                ? { buffer: accentPatternFile.buffer, mimetype: accentPatternFile.mimetype }
                : (accentPatternUrl || null),
            third: thirdPatternFile && thirdPatternFile.buffer && thirdPatternFile.buffer.length
                ? { buffer: thirdPatternFile.buffer, mimetype: thirdPatternFile.mimetype }
                : (thirdPatternUrl || null)
        };
        const patCount = (patternRefs.main ? 1 : 0) + (patternRefs.accent ? 1 : 0) + (patternRefs.third ? 1 : 0);
        if (patCount > 1) {
            return res.status(400).json({ error: '印花圖樣只能用於其中一區，不可同時多張' });
        }
        const printKind = patCount
            ? normalizeDualColorPrintKind(body.print_kind || body.printKind)
            : 'pattern';
        const materialLinks = parseMaterialComboMaterialLinksInput(body.material_links_json || body.material_links, colorCount);
        const transitionsInput = body.transitions_json || body.transitions;
        const swatchMode = String(body.swatch_mode || body.swatchMode || 'banded').trim() === 'mixed' ? 'mixed' : 'banded';
        let mixInput = null;
        try {
            const mixRaw = body.mix_json || body.mix;
            if (mixRaw) mixInput = typeof mixRaw === 'string' ? JSON.parse(mixRaw) : mixRaw;
        } catch (_) { mixInput = null; }
        const mixWeights = swatchMode === 'mixed'
            ? (mixInput && Array.isArray(mixInput.weights) ? mixInput.weights : ratioPercents)
            : ratioPercents;
        const comboExtras = {
            thirdMaterial: thirdMaterial,
            colorCount: colorCount,
            ratioPercents: mixWeights,
            materialLinks: materialLinks,
            transitions: transitionsInput,
            swatchMode: swatchMode,
            mix: swatchMode === 'mixed' ? Object.assign({ style: 'heather' }, mixInput || {}, { weights: mixWeights }) : null,
            mainHex: body.main_hex || body.mainHex || '',
            accentHex: body.accent_hex || body.accentHex || '',
            thirdHex: body.third_hex || body.thirdHex || ''
        };
        let aiPromptUsed;
        try {
            aiPromptUsed = buildMaterialDualColorFluxPrompt(mainMaterial, accentMaterial, boundary, {
                hasMainPattern: !!(patternRefs.main),
                hasAccentPattern: !!(patternRefs.accent),
                hasThirdPattern: !!(patternRefs.third),
                printKind,
                thirdMaterial: thirdMaterial,
                colorCount: colorCount,
                ratioPercents: mixWeights,
                materialLinks: materialLinks,
                transitions: transitionsInput,
                swatchMode: swatchMode,
                mix: comboExtras.mix,
                mainHex: body.main_hex || body.mainHex || '',
                accentHex: body.accent_hex || body.accentHex || '',
                thirdHex: body.third_hex || body.thirdHex || ''
            });
        } catch (promptErr) {
            return res.status(400).json({ error: promptErr.message || '請填各區材質或選擇印花圖樣' });
        }
        const pointsRequired = await getPointsMaterialDualColorFlux();
        const ownerId = seedUser.id;
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }

        let optimized;
        let dualRefCount = null;
        let dualEngine = null;
        let dualModel = null;
        let dualFallback = false;
        let dualFallbackReason = null;
        try {
            const result = await optimizeMaterialDualColor(
                swatchBuffer, mainMaterial, accentMaterial, boundary, patternRefs, printKind, comboExtras
            );
            optimized = result.buffer;
            aiPromptUsed = result.prompt;
            dualRefCount = result.reference_count || null;
            dualEngine = result.engine || null;
            dualModel = result.model || null;
            dualFallback = !!result.fallback;
            dualFallbackReason = result.fallback_reason || null;
        } catch (optErr) {
            console.error('material-dual-color-flux optimize:', optErr);
            if (optErr && optErr.status === 429) {
                return res.status(429).json({
                    error: optErr.message || '生圖次數已達上限，請稍後再試',
                    retry_after_sec: optErr.retry_after_sec || null,
                    quota_reason: optErr.quota_reason || null
                });
            }
            const mapped = vendorAssetOptimizeErrorResponse(optErr, 'material');
            return res.status(mapped.status).json(mapped.body);
        }
        const previewName = `dual-color-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products', storageFolder, { buffer: optimized, mimetype: 'image/jpeg', originalname: previewName }
        );
        let balanceAfter = null;
        let creditTransactionId = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'material_dual_color_flux',
                `材料組合材質生成（${pointsRequired} 點）`,
                { manufacturer_id: manufacturerId, preview: true }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
            creditTransactionId = consumed.transaction_id || null;
        }
        const comboForLibrary = normalizeMaterialCombo({
            main: { hex: body.main_hex || body.mainHex, material: mainMaterial },
            accent: { hex: body.accent_hex || body.accentHex, material: swatchMode === 'mixed' ? mainMaterial : accentMaterial },
            third: colorCount === 3
                ? { hex: body.third_hex || body.thirdHex, material: swatchMode === 'mixed' ? mainMaterial : thirdMaterial }
                : null,
            boundary: boundary,
            ratio_percents: mixWeights,
            ratio_preset: body.ratio_preset || body.ratioPreset || null,
            color_count: colorCount,
            swatch_mode: swatchMode,
            mix: swatchMode === 'mixed' ? comboExtras.mix : null,
            material_links: swatchMode === 'mixed' ? null : materialLinks,
            transitions: swatchMode === 'mixed' ? null : transitionsInput,
            source_palette: (function () {
                try {
                    const raw = body.source_palette_json || body.source_palette;
                    if (!raw) return null;
                    return typeof raw === 'string' ? JSON.parse(raw) : raw;
                } catch (_) {
                    return null;
                }
            })()
        });
        let librarySaved = false;
        let librarySaveError = null;
        let libraryGenerationId = null;
        if (comboForLibrary && publicUrl) {
            const comboTitle = normalizeUserAssetLibraryTitle(body.title || body.library_title)
                || ((mainMaterial && accentMaterial) ? `${mainMaterial}／${accentMaterial}` : '材料組合');
            const comboCategory = normalizeUserAssetLibraryCategory(body.category || body.library_category);
            const saved = await insertUserMaterialComboGeneration(
                ownerId, publicUrl, comboForLibrary, comboTitle, creditTransactionId, comboCategory
            );
            librarySaved = !!(saved && saved.ok);
            libraryGenerationId = saved && saved.id ? saved.id : null;
            if (libraryGenerationId) comboForLibrary.source_generation_id = libraryGenerationId;
            if (!librarySaved) librarySaveError = (saved && saved.reason) || 'insert_failed';
        } else if (publicUrl && !comboForLibrary) {
            librarySaveError = 'combo_invalid';
        }
        res.json({
            preview_url: publicUrl,
            preview_base64: optimized.toString('base64'),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            credit_transaction_id: creditTransactionId,
            ai_prompt: aiPromptUsed,
            reference_count: dualRefCount,
            engine: dualEngine,
            model: dualModel,
            fallback: dualFallback,
            fallback_reason: dualFallbackReason,
            library_saved: librarySaved,
            library_save_error: librarySaveError,
            library_generation_id: libraryGenerationId,
            material_combo: comboForLibrary || null
        });
    } catch (e) {
        console.error('POST /api/me/vendor-assets/material-dual-color-flux:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

async function insertUserPrintGeneration(userId, imageUrl, meta, title, creditTransactionId, category) {
    if (!userId || !imageUrl) return { ok: false, reason: 'invalid' };
    try {
        const row = {
            user_id: userId,
            image_url: imageUrl,
            title: normalizeUserAssetLibraryTitle(title),
            print_meta_json: (meta && typeof meta === 'object') ? meta : {},
            credit_transaction_id: creditTransactionId || null
        };
        const cat = normalizeUserAssetLibraryCategory(category);
        if (cat) row.category = cat;
        const { error } = await supabase.from('user_print_generations').insert(row);
        if (error) {
            if (isSupabaseMissingTableError(error) || error.code === '42P01') {
                return { ok: false, reason: 'table_missing' };
            }
            console.warn('insertUserPrintGeneration:', error.message);
            return { ok: false, reason: error.message || 'insert_failed' };
        }
        return { ok: true };
    } catch (e) {
        console.warn('insertUserPrintGeneration:', e.message || e);
        return { ok: false, reason: (e && e.message) || 'insert_failed' };
    }
}

function printAssetStorageFolder(userId) {
    return `print-asset-preview/${userId}`;
}

