/** POST /api/me/print-generations — 存入數位資產庫（不扣點；可存原圖或已重繪圖） */
app.post('/api/me/print-generations', upload.single('image'), async (req, res) => {
    try {
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        const body = req.body || {};
        const title = normalizeUserAssetLibraryTitle(body.title);
        const category = normalizeUserAssetLibraryCategory(body.category);
        const printType = normalizePrintAssetType(body.print_type || body.printType || '');
        const sourceKind = String(body.source_kind || body.sourceKind || 'original').trim().toLowerCase() === 'redraw'
            ? 'redraw'
            : 'original';
        let publicUrl = String(body.image_url || body.imageUrl || '').trim();
        if (!publicUrl) {
            const file = await vendorAssetFileFromMulter(req.file);
            if (!file) return res.status(400).json({ error: '請上傳圖片或提供 image_url' });
            const name = `print-${sourceKind}-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
            const uploaded = await uploadToSupabaseStorage(
                'custom-products',
                printAssetStorageFolder(seedUser.id),
                { buffer: file.buffer, mimetype: file.mimetype || 'image/jpeg', originalname: name }
            );
            publicUrl = uploaded.publicUrl;
        }
        if (!/^https?:\/\//i.test(publicUrl) && !publicUrl.startsWith('data:')) {
            return res.status(400).json({ error: '無效的圖片網址' });
        }
        const meta = {
            version: 1,
            source_kind: sourceKind,
            print_type: printType || null
        };
        const saved = await insertUserPrintGeneration(
            seedUser.id,
            publicUrl,
            meta,
            title || printType || (sourceKind === 'redraw' ? '印花（重繪）' : '印花'),
            null,
            category
        );
        if (!saved.ok) {
            if (saved.reason === 'table_missing') {
                return res.status(503).json({
                    error: '印花資料表尚未建立',
                    table_missing: true,
                    hint: '請在 Supabase 執行 docs/add-user-print-generations.sql'
                });
            }
            return res.status(500).json({ error: saved.reason || '寫入失敗' });
        }
        res.json({
            success: true,
            image_url: publicUrl,
            points_deducted: 0,
            library_saved: true
        });
    } catch (e) {
        console.error('POST /api/me/print-generations:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

/** POST /api/me/print-generations/redraw — AI 重繪（成功後扣點；不自動寫入資產庫） */
app.post('/api/me/print-generations/redraw', upload.single('image'), async (req, res) => {
    try {
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        const body = req.body || {};
        const isAdmin = await isAdminUserId(seedUser.id);
        const file = await vendorAssetFileFromMulter(req.file);
        if (!file) return res.status(400).json({ error: '請上傳印花圖片' });
        const printType = normalizePrintAssetType(body.print_type || body.printType || '');
        let aiPromptUsed;
        try {
            aiPromptUsed = buildPrintAssetOptimizePrompt(printType);
        } catch (promptErr) {
            return res.status(400).json({ error: promptErr.message || '請填印花材質' });
        }
        const pointsRequired = await getPointsPrintAssetFlux();
        const ownerId = seedUser.id;
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        let optimized;
        let printEngine = null;
        let printModel = null;
        let printFallback = false;
        let printFallbackReason = null;
        try {
            const result = await optimizePrintAsset(file.buffer, printType);
            optimized = result.buffer;
            aiPromptUsed = result.prompt;
            printEngine = result.engine || null;
            printModel = result.model || null;
            printFallback = !!result.fallback;
            printFallbackReason = result.fallback_reason || null;
        } catch (optErr) {
            console.error('print-generations/redraw optimize:', optErr);
            if (optErr && optErr.status === 429) {
                return res.status(429).json({
                    error: optErr.message || '生圖次數已達上限，請稍後再試',
                    retry_after_sec: optErr.retry_after_sec || null,
                    quota_reason: optErr.quota_reason || null
                });
            }
            const mapped = vendorAssetOptimizeErrorResponse(optErr, 'material');
            return res.status(mapped.status).json(mapped.body);
        }
        const previewName = `print-redraw-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products',
            printAssetStorageFolder(ownerId),
            { buffer: optimized, mimetype: 'image/jpeg', originalname: previewName }
        );
        let balanceAfter = null;
        let creditTransactionId = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'print_asset_flux',
                `印花 AI 重繪（${pointsRequired} 點）`,
                { preview: true, print_type: printType, engine: printEngine, model: printModel }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
            creditTransactionId = consumed.transaction_id || null;
        }
        res.json({
            preview_url: publicUrl,
            preview_base64: optimized.toString('base64'),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            credit_transaction_id: creditTransactionId,
            ai_prompt: aiPromptUsed,
            print_type: printType,
            engine: printEngine,
            model: printModel,
            fallback: printFallback,
            fallback_reason: printFallbackReason
        });
    } catch (e) {
        console.error('POST /api/me/print-generations/redraw:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/vendor-assets/preview-image-upscale — 上傳前原圖 Real-ESRGAN 放大預覽（輸出 ≤1MP）
app.post('/api/me/vendor-assets/preview-image-upscale', upload.single('image'), async (req, res) => {
    try {
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        if (!req.file || !req.file.buffer) return res.status(400).json({ error: '請上傳圖片' });
        const body = req.body || {};
        const assetKind = normalizeVendorAssetKind(body.asset_kind);
        if (assetKind !== 'prototype' && assetKind !== 'part' && assetKind !== 'material') {
            return res.status(400).json({ error: '不支援的素材類型' });
        }
        if (assetKind === 'material') {
            return res.status(400).json({ error: '材料參考不提供 AI 放大，請直接上傳原圖或使用 AI 重繪' });
        }
        const upscaleNeed = await evaluateVendorUpscaleNeedFromBuffer(req.file.buffer);
        if (!upscaleNeed.needed) {
            return res.status(400).json({
                error: vendorUpscaleRejectMessage(upscaleNeed),
                upscale_needed: false,
                megapixels: upscaleNeed.megapixels,
                width: upscaleNeed.width,
                height: upscaleNeed.height,
                ai_edit_url: AI_EDIT_UPSCALE_PAGE
            });
        }
        const REPLICATE_API_TOKEN = getReplicateApiToken();
        if (!REPLICATE_API_TOKEN) {
            return res.status(503).json({ error: replicateTokenMissingMessage() });
        }
        const scale = parseUpscaleScaleFromRequest(req);
        const basePts = await getPointsVendorAssetUpscale();
        const pointsRequired = pointsForUpscaleScale(basePts, scale);
        let ownerId = seedUser.id;
        let isAdmin = false;
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
        isAdmin = profile?.role === 'admin';
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        const file = await vendorAssetFileFromMulter(req.file);
        if (!file) return res.status(400).json({ error: '請上傳圖片' });
        let upscaled;
        try {
            upscaled = await vendorMaterialUpscale(file.buffer, file.mimetype, REPLICATE_API_TOKEN, { scale: scale });
        } catch (upErr) {
            console.error('preview-image-upscale:', upErr.status, upErr.details || upErr.message);
            return res.status(502).json({
                error: upErr.message && String(upErr.message).indexOf('REPLICATE') >= 0
                    ? String(upErr.message)
                    : '放大服務暫時無法使用，請稍後再試',
                details: upErr.status === 401 ? 'API Token 無效' : (upErr.details || upErr.message || '').slice(0, 200)
            });
        }
        const previewName = `upscale-preview-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products',
            `vendor-assets-preview/${manufacturerId}`,
            { buffer: upscaled.buffer, mimetype: upscaled.mimetype, originalname: previewName }
        );
        let balanceAfter = null;
        let creditTransactionId = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_upscale',
                `上傳前 AI 放大預覽 ${scale}×（${pointsRequired} 點）`,
                { manufacturer_id: manufacturerId, preview: true, max_output_mp: 1, scale: scale }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
            creditTransactionId = consumed.transaction_id || null;
        }
        res.json({
            preview_url: publicUrl,
            preview_base64: upscaled.buffer.toString('base64'),
            output_width: upscaled.width,
            output_height: upscaled.height,
            scale: scale,
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            credit_transaction_id: creditTransactionId
        });
    } catch (e) {
        console.error('POST /api/me/vendor-assets/preview-image-upscale:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

