// POST /api/me/vendor-assets/:id/gallery-images/upscale — 單張原圖 Real-ESRGAN 放大並追加新圖（輸出 ≤1MP）
app.post('/api/me/vendor-assets/:id/gallery-images/upscale', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const body = req.body || {};
        const sourceUrl = String(body.source_url || '').trim();
        if (!sourceUrl) return res.status(400).json({ error: '請提供 source_url' });
        const REPLICATE_API_TOKEN = getReplicateApiToken();
        if (!REPLICATE_API_TOKEN) {
            return res.status(503).json({ error: replicateTokenMissingMessage() });
        }
        const scale = parseUpscaleScaleFromRequest(req);
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind, title, cover_image_label'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        const assetKind = normalizeVendorAssetKind(row.asset_kind);
        if (!vendorAssetSupportsGalleryImages(assetKind)) {
            return res.status(400).json({ error: '此素材類型不支援多角度圖放大' });
        }
        if (assetKind === 'material') {
            return res.status(400).json({ error: '材料參考不提供 AI 放大，請直接上傳原圖或使用 AI 重繪' });
        }
        const allUrls = getVendorAssetAllImageUrls(row);
        if (allUrls.indexOf(sourceUrl) < 0) {
            return res.status(400).json({ error: '來源圖片不屬於此素材' });
        }
        const existing = parseGalleryImages(row.gallery_images);
        const totalNow = allUrls.length;
        const room = vendorAssetGalleryMaxTotal(assetKind) - totalNow;
        if (room <= 0) {
            return res.status(400).json({ error: vendorAssetGalleryLimitError(assetKind) });
        }
        const sourceItems = buildVendorAssetImageItems(row);
        const srcItem = sourceItems.find(function (it) { return it.url === sourceUrl; });
        const srcLabel = (srcItem && srcItem.label) || '';
        const basePts = await getPointsVendorAssetUpscale();
        const pointsRequired = pointsForUpscaleScale(basePts, scale);
        let ownerId = seedUser.id;
        let isAdmin = false;
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
        isAdmin = profile?.role === 'admin';
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        const resImg = await fetch(sourceUrl, { redirect: 'follow' });
        if (!resImg.ok) return res.status(503).json({ error: '無法讀取來源圖片' });
        const imgBuf = Buffer.from(await resImg.arrayBuffer());
        const imgMime = (resImg.headers.get('content-type') || 'image/jpeg').split(';')[0].trim();
        const upscaleNeed = await evaluateVendorUpscaleNeedFromBuffer(imgBuf);
        if (!upscaleNeed.needed) {
            return res.status(400).json({
                error: vendorUpscaleRejectMessage(upscaleNeed),
                upscale_needed: false,
                megapixels: upscaleNeed.megapixels,
                width: upscaleNeed.width,
                height: upscaleNeed.height,
                ai_edit_url: AI_EDIT_UPSCALE_PAGE
            });
        }
        let upscaled;
        try {
            upscaled = await vendorMaterialUpscale(imgBuf, imgMime, REPLICATE_API_TOKEN, { scale: scale });
        } catch (upErr) {
            console.error('gallery-images/upscale:', upErr.status, upErr.details || upErr.message);
            return res.status(502).json({
                error: '放大服務暫時無法使用，請稍後再試',
                details: upErr.status === 401 ? 'API Token 無效' : (upErr.details || upErr.message || '').slice(0, 200)
            });
        }
        const startSort = existing.length ? Math.max.apply(null, existing.map(function (g) { return g.sort_order; })) + 1 : 1;
        const upscaleLabel = vendorImageLabelFromSource(srcLabel, labelFromImageUrl(sourceUrl) || '放大');
        const upscaleFile = {
            buffer: upscaled.buffer,
            mimetype: upscaled.mimetype,
            originalname: 'upscale-' + Date.now() + '.jpg'
        };
        const newEntries = await uploadVendorAssetGalleryFiles(manufacturerId, [upscaleFile], startSort, [upscaleLabel], ['upscale']);
        if (!newEntries.length) {
            return res.status(500).json({ error: '上傳放大結果失敗' });
        }
        newEntries.forEach(function (e) { e.source_url = sourceUrl; });
        const updatePayload = {
            gallery_images: existing.concat(newEntries),
            updated_at: new Date().toISOString()
        };
        const { data: updated, error } = await supabase.from('vendor_assets')
            .update(updatePayload)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_GALLERY_API)
            .single();
        if (error) {
            if (error.code === '42703') {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql 新增多角度圖欄位' });
            }
            return res.status(500).json({ error: '更新失敗' });
        }
        let balanceAfter = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_upscale',
                `單張多角度圖 AI 放大 ${scale}×（${pointsRequired} 點）`,
                { manufacturer_id: manufacturerId, asset_id: id, source_url: sourceUrl, scale: scale }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
        }
        res.json({
            ...(await mapVendorAssetForApiEnriched(updated)),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            upscale_from_url: sourceUrl,
            scale: scale
        });
    } catch (e) {
        console.error('POST /api/me/vendor-assets/:id/gallery-images/upscale:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/vendor-assets/:id/gallery-images — 數位原型／零件新增多角度圖（可選每張 AI 重繪）
app.post('/api/me/vendor-assets/:id/gallery-images', upload.array('images', VENDOR_GALLERY_MULTER_MAX_EXTRA), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind, title, category_key, subcategory_key, description'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        const assetKind = normalizeVendorAssetKind(row.asset_kind);
        if (!vendorAssetSupportsGalleryImages(assetKind)) {
            return res.status(400).json({ error: '此素材類型不支援新增多角度圖' });
        }
        const files = (req.files && req.files.length) ? req.files : [];
        if (!files.length) return res.status(400).json({ error: '請上傳至少一張圖片' });
        const body = req.body || {};
        const optimizeIndices = parseOptimizeImageIndices(body, files.length);
        const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
        const useDisplayStand = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
        const productNameForPrompt = resolveOptimizeProductNameForPrompt(body, row.title);
        const titleForPrompt = (row.title || '').trim() || null;
        const materialCatalogHint = assetKind === 'material'
            ? await materialCatalogHintForVendorAsset(manufacturerId, id)
            : '';
        const imageLabels = parseImageLabelsBody(body, files.length);
        const materialSurfaceType = assetKind === 'material' ? resolveMaterialSurfaceType(body, row) : '';
        let pointsRequired = 0;
        if (optimizeIndices.length) {
            pointsRequired = await computeVendorAssetOptimizeTotalPoints(optimizeIndices.length, assetKind);
        }
        let ownerId = seedUser.id;
        let isAdmin = false;
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
        isAdmin = profile?.role === 'admin';
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        const existing = parseGalleryImages(row.gallery_images);
        const totalNow = getVendorAssetAllImageUrls(row).length;
        const room = vendorAssetGalleryMaxTotal(assetKind) - totalNow;
        if (room <= 0) {
            return res.status(400).json({ error: vendorAssetGalleryLimitError(assetKind) });
        }
        const sliceCount = Math.min(files.length, room);
        const galleryToUpload = [];
        const fluxScheduler = createVendorFluxOptimizeScheduler(ownerId, materialSurfaceType, useDisplayStand, {
            categoryKey: row.category_key || '',
            subcategoryKey: row.subcategory_key || ''
        });
        for (let gi = 0; gi < sliceCount; gi++) {
            let gf = await vendorAssetFileFromMulter(files[gi]);
            if (!gf) continue;
            if (optimizeIndices.includes(gi)) {
                try {
                    const galleryFilenameHint = (imageLabels[gi] && String(imageLabels[gi]).trim())
                        || labelFromOriginalFilename(gf.originalname);
                    gf = await fluxScheduler.optimize(
                        gf,
                        productNameForPrompt,
                        assetKind,
                        assetKind === 'material' ? materialCatalogHint : null,
                        assetKind === 'material' ? 'white' : optimizeBackground,
                        galleryFilenameHint
                    );
                } catch (optErr) {
                    console.error('gallery-images optimize:', optErr);
                    const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
                    return res.status(mapped.status).json(mapped.body);
                }
            }
            galleryToUpload.push(gf);
        }
        if (!galleryToUpload.length) {
            return res.status(400).json({ error: '無法讀取上傳的圖片，請改用 JPG／PNG／WebP 後重試' });
        }
        const startSort = existing.length ? Math.max.apply(null, existing.map(function (g) { return g.sort_order; })) + 1 : 1;
        const uploadLabels = parseImageLabelsBody(body, sliceCount);
        const uploadDerived = parseImageAiDerivedBody(body, sliceCount);
        const uploadLinkGroups = assetKind === 'prototype' ? parseImageLinkGroupsBody(body, sliceCount) : [];
        const uploadDesignerSelectable = (assetKind === 'prototype' || assetKind === 'part' || assetKind === 'material')
            ? parseImageDesignerSelectableBody(body, sliceCount) : [];
        const uploadSourceUrls = parseImageSourceUrlsBody(body, sliceCount);
        const newEntries = await uploadVendorAssetGalleryFiles(
            manufacturerId, galleryToUpload, startSort, uploadLabels, uploadDerived, uploadLinkGroups, uploadDesignerSelectable, uploadSourceUrls
        );
        if (!newEntries.length) {
            return res.status(500).json({ error: '圖片上傳至 Storage 失敗，請改用 JPG／PNG／WebP 後重試' });
        }
        if (assetKind === 'material') {
            newEntries.forEach(function (e) { delete e.designer_selectable; });
        }
        let merged = existing.concat(newEntries);
        merged = applyCoverDesignerSelectableMeta(
            merged,
            normalizeVendorAssetKind(assetKind) === 'material'
                ? false
                : readCoverDesignerSelectableMeta(row.gallery_images)
        );
        const { data: updated, error } = await supabase.from('vendor_assets')
            .update({ gallery_images: merged, updated_at: new Date().toISOString() })
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_GALLERY_API)
            .single();
        if (error) {
            if (error.code === '42703') {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql 新增多角度圖欄位' });
            }
            return res.status(500).json({ error: '更新失敗' });
        }
        const afterGallery = parseGalleryImages(updated && updated.gallery_images);
        if (afterGallery.length < existing.length + newEntries.length) {
            return res.status(500).json({
                error: '圖片可能未寫入資料庫。請在 Supabase 執行 docs/add-vendor-asset-gallery-images.sql',
                gallery_images_missing: true
            });
        }
        let balanceAfter = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_optimize',
                `多角度圖 ${optimizeIndices.length} 張 AI 重繪（${pointsRequired} 點）`,
                { manufacturer_id: manufacturerId, asset_id: id, optimize_count: optimizeIndices.length }
            );
            if (consumed.ok) balanceAfter = consumed.balance_after;
        }
        const tagContext = {
            asset_kind: assetKind,
            category_key: updated.category_key || row.category_key,
            title: titleForPrompt,
            description: updated.description || row.description,
            material_catalog_hint: materialCatalogHint || undefined
        };
        // 圖庫新增：先回應用戶，AI 標籤背景重算（避免每次儲存卡在 Gemini）
        scheduleVendorAssetTagRefreshInBackground(updated, manufacturerId, id, tagContext, ownerId);
        res.json({
            ...(await mapVendorAssetForApiEnriched(updated)),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            ai_tags_refreshed: false,
            ai_tags_refresh_pending: true
        });
    } catch (e) {
        console.error('POST /api/me/vendor-assets/:id/gallery-images:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/me/vendor-assets/:id/image-labels — 更新封面／各張圖顯示名稱
app.patch('/api/me/vendor-assets/:id/image-labels', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const body = req.body || {};
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind, cover_image_label, cover_link_group'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (!vendorAssetSupportsGalleryImages(row.asset_kind) && body.entries && body.entries.length) {
            return res.status(400).json({ error: '僅數位原型或配件／零件可設定多角度圖名稱' });
        }
        if (normalizeVendorAssetKind(row.asset_kind) !== 'prototype'
            && (body.cover_linked_asset_ids !== undefined
                || (Array.isArray(body.entries) && body.entries.some((ent) => ent && ent.linked_asset_ids !== undefined)))) {
            return res.status(400).json({ error: '僅數位原型圖片可設定材料／配件覆寫' });
        }
        const requestedOverrideIds = [...new Set([
            ...normalizeImageLinkedAssetIds(body.cover_linked_asset_ids),
            ...(Array.isArray(body.entries) ? body.entries.flatMap((ent) => normalizeImageLinkedAssetIds(ent && ent.linked_asset_ids)) : [])
        ])];
        if (requestedOverrideIds.length) {
            const { data: overrideRows, error: overrideErr } = await supabase
                .from('vendor_assets')
                .select('id, asset_kind')
                .eq('manufacturer_id', manufacturerId)
                .in('id', requestedOverrideIds);
            if (overrideErr) throw overrideErr;
            const validOverrideIds = new Set((overrideRows || []).filter((asset) => {
                const kind = normalizeVendorAssetKind(asset.asset_kind);
                return kind === 'material' || kind === 'part';
            }).map((asset) => String(asset.id)));
            if (validOverrideIds.size !== requestedOverrideIds.length) {
                return res.status(400).json({ error: '圖片覆寫只能選同一廠商的材料或配件' });
            }
        }
        const updates = { updated_at: new Date().toISOString() };
        if (body.cover_label !== undefined) {
            updates.cover_image_label = String(body.cover_label || '').trim() || null;
        }
        if (body.cover_link_group !== undefined) {
            const clg = normalizeImageLinkGroup(body.cover_link_group);
            updates.cover_link_group = clg || null;
        }
        let galleryWorking = null;
        if (Array.isArray(body.entries) && body.entries.length) {
            const byUrl = {};
            body.entries.forEach(function (ent) {
                if (!ent || !ent.url) return;
                const key = String(ent.url).trim();
                if (!byUrl[key]) byUrl[key] = {};
                if (ent.label !== undefined) byUrl[key].label = String(ent.label != null ? ent.label : '').trim();
                if (ent.link_group !== undefined) {
                    const lg = normalizeImageLinkGroup(ent.link_group);
                    byUrl[key].link_group = lg || null;
                }
                if (ent.designer_selectable !== undefined) {
                    byUrl[key].designer_selectable = normalizeDesignerSelectable(ent.designer_selectable);
                }
                if (ent.linked_asset_ids !== undefined) {
                    byUrl[key].linked_asset_ids = normalizeImageLinkedAssetIds(ent.linked_asset_ids);
                }
            });
            galleryWorking = parseGalleryImages(row.gallery_images).map(function (g) {
                const patch = byUrl[g.url];
                if (!patch) return g;
                const next = { url: g.url, sort_order: g.sort_order, label: patch.label !== undefined ? patch.label : g.label };
                const derivedKeep = normalizeVendorAiDerivedKind(g.ai_derived);
                if (derivedKeep) next.ai_derived = derivedKeep;
                if (g.source_url) next.source_url = g.source_url;
                if (patch.linked_asset_ids !== undefined) {
                    if (patch.linked_asset_ids.length) next.linked_asset_ids = patch.linked_asset_ids;
                } else if (normalizeImageLinkedAssetIds(g.linked_asset_ids).length) {
                    next.linked_asset_ids = normalizeImageLinkedAssetIds(g.linked_asset_ids);
                }
                const selectable = patch.designer_selectable !== undefined
                    ? patch.designer_selectable
                    : (g.designer_selectable === undefined ? true : normalizeDesignerSelectable(g.designer_selectable));
                if (!selectable) {
                    next.designer_selectable = false;
                    // 僅展示不需連動組
                } else {
                    if (patch.link_group !== undefined) {
                        if (patch.link_group) next.link_group = patch.link_group;
                    } else if (g.link_group) {
                        next.link_group = g.link_group;
                    }
                }
                if (normalizeVendorAssetKind(row.asset_kind) === 'material') {
                    delete next.designer_selectable;
                }
                return next;
            });
        }
        if (normalizeVendorAssetKind(row.asset_kind) === 'material') {
            // 材料封面一律不可選用
            if (!galleryWorking) galleryWorking = parseGalleryImages(row.gallery_images);
            galleryWorking = applyCoverDesignerSelectableMeta(galleryWorking, false);
        } else if (body.cover_designer_selectable !== undefined) {
            if (!galleryWorking) galleryWorking = parseGalleryImages(row.gallery_images);
            const coverSel = normalizeDesignerSelectable(body.cover_designer_selectable);
            galleryWorking = applyCoverDesignerSelectableMeta(galleryWorking, coverSel);
            if (!coverSel && body.cover_link_group === undefined) {
                updates.cover_link_group = null;
            }
        } else if (galleryWorking) {
            // 保留既有封面 meta
            galleryWorking = applyCoverDesignerSelectableMeta(
                galleryWorking,
                readCoverDesignerSelectableMeta(row.gallery_images)
            );
        }
        if ((galleryWorking || body.cover_linked_asset_ids !== undefined)
            && normalizeVendorAssetKind(row.asset_kind) === 'prototype') {
            if (!galleryWorking) galleryWorking = parseGalleryImages(row.gallery_images);
            galleryWorking = galleryWorking.filter((entry) => !(entry && typeof entry === 'object'
                && !entry.url && Object.prototype.hasOwnProperty.call(entry, '__cover_linked_asset_ids')));
            const coverLinkedAssetIds = body.cover_linked_asset_ids !== undefined
                ? normalizeImageLinkedAssetIds(body.cover_linked_asset_ids)
                : readCoverLinkedAssetIdsMeta(row.gallery_images);
            if (coverLinkedAssetIds.length) {
                galleryWorking.push({ __cover_linked_asset_ids: coverLinkedAssetIds });
            }
        }
        if (galleryWorking) updates.gallery_images = galleryWorking;
        if (Object.keys(updates).length <= 1) {
            return res.status(400).json({ error: '請提供 cover_label、cover_link_group、cover_designer_selectable 或 entries' });
        }
        const coverLabelRequested = body.cover_label !== undefined;
        const coverLinkGroupRequested = body.cover_link_group !== undefined;
        let coverLabelSkipped = false;
        let coverLinkGroupSkipped = false;
        let { data: updated, error } = await supabase.from('vendor_assets')
            .update(updates)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_ME)
            .single();
        if (error && error.code === '42703') {
            if (String(error.message || '').includes('cover_image_label')) {
                delete updates.cover_image_label;
                coverLabelSkipped = coverLabelRequested;
            }
            if (String(error.message || '').includes('cover_link_group')) {
                delete updates.cover_link_group;
                coverLinkGroupSkipped = coverLinkGroupRequested;
            }
            if (String(error.message || '').includes('gallery_images')) {
                delete updates.gallery_images;
            }
            if (Object.keys(updates).length <= 1) {
                return res.status(503).json({
                    error: '資料庫尚未支援圖片名稱欄位',
                    code: 'IMAGE_LABELS_SCHEMA',
                    hint: '請至 Supabase 執行 docs/add-vendor-asset-image-labels.sql 與 docs/add-vendor-asset-gallery-images.sql'
                });
            }
            ({ data: updated, error } = await supabase.from('vendor_assets')
                .update(updates)
                .eq('id', id)
                .eq('manufacturer_id', manufacturerId)
                .select(VENDOR_ASSET_SELECT_ME_LEGACY)
                .single());
            if (error && error.code === '42703') {
                ({ data: updated, error } = await supabase.from('vendor_assets')
                    .update(updates)
                    .eq('id', id)
                    .eq('manufacturer_id', manufacturerId)
                    .select(VENDOR_ASSET_SELECT_ME_MINIMAL)
                    .single());
            }
        }
        if (error) {
            console.error('PATCH image-labels:', error);
            return res.status(500).json({ error: error.message || '更新失敗' });
        }
        const payload = mapVendorAssetForApi(updated);
        if (coverLabelSkipped && coverLinkGroupSkipped) {
            payload.warning = '資料庫尚未支援連動組；請執行 docs/add-vendor-asset-image-link-groups.sql';
        } else if (coverLinkGroupSkipped) {
            payload.cover_link_group_skipped = true;
            payload.warning = '部分欄位已儲存；連動組需執行 docs/add-vendor-asset-image-link-groups.sql';
        } else if (coverLabelSkipped) {
            payload.cover_label_skipped = true;
            payload.warning = '多角度圖名稱已儲存；封面名稱需執行 docs/add-vendor-asset-image-labels.sql';
        }
        res.json(payload);
    } catch (e) {
        console.error('PATCH /api/me/vendor-assets/:id/image-labels:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/me/vendor-assets/:id/gallery-images/cover — 將現有角度圖設為封面（其餘順序往後）
app.patch('/api/me/vendor-assets/:id/gallery-images/cover', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const targetUrl = String((req.body && req.body.url) || '').trim();
        if (!targetUrl) return res.status(400).json({ error: '請提供 url' });
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind, cover_image_label'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (!vendorAssetSupportsGalleryImages(row.asset_kind)) {
            return res.status(400).json({ error: '僅數位原型或配件／零件可設定封面' });
        }
        const reordered = reorderVendorAssetCoverFromUrl(row, targetUrl);
        if (!reordered) return res.status(400).json({ error: '該圖片不屬於此素材' });
        let coverUpdate = {
            image_url: reordered.image_url,
            cover_image_label: reordered.cover_image_label,
            gallery_images: reordered.gallery_images,
            updated_at: new Date().toISOString()
        };
        let { data: updated, error } = await supabase.from('vendor_assets')
            .update(coverUpdate)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_GALLERY_API)
            .single();
        if (error && error.code === '42703' && String(error.message || '').includes('cover_image_label')) {
            delete coverUpdate.cover_image_label;
            ({ data: updated, error } = await supabase.from('vendor_assets')
                .update(coverUpdate)
                .eq('id', id)
                .eq('manufacturer_id', manufacturerId)
                .select(VENDOR_ASSET_SELECT_GALLERY_API)
                .single());
        }
        if (error) {
            if (error.code === '42703') {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql' });
            }
            return res.status(500).json({ error: '更新失敗' });
        }
        // 換封面僅重排既有圖，無需重跑 Gemini
        res.json(await mapVendorAssetForApiEnriched(updated));
    } catch (e) {
        console.error('PATCH /api/me/vendor-assets/:id/gallery-images/cover:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/me/vendor-assets/:id/gallery-images/order — 調整已上傳圖片順序（body.urls 為完整 url 陣列，第一張為封面）
app.patch('/api/me/vendor-assets/:id/gallery-images/order', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const orderedUrls = req.body && req.body.urls;
        if (!Array.isArray(orderedUrls) || !orderedUrls.length) {
            return res.status(400).json({ error: '請提供 urls 陣列' });
        }
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind, cover_image_label, cover_link_group'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (!vendorAssetSupportsGalleryImages(row.asset_kind)) {
            return res.status(400).json({ error: '僅數位原型或配件／零件可調整圖片順序' });
        }
        const reordered = reorderVendorAssetGalleryFromUrls(row, orderedUrls);
        if (!reordered) return res.status(400).json({ error: 'urls 必須包含此素材全部圖片且不可重複' });
        let orderUpdate = {
            image_url: reordered.image_url,
            cover_image_label: reordered.cover_image_label,
            cover_link_group: reordered.cover_link_group,
            gallery_images: reordered.gallery_images,
            updated_at: new Date().toISOString()
        };
        let { data: updated, error } = await supabase.from('vendor_assets')
            .update(orderUpdate)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_GALLERY_API)
            .single();
        if (error && error.code === '42703') {
            const msg = String(error.message || '');
            if (msg.includes('cover_image_label')) delete orderUpdate.cover_image_label;
            if (msg.includes('cover_link_group')) delete orderUpdate.cover_link_group;
            if (Object.keys(orderUpdate).length <= 1) {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql' });
            }
            ({ data: updated, error } = await supabase.from('vendor_assets')
                .update(orderUpdate)
                .eq('id', id)
                .eq('manufacturer_id', manufacturerId)
                .select(VENDOR_ASSET_SELECT_GALLERY_API)
                .single());
        }
        if (error) {
            if (error.code === '42703') {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql' });
            }
            return res.status(500).json({ error: '更新失敗' });
        }
        // 排序僅重排既有圖，無需重跑 Gemini
        res.json(await mapVendorAssetForApiEnriched(updated));
    } catch (e) {
        console.error('PATCH /api/me/vendor-assets/:id/gallery-images/order:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// DELETE /api/me/vendor-assets/:id/gallery-images — 刪除某一張多角度圖或封面（body.url 必填）
app.delete('/api/me/vendor-assets/:id/gallery-images', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const targetUrl = String((req.body && req.body.url) || '').trim();
        if (!targetUrl) return res.status(400).json({ error: '請提供 url' });
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, gallery_images, asset_kind'
        );
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (!vendorAssetSupportsGalleryImages(row.asset_kind)) {
            return res.status(400).json({ error: '僅數位原型或配件／零件可管理多角度圖' });
        }
        let cover = String(row.image_url || '').trim();
        let gallery = parseGalleryImages(row.gallery_images).filter(function (g) { return g.url !== targetUrl; });
        let coverLabel = String(row.cover_image_label || '').trim();
        if (targetUrl === cover) {
            if (!gallery.length) {
                return res.status(400).json({ error: '至少需保留一張圖片，請改為上傳新封面或刪除整筆素材' });
            }
            cover = gallery[0].url;
            coverLabel = String(gallery[0].label || '').trim() || labelFromImageUrl(cover);
            gallery = gallery.slice(1).map(function (g, i) { return { url: g.url, sort_order: i + 1, label: g.label || '' }; });
        }
        const { data: updated, error } = await supabase.from('vendor_assets')
            .update({
                image_url: cover,
                cover_image_label: coverLabel || labelFromImageUrl(cover),
                gallery_images: gallery,
                updated_at: new Date().toISOString()
            })
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_GALLERY_API)
            .single();
        if (error) {
            if (error.code === '42703') {
                return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-gallery-images.sql' });
            }
            return res.status(500).json({ error: '更新失敗' });
        }
        const assetKindDel = normalizeVendorAssetKind(updated.asset_kind);
        let materialHintDel = '';
        if (assetKindDel === 'material') {
            materialHintDel = await materialCatalogHintForVendorAsset(manufacturerId, id);
        }
        // 刪圖：先回應，標籤背景更新
        scheduleVendorAssetTagRefreshInBackground(updated, manufacturerId, id, {
            asset_kind: assetKindDel,
            category_key: updated.category_key,
            title: updated.title,
            description: updated.description,
            material_catalog_hint: materialHintDel || undefined
        }, seedUser.id);
        res.json(await mapVendorAssetForApiEnriched(updated));
    } catch (e) {
        console.error('DELETE /api/me/vendor-assets/:id/gallery-images:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/me/vendor-assets/:id — 上架／下架等輕量更新（僅本人廠商；種子廠商不得操作）
app.patch('/api/me/vendor-assets/:id', express.json(), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const body = req.body || {};
        const updates = { updated_at: new Date().toISOString() };
        if (body.is_public !== undefined) updates.is_public = !!parseTruthyBody(body.is_public);
        if (Object.keys(updates).length <= 1) return res.status(400).json({ error: '無可更新的欄位' });
        const { data: updated, error } = await supabase
            .from('vendor_assets')
            .update(updates)
            .eq('id', id)
            .eq('manufacturer_id', manufacturerId)
            .select(VENDOR_ASSET_SELECT_ME)
            .single();
        if (error) {
            console.error('PATCH /api/me/vendor-assets/:id:', error);
            return res.status(500).json({ error: error.message || '更新失敗' });
        }
        if (!updated) return res.status(404).json({ error: '找不到該素材' });
        const lang = resolveVendorAssetApiLang(req);
        res.json(mapVendorAssetForApi(updated, lang));
    } catch (e) {
        console.error('PATCH /api/me/vendor-assets/:id 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/me/vendor-assets/:id/prototype-links — 主產品 ↔ 材料／配件關聯（編輯用）
app.get('/api/me/vendor-assets/:id/prototype-links', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const id = (req.params.id || '').trim();
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, title, image_url, asset_kind'
        );
        if (rowErr) {
            console.error('GET prototype-links select:', rowErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (!(await vendorPrototypeLinksTableReady())) {
            return res.json({
                asset_kind: normalizeVendorAssetKind(row.asset_kind),
                linked_asset_ids: [],
                linked_prototype_ids: [],
                candidates: [],
                table_ready: false
            });
        }
        const kind = normalizeVendorAssetKind(row.asset_kind);
        const { data: allRows, error: allErr } = await supabase
            .from('vendor_assets')
            .select('id, title, image_url, asset_kind, category_key, subcategory_key, source_catalog_item_id, sort_order, created_at')
            .eq('manufacturer_id', manufacturerId)
            .order('sort_order', { ascending: true })
            .order('created_at', { ascending: false });
        if (allErr) return res.status(500).json({ error: '查詢失敗' });
        let candidates = (allRows || [])
            .filter((r) => r.id !== id)
            .map((r) => ({
                id: r.id,
                title: r.title,
                image_url: r.image_url,
                asset_kind: normalizeVendorAssetKind(r.asset_kind),
                category_key: r.category_key || null,
                subcategory_key: r.subcategory_key || null,
                source_catalog_item_id: r.source_catalog_item_id || null
            }));
        if (candidates.length) {
            try {
                candidates = await enrichVendorAssetsWithSupplierMeta(manufacturerId, candidates);
            } catch (supErr) {
                console.warn('GET prototype-links supplier meta:', supErr && supErr.message);
            }
            candidates = candidates.map((c) => ({
                ...c,
                asset_origin: vendorAssetOriginForApi(c)
            }));
        }
        if (candidates.length && (await vendorCatalogGroupsTableReady()) && (await vendorAssetGroupLinksTableReady())) {
            try {
                candidates = await attachCatalogGroupIdsToAssets(candidates);
            } catch (catErr) {
                console.warn('GET prototype-links catalog_groups:', catErr && catErr.message);
            }
        }
        if (kind === 'prototype') {
            const linkPack = await getLinkedAssetIdsForPrototype(manufacturerId, id);
            const linkedLinks = (linkPack.ids || []).map(function (lid) {
                const m = (linkPack.metaById && linkPack.metaById[lid]) || {};
                return {
                    linked_asset_id: lid,
                    allow_multi_pick: m.allow_multi_pick !== false,
                    pick_group: m.pick_group || null
                };
            });
            return res.json({
                asset_kind: kind,
                linked_asset_ids: linkPack.ids,
                linked_links: linkedLinks,
                linked_prototype_ids: [],
                candidates: candidates.filter((c) => c.asset_kind === 'material' || c.asset_kind === 'part'),
                table_ready: true
            });
        }
        if (kind === 'material' || kind === 'part') {
            const linkedPrototypeIds = await getPrototypeIdsForLinkedAsset(manufacturerId, id);
            return res.json({
                asset_kind: kind,
                linked_asset_ids: [],
                linked_prototype_ids: linkedPrototypeIds,
                candidates: candidates.filter((c) => c.asset_kind === 'prototype'),
                table_ready: true
            });
        }
        return res.json({
            asset_kind: kind,
            linked_asset_ids: [],
            linked_prototype_ids: [],
            candidates: [],
            table_ready: true
        });
    } catch (e) {
        console.error('GET /api/me/vendor-assets/:id/prototype-links:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/me/vendor-assets/:id/design-insights — 主產品：生圖次數、熱門搭配、近期成圖
app.get('/api/me/vendor-assets/:id/design-insights', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const id = (req.params.id || '').trim();
        const payload = await buildVendorPrototypeDesignInsights(manufacturerId, id);
        if (payload.error === 'not_found') return res.status(404).json({ error: '找不到該主產品' });
        res.json(payload);
    } catch (e) {
        console.error('GET /api/me/vendor-assets/:id/design-insights:', e);
        res.status(500).json({ error: '查詢失敗' });
    }
});

// PUT /api/me/vendor-assets/:id — 更新廠商素材（僅本人廠商）；種子廠商不得編輯
app.put('/api/me/vendor-assets/:id', upload.single('image'), async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const body = req.body || {};
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(
            id, manufacturerId, 'id, image_url, category_key, subcategory_key, title, description, asset_kind, material_key, min_order_quantity, customization_levels'
        );
        if (rowErr) {
            console.error('PUT /api/me/vendor-assets/:id select:', rowErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        if (!row) return res.status(404).json({ error: '找不到該素材' });

        const updates = { updated_at: new Date().toISOString() };
        if (body.category_key !== undefined) updates.category_key = (String(body.category_key || '').trim()) || row.category_key;
        const assetKindPut = normalizeVendorAssetKind(body.asset_kind !== undefined ? body.asset_kind : row.asset_kind);
        if (body.subcategory_key !== undefined) {
            updates.subcategory_key = (assetKindPut === 'material' || assetKindPut === 'part')
                ? null
                : ((body.subcategory_key || '').trim() || null);
        }
        if (body.title !== undefined) updates.title = (body.title || '').trim() || null;
        if (body.description !== undefined) updates.description = (body.description || '').trim() || null;
        if (body.usage_type !== undefined) updates.usage_type = (body.usage_type || 'reference_only').trim() || 'reference_only';
        if (body.sort_order !== undefined) updates.sort_order = (body.sort_order != null && !isNaN(body.sort_order)) ? parseInt(body.sort_order, 10) : 0;
        if (body.is_public !== undefined) updates.is_public = !!parseTruthyBody(body.is_public);
        if (body.style_key !== undefined) updates.style_key = (body.style_key || '').trim() || null;
        if (body.material_key !== undefined) {
            updates.material_key = assetKindPut === 'material' ? null : ((body.material_key || '').trim() || null);
        }
        if (body.asset_kind !== undefined) updates.asset_kind = normalizeVendorAssetKind(body.asset_kind);
        const assetKindForPart = normalizeVendorAssetKind(updates.asset_kind || row.asset_kind);
        if (body.part_key !== undefined && (assetKindForPart === 'prototype' || assetKindForPart === 'part')) {
            updates.part_key = normalizeVendorPartKey(body.part_key, assetKindForPart);
        }
        const assetKind = normalizeVendorAssetKind(updates.asset_kind || row.asset_kind);
        const catalogGroupIdsPut = parseCatalogGroupIdsFromBody(body);
        let materialCatalogHintPut = '';
        if (assetKind === 'material' && catalogGroupIdsPut.length) {
            materialCatalogHintPut = await vendorCatalogGroupNamesByIds(manufacturerId, catalogGroupIdsPut);
        }
        const productionTypeKeyPut = manufacturerTaxonomy.parseProductionTypeKeyFromBody(body);
        if (productionTypeKeyPut !== undefined) {
            const ptValid = await manufacturerTaxonomy.validateProductionTypeKey(supabase, productionTypeKeyPut);
            if (!ptValid.ok) return res.status(400).json({ error: ptValid.error });
            updates.production_type_key = productionTypeKeyPut;
        }
        if (assetKind === 'prototype') {
            const moqIn = body.min_order_quantity !== undefined ? body.min_order_quantity : row.min_order_quantity;
            const moqParsed = parseVendorAssetPrototypeMoq(moqIn, { required: true });
            if (moqParsed.error) return res.status(400).json({ error: moqParsed.error });
            updates.min_order_quantity = moqParsed.value;
            let levels;
            if (body.customization_levels !== undefined) {
                const clValid = validatePrototypeCustomizationLevels(body.customization_levels);
                if (clValid.error) return res.status(400).json({ error: clValid.error });
                levels = clValid.levels;
            } else {
                levels = sanitizeCustomizationLevelsForStorage(row.customization_levels);
            }
            if (!levels.length) return res.status(400).json({ error: '請至少選擇一項訂製程度' });
            updates.customization_levels = levels;
            const finalSubKey = updates.subcategory_key !== undefined
                ? (updates.subcategory_key || '').trim()
                : ((row.subcategory_key || '').trim());
            if (!finalSubKey) {
                return res.status(400).json({ error: '請選擇子分類（數位原型必填，會影響設計端生圖提示詞）' });
            }
        }
        if (assetKind === 'material' && body.material_surface_type !== undefined) {
            let baseSem = null;
            if (body.image_semantics_json) {
                try {
                    baseSem = typeof body.image_semantics_json === 'string'
                        ? JSON.parse(body.image_semantics_json)
                        : body.image_semantics_json;
                } catch (_) {}
            }
            if (!baseSem) {
                const { data: semRow } = await supabase.from('vendor_assets')
                    .select('image_semantics_json').eq('id', id).maybeSingle();
                baseSem = semRow?.image_semantics_json;
            }
            updates.image_semantics_json = mergeMaterialSurfaceIntoSemantics(baseSem, body.material_surface_type);
        }

        let file = req.file ? await vendorAssetFileFromMulter(req.file) : null;
        const wantsOptimize = parseTruthyBody(body.optimize_product_image);
        const titleForPrompt = updates.title !== undefined ? updates.title : row.title;
        const productNameForPrompt = resolveOptimizeProductNameForPrompt(body, titleForPrompt);
        const categoryKeyForTags = updates.category_key || row.category_key;
        let balanceAfter = null;
        let pointsDeducted = 0;

        if (file) {
            const pointsRequired = wantsOptimize
                ? await getPointsVendorAssetOptimizeForKind(assetKind)
                : await getPointsVendorAssetUpload();

            const authHeader = req.headers.authorization || req.headers['x-auth-token'];
            const token = authHeader && (authHeader.replace(/^\s*Bearer\s+/i, '') || authHeader);
            let ownerId = null;
            if (token) {
                const { data: { user } } = await supabase.auth.getUser(token);
                ownerId = user?.id || null;
            }
            let isAdmin = false;
            if (ownerId) {
                const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
                isAdmin = profile?.role === 'admin';
            }
            if (!isAdmin && ownerId && pointsRequired > 0) {
                const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
                if (!sufficient) {
                    return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
                }
            }

            let tags = parseAiTagsFromBody(body);
            let semanticsJson = null;
            let semanticsFromThisFile = false;
            if (body.image_semantics_json) {
                try {
                    semanticsJson = typeof body.image_semantics_json === 'string'
                        ? JSON.parse(body.image_semantics_json)
                        : body.image_semantics_json;
                } catch (_) {}
            }
            if (!tags || !tags.length) {
                try {
                    const subKeyPut = updates.subcategory_key !== undefined ? updates.subcategory_key : row.subcategory_key;
                    const sem = await runVendorAssetImageSemanticsCoverPlusGallery(file, row, await vendorAssetSemanticsContextFields({
                        asset_kind: assetKind,
                        category_key: categoryKeyForTags,
                        subcategory_key: subKeyPut || '',
                        title: titleForPrompt,
                        description: updates.description !== undefined ? updates.description : row.description,
                        material_catalog_hint: materialCatalogHintPut || undefined
                    }), ownerId);
                    tags = sem.tags;
                    semanticsJson = sem.semantics;
                    semanticsFromThisFile = true;
                } catch (semErr) {
                    console.error('PUT vendor-assets semantics:', semErr);
                    return res.status(503).json({ error: semErr.message || 'AI 標籤產生失敗，請稍後重試' });
                }
            } else if (assetKind === 'material' && semanticsJson) {
                const finPut = finalizeVendorAssetSemantics(semanticsJson, tags, assetKind);
                semanticsJson = finPut.semantics;
                tags = finPut.tags;
            }
            if (!titleForPrompt && semanticsJson && (assetKind === 'material' || assetKind === 'prototype')) {
                const uiLocalePut = resolveUiLocaleFromRequest(req);
                let subcategoryNamePut = null;
                const subKeyPut = updates.subcategory_key !== undefined ? updates.subcategory_key : row.subcategory_key;
                if (assetKind === 'prototype' && subKeyPut) {
                    subcategoryNamePut = await lookupAiSubcategoryName(categoryKeyForTags, subKeyPut);
                }
                let materialHintPut = '';
                if (assetKind === 'material' && catalogGroupIdsPut.length) {
                    materialHintPut = await vendorCatalogGroupNamesByIds(manufacturerId, catalogGroupIdsPut);
                }
                const autoTitle = autoVendorAssetTitleFromSemantics(semanticsJson, assetKind, uiLocalePut, {
                    subcategoryName: subcategoryNamePut,
                    materialCatalogHint: materialHintPut
                });
                if (autoTitle) {
                    titleForPrompt = autoTitle;
                    updates.title = autoTitle;
                }
            }
            updates.ai_tags = tags;
            updates.ai_tags_generated_at = new Date().toISOString();
            updates.tags_source = semanticsJson ? 'gemini' : (parseAiTagsFromBody(body) ? 'manual' : 'gemini');
            if (semanticsJson) updates.image_semantics_json = semanticsJson;
            const bodyDesc = (body.description || '').trim();
            if (!bodyDesc && semanticsJson) {
                const autoDesc = vendorAssetDescriptionFromSemantics(semanticsJson);
                if (autoDesc) updates.description = autoDesc;
            }

            let uploadFile = file;
            if (wantsOptimize) {
                try {
                    const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
                    const useDisplayStandPut = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
                    const materialSurfacePut = assetKind === 'material' ? resolveMaterialSurfaceType(body, row) : '';
                    const optimizedBuf = await optimizeVendorAssetImage(
                        file.buffer, file.mimetype, productNameForPrompt, assetKind,
                        assetKind === 'material' ? materialCatalogHintPut : ((updates.material_key != null ? updates.material_key : row.material_key) || ''),
                        optimizeBackground,
                        fluxSeedFromImageBuffer(file.buffer),
                        labelFromOriginalFilename(file.originalname),
                        undefined,
                        materialSurfacePut,
                        ownerId,
                        useDisplayStandPut
                    );
                    uploadFile = {
                        buffer: optimizedBuf,
                        mimetype: 'image/jpeg',
                        originalname: (file.originalname || 'image.jpg').replace(/\.[^.]+$/, '') + '.jpg'
                    };
                } catch (optErr) {
                    console.error('PUT vendor-assets image optimize:', optErr);
                    const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
                    return res.status(mapped.status).json(mapped.body);
                }
            }

            const { publicUrl } = await uploadToSupabaseStorage('custom-products', `vendor-assets/${manufacturerId}`, uploadFile);
            updates.image_url = publicUrl;

            if (!isAdmin && ownerId && pointsRequired > 0) {
                const consumed = await consumeUserCredits(
                    ownerId,
                    pointsRequired,
                    wantsOptimize ? 'vendor_asset_optimize' : 'vendor_asset_upload',
                    wantsOptimize
                        ? (assetKind === 'material'
                            ? `材料參考更新圖＋材質圖優化（${pointsRequired} 點）`
                            : `數位原型更新圖＋產品圖優化（${pointsRequired} 點）`)
                        : (assetKind === 'material'
                            ? `材料參考更新圖（${pointsRequired} 點）`
                            : `數位原型更新圖（${pointsRequired} 點）`),
                    { manufacturer_id: manufacturerId, vendor_asset_id: id, optimize: wantsOptimize, asset_kind: assetKind }
                );
                if (consumed.ok) {
                    balanceAfter = consumed.balance_after;
                    pointsDeducted = pointsRequired;
                }
            }
        } else if (body.ai_tags !== undefined) {
            const tags = parseAiTagsFromBody(body);
            updates.ai_tags = tags || [];
            updates.tags_source = 'manual';
            if (body.image_semantics_json) {
                try {
                    updates.image_semantics_json = typeof body.image_semantics_json === 'string'
                        ? JSON.parse(body.image_semantics_json)
                        : body.image_semantics_json;
                } catch (_) {}
            }
        }

        const putSelectCols = 'id, manufacturer_id, category_key, subcategory_key, title, description, image_url, gallery_images, usage_type, sort_order, style_key, material_key, asset_kind, ai_tags, min_order_quantity, customization_levels, production_type_key, updated_at';
        let { data: updated, error } = await supabase.from('vendor_assets').update(updates).eq('id', id).eq('manufacturer_id', manufacturerId).select(putSelectCols).single();
        if (error && error.code === '42703' && (
            String(error.message || '').includes('min_order_quantity') ||
            String(error.message || '').includes('customization_levels')
        )) {
            return res.status(500).json({ error: '請先執行 docs/add-vendor-asset-prototype-moq-customization.sql' });
        }
        if (error && error.code === '42703' && String(error.message || '').includes('production_type_key')) {
            delete updates.production_type_key;
            ({ data: updated, error } = await supabase.from('vendor_assets').update(updates).eq('id', id).eq('manufacturer_id', manufacturerId).select(putSelectCols.replace(', production_type_key', '')).single());
        }
        if (error) {
            console.error('PUT /api/me/vendor-assets/:id 失敗:', error);
            return res.status(500).json({ error: '更新失敗' });
        }
        // 分類／taxonomy／原型連結須寫完再回傳：前端用 catalog_group_ids 重繪勾選；
        // 若 setImmediate 延後寫，回傳無分類欄位 → 畫面像「勾選沒存住」（官方與廠商同路徑）。
        try {
            const taxonomyPutErr = await manufacturerTaxonomy.applyVendorAssetTaxonomyWrites(supabase, id, body);
            if (taxonomyPutErr) console.warn('PUT taxonomy error:', taxonomyPutErr);

            if (body.catalog_group_ids !== undefined || body.catalog_group_id) {
                await setVendorAssetCatalogGroups(id, manufacturerId, parseCatalogGroupIdsFromBody(body));
            }

            const finalKind = normalizeVendorAssetKind(updated.asset_kind || assetKind);
            if (finalKind === 'prototype' && (body.linked_links !== undefined || body.linked_asset_ids !== undefined)) {
                let linkEntries = parseLinkedLinksFromBody(body);
                if (linkEntries === undefined) {
                    const linkedIds = parseJsonUuidArrayFromBody(body.linked_asset_ids);
                    if (linkedIds !== null) {
                        linkEntries = normalizePrototypeLinkEntries(linkedIds);
                    }
                }
                if (linkEntries && linkEntries.length >= 0) {
                    const linkErr = await replacePrototypeMaterialPartLinks(manufacturerId, id, linkEntries);
                    if (linkErr) console.warn('PUT prototype links error:', linkErr);
                }
            }

            if (body.linked_prototype_ids !== undefined && (finalKind === 'material' || finalKind === 'part')) {
                const protoIds = parseJsonUuidArrayFromBody(body.linked_prototype_ids);
                if (protoIds !== null) {
                    const linkErr = await replaceLinkedAssetPrototypeLinks(manufacturerId, id, protoIds);
                    if (linkErr) console.warn('PUT linked prototypes error:', linkErr);
                }
            }
        } catch (e) {
            console.warn('PUT related writes error:', e && e.message ? e.message : e);
            return res.status(500).json({ error: (e && e.message) || '關聯資料儲存失敗' });
        }
        let putMapped;
        try {
            putMapped = await mapVendorAssetForApiEnriched(updated);
        } catch (e) {
            console.warn('PUT enrich error:', e && e.message ? e.message : e);
            putMapped = mapVendorAssetForApi(updated);
        }
        res.json({
            ...putMapped,
            points_deducted: pointsDeducted,
            balance_after: balanceAfter,
            product_optimized: file ? wantsOptimize : false
        });
    } catch (e) {
        console.error('PUT /api/me/vendor-assets/:id 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// DELETE /api/me/vendor-assets/:id — 刪除廠商素材（僅本人廠商）；種子廠商不得刪除
app.delete('/api/me/vendor-assets/:id', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (await rejectSeedVendorSelfServiceWrite(seedUser.id, manufacturerId, res)) return;
        const id = (req.params.id || '').trim();
        const { data: row, error: rowErr } = await fetchVendorAssetOwnedByManufacturer(id, manufacturerId, 'id, source_catalog_item_id');
        if (rowErr) {
            console.error('DELETE /api/me/vendor-assets/:id select:', rowErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        if (!row) return res.status(404).json({ error: '找不到該素材' });
        if (row.source_catalog_item_id && (await supplierCatalogTablesReady())) {
            await supabase.from('manufacturer_supplier_imports').delete()
                .eq('manufacturer_id', manufacturerId)
                .eq('catalog_item_id', row.source_catalog_item_id);
        }
        const { error } = await supabase.from('vendor_assets').delete().eq('id', id);
        if (error) {
            console.error('DELETE /api/me/vendor-assets/:id 失敗:', error);
            return res.status(500).json({ error: '刪除失敗' });
        }
        res.status(204).send();
    } catch (e) {
        console.error('DELETE /api/me/vendor-assets/:id 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// ---------- 產業供應商目錄（B 線：製造商導入材料）----------
// GET /api/me/capabilities — 頁面/API 資格（勿用 nav.* 隱藏選單；見 docs/account-one-login-capabilities.md）
app.get('/api/me/capabilities', async (req, res) => {
    try {
        const authHeader = req.headers.authorization || req.headers['x-auth-token'];
        const token = authHeader && (authHeader.replace(/^\s*Bearer\s+/i, '') || authHeader);
        if (!token) return res.status(401).json({ error: '請先登入' });
        const { data: { user }, error: authError } = await supabase.auth.getUser(token);
        if (authError || !user) return res.status(401).json({ error: '登入已過期或無效' });
        if (isOfficialPlatformLibraryRequest(req)) {
            const { data: profile } = await supabase.from('profiles').select('role').eq('id', user.id).maybeSingle();
            if (profile?.role !== 'admin') {
                return res.status(403).json({ error: '僅管理員可編輯官方版型庫', code: 'OFFICIAL_PLATFORM_ADMIN_REQUIRED' });
            }
            const officialId = await getOrEnsureOfficialPlatformManufacturerId();
            if (!officialId) return res.status(503).json({ error: '無法讀取官方版型庫（MATCHDO 官方版型）' });
            const catalogReady = await supplierCatalogTablesReady();
            return res.json({
                has_manufacturer: true,
                is_industry_supplier: false,
                industry_supplier_id: null,
                is_qualified_manufacturer: true,
                manufacturer_id: officialId,
                manufacturer_is_active: true,
                portfolio_total_count: 0,
                vendor_assets_count: 0,
                active_portfolio_count: 0,
                portfolio_count: 0,
                qualifies_for_supplier_import: false,
                bypass_supplier_portfolio_gate: true,
                vendor_source: 'platform',
                is_seed_vendor: false,
                seed_vendor_self_service_locked: false,
                can_edit_vendor_content: true,
                supplier_catalog_ready: catalogReady,
                can_upload_products_and_assets: true,
                can_control_design_show_on_homepage: true,
                can_browse_supplier_catalog: false,
                can_use_supplier_catalog: false,
                can_import_supplier_catalog: false,
                can_manage_supplier_catalog: false,
                official_platform_library: true,
                zones: { design: true, manufacturer: true, industry_supplier: false },
                nav: { show_all_workspace_menus: true }
            });
        }
        syncMembershipCatalogVisibility(user.id).catch((syncErr) => {
            console.warn('syncMembershipCatalogVisibility:', syncErr && syncErr.message);
        });

        const [mfrRes, staffBypassPortfolio, catalogReady] = await Promise.all([
            supabase.from('manufacturers').select('id, vendor_source, is_active, seed_vendor_self_service_enabled').eq('user_id', user.id).maybeSingle(),
            isStaffProfileUserId(user.id),
            supplierCatalogTablesReady()
        ]);
        let mfr = mfrRes.data;
        if (mfrRes.error && isMissingManufacturerColumnError(mfrRes.error, 'seed_vendor_self_service_enabled')) {
            const fb = await supabase.from('manufacturers').select('id, vendor_source, is_active').eq('user_id', user.id).maybeSingle();
            mfr = fb.data;
        } else if (mfrRes.error) {
            console.error('GET /api/me/capabilities mfr:', mfrRes.error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        const hasManufacturer = !!mfr;
        let portfolioTotalCount = 0;
        let vendorAssetsCount = 0;
        let activePortfolioCount = 0;
        if (mfr && mfr.id) {
            portfolioTotalCount = await countManufacturerPortfolioRows(mfr.id);
            vendorAssetsCount = await countManufacturerVendorAssets(mfr.id);
        }
        if (mfr && mfr.is_active !== false) {
            activePortfolioCount = portfolioTotalCount;
        }
        const isSeed = mfr && mfr.vendor_source === 'seed';
        const seedSelfServiceLocked = isSeed && !manufacturerSeedSelfServiceEnabled(mfr);
        const canEditVendorContent = !seedSelfServiceLocked;
        const isQualifiedManufacturer = !!mfr && mfr.is_active !== false;
        const canBrowseCatalog = catalogReady && isQualifiedManufacturer;
        const canImport = catalogReady && isQualifiedManufacturer;
        const qualifiesForSupplierImport = isQualifiedManufacturer;
        const canUploadProductsAndAssets = await canUploadProductsAndAssetsUserId(user.id);
        const canControlDesignShowOnHomepageFlag = await canControlDesignShowOnHomepage(user.id);
        let isIndustrySupplier = false;
        let industrySupplierId = null;
        if (catalogReady) {
            try {
                const { data: indRow } = await supabase
                    .from('industry_suppliers')
                    .select('id')
                    .eq('user_id', user.id)
                    .maybeSingle();
                isIndustrySupplier = !!indRow;
                industrySupplierId = indRow ? indRow.id : null;
            } catch (_) { /* 表未建時忽略 */ }
        }
        res.json({
            has_manufacturer: hasManufacturer,
            is_industry_supplier: isIndustrySupplier,
            industry_supplier_id: industrySupplierId,
            is_qualified_manufacturer: isQualifiedManufacturer,
            manufacturer_id: mfr ? mfr.id : null,
            manufacturer_is_active: mfr ? mfr.is_active !== false : null,
            portfolio_total_count: portfolioTotalCount,
            vendor_assets_count: vendorAssetsCount,
            active_portfolio_count: activePortfolioCount,
            portfolio_count: activePortfolioCount,
            qualifies_for_supplier_import: qualifiesForSupplierImport,
            bypass_supplier_portfolio_gate: staffBypassPortfolio,
            vendor_source: mfr ? mfr.vendor_source : null,
            is_seed_vendor: !!isSeed,
            seed_vendor_self_service_locked: !!seedSelfServiceLocked,
            can_edit_vendor_content: canEditVendorContent,
            supplier_catalog_ready: catalogReady,
            can_upload_products_and_assets: canUploadProductsAndAssets,
            can_control_design_show_on_homepage: canControlDesignShowOnHomepageFlag,
            can_browse_supplier_catalog: canBrowseCatalog,
            can_use_supplier_catalog: canImport,
            can_import_supplier_catalog: canImport,
            can_manage_supplier_catalog: catalogReady && isIndustrySupplier,
            zones: {
                design: true,
                manufacturer: isQualifiedManufacturer || (hasManufacturer && staffBypassPortfolio),
                industry_supplier: isIndustrySupplier
            },
            nav: {
                show_all_workspace_menus: true
            }
        });
    } catch (e) {
        console.error('GET /api/me/capabilities:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/me/industry-suppliers — 產業供應商目錄（製造商瀏覽，需作品門檻）
app.get('/api/me/industry-suppliers', async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.json({ items: [], message: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const manufacturerId = await getMeManufacturerB2BAccess(req, res, { requirePortfolio: false });
        if (!manufacturerId) return;
        const { data: suppliers, error: supErr } = await supabase
            .from('industry_suppliers')
            .select('id, name, description, contact_json, is_active')
            .eq('is_active', true)
            .order('name', { ascending: true });
        if (supErr) {
            if (supErr.code === '42P01') return res.json({ items: [] });
            console.error('GET industry-suppliers:', supErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        const ids = (suppliers || []).map((s) => s.id);
        const countsBySupplier = {};
        const previewBySupplier = {};
        if (ids.length) {
            const { data: catRows } = await supabase
                .from('supplier_catalog_items')
                .select('industry_supplier_id, cover_image_url, sort_order')
                .in('industry_supplier_id', ids)
                .eq('is_active', true)
                .order('sort_order', { ascending: true })
                .limit(500);
            (catRows || []).forEach((row) => {
                countsBySupplier[row.industry_supplier_id] = (countsBySupplier[row.industry_supplier_id] || 0) + 1;
                if (!previewBySupplier[row.industry_supplier_id] && row.cover_image_url) {
                    previewBySupplier[row.industry_supplier_id] = row.cover_image_url;
                }
            });
        }
        const items = (suppliers || []).map((s) => ({
            id: s.id,
            name: s.name,
            description: s.description,
            contact_json: s.contact_json,
            catalog_item_count: countsBySupplier[s.id] || 0,
            preview_image_url: previewBySupplier[s.id] || null
        }));
        res.json({ items });
    } catch (e) {
        console.error('GET /api/me/industry-suppliers:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// GET /api/me/supplier-catalog-items — 可導入的產業供應商目錄（材料）
app.get('/api/me/supplier-catalog-items', async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.json({ items: [], message: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const manufacturerId = await getMeManufacturerB2BAccess(req, res, { requirePortfolio: false });
        if (!manufacturerId) return;
        const itemKind = (req.query.item_kind || 'material').trim();
        if (itemKind !== 'material' && itemKind !== 'prototype_set' && itemKind !== 'part') {
            return res.status(400).json({ error: 'item_kind 須為 material、prototype_set 或 part' });
        }
        const supplierId = (req.query.supplier_id || '').trim();
        let catQ = supabase
            .from('supplier_catalog_items')
            .select('id, industry_supplier_id, item_kind, title, description, cover_image_url, spec_json, category_key, sort_order, industry_suppliers(id, name, description, contact_json)')
            .eq('item_kind', itemKind)
            .eq('is_active', true)
            .order('sort_order', { ascending: true })
            .order('created_at', { ascending: false });
        if (supplierId) catQ = catQ.eq('industry_supplier_id', supplierId);
        const catalogPromise = catQ;
        const importsPromise = supabase
            .from('manufacturer_supplier_imports')
            .select('catalog_item_id, vendor_asset_id')
            .eq('manufacturer_id', manufacturerId)
            .eq('item_kind', itemKind);
        const supplierMetaPromise = supplierId
            ? supabase.from('industry_suppliers').select('id, name, description').eq('id', supplierId).eq('is_active', true).maybeSingle()
            : Promise.resolve({ data: null, error: null });
        const [catRes, impRes, supMetaRes] = await Promise.all([catalogPromise, importsPromise, supplierMetaPromise]);
        const { data: catalogRows, error: catErr } = catRes;
        if (catErr) {
            if (catErr.code === '42P01') return res.json({ items: [] });
            console.error('GET supplier-catalog-items:', catErr);
            return res.status(500).json({ error: '查詢失敗' });
        }
        const { data: imported } = impRes;
        const importedByCatalog = {};
        (imported || []).forEach((r) => {
            importedByCatalog[r.catalog_item_id] = r.vendor_asset_id || null;
        });
        const items = (catalogRows || []).map((row) => {
            const sup = row.industry_suppliers;
            const supplier = Array.isArray(sup) ? sup[0] : sup;
            const vendorAssetId = importedByCatalog[row.id] || null;
            return {
                id: row.id,
                item_kind: row.item_kind,
                title: row.title,
                description: row.description,
                cover_image_url: row.cover_image_url,
                spec_json: row.spec_json,
                category_key: row.category_key,
                supplier_id: row.industry_supplier_id,
                supplier_name: supplier ? supplier.name : null,
                supplier_contact: supplier ? supplier.contact_json : null,
                already_imported: !!vendorAssetId,
                vendor_asset_id: vendorAssetId
            };
        });
        const supplierHeader = supMetaRes.data
            ? { id: supMetaRes.data.id, name: supMetaRes.data.name, description: supMetaRes.data.description }
            : null;
        res.json({ items, supplier: supplierHeader });
    } catch (e) {
        console.error('GET /api/me/supplier-catalog-items 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/supplier-catalog-imports — 導入供應商材料至「材料參考」(vendor_assets)
app.post('/api/me/supplier-catalog-imports', express.json(), async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.status(503).json({ error: '請先執行 docs/add-industry-supplier-catalog.sql 建立產業供應商目錄' });
        }
        const manufacturerId = await getMeManufacturerB2BAccess(req, res);
        if (!manufacturerId) return;
        const catalogItemId = (req.body && req.body.catalog_item_id || '').trim();
        if (!catalogItemId) return res.status(400).json({ error: '請提供 catalog_item_id' });

        const { data: existingImp } = await supabase
            .from('manufacturer_supplier_imports')
            .select('id, vendor_asset_id')
            .eq('manufacturer_id', manufacturerId)
            .eq('catalog_item_id', catalogItemId)
            .maybeSingle();
        if (existingImp) {
            return res.status(409).json({
                error: '此品項已匯入',
                code: 'ALREADY_IMPORTED',
                import_id: existingImp.id,
                vendor_asset_id: existingImp.vendor_asset_id
            });
        }

        let catalogItem = null;
        let itemErr = null;
        const catalogSelectFull = 'id, item_kind, title, description, cover_image_url, cover_image_label, gallery_images, spec_json, category_key, ai_tags, image_semantics_json, tags_source, industry_supplier_id, industry_suppliers(id, name, contact_json)';
        ({ data: catalogItem, error: itemErr } = await supabase
            .from('supplier_catalog_items')
            .select(catalogSelectFull)
            .eq('id', catalogItemId)
            .eq('is_active', true)
            .single());
        if (itemErr && isSupabaseMissingColumnError(itemErr)) {
            ({ data: catalogItem, error: itemErr } = await supabase
                .from('supplier_catalog_items')
                .select(SUPPLIER_CATALOG_ITEM_LEGACY_SELECT + ', ai_tags, image_semantics_json, tags_source, industry_supplier_id, industry_suppliers(id, name, contact_json)')
                .eq('id', catalogItemId)
                .eq('is_active', true)
                .single());
        }
        if (itemErr || !catalogItem) return res.status(404).json({ error: '找不到該目錄品項' });
        if (catalogItem.item_kind !== 'material' && catalogItem.item_kind !== 'prototype_set' && catalogItem.item_kind !== 'part') {
            return res.status(400).json({ error: '不支援的品項類型' });
        }
        if (!catalogItem.cover_image_url) {
            return res.status(400).json({ error: '此品項尚無參考圖，無法導入' });
        }

        const sup = catalogItem.industry_suppliers;
        const supplier = Array.isArray(sup) ? sup[0] : sup;
        const { fields: catalogFields, targetKind } = buildVendorAssetFieldsFromSupplierCatalog(catalogItem, { copyText: true });

        const insertPayload = {
            manufacturer_id: manufacturerId,
            usage_type: 'reference_only',
            is_public: true,
            sort_order: 0,
            source_catalog_item_id: catalogItem.id,
            tags_source: 'import',
            ...catalogFields
        };
        const spec = catalogItem.spec_json && typeof catalogItem.spec_json === 'object' ? catalogItem.spec_json : {};

        let inserted;
        let insErr;
        ({ data: inserted, error: insErr } = await supabase
            .from('vendor_assets')
            .insert(insertPayload)
            .select('id, manufacturer_id, category_key, title, description, image_url, asset_kind, source_catalog_item_id, material_key, created_at')
            .single());
        if (insErr && insErr.code === '42703') {
            const fallback = { ...insertPayload };
            delete fallback.asset_kind;
            delete fallback.source_catalog_item_id;
            ({ data: inserted, error: insErr } = await supabase
                .from('vendor_assets')
                .insert(fallback)
                .select('id, manufacturer_id, category_key, title, description, image_url, material_key, created_at')
                .single());
        }
        if (insErr || !inserted) {
            console.error('import vendor_asset:', insErr);
            return res.status(500).json({ error: insErr && insErr.message ? insErr.message : '建立材料參考失敗' });
        }

        const snapshot = {
            supplier_id: catalogItem.industry_supplier_id,
            supplier_name: supplier ? supplier.name : null,
            supplier_contact: supplier ? supplier.contact_json : null,
            catalog_item_id: catalogItem.id,
            title: catalogItem.title,
            description: catalogItem.description,
            cover_image_url: catalogItem.cover_image_url,
            spec_json: spec
        };
        const { data: impRow, error: impErr } = await supabase
            .from('manufacturer_supplier_imports')
            .insert({
                manufacturer_id: manufacturerId,
                catalog_item_id: catalogItem.id,
                item_kind: catalogItem.item_kind,
                vendor_asset_id: inserted.id,
                snapshot_json: snapshot
            })
            .select('id, imported_at')
            .single();
        if (impErr) {
            await supabase.from('vendor_assets').delete().eq('id', inserted.id);
            console.error('import record:', impErr);
            return res.status(500).json({ error: '寫入導入紀錄失敗' });
        }

        res.status(201).json({
            import: impRow,
            vendor_asset: { ...inserted, asset_kind: targetKind, supplier_name: snapshot.supplier_name, from_supplier_catalog: true }
        });
    } catch (e) {
        console.error('POST /api/me/supplier-catalog-imports 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

function normalizeSupplierImportItemKind(raw) {
    const k = String(raw || '').trim().toLowerCase();
    if (k === 'prototype_set' || k === 'prototype') return 'prototype_set';
    if (k === 'part') return 'part';
    return 'material';
}

/** 製造商已匯入的供應商品項（import 表為主；缺紀錄時從 vendor_assets.source_catalog_item_id 補齊） */
async function listSupplierCatalogImportsForManufacturer(manufacturerId) {
    const byCatalogId = new Map();
    const ready = await supplierCatalogTablesReady();
    if (ready) {
        const { data: rows, error } = await supabase
            .from('manufacturer_supplier_imports')
            .select('id, catalog_item_id, item_kind, vendor_asset_id, imported_at, snapshot_json')
            .eq('manufacturer_id', manufacturerId)
            .order('imported_at', { ascending: false });
        if (error && error.code !== '42P01') console.error('listSupplierCatalogImports imports:', error);
        (rows || []).forEach((row) => {
            if (!row.catalog_item_id) return;
            const snap = row.snapshot_json && typeof row.snapshot_json === 'object' ? row.snapshot_json : {};
            byCatalogId.set(row.catalog_item_id, {
                id: row.id,
                catalog_item_id: row.catalog_item_id,
                item_kind: normalizeSupplierImportItemKind(row.item_kind),
                vendor_asset_id: row.vendor_asset_id,
                imported_at: row.imported_at,
                supplier_name: snap.supplier_name || null,
                catalog_title: snap.title || null,
                cover_image_url: snap.cover_image_url || null
            });
        });
    }
    let assets = [];
    let assetRes = await supabase
        .from('vendor_assets')
        .select('id, source_catalog_item_id, asset_kind, title, image_url, created_at')
        .eq('manufacturer_id', manufacturerId)
        .not('source_catalog_item_id', 'is', null)
        .order('created_at', { ascending: false });
    if (assetRes.error && assetRes.error.code === '42703') {
        assetRes = await supabase
            .from('vendor_assets')
            .select('id, asset_kind, title, image_url, created_at')
            .eq('manufacturer_id', manufacturerId)
            .order('created_at', { ascending: false });
    }
    assets = assetRes.data || [];
    const orphanCatalogIds = [];
    assets.forEach((a) => {
        const cid = a.source_catalog_item_id;
        if (!cid || byCatalogId.has(cid)) return;
        orphanCatalogIds.push(cid);
        byCatalogId.set(cid, {
            id: 'asset-' + a.id,
            catalog_item_id: cid,
            item_kind: normalizeSupplierImportItemKind(
                a.asset_kind === 'prototype' ? 'prototype_set' : a.asset_kind
            ),
            vendor_asset_id: a.id,
            imported_at: a.created_at,
            supplier_name: null,
            catalog_title: a.title || null,
            cover_image_url: a.image_url || null
        });
    });
    if (orphanCatalogIds.length && ready) {
        const { data: cats } = await supabase
            .from('supplier_catalog_items')
            .select('id, title, cover_image_url, item_kind, industry_suppliers(name)')
            .in('id', orphanCatalogIds);
        (cats || []).forEach((c) => {
            const row = byCatalogId.get(c.id);
            if (!row) return;
            const sup = c.industry_suppliers;
            const supplier = Array.isArray(sup) ? sup[0] : sup;
            if (!row.catalog_title) row.catalog_title = c.title;
            if (!row.cover_image_url) row.cover_image_url = c.cover_image_url;
            row.item_kind = normalizeSupplierImportItemKind(c.item_kind || row.item_kind);
            if (!row.supplier_name && supplier) row.supplier_name = supplier.name;
        });
    }
    return Array.from(byCatalogId.values()).sort((a, b) => {
        const ta = a.imported_at ? new Date(a.imported_at).getTime() : 0;
        const tb = b.imported_at ? new Date(b.imported_at).getTime() : 0;
        return tb - ta;
    });
}

// GET /api/me/supplier-catalog-imports — 製造商：我引用的供應商數位產品庫清單
app.get('/api/me/supplier-catalog-imports', async (req, res) => {
    try {
        const manufacturerId = await getMeManufacturerId(req, res);
        if (!manufacturerId) return;
        const itemKind = (req.query.item_kind || '').trim();
        const allItems = await listSupplierCatalogImportsForManufacturer(manufacturerId);
        const counts = { all: allItems.length, material: 0, prototype_set: 0, part: 0 };
        allItems.forEach((row) => {
            if (row.item_kind === 'material') counts.material += 1;
            else if (row.item_kind === 'prototype_set') counts.prototype_set += 1;
            else if (row.item_kind === 'part') counts.part += 1;
        });
        let items = allItems;
        if (itemKind === 'material' || itemKind === 'prototype_set' || itemKind === 'part') {
            const want = normalizeSupplierImportItemKind(itemKind);
            items = allItems.filter((row) => row.item_kind === want);
        }
        res.json({ items, counts });
    } catch (e) {
        console.error('GET /api/me/supplier-catalog-imports:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

function normalizeSupplierCatalogItemKind(raw) {
    const k = String(raw || 'material').trim().toLowerCase();
    if (k === 'prototype_set' || k === 'prototype') return 'prototype_set';
    if (k === 'part') return 'part';
    return 'material';
}

function parseSupplierCatalogSpecJson(itemKind, body) {
    let specJson = body && body.spec_json;
    if (specJson && typeof specJson === 'string') {
        try { specJson = JSON.parse(specJson); } catch (_) { specJson = {}; }
    }
    if (!specJson || typeof specJson !== 'object') specJson = {};
    const pickStr = (key) => {
        if (!body || body[key] == null) return;
        const v = String(body[key]).trim();
        if (v) specJson[key] = v;
    };
    if (itemKind === 'material') {
        pickStr('material_type');
        pickStr('composition');
        pickStr('finish');
        if (body && body.width_cm != null && String(body.width_cm).trim() !== '') {
            const w = parseInt(body.width_cm, 10);
            specJson.width_cm = Number.isFinite(w) ? w : String(body.width_cm).trim();
        }
    } else if (itemKind === 'prototype_set') {
        pickStr('style');
        pickStr('fit');
        pickStr('moq_hint');
        pickStr('customization_notes');
        if (body && body.subcategory_key) specJson.subcategory_key = String(body.subcategory_key).trim();
    } else if (itemKind === 'part') {
        pickStr('part_type');
        pickStr('finish');
        pickStr('material');
        pickStr('dimensions');
    }
    return specJson;
}

function mapSupplierCatalogItemForApi(row) {
    if (!row) return row;
    const spec = row.spec_json && typeof row.spec_json === 'object' ? row.spec_json : {};
    const out = { ...row, subcategory_key: spec.subcategory_key || null };
    let gallery = parseGalleryImages(row.gallery_images);
    if (!gallery.length && spec.gallery_images) gallery = parseGalleryImages(spec.gallery_images);
    out.gallery_images = gallery;
    const cover = (row.cover_image_url || '').trim();
    const imageUrls = cover ? [cover] : [];
    gallery.forEach(function (g) {
        if (g.url && imageUrls.indexOf(g.url) < 0) imageUrls.push(g.url);
    });
    out.image_urls = imageUrls;
    out.image_count = imageUrls.length;
    return out;
}

function buildSupplierCatalogImageItems(row) {
    if (!row) return [];
    const items = [];
    const cover = String(row.cover_image_url || '').trim();
    if (cover) {
        items.push({
            url: cover,
            sort_order: 0,
            label: String(row.cover_image_label || '').trim() || labelFromImageUrl(cover),
            is_cover: true
        });
    }
    let gallery = parseGalleryImages(row.gallery_images);
    if (!gallery.length && row.spec_json && row.spec_json.gallery_images) {
        gallery = parseGalleryImages(row.spec_json.gallery_images);
    }
    gallery.forEach((g) => {
        const u = String(g.url || '').trim();
        if (!u || u === cover) return;
        items.push({
            url: u,
            sort_order: g.sort_order != null ? g.sort_order : items.length,
            label: String(g.label || '').trim() || labelFromImageUrl(u),
            is_cover: false,
            ai_derived: g.ai_derived || ''
        });
    });
    return items;
}

function getSupplierCatalogAllImageUrls(row) {
    return buildSupplierCatalogImageItems(row).map((it) => it.url);
}

function reorderSupplierCatalogGalleryFromUrls(row, orderedUrls) {
    if (!row || !Array.isArray(orderedUrls) || !orderedUrls.length) return null;
    const items = buildSupplierCatalogImageItems(row);
    const urls = items.map(function (it) { return it.url; });
    if (!urls.length || orderedUrls.length !== urls.length) return null;
    const urlSet = new Set(urls);
    const reordered = orderedUrls.map(function (u) { return String(u || '').trim(); }).filter(Boolean);
    if (reordered.length !== urls.length) return null;
    for (let i = 0; i < reordered.length; i++) {
        if (!urlSet.has(reordered[i])) return null;
    }
    if (new Set(reordered).size !== reordered.length) return null;
    const metaByUrl = {};
    items.forEach(function (it) {
        metaByUrl[it.url] = {
            label: it.label || '',
            ai_derived: normalizeVendorAiDerivedKind(it.ai_derived),
            source_url: it.source_url ? String(it.source_url).trim() : ''
        };
    });
    return {
        cover_image_url: reordered[0],
        cover_image_label: (metaByUrl[reordered[0]] && metaByUrl[reordered[0]].label) || '',
        gallery_images: reordered.slice(1).map(function (u, i) {
            const meta = metaByUrl[u] || {};
            const g = { url: u, sort_order: i + 1, label: meta.label || '' };
            if (meta.ai_derived) g.ai_derived = meta.ai_derived;
            if (meta.source_url) g.source_url = meta.source_url;
            return g;
        })
    };
}

function reorderSupplierCatalogCoverFromUrl(row, targetUrl) {
    const url = String(targetUrl || '').trim();
    if (!url || !row) return null;
    const items = buildSupplierCatalogImageItems(row);
    const urls = items.map(function (it) { return it.url; });
    if (!urls.length || urls.indexOf(url) < 0) return null;
    const reordered = urls[0] === url ? urls.slice() : [url].concat(urls.filter(function (u) { return u !== url; }));
    return reorderSupplierCatalogGalleryFromUrls(row, reordered);
}

const SUPPLIER_CATALOG_SYNC_SELECT =
    'id, item_kind, title, description, cover_image_url, cover_image_label, gallery_images, spec_json, category_key, ai_tags, image_semantics_json, tags_source, industry_supplier_id, industry_suppliers(id, name, contact_json)';

function buildSupplierCatalogImportSnapshot(catalogItem, supplier) {
    const spec = catalogItem.spec_json && typeof catalogItem.spec_json === 'object' ? catalogItem.spec_json : {};
    return {
        supplier_id: catalogItem.industry_supplier_id,
        supplier_name: supplier ? supplier.name : null,
        supplier_contact: supplier ? supplier.contact_json : null,
        catalog_item_id: catalogItem.id,
        title: catalogItem.title,
        description: catalogItem.description,
        cover_image_url: catalogItem.cover_image_url,
        spec_json: spec
    };
}

function mergeSupplierCatalogSpecIntoSemantics(semanticsJson, itemKind, spec) {
    const base = (semanticsJson && typeof semanticsJson === 'object') ? { ...semanticsJson } : {};
    const s = spec && typeof spec === 'object' ? spec : {};
    const kind = normalizeSupplierCatalogItemKind(itemKind);
    const sub = {};
    if (kind === 'material') {
        if (s.material_type) sub.material_type = String(s.material_type).trim();
        if (s.composition) sub.composition = String(s.composition).trim();
        if (s.finish) sub.finish = String(s.finish).trim();
        if (s.width_cm != null && String(s.width_cm).trim() !== '') sub.width_cm = s.width_cm;
    } else if (kind === 'part') {
        ['part_type', 'finish', 'material', 'dimensions'].forEach(function (k) {
            if (s[k]) sub[k] = String(s[k]).trim();
        });
    } else if (kind === 'prototype_set') {
        ['style', 'fit', 'moq_hint', 'customization_notes'].forEach(function (k) {
            if (s[k]) sub[k] = String(s[k]).trim();
        });
        if (s.subcategory_key) sub.subcategory_key = String(s.subcategory_key).trim();
    }
    if (Object.keys(sub).length) base.supplier_catalog_spec = sub;
    else delete base.supplier_catalog_spec;
    return Object.keys(base).length ? base : null;
}

/** 供應商目錄 → 製造商 vendor_assets 欄位（匯入與同步共用） */
function buildVendorAssetFieldsFromSupplierCatalog(catalogItem, opts) {
    opts = opts || {};
    const copyText = opts.copyText !== false;
    const spec = catalogItem.spec_json && typeof catalogItem.spec_json === 'object' ? catalogItem.spec_json : {};
    const targetKind = catalogItem.item_kind === 'prototype_set'
        ? 'prototype'
        : (catalogItem.item_kind === 'part' ? 'part' : 'material');
    const fields = {
        category_key: (catalogItem.category_key || '').trim() || 'other',
        asset_kind: targetKind,
        updated_at: new Date().toISOString()
    };
    if (copyText) {
        fields.title = String(catalogItem.title || '').trim();
        fields.description = catalogItem.description || null;
    }
    if (catalogItem.cover_image_url) fields.image_url = catalogItem.cover_image_url;
    if (Array.isArray(catalogItem.ai_tags)) {
        fields.ai_tags = catalogItem.ai_tags;
        fields.ai_tags_generated_at = new Date().toISOString();
    }
    const mergedSem = mergeSupplierCatalogSpecIntoSemantics(
        catalogItem.image_semantics_json,
        catalogItem.item_kind,
        spec
    );
    if (mergedSem) fields.image_semantics_json = mergedSem;
    const catalogGallery = parseGalleryImages(catalogItem.gallery_images);
    if (!catalogGallery.length && spec.gallery_images) {
        fields.gallery_images = parseGalleryImages(spec.gallery_images);
    } else {
        fields.gallery_images = catalogGallery;
    }
    const coverLabel = catalogItem.cover_image_label || spec.cover_image_label;
    if (coverLabel) fields.cover_image_label = String(coverLabel).trim() || null;
    if (targetKind === 'prototype') {
        fields.min_order_quantity = null;
        fields.customization_levels = [];
        if (spec.subcategory_key) fields.subcategory_key = String(spec.subcategory_key).trim();
    }
    return { fields, targetKind, spec };
}

function buildVendorAssetSyncPatchFromSupplierCatalogItem(catalogItem) {
    return buildVendorAssetFieldsFromSupplierCatalog(catalogItem, { copyText: true }).fields;
}

async function syncImportedVendorAssetsFromCatalogItem(catalogItemId) {
    if (!catalogItemId || !(await supplierCatalogTablesReady())) return 0;
    let { data: catalogItem, error: catErr } = await supabase
        .from('supplier_catalog_items')
        .select(SUPPLIER_CATALOG_SYNC_SELECT)
        .eq('id', catalogItemId)
        .maybeSingle();
    if (catErr && isSupabaseMissingColumnError(catErr)) {
        ({ data: catalogItem, error: catErr } = await supabase
            .from('supplier_catalog_items')
            .select(SUPPLIER_CATALOG_ITEM_LEGACY_SELECT + ', ai_tags, image_semantics_json, tags_source, industry_supplier_id, industry_suppliers(id, name, contact_json)')
            .eq('id', catalogItemId)
            .maybeSingle());
    }
    if (catErr || !catalogItem) return 0;
    const { data: imports, error: impErr } = await supabase
        .from('manufacturer_supplier_imports')
        .select('id, vendor_asset_id')
        .eq('catalog_item_id', catalogItemId);
    if (impErr || !imports || !imports.length) return 0;

    const sup = catalogItem.industry_suppliers;
    const supplier = Array.isArray(sup) ? sup[0] : sup;
    const snapshot = buildSupplierCatalogImportSnapshot(catalogItem, supplier);
    const basePatch = buildVendorAssetSyncPatchFromSupplierCatalogItem(catalogItem);
    let synced = 0;

    for (const imp of imports) {
        if (!imp.vendor_asset_id) continue;
        const { data: asset } = await supabase
            .from('vendor_assets')
            .select('id, tags_source')
            .eq('id', imp.vendor_asset_id)
            .maybeSingle();
        if (!asset) continue;
        const patch = { ...basePatch };
        if (asset.tags_source && asset.tags_source !== 'import') {
            delete patch.ai_tags;
            delete patch.ai_tags_generated_at;
            delete patch.image_semantics_json;
        }
        let { error: upErr } = await supabase
            .from('vendor_assets')
            .update(patch)
            .eq('id', imp.vendor_asset_id);
        if (upErr && upErr.code === '42703') {
            const fallback = { ...patch };
            delete fallback.cover_image_label;
            delete fallback.gallery_images;
            delete fallback.subcategory_key;
            delete fallback.asset_kind;
            delete fallback.image_semantics_json;
            delete fallback.ai_tags;
            delete fallback.ai_tags_generated_at;
            ({ error: upErr } = await supabase
                .from('vendor_assets')
                .update(fallback)
                .eq('id', imp.vendor_asset_id));
        }
        if (!upErr) synced += 1;
        await supabase
            .from('manufacturer_supplier_imports')
            .update({ snapshot_json: snapshot })
            .eq('id', imp.id);
    }
    return synced;
}

function queueSyncImportedVendorAssetsFromCatalogItem(catalogItemId) {
    syncImportedVendorAssetsFromCatalogItem(catalogItemId).catch(function (e) {
        console.error('syncImportedVendorAssetsFromCatalogItem:', catalogItemId, e.message || e);
    });
}

async function syncImportSnapshotsForSupplier(supplierId) {
    if (!supplierId || !(await supplierCatalogTablesReady())) return 0;
    const { data: supplier } = await supabase
        .from('industry_suppliers')
        .select('id, name, contact_json')
        .eq('id', supplierId)
        .maybeSingle();
    if (!supplier) return 0;
    const { data: catalogRows } = await supabase
        .from('supplier_catalog_items')
        .select('id')
        .eq('industry_supplier_id', supplierId);
    const catalogIds = (catalogRows || []).map(function (r) { return r.id; }).filter(Boolean);
    if (!catalogIds.length) return 0;
    const { data: imports } = await supabase
        .from('manufacturer_supplier_imports')
        .select('id, catalog_item_id, snapshot_json')
        .in('catalog_item_id', catalogIds);
    if (!imports || !imports.length) return 0;
    let updated = 0;
    for (const imp of imports) {
        const snap = imp.snapshot_json && typeof imp.snapshot_json === 'object' ? { ...imp.snapshot_json } : {};
        snap.supplier_id = supplier.id;
        snap.supplier_name = supplier.name;
        snap.supplier_contact = supplier.contact_json;
        const { error } = await supabase
            .from('manufacturer_supplier_imports')
            .update({ snapshot_json: snap })
            .eq('id', imp.id);
        if (!error) updated += 1;
    }
    return updated;
}

function queueSyncImportSnapshotsForSupplier(supplierId) {
    syncImportSnapshotsForSupplier(supplierId).catch(function (e) {
        console.error('syncImportSnapshotsForSupplier:', supplierId, e.message || e);
    });
}

function supplierCatalogSupportsGallery(itemKind) {
    const k = normalizeSupplierCatalogItemKind(itemKind);
    return k === 'prototype_set' || k === 'material' || k === 'part';
}

async function uploadSupplierCatalogGalleryFiles(supplierId, files, startSortOrder, labelOverrides, derivedKinds) {
    const entries = [];
    const list = Array.isArray(files) ? files : [];
    const labels = Array.isArray(labelOverrides) ? labelOverrides : [];
    const derived = Array.isArray(derivedKinds) ? derivedKinds : [];
    for (let i = 0; i < list.length; i++) {
        const normalized = await vendorAssetFileFromMulter(list[i]);
        if (!normalized) continue;
        const { publicUrl } = await uploadToSupabaseStorage('custom-products', `supplier-catalog/${supplierId}`, normalized);
        const lab = (labels[i] != null && String(labels[i]).trim())
            ? String(labels[i]).trim()
            : labelFromOriginalFilename(normalized.originalname);
        const entry = {
            url: publicUrl,
            sort_order: startSortOrder + i,
            label: lab || labelFromImageUrl(publicUrl)
        };
        const dk = derived[i] != null ? String(derived[i]).trim() : '';
        const derivedNorm = normalizeVendorAiDerivedKind(dk);
        if (derivedNorm) entry.ai_derived = derivedNorm;
        entries.push(entry);
    }
    return entries;
}

function supplierCatalogItemKindToAssetKind(itemKind) {
    const k = normalizeSupplierCatalogItemKind(itemKind);
    if (k === 'material') return 'material';
    if (k === 'part') return 'part';
    return 'prototype';
}

const SUPPLIER_CATALOG_ITEM_SELECT =
    'id, item_kind, title, description, cover_image_url, cover_image_label, gallery_images, spec_json, category_key, is_active, sort_order, ai_tags, image_semantics_json, tags_source, created_at, updated_at';

async function getAuthOwnerIdFromReq(req) {
    const authHeader = req.headers.authorization || req.headers['x-auth-token'];
    const token = authHeader && (authHeader.replace(/^\s*Bearer\s+/i, '') || authHeader);
    if (!token) return null;
    const { data: { user } } = await supabase.auth.getUser(token);
    return user?.id || null;
}

async function isProfileAdminUser(ownerId) {
    if (!ownerId) return false;
    const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
    return profile?.role === 'admin';
}

/** 供應商上架：語意標籤、可選 AI 重繪、點數預檢（與 vendor-assets 相同邏輯） */
async function processSupplierCatalogImagePipeline({
    file,
    body,
    itemKind,
    title,
    description,
    categoryKey,
    ownerId,
    uiLocale
}) {
    const assetKind = supplierCatalogItemKindToAssetKind(itemKind);
    const wantsOptimize = parseTruthyBody(body.optimize_product_image);
    const pointsRequired = wantsOptimize
        ? await getPointsVendorAssetOptimizeForKind(assetKind)
        : await getPointsVendorAssetUpload();
    const isAdmin = await isProfileAdminUser(ownerId);
    if (!isAdmin && ownerId && pointsRequired > 0) {
        const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
        if (!sufficient) {
            return { error: '點數不足', status: 402, balance, required: pointsRequired };
        }
    }

    let tags = parseAiTagsFromBody(body);
    let semanticsJson = null;
    let tagsSource = 'gemini';
    let semanticsFromThisFile = false;
    if (body.image_semantics_json) {
        try {
            semanticsJson = typeof body.image_semantics_json === 'string'
                ? JSON.parse(body.image_semantics_json)
                : body.image_semantics_json;
        } catch (_) {}
    }
    let desc = (description || '').trim() || null;
    let tit = (title || '').trim() || null;

    if (!tags || !tags.length) {
        const sem = await runVendorAssetImageSemantics(file, await vendorAssetSemanticsContextFields({
            asset_kind: assetKind,
            category_key: categoryKey,
            title: tit,
            description: desc
        }), ownerId);
        tags = sem.tags;
        semanticsJson = sem.semantics;
        tagsSource = 'gemini';
        semanticsFromThisFile = true;
        if (!desc && sem.description) desc = sem.description;
    } else {
        tagsSource = semanticsJson ? 'gemini' : 'manual';
        if (!desc && semanticsJson) desc = vendorAssetDescriptionFromSemantics(semanticsJson);
    }
    if (assetKind === 'material' && semanticsJson) {
        const fin = finalizeVendorAssetSemantics(semanticsJson, tags, assetKind);
        semanticsJson = fin.semantics;
        tags = fin.tags;
    }
    if (!tit && semanticsJson) {
        tit = autoVendorAssetTitleFromSemantics(semanticsJson, assetKind, uiLocale, {});
    }

    let uploadFile = file;
    if (wantsOptimize) {
        try {
            const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
            const useDisplayStand = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
            const materialSurfaceCat = assetKind === 'material' ? resolveMaterialSurfaceType(body, null) : '';
            const optimizedBuf = await optimizeVendorAssetImage(
                file.buffer, file.mimetype, tit, assetKind, null, optimizeBackground,
                fluxSeedFromImageBuffer(file.buffer),
                labelFromOriginalFilename(file.originalname),
                undefined,
                materialSurfaceCat,
                ownerId,
                useDisplayStand
            );
            uploadFile = {
                buffer: optimizedBuf,
                mimetype: 'image/jpeg',
                originalname: (file.originalname || 'image.jpg').replace(/\.[^.]+$/, '') + '.jpg'
            };
        } catch (optErr) {
            console.error('supplier-catalog image optimize:', optErr);
            const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
            return { error: mapped.body.error || 'AI 重繪失敗', status: mapped.status };
        }
    }

    return {
        uploadFile,
        tags,
        semanticsJson,
        tagsSource,
        title: tit,
        description: desc,
        pointsRequired,
        wantsOptimize,
        isAdmin,
        assetKind
    };
}

async function consumeSupplierCatalogUploadPoints(ownerId, isAdmin, pointsRequired, optimizeCount, assetKind, supplierId, catalogItemId) {
    if (isAdmin || !ownerId || pointsRequired <= 0) return { balance_after: null, points_deducted: 0 };
    const wantsOptimize = optimizeCount > 0;
    const consumed = await consumeUserCredits(
        ownerId,
        pointsRequired,
        wantsOptimize ? 'vendor_asset_optimize' : 'vendor_asset_upload',
        wantsOptimize
            ? (assetKind === 'material'
                ? `供應商產品庫上架＋${optimizeCount} 張材質圖優化（${pointsRequired} 點）`
                : `供應商產品庫上架＋${optimizeCount} 張產品圖重繪（${pointsRequired} 點）`)
            : (assetKind === 'material'
                ? `供應商產品庫上架（${pointsRequired} 點）`
                : `供應商產品庫上架（${pointsRequired} 點）`),
        { industry_supplier_id: supplierId, catalog_item_id: catalogItemId, optimize: wantsOptimize, optimize_count: optimizeCount, asset_kind: assetKind }
    );
    if (!consumed.ok) {
        console.warn('supplier-catalog 扣點失敗（已上架）:', consumed.error);
        return { balance_after: null, points_deducted: 0 };
    }
    return { balance_after: consumed.balance_after, points_deducted: pointsRequired };
}

async function respondSupplierCatalogUploadFailure(res, status, userId, body, jsonBody) {
    const out = { ...(jsonBody || {}) };
    if (status >= 500 && userId) {
        const refund = await refundConsumedPreviewCredits(userId, parsePreviewCreditTxIdsFromBody(body));
        if (refund.refunded > 0) {
            out.preview_points_refunded = refund.refunded;
            out.balance_after = refund.balance_after;
            const base = out.error || '上架失敗';
            out.error = base + `（已退還預覽重繪／放大 ${refund.refunded} 點；修正後可再發布）`;
        }
    }
    return res.status(status).json(out);
}

/** 供應商 catalog insert：依缺欄分批重試（含 PGRST204／schema cache） */
async function insertSupplierCatalogItemRow(insertPayload, galleryImagesForSpecFallback) {
    let aiMigrationRequired = false;
    let galleryMigrationRequired = false;
    let inserted = null;
    let insertError = null;
    let selectCols = SUPPLIER_CATALOG_ITEM_SELECT;

    for (let attempt = 0; attempt < 10; attempt++) {
        ({ data: inserted, error: insertError } = await supabase
            .from('supplier_catalog_items')
            .insert(insertPayload)
            .select(selectCols)
            .single());
        if (!insertError) break;

        if (isSupabaseMissingColumnError(insertError, 'cover_image_label')) {
            delete insertPayload.cover_image_label;
            if (selectCols.indexOf('cover_image_label') >= 0) selectCols = SUPPLIER_CATALOG_ITEM_LEGACY_SELECT;
            continue;
        }
        if (isSupabaseMissingColumnError(insertError, 'gallery_images')) {
            delete insertPayload.gallery_images;
            delete insertPayload.cover_image_label;
            if (galleryImagesForSpecFallback && galleryImagesForSpecFallback.length) {
                insertPayload.spec_json = { ...(insertPayload.spec_json || {}), gallery_images: galleryImagesForSpecFallback };
                galleryMigrationRequired = true;
            }
            selectCols = SUPPLIER_CATALOG_ITEM_LEGACY_SELECT;
            continue;
        }
        if (isSupabaseMissingColumnError(insertError, 'ai_tags')
            || isSupabaseMissingColumnError(insertError, 'image_semantics_json')
            || isSupabaseMissingColumnError(insertError, 'tags_source')
            || isSupabaseMissingColumnError(insertError, 'ai_tags_generated_at')) {
            delete insertPayload.ai_tags;
            delete insertPayload.image_semantics_json;
            delete insertPayload.tags_source;
            delete insertPayload.ai_tags_generated_at;
            aiMigrationRequired = true;
            if (selectCols.indexOf('ai_tags') >= 0) {
                selectCols = selectCols.split(',').map(function (s) { return s.trim(); })
                    .filter(function (c) {
                        return c && c !== 'ai_tags' && c !== 'image_semantics_json' && c !== 'tags_source'
                            && c !== 'ai_tags_generated_at' && c !== 'updated_at';
                    }).join(', ');
            }
            continue;
        }
        if (isSupabaseMissingColumnError(insertError)) {
            delete insertPayload.cover_image_label;
            delete insertPayload.gallery_images;
            delete insertPayload.ai_tags;
            delete insertPayload.image_semantics_json;
            delete insertPayload.tags_source;
            delete insertPayload.ai_tags_generated_at;
            aiMigrationRequired = true;
            if (galleryImagesForSpecFallback && galleryImagesForSpecFallback.length) {
                insertPayload.spec_json = { ...(insertPayload.spec_json || {}), gallery_images: galleryImagesForSpecFallback };
                galleryMigrationRequired = true;
            }
            selectCols = SUPPLIER_CATALOG_ITEM_LEGACY_SELECT;
            continue;
        }
        break;
    }

    return { inserted, error: insertError, aiMigrationRequired, galleryMigrationRequired };
}

async function resolveSupplierCatalogCoverUrl(supplierId, req, existingUrl) {
    const urlFromBody = (req.body && req.body.cover_image_url || '').trim();
    if (req.file) {
        const file = await vendorAssetFileFromMulter(req.file);
        if (!file) return { error: '圖片格式無效' };
        const { publicUrl } = await uploadToSupabaseStorage('custom-products', `supplier-catalog/${supplierId}`, file);
        return { url: publicUrl };
    }
    if (urlFromBody) return { url: urlFromBody };
    if (existingUrl) return { url: existingUrl };
    return { error: '請上傳產品圖片' };
}

