// POST /api/me/industry-supplier/catalog-items/preview-image-redraw — 上傳前單張 AI 重繪預覽
app.post('/api/me/industry-supplier/catalog-items/preview-image-redraw', upload.single('image'), async (req, res) => {
    try {
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        const file = await vendorAssetFileFromMulter(req.file);
        if (!file) return res.status(400).json({ error: '請上傳圖片' });
        const body = req.body || {};
        const assetKind = normalizeVendorAssetKind(body.asset_kind);
        if (assetKind !== 'prototype' && assetKind !== 'part' && assetKind !== 'material') {
            return res.status(400).json({ error: '不支援的素材類型' });
        }
        const isCover = parseTruthyBody(body.is_cover);
        const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
        const useDisplayStand = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
        const productNameRaw = resolveOptimizeProductNameForPrompt(body);
        const productNameForPrompt = await translateOptimizeProductNameForFlux(productNameRaw);
        const imageLabelHint = (body.image_label || body.filename_hint || '').trim();
        let materialCatalogHint = '';
        if (assetKind === 'material') {
            const groupIds = parseCatalogGroupIdsFromBody(body);
            if (groupIds.length) {
                materialCatalogHint = await supplierCatalogGroupNamesByIds(ctx.supplier.id, groupIds);
            }
        }
        const materialSurfaceType = assetKind === 'material' ? resolveMaterialSurfaceType(body, null) : '';
        const pointsRequired = await computePendingPreviewRedrawPoints(assetKind, isCover);
        let ownerId = seedUser.id;
        let isAdmin = false;
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
        isAdmin = profile?.role === 'admin';
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        let optimized;
        const filenameHint = imageLabelHint || labelFromOriginalFilename(file.originalname);
        const photoCtxSupplier = {
            categoryKey: (body.category_key || '').trim(),
            subcategoryKey: (body.subcategory_key || '').trim()
        };
        let aiPromptUsed = assetKind === 'material'
            ? await buildVendorAssetMaterialFluxOptimizePromptWithPhoto(materialSurfaceType)
            : await buildVendorAssetProductOptimizePromptWithPhoto(
                productNameForPrompt, optimizeBackground, useDisplayStand,
                photoCtxSupplier.categoryKey, photoCtxSupplier.subcategoryKey, assetKind
            );
        try {
            optimized = await maybeOptimizeVendorAssetMulterFile(
                file,
                productNameRaw,
                assetKind,
                assetKind === 'material' ? materialCatalogHint : null,
                assetKind === 'material' ? 'white' : optimizeBackground,
                filenameHint,
                undefined,
                materialSurfaceType,
                ownerId,
                useDisplayStand,
                photoCtxSupplier
            );
        } catch (optErr) {
            console.error('supplier preview-image-redraw optimize:', optErr);
            const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
            return res.status(mapped.status).json(mapped.body);
        }
        const previewName = `preview-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products', `supplier-catalog-preview/${ctx.supplier.id}`, { ...optimized, originalname: previewName }
        );
        let balanceAfter = null;
        let creditTransactionId = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_optimize',
                `供應商上架前單張 ${assetKind === 'material' ? '材質圖 AI 優化' : 'AI 重繪'}預覽（${pointsRequired} 點）`,
                { industry_supplier_id: ctx.supplier.id, preview: true, is_cover: isCover }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
            creditTransactionId = consumed.transaction_id || null;
        }
        res.json({
            preview_url: publicUrl,
            preview_base64: optimized.buffer.toString('base64'),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            credit_transaction_id: creditTransactionId,
            ai_prompt: aiPromptUsed
        });
    } catch (e) {
        console.error('POST /api/me/industry-supplier/catalog-items/preview-image-redraw:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/industry-supplier/catalog-items/preview-image-upscale — 上傳前原圖 AI 放大預覽
app.post('/api/me/industry-supplier/catalog-items/preview-image-upscale', upload.single('image'), async (req, res) => {
    try {
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const seedUser = await getRequestUserFromAuthHeader(req);
        if (!seedUser) return res.status(401).json({ error: '請先登入' });
        if (!req.file || !req.file.buffer) return res.status(400).json({ error: '請上傳圖片' });
        const body = req.body || {};
        const assetKind = normalizeVendorAssetKind(body.asset_kind);
        if (assetKind !== 'prototype' && assetKind !== 'part' && assetKind !== 'material') {
            return res.status(400).json({ error: '不支援的素材類型' });
        }
        if (assetKind === 'material') {
            return res.status(400).json({ error: '材料參考不提供 AI 放大，請直接上傳原圖或使用 AI 重繪' });
        }
        const upscaleNeed = await evaluateVendorUpscaleNeedFromBuffer(req.file.buffer);
        if (!upscaleNeed.needed) {
            return res.status(400).json({
                error: vendorUpscaleRejectMessage(upscaleNeed),
                upscale_needed: false,
                megapixels: upscaleNeed.megapixels,
                width: upscaleNeed.width,
                height: upscaleNeed.height,
                ai_edit_url: AI_EDIT_UPSCALE_PAGE
            });
        }
        const REPLICATE_API_TOKEN = getReplicateApiToken();
        if (!REPLICATE_API_TOKEN) {
            return res.status(503).json({ error: replicateTokenMissingMessage() });
        }
        const scale = parseUpscaleScaleFromRequest(req);
        const basePts = await getPointsVendorAssetUpscale();
        const pointsRequired = pointsForUpscaleScale(basePts, scale);
        let ownerId = seedUser.id;
        let isAdmin = false;
        const { data: profile } = await supabase.from('profiles').select('role').eq('id', ownerId).maybeSingle();
        isAdmin = profile?.role === 'admin';
        if (!isAdmin && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        const file = await vendorAssetFileFromMulter(req.file);
        if (!file) return res.status(400).json({ error: '請上傳圖片' });
        let upscaled;
        try {
            upscaled = await vendorMaterialUpscale(file.buffer, file.mimetype, REPLICATE_API_TOKEN, { scale: scale });
        } catch (upErr) {
            console.error('supplier preview-image-upscale:', upErr.status, upErr.details || upErr.message);
            return res.status(502).json({
                error: '放大服務暫時無法使用，請稍後再試',
                details: upErr.status === 401 ? 'API Token 無效' : (upErr.details || upErr.message || '').slice(0, 200)
            });
        }
        const previewName = `upscale-preview-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.jpg`;
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products',
            `supplier-catalog-preview/${ctx.supplier.id}`,
            { buffer: upscaled.buffer, mimetype: upscaled.mimetype, originalname: previewName }
        );
        let balanceAfter = null;
        let creditTransactionId = null;
        if (!isAdmin && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_upscale',
                `供應商上架前 AI 放大預覽 ${scale}×（${pointsRequired} 點）`,
                { industry_supplier_id: ctx.supplier.id, preview: true, max_output_mp: 1, scale: scale }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: '點數不足', balance: consumed.balance, required: pointsRequired });
            }
            balanceAfter = consumed.balance_after;
            creditTransactionId = consumed.transaction_id || null;
        }
        res.json({
            preview_url: publicUrl,
            preview_base64: upscaled.buffer.toString('base64'),
            output_width: upscaled.width,
            output_height: upscaled.height,
            scale: scale,
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            credit_transaction_id: creditTransactionId
        });
    } catch (e) {
        console.error('POST /api/me/industry-supplier/catalog-items/preview-image-upscale:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/industry-supplier/catalog-items/generate-description — 編輯區 AI 說明（扣點）
app.post('/api/me/industry-supplier/catalog-items/generate-description', supplierCatalogItemUpload, async (req, res) => {
    try {
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const body = req.body || {};
        const catalogItemId = (body.catalog_item_id || '').trim();
        const itemKind = normalizeSupplierCatalogItemKind(body.item_kind || 'material');
        const assetKind = supplierCatalogItemKindToAssetKind(itemKind);
        let imageFile = req.file ? await vendorAssetFileFromMulter(req.file) : null;
        let context = await vendorAssetSemanticsContextFields({
            asset_kind: assetKind,
            category_key: body.category_key,
            title: body.title,
            description: body.description
        });
        if (!imageFile && catalogItemId) {
            const { data: row } = await supabase
                .from('supplier_catalog_items')
                .select('id, cover_image_url, category_key, title, description, item_kind')
                .eq('id', catalogItemId)
                .eq('industry_supplier_id', ctx.supplier.id)
                .maybeSingle();
            if (!row || !row.cover_image_url) return res.status(404).json({ error: '找不到該品項或無圖片' });
            context = await vendorAssetSemanticsContextFields({
                asset_kind: supplierCatalogItemKindToAssetKind(row.item_kind),
                category_key: (body.category_key || '').trim() || row.category_key || '',
                title: (body.title || '').trim() || row.title || '',
                description: (body.description || '').trim() || row.description || '',
                image_url: row.cover_image_url
            });
            imageFile = await fetchPortfolioImageFileFromUrl(row.cover_image_url);
            if (!imageFile) return res.status(503).json({ error: '無法讀取產品圖片' });
        }
        if (!imageFile) return res.status(400).json({ error: '請上傳圖片或提供品項 id' });
        const ownerId = await getAuthOwnerIdFromReq(req);
        const result = await runVendorAssetImageSemantics(imageFile, context, ownerId);
        const description = result.description || vendorAssetDescriptionFromSemantics(result.semantics);
        if (!description) return res.status(503).json({ error: '無法產生說明，請稍後重試' });
        const pointsRequired = await getPointsVendorAssetDescription();
        const isAdmin = await isProfileAdminUser(ownerId);
        let balanceAfter = null;
        let pointsDeducted = 0;
        if (!isAdmin && ownerId && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_description',
                '供應商產品庫 AI 產生說明',
                { industry_supplier_id: ctx.supplier.id, catalog_item_id: catalogItemId || null }
            );
            if (!consumed.ok) {
                return res.status(402).json({ error: consumed.error || '扣點失敗', balance: consumed.balance });
            }
            balanceAfter = consumed.balance_after;
            pointsDeducted = pointsRequired;
        }
        res.json({
            description,
            product_description_zh: result.semantics?.product_description_zh || null,
            product_description_en: result.semantics?.product_description_en || null,
            points_deducted: pointsDeducted,
            balance_after: balanceAfter
        });
    } catch (e) {
        console.error('POST industry-supplier catalog generate-description:', e);
        res.status(503).json({ error: e.message || 'AI 說明產生失敗，請稍後重試' });
    }
});

// GET /api/me/industry-supplier/catalog-items — 產業供應商管理自己的目錄
app.get('/api/me/industry-supplier/catalog-items', async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.json({ items: [], message: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const itemKind = (req.query.item_kind || '').trim();
        let q = supabase
            .from('supplier_catalog_items')
            .select(SUPPLIER_CATALOG_ITEM_SELECT)
            .eq('industry_supplier_id', ctx.supplier.id)
            .order('sort_order', { ascending: true })
            .order('created_at', { ascending: false });
        if (itemKind === 'material' || itemKind === 'prototype_set' || itemKind === 'part') q = q.eq('item_kind', itemKind);
        let { data: rows, error } = await q;
        if (error && error.code === '42703') {
            const legacySelect = 'id, item_kind, title, description, cover_image_url, spec_json, category_key, is_active, sort_order, created_at';
            let q2 = supabase
                .from('supplier_catalog_items')
                .select(legacySelect)
                .eq('industry_supplier_id', ctx.supplier.id)
                .order('sort_order', { ascending: true })
                .order('created_at', { ascending: false });
            if (itemKind === 'material' || itemKind === 'prototype_set' || itemKind === 'part') q2 = q2.eq('item_kind', itemKind);
            ({ data: rows, error } = await q2);
        }
        if (error) {
            console.error('GET industry-supplier catalog-items:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        const includeRefs = req.query.include_references === '1';
        const catalogIds = (rows || []).map((r) => r.id);
        const refsByCatalog = {};
        if (includeRefs && catalogIds.length) {
            const { data: refs, error: refErr } = await supabase
                .from('manufacturer_supplier_imports')
                .select('id, catalog_item_id, manufacturer_id, imported_at, manufacturers(id, name)')
                .in('catalog_item_id', catalogIds)
                .order('imported_at', { ascending: false });
            if (!refErr && refs) {
                refs.forEach((ref) => {
                    const cid = ref.catalog_item_id;
                    if (!refsByCatalog[cid]) refsByCatalog[cid] = [];
                    const mfr = ref.manufacturers;
                    const m = Array.isArray(mfr) ? mfr[0] : mfr;
                    refsByCatalog[cid].push({
                        import_id: ref.id,
                        manufacturer_id: ref.manufacturer_id,
                        manufacturer_name: m ? m.name : null,
                        imported_at: ref.imported_at
                    });
                });
            }
        }
        let items = (rows || []).map((row) => {
            const references = refsByCatalog[row.id] || [];
            const base = mapSupplierCatalogItemForApi(row);
            return {
                ...base,
                reference_count: includeRefs ? references.length : 0,
                references: includeRefs ? references : []
            };
        });
        try {
            items = await attachCatalogGroupsToSupplierItems(items);
        } catch (grpErr) {
            console.warn('attachCatalogGroupsToSupplierItems:', grpErr.message);
        }
        res.json({ supplier: ctx.supplier, items });
    } catch (e) {
        console.error('GET /api/me/industry-supplier/catalog-items:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/me/industry-supplier/catalog-items — 上架品項（含 AI 標籤／可選重繪，對稱 vendor-assets）
app.post('/api/me/industry-supplier/catalog-items', supplierCatalogItemCreateUpload, async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.status(503).json({ error: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const body = req.body || {};
        const itemKind = normalizeSupplierCatalogItemKind(body.item_kind);
        const categoryKey = (body.category_key || '').trim();
        if (!categoryKey) return res.status(400).json({ error: '請選擇平台主分類' });
        if (itemKind === 'prototype_set' && !(body.subcategory_key || '').trim()) {
            return res.status(400).json({ error: '請選擇子分類（數位原型必填，會影響設計端生圖提示詞）' });
        }
        const supportsGallery = supplierCatalogSupportsGallery(itemKind);
        const assetKind = supplierCatalogItemKindToAssetKind(itemKind);
        const fileFromFields = (req.files && req.files.image && req.files.image[0]) ? req.files.image[0] : req.file;
        let file = await vendorAssetFileFromMulter(fileFromFields);
        if (!file) return res.status(400).json({ error: '請上傳產品圖片' });
        const galleryUploadFiles = (supportsGallery && req.files && req.files.gallery) ? req.files.gallery : [];
        const totalUploadFiles = 1 + galleryUploadFiles.length;
        const optimizeIndices = parseOptimizeImageIndices(body, totalUploadFiles);
        const pointsRequired = await computeVendorAssetCreatePoints(assetKind, optimizeIndices, totalUploadFiles);
        const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
        const useDisplayStandCreate = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
        const catalogGroupIdsEarly = parseCatalogGroupIdsFromBody(body);
        let materialCatalogHint = '';
        if (assetKind === 'material' && catalogGroupIdsEarly.length) {
            materialCatalogHint = await supplierCatalogGroupNamesByIds(ctx.supplier.id, catalogGroupIdsEarly);
        }
        const ownerId = uploadUser.id || (await getAuthOwnerIdFromReq(req));
        const isAdmin = await isProfileAdminUser(ownerId);
        if (!isAdmin && ownerId && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        let title = (body.title || '').trim() || null;
        let description = (body.description || '').trim() || null;
        const uiLocale = resolveUiLocaleFromRequest(req);
        const imageLabels = parseImageLabelsBody(body, totalUploadFiles);
        const materialSurfaceCreate = assetKind === 'material' ? resolveMaterialSurfaceType(body, null) : '';

        let tags = parseAiTagsFromBody(body);
        let semanticsJson = null;
        let tagsSource = 'gemini';
        if (body.image_semantics_json) {
            try {
                semanticsJson = typeof body.image_semantics_json === 'string'
                    ? JSON.parse(body.image_semantics_json)
                    : body.image_semantics_json;
            } catch (_) {}
        }
        if (!tags || !tags.length) {
            try {
                const sem = await runVendorAssetImageSemantics(file, await vendorAssetSemanticsContextFields({
                    asset_kind: assetKind,
                    category_key: categoryKey,
                    title,
                    description,
                    material_catalog_hint: materialCatalogHint || undefined,
                    image_label: (imageLabels[0] && String(imageLabels[0]).trim())
                        || labelFromOriginalFilename(file.originalname)
                        || '封面'
                }), ownerId);
                tags = sem.tags;
                semanticsJson = sem.semantics;
                tagsSource = 'gemini';
                if (!description && sem.description) description = sem.description;
            } catch (semErr) {
                console.error('supplier-catalog semantics:', semErr);
                return res.status(503).json({ error: semErr.message || 'AI 標籤產生失敗，請稍後重試' });
            }
        } else {
            tagsSource = semanticsJson ? 'gemini' : 'manual';
            if (!description && semanticsJson) {
                description = vendorAssetDescriptionFromSemantics(semanticsJson);
            }
        }
        if (assetKind === 'material' && semanticsJson) {
            const fin = finalizeVendorAssetSemantics(semanticsJson, tags, assetKind);
            semanticsJson = fin.semantics;
            tags = fin.tags;
        }
        if (!title && semanticsJson) {
            title = autoVendorAssetTitleFromSemantics(semanticsJson, assetKind, uiLocale, {
                materialCatalogHint
            });
        }
        if (assetKind === 'material') {
            semanticsJson = mergeMaterialSurfaceIntoSemantics(semanticsJson, materialSurfaceCreate);
            const materialComboCreate = parseMaterialComboFromBody(body);
            if (materialComboCreate) {
                semanticsJson = mergeMaterialComboIntoSemantics(semanticsJson, materialComboCreate);
            }
        }
        if (!title) return res.status(400).json({ error: '請填寫產品名稱，或上傳可辨識的圖片以自動產生標題' });
        if (!description) return res.status(400).json({ error: '請填寫產品說明，或留空由 AI 產生（需可讀圖）' });

        const productNameForPrompt = resolveOptimizeProductNameForPrompt(body, title);
        const fluxScheduler = createVendorFluxOptimizeScheduler(ownerId, materialSurfaceCreate, useDisplayStandCreate, {
            categoryKey: (body.category_key || '').trim(),
            subcategoryKey: (body.subcategory_key || '').trim()
        });
        let uploadFile = file;
        if (optimizeIndices.includes(0)) {
            try {
                const coverFilenameHint = (imageLabels[0] && String(imageLabels[0]).trim())
                    || labelFromOriginalFilename(file.originalname);
                uploadFile = await fluxScheduler.optimize(
                    file, productNameForPrompt, assetKind, materialCatalogHint || null, optimizeBackground, coverFilenameHint
                );
            } catch (optErr) {
                console.error('supplier-catalog cover optimize:', optErr);
                const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
                return res.status(mapped.status).json(mapped.body);
            }
        }
        const { publicUrl } = await uploadToSupabaseStorage(
            'custom-products',
            `supplier-catalog/${ctx.supplier.id}`,
            uploadFile
        );
        const coverLabel = (imageLabels[0] && String(imageLabels[0]).trim())
            || labelFromOriginalFilename(uploadFile.originalname)
            || labelFromImageUrl(publicUrl);
        let galleryImages = [];
        if (supportsGallery && galleryUploadFiles.length) {
            const maxExtra = Math.min(galleryUploadFiles.length, PROTOTYPE_GALLERY_MAX_EXTRA);
            const galleryToUpload = [];
            for (let gi = 0; gi < maxExtra; gi++) {
                let gf = await vendorAssetFileFromMulter(galleryUploadFiles[gi]);
                if (!gf) continue;
                if (optimizeIndices.includes(gi + 1)) {
                    try {
                        const galleryFilenameHint = (imageLabels[gi + 1] && String(imageLabels[gi + 1]).trim())
                            || labelFromOriginalFilename(gf.originalname);
                        gf = await fluxScheduler.optimize(
                            gf, productNameForPrompt, assetKind, materialCatalogHint || null, optimizeBackground, galleryFilenameHint
                        );
                    } catch (optErr) {
                        console.error('supplier-catalog gallery optimize:', optErr);
                        const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
                        return res.status(mapped.status).json(mapped.body);
                    }
                }
                galleryToUpload.push(gf);
            }
            if (galleryToUpload.length) {
                const galleryDerived = parseImageAiDerivedBody(body, totalUploadFiles).slice(1, 1 + galleryToUpload.length);
                galleryImages = await uploadSupplierCatalogGalleryFiles(
                    ctx.supplier.id,
                    galleryToUpload,
                    1,
                    imageLabels.slice(1, 1 + galleryToUpload.length),
                    galleryDerived
                );
            }
        }
        const specJson = parseSupplierCatalogSpecJson(itemKind, body);
        const sortOrder = (body.sort_order != null && !isNaN(body.sort_order)) ? parseInt(body.sort_order, 10) : 0;
        const safeTags = Array.isArray(tags) ? tags : [];
        const insertPayload = {
            industry_supplier_id: ctx.supplier.id,
            item_kind: itemKind,
            title,
            description,
            cover_image_url: publicUrl,
            cover_image_label: supportsGallery ? coverLabel : null,
            gallery_images: galleryImages,
            spec_json: specJson,
            category_key: categoryKey,
            is_active: true,
            sort_order: sortOrder,
            ai_tags: safeTags,
            ai_tags_generated_at: new Date().toISOString(),
            tags_source: tagsSource
        };
        if (semanticsJson) insertPayload.image_semantics_json = semanticsJson;
        const insertResult = await insertSupplierCatalogItemRow(insertPayload, galleryImages);
        const inserted = insertResult.inserted;
        const error = insertResult.error;
        const aiMigrationRequired = insertResult.aiMigrationRequired;
        const galleryMigrationRequired = insertResult.galleryMigrationRequired;
        if (error) {
            console.error('POST industry-supplier catalog-item:', error);
            if (error.code === '23514') {
                return res.status(400).json({ error: '資料庫尚未支援此品項類型，請執行 docs/add-supplier-catalog-item-kind-part.sql' });
            }
            if (error.code === '42703' || error.code === 'PGRST204' || isSupabaseMissingColumnError(error)) {
                return respondSupplierCatalogUploadFailure(res, 500, ownerId, body, {
                    error: '資料庫缺欄位：請在 Supabase SQL Editor 執行 docs/add-supplier-catalog-gallery-images.sql 與 docs/add-supplier-catalog-ai-fields.sql',
                    ai_migration_required: true,
                    gallery_migration_required: true
                });
            }
            const detail = String(error.message || error.details || '').trim();
            return respondSupplierCatalogUploadFailure(res, 500, ownerId, body, {
                error: detail ? ('上架失敗：' + detail) : '上架失敗'
            });
        }
        await recordVisualSemanticsEvent({
            source_type: 'catalog_item',
            source_id: inserted.id,
            image_url: publicUrl,
            text_input: null,
            semantics_kind: 'image',
            ai_tags: tags,
            semantics_json: semanticsJson,
            model: tagsSource === 'gemini' ? await getTaggingModelName() : null,
            prompt_version: visualSemantics.PROMPT_VERSION,
            owner_id: ownerId,
            category_key: categoryKey
        });
        if (body.catalog_group_ids !== undefined || body.catalog_group_id) {
            await setSupplierCatalogItemCatalogGroups(
                inserted.id,
                ctx.supplier.id,
                parseCatalogGroupIdsFromBody(body),
                itemKind
            );
        }
        const optimizeCount = optimizeIndices.length;
        const pointsMeta = await consumeSupplierCatalogUploadPoints(
            ownerId,
            isAdmin,
            pointsRequired,
            optimizeCount,
            assetKind,
            ctx.supplier.id,
            inserted.id
        );
        res.status(201).json({
            item: mapSupplierCatalogItemForApi(inserted),
            points_deducted: pointsMeta.points_deducted,
            balance_after: pointsMeta.balance_after,
            product_optimized: optimizeCount > 0,
            optimize_image_indices: optimizeIndices,
            ai_migration_required: aiMigrationRequired,
            gallery_migration_required: galleryMigrationRequired
        });
    } catch (e) {
        console.error('POST /api/me/industry-supplier/catalog-items:', e);
        const ownerId = await getAuthOwnerIdFromReq(req);
        return respondSupplierCatalogUploadFailure(res, 500, ownerId, req.body || {}, {
            error: e.message || '系統錯誤'
        });
    }
});

// PATCH /api/me/industry-supplier/catalog-items/:id
app.patch('/api/me/industry-supplier/catalog-items/:id', supplierCatalogItemUpload, async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.status(503).json({ error: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const itemId = (req.params.id || '').trim();
        if (!itemId) return res.status(400).json({ error: '缺少 id' });
        const { data: existing } = await supabase
            .from('supplier_catalog_items')
            .select('id, cover_image_url, item_kind, spec_json, title, description, category_key, ai_tags, image_semantics_json')
            .eq('id', itemId)
            .eq('industry_supplier_id', ctx.supplier.id)
            .maybeSingle();
        if (!existing) return res.status(404).json({ error: '找不到該品項' });
        const body = req.body || {};
        const patch = {};
        if (body.title != null) {
            const t = String(body.title).trim();
            if (!t) return res.status(400).json({ error: '標題不可為空' });
            patch.title = t;
        }
        if (body.description != null) {
            const d = String(body.description).trim();
            if (!d) return res.status(400).json({ error: '產品說明不可為空' });
            patch.description = d;
        }
        if (body.category_key != null) {
            const ck = String(body.category_key).trim();
            if (!ck) return res.status(400).json({ error: '請選擇平台主分類' });
            patch.category_key = ck;
        }
        if (body.is_active != null) patch.is_active = !!body.is_active;
        if (body.sort_order != null && !isNaN(body.sort_order)) patch.sort_order = parseInt(body.sort_order, 10);
        const itemKind = normalizeSupplierCatalogItemKind(existing.item_kind);
        if (body.spec_json != null || body.material_type != null || body.subcategory_key != null) {
            const baseSpec = (existing.spec_json && typeof existing.spec_json === 'object') ? existing.spec_json : {};
            patch.spec_json = parseSupplierCatalogSpecJson(itemKind, { ...baseSpec, ...body, spec_json: body.spec_json || baseSpec });
        }
        if (itemKind === 'material' && body.material_surface_type !== undefined) {
            const baseSem = patch.image_semantics_json !== undefined
                ? patch.image_semantics_json
                : (existing.image_semantics_json || null);
            patch.image_semantics_json = mergeMaterialSurfaceIntoSemantics(baseSem, body.material_surface_type);
        }
        if (body.ai_tags !== undefined) {
            const manualTags = parseAiTagsFromBody(body);
            patch.ai_tags = manualTags || [];
            patch.tags_source = body.image_semantics_json ? 'gemini' : 'manual';
            patch.ai_tags_generated_at = new Date().toISOString();
            if (body.image_semantics_json) {
                try {
                    patch.image_semantics_json = typeof body.image_semantics_json === 'string'
                        ? JSON.parse(body.image_semantics_json)
                        : body.image_semantics_json;
                } catch (_) {}
            }
        }
        let pointsMeta = { points_deducted: 0, balance_after: null };
        let productOptimized = false;
        if (req.file) {
            let file = await vendorAssetFileFromMulter(req.file);
            if (!file) return res.status(400).json({ error: '圖片格式無效' });
            const ownerId = await getAuthOwnerIdFromReq(req);
            const uiLocale = resolveUiLocaleFromRequest(req);
            const pipeline = await processSupplierCatalogImagePipeline({
                file,
                body,
                itemKind,
                title: patch.title || existing.title,
                description: patch.description != null ? patch.description : existing.description,
                categoryKey: patch.category_key || existing.category_key || '',
                ownerId,
                uiLocale
            });
            if (pipeline.error) {
                return res.status(pipeline.status || 400).json({
                    error: pipeline.error,
                    balance: pipeline.balance,
                    required: pipeline.required
                });
            }
            const { publicUrl } = await uploadToSupabaseStorage(
                'custom-products',
                `supplier-catalog/${ctx.supplier.id}`,
                pipeline.uploadFile
            );
            patch.cover_image_url = publicUrl;
            patch.ai_tags = pipeline.tags;
            patch.image_semantics_json = pipeline.semanticsJson;
            patch.tags_source = pipeline.tagsSource;
            patch.ai_tags_generated_at = new Date().toISOString();
            if (!patch.title && pipeline.title) patch.title = pipeline.title;
            if (!patch.description && pipeline.description) patch.description = pipeline.description;
            productOptimized = pipeline.wantsOptimize;
            pointsMeta = await consumeSupplierCatalogUploadPoints(
                ownerId,
                pipeline.isAdmin,
                pipeline.pointsRequired,
                pipeline.wantsOptimize,
                pipeline.assetKind,
                ctx.supplier.id,
                itemId
            );
        } else if (body.cover_image_url != null && String(body.cover_image_url).trim()) {
            const coverResolved = await resolveSupplierCatalogCoverUrl(ctx.supplier.id, req, existing.cover_image_url);
            if (coverResolved.error) return res.status(400).json({ error: coverResolved.error });
            patch.cover_image_url = coverResolved.url;
        }
        if (itemKind === 'prototype_set') {
            const mergedSpec = patch.spec_json !== undefined
                ? patch.spec_json
                : ((existing.spec_json && typeof existing.spec_json === 'object') ? existing.spec_json : {});
            const subKeyFinal = (mergedSpec && mergedSpec.subcategory_key) ? String(mergedSpec.subcategory_key).trim() : '';
            if (body.subcategory_key !== undefined && !String(body.subcategory_key).trim()) {
                return res.status(400).json({ error: '請選擇子分類（數位原型必填，會影響設計端生圖提示詞）' });
            }
            if (!subKeyFinal) {
                return res.status(400).json({ error: '請選擇子分類（數位原型必填，會影響設計端生圖提示詞）' });
            }
        }
        patch.updated_at = new Date().toISOString();
        let { data: updated, error } = await supabase
            .from('supplier_catalog_items')
            .update(patch)
            .eq('id', itemId)
            .select(SUPPLIER_CATALOG_ITEM_SELECT)
            .single();
        if (error && error.code === '42703') {
            delete patch.ai_tags;
            delete patch.image_semantics_json;
            delete patch.tags_source;
            delete patch.ai_tags_generated_at;
            ({ data: updated, error } = await supabase
                .from('supplier_catalog_items')
                .update(patch)
                .eq('id', itemId)
                .select('id, item_kind, title, description, cover_image_url, spec_json, category_key, is_active, sort_order, created_at')
                .single());
        }
        if (error) {
            console.error('PATCH industry-supplier catalog-item:', error);
            return res.status(500).json({ error: '更新失敗' });
        }
        if (body.catalog_group_ids !== undefined || body.catalog_group_id) {
            await setSupplierCatalogItemCatalogGroups(
                itemId,
                ctx.supplier.id,
                parseCatalogGroupIdsFromBody(body),
                itemKind
            );
        }
        let itemOut = updated;
        try {
            const withGroups = await attachCatalogGroupsToSupplierItems([updated]);
            if (withGroups && withGroups[0]) itemOut = withGroups[0];
        } catch (_) {}
        queueSyncImportedVendorAssetsFromCatalogItem(itemId);
        res.json({
            item: mapSupplierCatalogItemForApi(itemOut),
            points_deducted: pointsMeta.points_deducted,
            balance_after: pointsMeta.balance_after,
            product_optimized: productOptimized
        });
    } catch (e) {
        console.error('PATCH /api/me/industry-supplier/catalog-items/:id:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// POST /api/me/industry-supplier/catalog-items/:id/gallery-images — 新增多角度圖（可逐張 AI 重繪）
app.post('/api/me/industry-supplier/catalog-items/:id/gallery-images', supplierCatalogGalleryUpload, async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.status(503).json({ error: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const itemId = (req.params.id || '').trim();
        if (!itemId) return res.status(400).json({ error: '缺少 id' });
        const { data: row, error: rowErr } = await supabase
            .from('supplier_catalog_items')
            .select('id, cover_image_url, gallery_images, spec_json, item_kind, title, image_semantics_json')
            .eq('id', itemId)
            .eq('industry_supplier_id', ctx.supplier.id)
            .maybeSingle();
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該品項' });
        if (!supplierCatalogSupportsGallery(row.item_kind)) {
            return res.status(400).json({ error: '此品項類型不支援多角度圖' });
        }
        const files = (req.files && req.files.length) ? req.files : [];
        if (!files.length) return res.status(400).json({ error: '請上傳至少一張圖片' });
        const body = req.body || {};
        const assetKind = supplierCatalogItemKindToAssetKind(row.item_kind);
        const optimizeIndices = parseOptimizeImageIndices(body, files.length);
        const optimizeBackground = (body.optimize_background || body.background_color || '').trim() || 'white';
        const useDisplayStand = assetKind !== 'material' && parseUseDisplayStandFromBody(body);
        const productNameForPrompt = resolveOptimizeProductNameForPrompt(body, row.title);
        const titleForPrompt = (row.title || '').trim() || null;
        let materialCatalogHint = '';
        if (assetKind === 'material') {
            materialCatalogHint = await supplierCatalogGroupNamesByIds(ctx.supplier.id, parseCatalogGroupIdsFromBody(body));
        }
        const materialSurfaceType = assetKind === 'material' ? resolveMaterialSurfaceType(body, row) : '';
        let pointsRequired = 0;
        if (optimizeIndices.length) {
            pointsRequired = await computeVendorAssetOptimizeTotalPoints(optimizeIndices.length, assetKind);
        }
        const ownerId = uploadUser.id || (await getAuthOwnerIdFromReq(req));
        const isAdmin = await isProfileAdminUser(ownerId);
        if (!isAdmin && ownerId && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        let existing = parseGalleryImages(row.gallery_images);
        if (!existing.length && row.spec_json && row.spec_json.gallery_images) {
            existing = parseGalleryImages(row.spec_json.gallery_images);
        }
        const cover = String(row.cover_image_url || '').trim();
        const totalNow = (cover ? 1 : 0) + existing.length;
        const room = PROTOTYPE_GALLERY_MAX_EXTRA + 1 - totalNow;
        if (room <= 0) {
            return res.status(400).json({ error: '已達多角度圖上限（封面＋' + PROTOTYPE_GALLERY_MAX_EXTRA + ' 張）' });
        }
        const sliceCount = Math.min(files.length, room);
        const imageLabels = parseImageLabelsBody(body, sliceCount);
        const fluxScheduler = createVendorFluxOptimizeScheduler(ownerId, materialSurfaceType, useDisplayStand, {
            categoryKey: (body.category_key || row.category_key || '').trim(),
            subcategoryKey: (body.subcategory_key || row.subcategory_key || '').trim()
        });
        const galleryToUpload = [];
        for (let gi = 0; gi < sliceCount; gi++) {
            let gf = await vendorAssetFileFromMulter(files[gi]);
            if (!gf) continue;
            if (optimizeIndices.includes(gi)) {
                try {
                    const galleryFilenameHint = (imageLabels[gi] && String(imageLabels[gi]).trim())
                        || labelFromOriginalFilename(gf.originalname);
                    gf = await fluxScheduler.optimize(
                        gf,
                        productNameForPrompt,
                        assetKind,
                        assetKind === 'material' ? materialCatalogHint : null,
                        assetKind === 'material' ? 'white' : optimizeBackground,
                        galleryFilenameHint
                    );
                } catch (optErr) {
                    console.error('supplier gallery-images optimize:', optErr);
                    const mapped = vendorAssetOptimizeErrorResponse(optErr, assetKind);
                    return res.status(mapped.status).json(mapped.body);
                }
            }
            galleryToUpload.push(gf);
        }
        if (!galleryToUpload.length) return res.status(400).json({ error: '無法讀取上傳的圖片' });
        const startSort = existing.length ? Math.max.apply(null, existing.map(function (g) { return g.sort_order; })) + 1 : 1;
        const uploadDerived = parseImageAiDerivedBody(body, sliceCount);
        const newEntries = await uploadSupplierCatalogGalleryFiles(
            ctx.supplier.id, galleryToUpload, startSort, imageLabels, uploadDerived
        );
        const merged = existing.concat(newEntries);
        let patch = { gallery_images: merged, updated_at: new Date().toISOString() };
        let { data: updated, error } = await supabase
            .from('supplier_catalog_items')
            .update(patch)
            .eq('id', itemId)
            .select(SUPPLIER_CATALOG_ITEM_SELECT)
            .single();
        let galleryMigrationRequired = false;
        if (error && error.code === '42703') {
            const spec = (row.spec_json && typeof row.spec_json === 'object') ? { ...row.spec_json } : {};
            spec.gallery_images = merged;
            ({ data: updated, error } = await supabase
                .from('supplier_catalog_items')
                .update({ spec_json: spec, updated_at: new Date().toISOString() })
                .eq('id', itemId)
                .select(SUPPLIER_CATALOG_ITEM_SELECT)
                .single());
            galleryMigrationRequired = !error;
        }
        if (error) {
            console.error('POST supplier catalog gallery-images:', error);
            return res.status(500).json({ error: '更新失敗' });
        }
        const pointsMeta = await consumeSupplierCatalogUploadPoints(
            ownerId,
            isAdmin,
            pointsRequired,
            optimizeIndices.length,
            assetKind,
            ctx.supplier.id,
            itemId
        );
        queueSyncImportedVendorAssetsFromCatalogItem(itemId);
        res.json({
            item: mapSupplierCatalogItemForApi(updated),
            points_deducted: pointsMeta.points_deducted,
            balance_after: pointsMeta.balance_after,
            gallery_migration_required: galleryMigrationRequired
        });
    } catch (e) {
        console.error('POST /api/me/industry-supplier/catalog-items/:id/gallery-images:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

// POST /api/me/industry-supplier/catalog-items/:id/gallery-images/upscale — 單張 AI 放大並追加新圖
app.post('/api/me/industry-supplier/catalog-items/:id/gallery-images/upscale', express.json(), async (req, res) => {
    try {
        const uploadUser = await assertCanUploadProductsAndAssets(req, res);
        if (!uploadUser) return;
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const itemId = (req.params.id || '').trim();
        const body = req.body || {};
        const sourceUrl = String(body.source_url || '').trim();
        if (!itemId) return res.status(400).json({ error: '缺少 id' });
        if (!sourceUrl) return res.status(400).json({ error: '請提供 source_url' });
        const { data: row, error: rowErr } = await supabase
            .from('supplier_catalog_items')
            .select('id, cover_image_url, cover_image_label, gallery_images, spec_json, item_kind, title')
            .eq('id', itemId)
            .eq('industry_supplier_id', ctx.supplier.id)
            .maybeSingle();
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該品項' });
        const assetKind = supplierCatalogItemKindToAssetKind(row.item_kind);
        if (assetKind === 'material') {
            return res.status(400).json({ error: '材料參考不提供 AI 放大' });
        }
        const allUrls = getSupplierCatalogAllImageUrls(row);
        if (allUrls.indexOf(sourceUrl) < 0) {
            return res.status(400).json({ error: '來源圖片不屬於此品項' });
        }
        let existing = parseGalleryImages(row.gallery_images);
        if (!existing.length && row.spec_json && row.spec_json.gallery_images) {
            existing = parseGalleryImages(row.spec_json.gallery_images);
        }
        const totalNow = allUrls.length;
        const room = PROTOTYPE_GALLERY_MAX_EXTRA + 1 - totalNow;
        if (room <= 0) {
            return res.status(400).json({ error: '已達多角度圖上限（封面＋' + PROTOTYPE_GALLERY_MAX_EXTRA + ' 張）' });
        }
        const REPLICATE_API_TOKEN = getReplicateApiToken();
        if (!REPLICATE_API_TOKEN) {
            return res.status(503).json({ error: replicateTokenMissingMessage() });
        }
        const scale = parseUpscaleScaleFromRequest(req);
        const sourceItems = buildSupplierCatalogImageItems(row);
        const srcItem = sourceItems.find((it) => it.url === sourceUrl);
        const srcLabel = (srcItem && srcItem.label) || '';
        const basePts = await getPointsVendorAssetUpscale();
        const pointsRequired = pointsForUpscaleScale(basePts, scale);
        const ownerId = uploadUser.id || (await getAuthOwnerIdFromReq(req));
        const isAdmin = await isProfileAdminUser(ownerId);
        if (!isAdmin && ownerId && pointsRequired > 0) {
            const { balance, sufficient } = await checkUserCreditsBalance(ownerId, pointsRequired);
            if (!sufficient) {
                return res.status(402).json({ error: '點數不足', balance, required: pointsRequired });
            }
        }
        const resImg = await fetch(sourceUrl, { redirect: 'follow' });
        if (!resImg.ok) return res.status(503).json({ error: '無法讀取來源圖片' });
        const imgBuf = Buffer.from(await resImg.arrayBuffer());
        const imgMime = (resImg.headers.get('content-type') || 'image/jpeg').split(';')[0].trim();
        const upscaleNeed = await evaluateVendorUpscaleNeedFromBuffer(imgBuf);
        if (!upscaleNeed.needed) {
            return res.status(400).json({
                error: vendorUpscaleRejectMessage(upscaleNeed),
                upscale_needed: false,
                megapixels: upscaleNeed.megapixels,
                width: upscaleNeed.width,
                height: upscaleNeed.height,
                ai_edit_url: AI_EDIT_UPSCALE_PAGE
            });
        }
        let upscaled;
        try {
            upscaled = await vendorMaterialUpscale(imgBuf, imgMime, REPLICATE_API_TOKEN, { scale: scale });
        } catch (upErr) {
            console.error('supplier gallery-images/upscale:', upErr.status, upErr.details || upErr.message);
            return res.status(502).json({
                error: '放大服務暫時無法使用，請稍後再試',
                details: upErr.status === 401 ? 'API Token 無效' : (upErr.details || upErr.message || '').slice(0, 200)
            });
        }
        const startSort = existing.length ? Math.max.apply(null, existing.map(function (g) { return g.sort_order; })) + 1 : 1;
        const upscaleLabel = vendorImageLabelFromSource(srcLabel, labelFromImageUrl(sourceUrl) || '放大');
        const upscaleFile = {
            buffer: upscaled.buffer,
            mimetype: upscaled.mimetype,
            originalname: 'upscale-' + Date.now() + '.jpg'
        };
        const newEntries = await uploadSupplierCatalogGalleryFiles(
            ctx.supplier.id, [upscaleFile], startSort, [upscaleLabel], ['upscale']
        );
        if (!newEntries.length) return res.status(500).json({ error: '上傳放大結果失敗' });
        newEntries.forEach(function (e) { e.source_url = sourceUrl; });
        const merged = existing.concat(newEntries);
        let patch = { gallery_images: merged, updated_at: new Date().toISOString() };
        let { data: updated, error } = await supabase
            .from('supplier_catalog_items')
            .update(patch)
            .eq('id', itemId)
            .select(SUPPLIER_CATALOG_ITEM_SELECT)
            .single();
        if (error && error.code === '42703') {
            const spec = (row.spec_json && typeof row.spec_json === 'object') ? { ...row.spec_json } : {};
            spec.gallery_images = merged;
            ({ data: updated, error } = await supabase
                .from('supplier_catalog_items')
                .update({ spec_json: spec, updated_at: new Date().toISOString() })
                .eq('id', itemId)
                .select(SUPPLIER_CATALOG_ITEM_SELECT)
                .single());
        }
        if (error) return res.status(500).json({ error: '更新失敗' });
        let balanceAfter = null;
        if (!isAdmin && ownerId && pointsRequired > 0) {
            const consumed = await consumeUserCredits(
                ownerId,
                pointsRequired,
                'vendor_asset_upscale',
                `供應商品項多角度圖 AI 放大 ${scale}×（${pointsRequired} 點）`,
                { industry_supplier_id: ctx.supplier.id, catalog_item_id: itemId, source_url: sourceUrl, scale: scale }
            );
            if (consumed.ok) balanceAfter = consumed.balance_after;
        }
        queueSyncImportedVendorAssetsFromCatalogItem(itemId);
        res.json({
            item: mapSupplierCatalogItemForApi(updated),
            points_deducted: (!isAdmin && pointsRequired > 0) ? pointsRequired : 0,
            balance_after: balanceAfter,
            upscale_from_url: sourceUrl,
            scale: scale
        });
    } catch (e) {
        console.error('POST /api/me/industry-supplier/catalog-items/:id/gallery-images/upscale:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// PATCH /api/me/industry-supplier/catalog-items/:id/image-labels — 更新封面／各張圖顯示名稱
app.patch('/api/me/industry-supplier/catalog-items/:id/image-labels', express.json(), async (req, res) => {
    try {
        if (!(await supplierCatalogTablesReady())) {
            return res.status(503).json({ error: '請先執行 docs/add-industry-supplier-catalog.sql' });
        }
        const ctx = await getMeIndustrySupplier(req, res);
        if (!ctx) return;
        const itemId = (req.params.id || '').trim();
        const body = req.body || {};
        if (!itemId) return res.status(400).json({ error: '缺少 id' });
        const { data: row, error: rowErr } = await supabase
            .from('supplier_catalog_items')
            .select('id, cover_image_url, cover_image_label, gallery_images, spec_json, item_kind')
            .eq('id', itemId)
            .eq('industry_supplier_id', ctx.supplier.id)
            .maybeSingle();
        if (rowErr) return res.status(500).json({ error: '查詢失敗' });
        if (!row) return res.status(404).json({ error: '找不到該品項' });
        if (!supplierCatalogSupportsGallery(row.item_kind) && body.entries && body.entries.length) {
            return res.status(400).json({ error: '此品項類型不支援多角度圖名稱' });
        }
        const updates = { updated_at: new Date().toISOString() };
        if (body.cover_label !== undefined) {
            updates.cover_image_label = String(body.cover_label || '').trim() || null;
        }
        if (Array.isArray(body.entries) && body.entries.length) {
            const byUrl = {};
            body.entries.forEach(function (ent) {
                if (!ent || !ent.url) return;
                const key = String(ent.url).trim();
                if (!byUrl[key]) byUrl[key] = {};
                if (ent.label !== undefined) byUrl[key].label = String(ent.label != null ? ent.label : '').trim();
            });
            const gallery = parseGalleryImages(row.gallery_images).map(function (g) {
                const patch = byUrl[g.url];
                if (!patch) return g;
                const next = {
                    url: g.url,
                    sort_order: g.sort_order,
                    label: patch.label !== undefined ? patch.label : g.label
                };
                const derivedKeep = normalizeVendorAiDerivedKind(g.ai_derived);
                if (derivedKeep) next.ai_derived = derivedKeep;
                if (g.source_url) next.source_url = g.source_url;
                return next;
            });
            updates.gallery_images = gallery;
        }
        if (Object.keys(updates).length <= 1) {
            return res.status(400).json({ error: '請提供 cover_label 或 entries' });
        }
        const coverLabelRequested = body.cover_label !== undefined;
        let coverLabelSkipped = false;
        let { data: updated, error } = await supabase
            .from('supplier_catalog_items')
            .update(updates)
            .eq('id', itemId)
            .select(SUPPLIER_CATALOG_ITEM_SELECT)
            .single();
        if (error && error.code === '42703') {
            if (String(error.message || '').includes('cover_image_label')) {
                delete updates.cover_image_label;
                coverLabelSkipped = coverLabelRequested;
            }
            if (String(error.message || '').includes('gallery_images')) {
                delete updates.gallery_images;
            }
            if (Object.keys(updates).length <= 1) {
                return res.status(503).json({
                    error: '資料庫尚未支援圖片名稱欄位',
                    code: 'IMAGE_LABELS_SCHEMA',
                    hint: '請至 Supabase 執行 docs/add-supplier-catalog-gallery-images.sql'
                });
            }
            ({ data: updated, error } = await supabase
                .from('supplier_catalog_items')
                .update(updates)
                .eq('id', itemId)
                .select(SUPPLIER_CATALOG_ITEM_LEGACY_SELECT)
                .single());
        }
        if (error) {
            console.error('PATCH supplier catalog image-labels:', error);
            return res.status(500).json({ error: error.message || '更新失敗' });
        }
        const payload = { item: mapSupplierCatalogItemForApi(updated) };
        if (coverLabelSkipped) {
            payload.cover_label_skipped = true;
            payload.warning = '多角度圖名稱已儲存；封面名稱需執行 docs/add-supplier-catalog-gallery-images.sql';
        }
        queueSyncImportedVendorAssetsFromCatalogItem(itemId);
        res.json(payload);
    } catch (e) {
        console.error('PATCH /api/me/industry-supplier/catalog-items/:id/image-labels:', e);
        res.status(500).json({ error: e.message || '系統錯誤' });
    }
});

