const PROMO_SCENE_TEMPLATE_SELECT = 'id, key, name, name_en, name_ja, name_es, name_de, name_fr, description, scene_prompt, composition_hint, recommended_ratios, category, slot, sort_order, is_active, flux_safety_tolerance, created_at, updated_at';
const PROMO_SCENE_TEMPLATE_SELECT_NO_I18N = 'id, key, name, description, scene_prompt, composition_hint, recommended_ratios, category, slot, sort_order, is_active, flux_safety_tolerance, created_at, updated_at';
const PROMO_SCENE_TEMPLATE_SELECT_LEGACY = 'id, key, name, description, scene_prompt, composition_hint, recommended_ratios, category, sort_order, is_active, created_at, updated_at';
const PROMO_SCENE_TEMPLATE_SELECT_LEGACY_NO_FLUX = PROMO_SCENE_TEMPLATE_SELECT_LEGACY;

function normalizePromoSceneTemplateKey(raw) {
    return String(raw || '').trim().toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_-]/g, '').slice(0, 64);
}

function normalizePromoTemplateSlot(raw) {
    return String(raw || '').trim().toLowerCase() === 'scene' ? 'scene' : 'theme';
}

function parsePromoRecommendedRatios(raw) {
    if (Array.isArray(raw)) {
        return raw.map((x) => String(x || '').trim()).filter(Boolean).slice(0, 12);
    }
    if (typeof raw === 'string') {
        return raw.split(/[,，\s]+/).map((x) => x.trim()).filter(Boolean).slice(0, 12);
    }
    return ['1:1', '4:3', '16:9'];
}

// GET /api/admin/promo-scene-templates — 情境圖主題／場景
app.get('/api/admin/promo-scene-templates', async (req, res) => {
    try {
        const user = await requireAdmin(req, res);
        if (!user) return;
        const slotFilter = req.query.slot ? normalizePromoTemplateSlot(req.query.slot) : '';
        let usedNoI18nFallback = false;
        let { data, error } = await supabase
            .from('promo_scene_templates')
            .select(PROMO_SCENE_TEMPLATE_SELECT)
            .order('sort_order', { ascending: true })
            .order('key', { ascending: true });
        if (error && (error.code === '42703' || (error.message && /column.*does not exist|name_en|name_ja|flux_safety_tolerance/.test(error.message)))) {
            usedNoI18nFallback = true;
            ({ data, error } = await supabase
                .from('promo_scene_templates')
                .select(PROMO_SCENE_TEMPLATE_SELECT_NO_I18N)
                .order('sort_order', { ascending: true })
                .order('key', { ascending: true }));
        }
        if (error && (error.code === '42703' || (error.message && /flux_safety_tolerance/.test(error.message)))) {
            ({ data, error } = await supabase
                .from('promo_scene_templates')
                .select(PROMO_SCENE_TEMPLATE_SELECT_LEGACY_NO_FLUX)
                .order('sort_order', { ascending: true })
                .order('key', { ascending: true }));
        }
        if (isSupabaseMissingColumnError(error, 'slot')) {
            const legacy = await supabase
                .from('promo_scene_templates')
                .select(PROMO_SCENE_TEMPLATE_SELECT_LEGACY)
                .order('sort_order', { ascending: true })
                .order('key', { ascending: true });
            if (legacy.error) {
                if (legacy.error.code === '42P01') {
                    return res.status(503).json({ error: '請先執行 docs/add-product-promo-image.sql', code: 'MIGRATION_REQUIRED' });
                }
                console.error('GET /api/admin/promo-scene-templates legacy:', legacy.error);
                return res.status(500).json({ error: '查詢失敗' });
            }
            let items = (legacy.data || []).map((r) => ({ ...r, slot: 'theme' }));
            if (slotFilter === 'scene') items = [];
            else if (slotFilter === 'theme') items = items.filter((r) => r.slot === 'theme');
            return res.json({
                items,
                migration_hint: '請執行 docs/add-promo-theme-scene-slots.sql 以啟用「主題／場景」分欄',
                scene_count: 0,
                slot_ready: false
            });
        }
        if (error) {
            if (error.code === '42P01') {
                return res.status(503).json({ error: '請先執行 docs/add-product-promo-image.sql', code: 'MIGRATION_REQUIRED' });
            }
            console.error('GET /api/admin/promo-scene-templates:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        let items = data || [];
        items = items.map((r) => ({ ...r, slot: resolvePromoTemplateSlot(r) }));
        if (slotFilter) items = items.filter((r) => resolvePromoTemplateSlot(r) === slotFilter);
        res.json({
            items,
            migration_hint: usedNoI18nFallback ? '若要儲存多語系名稱，請執行 docs/add-promo-scene-templates-multilang.sql' : undefined,
            scene_count: promoSceneSeed.countSceneTemplates(items),
            slot_ready: true
        });
    } catch (e) {
        console.error('GET /api/admin/promo-scene-templates 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

// POST /api/admin/promo-scene-templates
app.post('/api/admin/promo-scene-templates', express.json(), async (req, res) => {
    try {
        const user = await requireAdmin(req, res);
        if (!user) return;
        const body = req.body || {};
        const key = normalizePromoSceneTemplateKey(body.key);
        const name = String(body.name || '').trim();
        if (!key) return res.status(400).json({ error: '請填寫 key' });
        if (!name) return res.status(400).json({ error: '請填寫名稱' });
        const payload = {
            key,
            name,
            description: body.description != null ? String(body.description).trim() : null,
            scene_prompt: body.scene_prompt != null ? String(body.scene_prompt) : '',
            composition_hint: body.composition_hint != null ? String(body.composition_hint) : null,
            recommended_ratios: parsePromoRecommendedRatios(body.recommended_ratios),
            category: body.category != null ? String(body.category).trim() || null : null,
            slot: normalizePromoTemplateSlot(body.slot),
            sort_order: body.sort_order != null ? Number(body.sort_order) || 0 : 0,
            is_active: body.is_active === undefined ? true : !!body.is_active,
            flux_safety_tolerance: body.flux_safety_tolerance !== undefined
                ? parseFluxSafetyToleranceInput(body.flux_safety_tolerance)
                : undefined,
            updated_at: new Date().toISOString()
        };
        if (payload.flux_safety_tolerance === undefined) delete payload.flux_safety_tolerance;
        appendPromoSceneMultilangFields(payload, body);
        let { data, error } = await supabase.from('promo_scene_templates').insert(payload).select(PROMO_SCENE_TEMPLATE_SELECT).single();
        if (error && (error.code === '42703' || (error.message && /column.*does not exist|name_en|name_ja/.test(error.message)))) {
            for (const col of ['name_en', 'name_ja', 'name_es', 'name_de', 'name_fr']) delete payload[col];
            ({ data, error } = await supabase.from('promo_scene_templates').insert(payload).select(PROMO_SCENE_TEMPLATE_SELECT_LEGACY).single());
            if (!error && data && Object.keys(body).some((k) => /^name_(en|ja|es|de|fr)$/.test(k))) {
                return res.status(201).json({
                    item: data,
                    warning: '已新增（尚無多語系欄位）。請執行 docs/add-promo-scene-templates-multilang.sql'
                });
            }
        }
        if (isSupabaseMissingColumnError(error, 'slot')) {
            delete payload.slot;
            for (const col of ['name_en', 'name_ja', 'name_es', 'name_de', 'name_fr']) delete payload[col];
            ({ data, error } = await supabase.from('promo_scene_templates').insert(payload).select(PROMO_SCENE_TEMPLATE_SELECT_LEGACY).single());
            if (!error && data) data = { ...data, slot: 'theme' };
            if (!error) {
                return res.status(201).json({
                    item: data,
                    warning: '已新增（尚無 slot 欄）。請執行 docs/add-promo-theme-scene-slots.sql 才能區分主題／場景'
                });
            }
        }
        if (isSupabaseMissingColumnError(error, 'flux_safety_tolerance')) {
            delete payload.flux_safety_tolerance;
            ({ data, error } = await supabase.from('promo_scene_templates').insert(payload).select(PROMO_SCENE_TEMPLATE_SELECT_NO_I18N.replace(', flux_safety_tolerance', '')).single());
            if (!error) {
                return res.status(201).json({
                    item: data,
                    warning: '已新增（尚無 FLUX 審核欄位）。請執行 docs/add-flux-safety-tolerance.sql'
                });
            }
        }
        if (error) {
            if (error.code === '42P01') {
                return res.status(503).json({ error: '請先執行 docs/add-product-promo-image.sql', code: 'MIGRATION_REQUIRED' });
            }
            if (error.code === '23505') return res.status(400).json({ error: '此 key 已存在' });
            console.error('POST /api/admin/promo-scene-templates:', error);
            return res.status(500).json({ error: '新增失敗' });
        }
        res.status(201).json({ item: data });
    } catch (e) {
        console.error('POST /api/admin/promo-scene-templates 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

