app.get('/api/admin/promo-camera-params', async (req, res) => {
    try {
        const user = await requireAdmin(req, res);
        if (!user) return;
        const category = String(req.query.category || '').trim();
        const catRes = await fetchPromoCameraParamCategories(false);
        const categoryDefs = catRes.categories && catRes.categories.length ? catRes.categories : [];
        const categoryKeys = categoryDefs.length ? categoryDefs.map(function (c) { return c.key; }) : PROMO_CAMERA_ADMIN_CATEGORIES;
        let { data, error } = await queryPromoCameraParamOptionsList(category, categoryKeys);
        if (error) {
            if (error.code === '42P01' || isSupabaseMissingTableError(error)) {
                return res.status(503).json({ error: '請先執行 docs/add-promo-camera-params.sql', code: 'MIGRATION_REQUIRED' });
            }
            console.error('GET /api/admin/promo-camera-params:', error);
            return res.status(500).json({ error: '查詢失敗' });
        }
        const catsToRepair = category ? [category] : categoryKeys;
        for (let ci = 0; ci < catsToRepair.length; ci++) {
            await dedupePromoCameraDefaultsInCategory(catsToRepair[ci], null);
        }
        if (catsToRepair.length) {
            ({ data, error } = await queryPromoCameraParamOptionsList(category, categoryKeys));
            if (error) {
                console.error('GET /api/admin/promo-camera-params (re-fetch):', error);
                return res.status(500).json({ error: '查詢失敗' });
            }
        }
        const groupsRes = await fetchPromoCameraParamGroups(false, category || null);
        const groupsIndex = buildPromoCameraGroupsIndex(groupsRes.items || []);
        const enrichedItems = (data || []).map(function (row) {
            return normalizePromoCameraOptionRow(row, groupsIndex.byId);
        });
        res.json({
            items: enrichedItems,
            groups: groupsRes.items || [],
            categories: categoryKeys,
            category_defs: categoryDefs,
            groups_migration_hint: groupsRes.error === 'MIGRATION_REQUIRED' ? '請執行 docs/add-promo-camera-param-groups.sql' : undefined,
            categories_migration_hint: catRes.error === 'MIGRATION_REQUIRED' ? '請執行 docs/add-promo-camera-param-categories.sql' : undefined
        });
    } catch (e) {
        console.error('GET /api/admin/promo-camera-params 異常:', e);
        res.status(500).json({ error: '系統錯誤' });
    }
});

